import React, { useState } from 'react'
import * as Tooltip from '@radix-ui/react-tooltip'
import { motion, AnimatePresence } from 'framer-motion'
import { ThemeProvider } from './components/ui/ThemeProvider'
import { logger } from './utils/logger'
import { ThemeStatusBadge } from './components/ui/ThemeStatusBadge'
import { CharacterSheet } from './components/game/CharacterSheet'
import { StatRoller } from './components/game/StatRoller'
import { UnifiedRollSystem } from './components/dice/UnifiedRollSystem'
import { ChronicleProvider } from './components/chronicle/ChronicleProvider'
import { SessionManager } from './components/game/SessionManager'
import { AlignmentXPTracker } from './components/game/AlignmentXPTracker'
import { DebilityTracker } from './components/game/DebilityTracker'
import { ContextAwareSystem } from './components/game/ContextAwareSystem'
import { CommandPalette } from './components/ui/CommandPalette'
import { ErrorBoundary } from './components/ui/ErrorBoundary'
import { Sparkles, User, Dice6, Settings, NotebookPen, Play } from 'lucide-react'
import { Card, CardContent, Button, Badge, ThemeComponentShowcase } from './components/ui'
import { DiceHistorySidebar } from './components/dice/DiceHistorySidebar'
import { QuickRollZones } from './components/dice/QuickRollZones'
import { CharacterBuilder } from './components/game/creation/CharacterBuilder'
import { PlayTab } from './components/game/PlayTab'
import { GameManagementTab } from './components/game/GameManagementTab'
import { SettingsPanel } from './components/ui/SettingsPanel'
import { useCharacterStore } from './stores/characterStore'
import { useCommandPalette, useNavigationShortcuts, useGlobalShortcuts, useDiceShortcuts } from './hooks/useKeyboardShortcuts'
import { useDiceKeyboardShortcuts } from './hooks/useDiceKeyboardShortcuts'
import './utils/initializeMockData' // Initialize mock data for development
import { ButtonDebugger } from './components/ui/ButtonDebugger'
import {
  diagnoseAllButtons,
  enableButtonDebugging,
  autoFixAllButtons,
  generateButtonReport,
  type ButtonDiagnostic
} from './utils/buttonUtils'
import { BugAntIcon, WrenchScrewdriverIcon, DocumentTextIcon } from '@heroicons/react/24/outline'

type ActiveTab = 'play' | 'character' | 'dice' | 'game-management' | 'settings' | 'button-debug'


const App: React.FC = () => {
  const { characters, getActiveCharacter } = useCharacterStore()
  const activeCharacter = getActiveCharacter()
  const [activeTab, setActiveTab] = useState<ActiveTab>('play')
  const [showCharacterBuilder, setShowCharacterBuilder] = useState(false)
  const [showSessionManager, setShowSessionManager] = useState(false)
  const [commandPaletteOpen, setCommandPaletteOpen] = useState(false)
  const [themeShowcaseOpen, setThemeShowcaseOpen] = useState(false)
  const [buttonDiagnostics, setButtonDiagnostics] = useState<ButtonDiagnostic[]>([])
  const [debuggingEnabled, setDebuggingEnabled] = useState(false)
  const [autoFixCount, setAutoFixCount] = useState(0)

  // Dice sidebar state
  const [diceHistoryCollapsed, setDiceHistoryCollapsed] = useState(false)

  const tabs = [
    { id: 'play' as const, label: 'Play', icon: Play, featured: true },
    { id: 'character' as const, label: 'Character', icon: User },
    { id: 'dice' as const, label: 'Dice', icon: Dice6 },
    { id: 'game-management' as const, label: 'Game Management', icon: NotebookPen, description: 'Chronicle, Campaign, Monsters & More' },
    { id: 'settings' as const, label: 'Settings', icon: Settings, enhanced: true },
    ...(process.env.NODE_ENV === 'development' ? [{ id: 'button-debug' as const, label: 'Button Debug', icon: WrenchScrewdriverIcon }] : [])
  ]

  // Command palette integration
  const { registerCommandPalette, setIsOpen } = useCommandPalette()
  
  React.useEffect(() => {
    registerCommandPalette(
      () => setCommandPaletteOpen(true),
      () => setCommandPaletteOpen(false)
    )
  }, [registerCommandPalette])

  React.useEffect(() => {
    setIsOpen(commandPaletteOpen)
  }, [commandPaletteOpen, setIsOpen])

  // Navigation shortcuts
  useNavigationShortcuts((tabId) => {
    setActiveTab(tabId as ActiveTab)
  })

  // Global shortcuts
  useGlobalShortcuts({
    onToggleTheme: () => {
      // Theme toggle logic would go here
      logger.info('Toggle theme')
    }
  })

  // Dice shortcuts (legacy system)
  useDiceShortcuts((_stat) => {
    setActiveTab('dice')
  }, activeTab === 'dice' || activeTab === 'character')

  // New advanced dice keyboard shortcuts
  useDiceKeyboardShortcuts({
    characterId: 'eldara-moonwhisper', // TODO: Use actual active character ID
    enabled: true,
    modifierKey: 'none' // Direct key presses for fast gameplay
  })

  const tabVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: { 
      opacity: 1, 
      y: 0,
      transition: {
        duration: 0.3,
        ease: "easeOut"
      }
    },
    exit: { 
      opacity: 0, 
      y: -20,
      transition: {
        duration: 0.2,
        ease: "easeIn"
      }
    }
  }

  const renderContent = () => {
    switch (activeTab) {
      case 'play':
        return (
          <motion.div
            key="play"
            variants={tabVariants}
            initial="hidden"
            animate="visible"
            exit="exit"
          >
            <div>
              <PlayTab />
            </div>
          </motion.div>
        )
      case 'character':
        return (
          <motion.div
            key="character"
            variants={tabVariants}
            initial="hidden"
            animate="visible"
            exit="exit"
          >
            <div className="space-y-8">
              {characters.length === 0 || showCharacterBuilder ? (
                <div className="space-y-4">
                  {characters.length > 0 && (
                    <div className="flex justify-between items-center">
                      <h3 className="text-lg font-semibold">Create New Character</h3>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => setShowCharacterBuilder(false)}
                      >
                        Cancel
                      </Button>
                    </div>
                  )}
                  <CharacterBuilder onFinished={() => setShowCharacterBuilder(false)} />
                </div>
              ) : (
                <>
                  <div className="flex justify-end">
                    <Button
                      variant="primary"
                      size="sm"
                      onClick={() => setShowCharacterBuilder(true)}
                    >
                      Create Character
                    </Button>
                  </div>
                  <CharacterSheet />
                </>
              )}
            </div>
          </motion.div>
        )
      case 'dice':
        return (
          <motion.div
            key="dice"
            variants={tabVariants}
            initial="hidden"
            animate="visible"
            exit="exit"
            className="max-w-2xl mx-auto"
          >
            <div className="space-y-6">
              <UnifiedRollSystem
                characterId="eldara-moonwhisper"
                layout="inline"
                showHistory={true}
                showQuickRolls={true}
                showCustomRolls={true}
                className="max-w-full"
              />

              {/* Chronicle-Enabled Stat Rolling */}
              <StatRoller
                characterName="Eldara Moonwhisper"
                statModifiers={{
                  STR: 1,
                  DEX: 2,
                  CON: 1,
                  INT: 4,
                  WIS: 3,
                  CHA: 2
                }}
                onStatRoll={(stat, result) => {
                  logger.info(`${stat} roll result:`, result)
                }}
              />

              <ContextAwareSystem context="dice" compact />
            </div>
          </motion.div>
        )
      case 'game-management':
        return (
          <motion.div
            key="game-management"
            variants={tabVariants}
            initial="hidden"
            animate="visible"
            exit="exit"
          >
            <GameManagementTab />
          </motion.div>
        )
      case 'settings':
        return (
          <motion.div
            key="settings"
            variants={tabVariants}
            initial="hidden"
            animate="visible"
            exit="exit"
          >
            <SettingsPanel />
          </motion.div>
        )
      case 'button-debug':
        return (
          <motion.div
            key="button-debug"
            variants={tabVariants}
            initial="hidden"
            animate="visible"
            exit="exit"
          >
            <div className="max-w-6xl mx-auto space-y-8">
              {/* Button Debug Control Panel */}
              <Card variant="magical" padding="lg">
                <CardContent>
                  <div className="space-y-6">
                    <div>
                      <h2 className="text-display-md mb-2">ZimboMate v2 Button Debugger</h2>
                      <p className="text-muted-foreground">
                        Diagnose and fix button functionality issues throughout the application
                      </p>
                    </div>
                    
                    <div className="flex flex-wrap gap-4">
                      <Button 
                        variant="cyber" 
                        onClick={() => {
                          const results = diagnoseAllButtons()
                          setButtonDiagnostics(results)
                          logger.info('🔍 Button diagnosis completed:', results)
                        }}
                      >
                        <BugAntIcon size={16} />
                        Run Diagnosis
                      </Button>
                      
                      <Button 
                        variant="secondary" 
                        onClick={() => {
                          enableButtonDebugging()
                          setDebuggingEnabled(true)
                          logger.info('🔧 Button debugging enabled')
                        }}
                        disabled={debuggingEnabled}
                      >
                        <WrenchScrewdriverIcon size={16} />
                        {debuggingEnabled ? 'Debugging Active' : 'Enable Debug Mode'}
                      </Button>
                      
                      <Button 
                        variant="magical" 
                        onClick={() => {
                          const fixed = autoFixAllButtons()
                          setAutoFixCount(prev => prev + fixed)
                          logger.info(`🔧 Auto-fixed ${fixed} button issues`)
                        }}
                      >
                        <WrenchScrewdriverIcon size={16} />
                        Auto-Fix Issues
                      </Button>
                      
                      <Button 
                        variant="outline" 
                        onClick={() => {
                          const report = generateButtonReport()
                          logger.info(report)
                          
                          // Download report
                          const blob = new Blob([report], { type: 'text/plain' })
                          const url = URL.createObjectURL(blob)
                          const a = document.createElement('a')
                          a.href = url
                          a.download = 'zimbomate-v2-button-report.txt'
                          a.click()
                          URL.revokeObjectURL(url)
                        }}
                      >
                        <DocumentTextIcon size={16} />
                        Download Report
                      </Button>
                    </div>
                    
                    {/* Status Summary */}
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                      <div className="text-center p-4 rounded-lg bg-popover">
                        <div className="text-2xl font-bold text-[color:var(--nature-500)]">
                          {buttonDiagnostics.filter(d => d.working).length}
                        </div>
                        <div className="text-sm text-muted-foreground">
                          Working Buttons
                        </div>
                      </div>
                      
                      <div className="text-center p-4 rounded-lg bg-popover">
                        <div className="text-2xl font-bold text-[color:var(--red-500)]">
                          {buttonDiagnostics.filter(d => !d.working).length}
                        </div>
                        <div className="text-sm text-muted-foreground">
                          Issues Found
                        </div>
                      </div>
                      
                      <div className="text-center p-4 rounded-lg bg-popover">
                        <div className="text-2xl font-bold text-[color:var(--yellow-500)]">
                          {autoFixCount}
                        </div>
                        <div className="text-sm text-muted-foreground">
                          Auto-Fixed
                        </div>
                      </div>
                      
                      <div className="text-center p-4 rounded-lg bg-popover">
                        <div className="text-2xl font-bold text-primary">
                          {debuggingEnabled ? '🔧' : '💤'}
                        </div>
                        <div className="text-sm text-muted-foreground">
                          Debug Mode
                        </div>
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>
              
              {/* Interactive Test Suite */}
              <ButtonDebugger 
                onTestResult={(testName, success, details) => {
                  logger.info(`✅ Test result: ${testName} - ${success ? 'SUCCESS' : 'FAILED'}`, details)
                }}
              />
              
              {/* Console Commands Help */}
              <Card>
                <CardContent>
                  <div className="space-y-4">
                    <h3 className="text-lg font-semibold">Console Commands</h3>
                    <div className="grid md:grid-cols-2 gap-4 text-sm font-mono">
                      <div>
                        <code className="text-primary">window.ZimboMate.debugButtons()</code>
                        <p className="text-muted-foreground">Enable visual debugging</p>
                      </div>
                      <div>
                        <code className="text-primary">window.ZimboMate.fixButtons()</code>
                        <p className="text-muted-foreground">Auto-fix all issues</p>
                      </div>
                      <div>
                        <code className="text-primary">window.ZimboMate.buttonReport()</code>
                        <p className="text-muted-foreground">Generate report</p>
                      </div>
                      <div>
                        <code className="text-primary">window.ZimboMate.diagnoseButtons()</code>
                        <p className="text-muted-foreground">Get diagnostics</p>
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>
            </div>
          </motion.div>
        )
      default:
        return (
          <motion.div
            key="play"
            variants={tabVariants}
            initial="hidden"
            animate="visible"
            exit="exit"
          >
            <PlayTab />
          </motion.div>
        )
    }
  }

  const handleSessionJoined = (session: any) => {
    setShowSessionManager(false)
    logger.info('Joined session:', session)
  }

  return (
    <ErrorBoundary>
      <ThemeProvider>
        <ChronicleProvider defaultEnabled={true}>
          <Tooltip.Provider delayDuration={200} skipDelayDuration={300}>
          <div className="texture" aria-hidden="true" />

        <div
          className="relative min-h-screen transition-colors duration-300 bg-background text-foreground"
        >
          {/* Header */}
          <header
            className="sticky top-0 z-50 border-b border-primary/20 bg-card/90 backdrop-blur supports-[backdrop-filter]:bg-card/80 shadow-sm"
          >
            <div className="container mx-auto px-6 py-4">
              <div className="flex items-center justify-between">
                <motion.div 
                  className="flex items-center gap-3"
                  initial={{ opacity: 0, x: -20 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ duration: 0.5 }}
                >
                  <motion.div 
                    className="w-10 h-10 rounded-lg flex items-center justify-center bg-primary/20 text-primary"
                    whileHover={{ scale: 1.1, rotate: 5 }}
                    whileTap={{ scale: 0.95 }}
                  >
                    <Sparkles 

                      className="w-6 h-6 text-primary"

                    />
                  </motion.div>
                  <div>
                    <h1 className="font-display text-xl">ZimboMate V2</h1>
                                        <p className="text-sm text-muted-foreground">
                      Dungeon World Companion
                    </p>
                  </div>
                </motion.div>
                <motion.div
                  initial={{ opacity: 0, x: 20 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ duration: 0.5, delay: 0.2 }}
                >
                  <ThemeStatusBadge />
                </motion.div>
              </div>
            </div>
          </header>

          {/* Navigation Tabs */}
          <nav
            className="sticky top-[73px] z-40 border-b border-primary/10 bg-card/90 backdrop-blur supports-[backdrop-filter]:bg-card/80"
          >
            <div className="container mx-auto px-6">
              <div className="flex gap-1 py-2 overflow-x-auto">
                {tabs.map((tab, index) => {
                  const Icon = tab.icon
                  const isActive = activeTab === tab.id
                  
                  return (
                    <motion.div
                      key={tab.id}
                      initial={{ opacity: 0, y: -10 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ duration: 0.3, delay: index * 0.1 }}
                    >
                      <Button
                        variant={isActive ? 'primary' : 'ghost'}
                        size="sm"
                        onClick={() => setActiveTab(tab.id)}
                        className={`relative whitespace-nowrap ${
                          tab.featured ? 'ring-2 ring-primary/30 ' : ''
                        }`}
                        title={tab.description || tab.label}
                      >
                        <Icon size={16} />
                        {tab.label}
                        {tab.featured && !isActive && (
                          <Badge variant="secondary" className="ml-1 text-xs">
                            ★
                          </Badge>
                        )}
                        {tab.enhanced && !isActive && (
                          <Badge variant="default" className="ml-1 text-xs">
                            ✨
                          </Badge>
                        )}
                        {isActive && (
                          <motion.div
                            className="absolute bottom-0 left-0 right-0 h-0.5 bg-primary"
                            
                            layoutId="activeTab"
                            transition={{ type: "spring", stiffness: 300, damping: 30 }} />
                        )}
                      </Button>
                    </motion.div>
                  )
                })}
              </div>
            </div>
          </nav>

          {/* Main Content Layout with Sidebar */}
          <div className="flex h-screen">
            {/* Dice History Sidebar */}
            <DiceHistorySidebar
              characterId={activeCharacter?.id || "fallback-character-id"}
              collapsed={diceHistoryCollapsed}
              onToggleCollapse={() => setDiceHistoryCollapsed(!diceHistoryCollapsed)}
            />

            {/* Main Content Area */}
            <main className="flex-1 overflow-y-auto">
              <div className="container mx-auto px-6 py-8">
                <AnimatePresence mode="wait">
                  {renderContent()}
                </AnimatePresence>
              </div>
            </main>
          </div>

          {/* Quick Roll Zones for Drag & Drop */}
          <QuickRollZones characterId="eldara-moonwhisper" />

          {/* Footer */}
          <footer
            className="mt-16 border-t border-primary/20 bg-card/95 backdrop-blur supports-[backdrop-filter]:bg-card/85"
          >
            <div className="container mx-auto px-6 py-8">
              <div className="flex items-center justify-between">
                <motion.div 
                  className="flex items-center gap-3"
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ duration: 0.5, delay: 0.5 }}
                >
                  <User 
                    className="w-5 h-5 text-muted-foreground" />
                  <span 
                    className="text-sm text-muted-foreground">
                    ZimboMate V2 • Built with React 19 & Tailwind v4
                  </span>
                </motion.div>
                <motion.div 
                  className="text-sm text-muted-foreground"
                  
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ duration: 0.5, delay: 0.7 }}>
                  Phase 4D: Advanced File Management System Complete ✨
                </motion.div>
              </div>
            </div>
          </footer>

          {/* Theme Component Showcase */}
          <ThemeComponentShowcase
            isOpen={themeShowcaseOpen}
            onClose={() => setThemeShowcaseOpen(false)}
          />

          {/* Command Palette */}
          <CommandPalette
            isOpen={commandPaletteOpen}
            onClose={() => setCommandPaletteOpen(false)}
            onNavigate={(tabId) => {
              setActiveTab(tabId as ActiveTab)
              setCommandPaletteOpen(false)
            }}
            onAction={(actionId) => {
              logger.info('Command palette action:', actionId)
              // Handle various actions here
              switch (actionId) {
                case 'quick-roll-2d6':
                  // Trigger dice roll
                  break
                case 'heal-character':
                  // Heal character
                  break
                case 'new-note':
                  // Create new note
                  break
                // Add more actions as needed
              }
            }}
          />

          {/* Session Manager Modal */}
          <SessionManager
            isVisible={showSessionManager}
            onClose={() => setShowSessionManager(false)}
            onSessionJoined={handleSessionJoined}
          />
        </div>
          </Tooltip.Provider>
        </ChronicleProvider>
      </ThemeProvider>
    </ErrorBoundary>
  )
}

export default App

// Mock data for Campaign Management System

// Campaign-related enums for the Campaign Management System
export enum LocationType {
  CITY = 'city',
  TOWN = 'town', 
  VILLAGE = 'village',
  DUNGEON = 'dungeon',
  WILDERNESS = 'wilderness',
  OTHER = 'other'
}

export enum NPCImportance {
  LOW = 'low',
  MEDIUM = 'medium',
  HIGH = 'high'
}

export enum NPCDisposition {
  FRIENDLY = 'friendly',
  NEUTRAL = 'neutral',
  HOSTILE = 'hostile',
  UNKNOWN = 'unknown'
}

export enum CampaignSortBy {
  DATE_CREATED = 'dateCreated',
  DATE_MODIFIED = 'dateModified',
  NAME = 'name',
  SESSIONS_COUNT = 'sessionsCount'
}

export enum SessionSortBy {
  DATE = 'date',
  XP_GAINED = 'xpGained',
  DURATION = 'duration',
  TITLE = 'title'
}

export enum JournalSortBy {
  DATE = 'date',
  IMPORTANCE = 'importance',
  TITLE = 'title',
  TAGS = 'tags'
}

// String formatting functions for Campaign Management System
export const toDate = (input: Date | string | number | null | undefined): Date => {
  if (input instanceof Date) return input;
  const parsed = new Date(input as any);
  return isNaN(parsed.getTime()) ? new Date() : parsed;
};
export const formatCampaignDuration = (created: Date | string | number): string => {
  const createdDate = toDate(created);
  const now = new Date();
  const diffTime = Math.abs(now.getTime() - createdDate.getTime());
  const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  
  if (diffDays === 1) return '1 day';
  if (diffDays < 30) return `${diffDays} days`;
  if (diffDays < 365) return `${Math.floor(diffDays / 30)} months`;
  return `${Math.floor(diffDays / 365)} years`;
};

export const formatSessionDuration = (duration?: number): string => {
  if (!duration) return 'Unknown duration';
  
  const hours = Math.floor(duration / 60);
  const minutes = duration % 60;
  
  if (hours === 0) return `${minutes}m`;
  if (minutes === 0) return `${hours}h`;
  return `${hours}h ${minutes}m`;
};

export const formatXPTotal = (xp: number): string => {
  if (xp === 0) return 'No XP';
  if (xp === 1) return '1 XP';
  return `${xp} XP`;
};

export const formatDateRelative = (date: Date | string | number): string => {
  const d = toDate(date);
  const now = new Date();
  const diffTime = now.getTime() - d.getTime();
  const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
  
  if (diffDays === 0) return 'Today';
  if (diffDays === 1) return 'Yesterday';
  if (diffDays < 7) return `${diffDays} days ago`;
  if (diffDays < 30) return `${Math.floor(diffDays / 7)} weeks ago`;
  if (diffDays < 365) return `${Math.floor(diffDays / 30)} months ago`;
  return `${Math.floor(diffDays / 365)} years ago`;
};

export const formatNPCDisposition = (disposition: NPCDisposition): string => {
  switch (disposition) {
    case NPCDisposition.FRIENDLY: return 'Friendly';
    case NPCDisposition.NEUTRAL: return 'Neutral';
    case NPCDisposition.HOSTILE: return 'Hostile';
    case NPCDisposition.UNKNOWN: return 'Unknown';
    default: return 'Unknown';
  }
};

export const formatLocationType = (type: LocationType): string => {
  switch (type) {
    case LocationType.CITY: return 'City';
    case LocationType.TOWN: return 'Town';
    case LocationType.VILLAGE: return 'Village';
    case LocationType.DUNGEON: return 'Dungeon';
    case LocationType.WILDERNESS: return 'Wilderness';
    case LocationType.OTHER: return 'Other';
    default: return 'Unknown';
  }
};

// Mock campaigns data
export const mockCampaigns = [
  {
    id: 'campaign-1',
    name: 'The Sundered Realm',
    description: 'A tale of political intrigue and ancient magic in the borderlands of Kaeroth',
    created: new Date('2024-01-15'),
    lastModified: new Date('2024-12-18'),
    playerNotes: 'Remember to investigate the mysterious cult activities in the capital',
    characterIds: ['char-1', 'char-2'],
    sessions: [
      {
        id: 'session-1',
        title: 'The Tavern Meeting',
        date: new Date('2024-01-20'),
        duration: 180,
        summary: 'The party met in the Silver Flagon and received their first quest',
        notes: 'Great roleplay between characters, established party dynamics',
        xpGained: 2,
        highlights: ['Epic bar fight', 'Mysterious hooded figure'],
        challenges: ['Combat took too long', 'Need better NPC voices'],
        nextSession: 'Travel to the ancient ruins, prepare dungeon maps'
      },
      {
        id: 'session-2', 
        title: 'The Ancient Ruins',
        date: new Date('2024-02-03'),
        duration: 240,
        summary: 'Explored the cursed temple and discovered the first artifact',
        notes: 'Players loved the puzzle mechanics, great atmosphere',
        xpGained: 3,
        highlights: ['Clever puzzle solution', 'Dramatic artifact reveal'],
        challenges: ['Lighting mechanics unclear', 'Need more trap variety']
      }
    ],
    journal: [
      {
        id: 'journal-1',
        title: 'The Cult of the Void',
        content: 'Strange reports of missing villagers and dark rituals in the northern provinces. The cult seems to be seeking ancient artifacts.',
        date: new Date('2024-01-22'),
        tags: ['cult', 'mystery', 'artifacts'],
        isImportant: true,
        relatedSessionId: 'session-1'
      },
      {
