/**
 * Contextual Roll Panel Component
 * Provides dedicated display space for roll results with rich interaction
 * Appears contextually near the roll source (stats, moves, etc.)
 */

import React from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { RotateCcw, Copy, Share2, X, Plus, Minus, Zap } from 'lucide-react'
import { useDiceStore, type RollResult } from '../../stores/diceStore'
import { Button } from '../ui/Button'
import { compatibility } from '../../utils/browserCompatibility'

interface ContextualRollPanelProps {
  roll: RollResult | null
  onClose?: () => void
  position?: 'top' | 'bottom' | 'left' | 'right' | 'center'
  anchorElement?: HTMLElement
  className?: string
}

interface RollPanelState {
  isVisible: boolean
  position: { x: number; y: number }
  showDetails: boolean
}

const DiceVisual: React.FC<{ value: number; size?: 'sm' | 'md' | 'lg' }> = ({
  value,
  size = 'md'
}) => {
  const sizeClasses = {
    sm: 'w-6 h-6 text-xs',
    md: 'w-8 h-8 text-sm',
    lg: 'w-12 h-12 text-lg'
  }

  return (
    <motion.div
      className={`
        ${sizeClasses[size]}
        bg-gradient-to-br from-white to-gray-100
        border-2 border-border
        rounded-lg shadow-sm
        flex items-center justify-center
        font-bold text-foreground
        relative
      `}
      whileHover={{ scale: 1.05, rotate: 2 }}
      transition={{ type: "spring", stiffness: 400 }}
    >
      {value}
      {/* Dot pattern for authenticity */}
      <div className="absolute inset-1 pointer-events-none opacity-20">
        {Array.from({ length: Math.min(value, 6) }).map((_, i) => (
          <div
            key={i}
            className="absolute w-0.5 h-0.5 bg-gray-600 rounded-full"
            style={{
              left: `${20 + (i % 2) * 60}%`,
              top: `${20 + Math.floor(i / 2) * 30}%`
            }}
          />
        ))}
      </div>
    </motion.div>
  )
}

const OutcomeIndicator: React.FC<{ outcome: RollResult['outcome'] }> = ({ outcome }) => {
  const config = {
    success: {
      color: 'bg-chart-2/120',
      icon: '🎉',
      text: 'Success!',
      description: '10+ • You achieve your goal'
    },
    partial: {
      color: 'bg-chart-4/120',
      icon: '⚡',
      text: 'Partial Success',
      description: '7-9 • You succeed with complications'
    },
    failure: {
      color: 'bg-destructive/120',
      icon: '💪',
      text: 'Learn & Mark XP',
      description: '6- • Things go wrong, but you grow'
    }
  }

  const { color, icon, text, description } = config[outcome]

  return (
    <motion.div
      className={`
        ${color} text-white px-3 py-1 rounded-full
        text-sm font-semibold shadow-sm
        flex items-center gap-2
      `}
      initial={{ scale: 0 }}
      animate={{ scale: 1 }}
      transition={{ type: "spring", stiffness: 300, delay: 0.1 }}
    >
      <span>{icon}</span>
      <span>{text}</span>
    </motion.div>
  )
}

const ModifierBadge: React.FC<{ value: number; source: string }> = ({ value, source }) => {
  if (value === 0) return null

  return (
    <div className={`
      inline-flex items-center gap-1 px-2 py-1 rounded text-xs
      ${value > 0 ? 'bg-chart-2/15 text-chart-2' : 'bg-destructive/15 text-destructive'}
    `}>
      {value > 0 ? <Plus size={10} /> : <Minus size={10} />}
      <span>{Math.abs(value)}</span>
      <span className="opacity-75">{source}</span>
    </div>
  )
}

const RollBreakdown: React.FC<{ roll: RollResult }> = ({ roll }) => {
  return (
    <div className="space-y-2 text-sm text-muted-foreground">
      {/* Dice breakdown */}
      <div className="flex items-center gap-2">
        <span>Roll:</span>
        <div className="flex gap-1">
          <DiceVisual value={roll.dice1} size="sm" />
          <span className="text-muted-foreground">+</span>
          <DiceVisual value={roll.dice2} size="sm" />
        </div>
        <span>= {roll.dice1 + roll.dice2}</span>
      </div>

      {/* Modifiers */}
      {roll.modifiers && roll.modifiers.length > 0 && (
        <div className="flex flex-wrap gap-1">
          {roll.modifiers.map((mod, i) => (
            <ModifierBadge key={i} value={mod.value} source={mod.source} />
          ))}
        </div>
      )}

      {/* Final calculation */}
      <div className="flex items-center gap-2 font-semibold">
        <span>Total:</span>
        <span className="text-lg">{roll.total}</span>
      </div>
    </div>
  )
}

export const ContextualRollPanel: React.FC<ContextualRollPanelProps> = ({
  roll,
  onClose,
  position = 'center',
  anchorElement,
  className = ''
}) => {
  const { rerollLast, addToHistory, getActiveCharacterId } = useDiceStore()
  const [panelState, setPanelState] = React.useState<RollPanelState>({
    isVisible: false,
    position: { x: 0, y: 0 },
    showDetails: false
  })

  // Calculate position based on anchor element
  React.useEffect(() => {
    if (!roll || !anchorElement) return

    const rect = anchorElement.getBoundingClientRect()
    const positions = {
      top: { x: rect.left + rect.width / 2, y: rect.top - 10 },
      bottom: { x: rect.left + rect.width / 2, y: rect.bottom + 10 },
      left: { x: rect.left - 10, y: rect.top + rect.height / 2 },
      right: { x: rect.right + 10, y: rect.top + rect.height / 2 },
      center: { x: window.innerWidth / 2, y: window.innerHeight / 2 }
    }

    setPanelState(prev => ({
      ...prev,
      isVisible: true,
      position: positions[position]
    }))
  }, [roll, anchorElement, position])

  const handleReroll = () => {
    if (!roll) return

    // Create a new roll with the same parameters
    rerollLast()
    onClose?.()
  }

  const handleCopy = async () => {
    if (!roll) return

    const rollText = `${roll.description}: ${roll.total} (${roll.dice1} + ${roll.dice2}${roll.modifiers?.map(m => ` ${m.value > 0 ? '+' : ''}${m.value}`).join('') || ''}) - ${roll.outcome}`

    const success = await compatibility.copyToClipboard(rollText)
    if (success) {
      // Could trigger a small success indication here
      console.log('Roll copied to clipboard')
    }
  }

  const handleShare = () => {
    if (!roll) return

    const rollText = `🎲 ${roll.description}: ${roll.total} - ${roll.outcome}`

    if (compatibility.hasFeature('webShare')) {
      navigator.share?.({
        title: 'Dice Roll Result',
        text: rollText
      }).catch(console.warn)
    } else {
      // Fallback to copy
      handleCopy()
    }
  }

  if (!roll) return null

  return (
    <AnimatePresence>
      <motion.div
        className={`
          fixed z-[100] pointer-events-none
          ${className}
        `}
        style={{
          left: panelState.position.x,
          top: panelState.position.y,
          transform: 'translate(-50%, -50%)'
        }}
        initial={{ opacity: 0, scale: 0.8 }}
        animate={{ opacity: 1, scale: 1 }}
        exit={{ opacity: 0, scale: 0.8 }}
        transition={{ type: "spring", stiffness: 300, damping: 25 }}
      >
        <div className="
          bg-card
          border border-border
          rounded-xl shadow-xl
          p-4 max-w-sm
          pointer-events-auto
        ">
          {/* Header */}
          <div className="flex items-start justify-between mb-3">
            <div className="flex-1">
              <h3 className="font-semibold text-foreground  text-sm">
                {roll.description}
              </h3>
              {roll.characterId && (
                <p className="text-xs text-muted-foreground mt-1">
                  Character Roll
                </p>
              )}
            </div>

            <Button
              variant="ghost"
              size="sm"
              onClick={onClose}
              className="p-1 -mt-1 -mr-1"
            >
              <X size={14} />
            </Button>
          </div>

          {/* Main result display */}
          <div className="text-center mb-4">
            {/* Total result */}
            <motion.div
              className="text-3xl font-bold text-foreground  mb-2"
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              transition={{ type: "spring", stiffness: 400, delay: 0.2 }}
            >
              {roll.total}
            </motion.div>

            {/* Outcome indicator */}
            <OutcomeIndicator outcome={roll.outcome} />
          </div>

          {/* Dice visualization */}
          <div className="flex justify-center items-center gap-2 mb-4">
            <DiceVisual value={roll.dice1} />
            <span className="text-muted-foreground font-bold">+</span>
            <DiceVisual value={roll.dice2} />

            {roll.modifiers && roll.modifiers.length > 0 && (
              <>
                {roll.modifiers.map((mod, i) => (
                  <React.Fragment key={i}>
                    <span className={`text-sm font-bold ${mod.value >= 0 ? 'text-chart-2' : 'text-destructive'}`}>
                      {mod.value >= 0 ? '+' : ''}{mod.value}
                    </span>
                  </React.Fragment>
                ))}
              </>
            )}
          </div>

          {/* Detailed breakdown (collapsible) */}
          {panelState.showDetails && (
            <motion.div
              className="border-t border-border pt-3 mb-4"
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: 'auto' }}
              exit={{ opacity: 0, height: 0 }}
            >
              <RollBreakdown roll={roll} />
            </motion.div>
          )}

          {/* Action buttons */}
          <div className="flex gap-2 justify-between">
            <div className="flex gap-1">
              <Button
                variant="ghost"
                size="sm"
                onClick={handleReroll}
                className="p-2"
                title="Reroll with same parameters"
              >
                <RotateCcw size={14} />
              </Button>

              <Button
                variant="ghost"
                size="sm"
                onClick={handleCopy}
                className="p-2"
                title="Copy result to clipboard"
              >
                <Copy size={14} />
              </Button>

              <Button
                variant="ghost"
                size="sm"
                onClick={handleShare}
                className="p-2"
                title="Share result"
              >
                <Share2 size={14} />
              </Button>
            </div>

            <Button
              variant="ghost"
              size="sm"
              onClick={() => setPanelState(prev => ({ ...prev, showDetails: !prev.showDetails }))}
              className="p-2 text-xs"
              title="Toggle details"
            >
              <Zap size={14} />
            </Button>
          </div>

          {/* Effects indicators */}
          {(roll.effects?.xpAwarded || roll.effects?.holdGranted) && (
            <div className="mt-3 pt-3 border-t border-border">
              <div className="flex flex-wrap gap-1">
                {roll.effects.xpAwarded && (
                  <div className="bg-chart-4/15 text-chart-4 text-xs px-2 py-1 rounded-full">
                    +1 XP Awarded
                  </div>
                )}
                {roll.effects.holdGranted && (
                  <div className="bg-muted text-foreground text-xs px-2 py-1 rounded-full">
                    +{roll.effects.holdGranted} Hold
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </motion.div>
    </AnimatePresence>
  )
}

// Hook for managing contextual roll panels
export const useContextualRollPanel = () => {
  const [activePanel, setActivePanel] = React.useState<{
    roll: RollResult
    anchorElement: HTMLElement
    position: ContextualRollPanelProps['position']
  } | null>(null)

  const showPanel = React.useCallback((
    roll: RollResult,
    anchorElement: HTMLElement,
    position: ContextualRollPanelProps['position'] = 'bottom'
  ) => {
    setActivePanel({ roll, anchorElement, position })
  }, [])

  const hidePanel = React.useCallback(() => {
    setActivePanel(null)
  }, [])

  // Auto-hide after delay
  React.useEffect(() => {
    if (!activePanel) return

    const timer = setTimeout(() => {
      hidePanel()
    }, 8000) // Auto-hide after 8 seconds

    return () => clearTimeout(timer)
  }, [activePanel, hidePanel])

  return {
    activePanel,
    showPanel,
    hidePanel,
    PanelComponent: activePanel ? (
      <ContextualRollPanel
        roll={activePanel.roll}
        anchorElement={activePanel.anchorElement}
        position={activePanel.position}
        onClose={hidePanel}
      />
    ) : null
  }
}

/**
 * Dice History Sidebar Component
 * Always-visible sidebar showing dice roll history with re-roll and copy functionality
 * Desktop-optimized with rich interactions
 */

import React, { useState, useMemo } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { Card, CardHeader, CardTitle, CardContent, Button, Badge } from '../ui'
import { Dices, Copy, RotateCcw, Trash2, Download, Filter, ChevronDown, ChevronRight, Clock, TrendingUp, TrendingDown, Minus, Check, MoreHorizontal, FileText } from 'lucide-react'
import { useDiceStore, type RollResult } from '../../stores/diceStore'
import { RollHistoryExportDialog } from './RollHistoryExportDialog'
import { format } from 'date-fns'

interface DiceHistorySidebarProps {
  characterId: string
  className?: string
  collapsed?: boolean
  onToggleCollapse?: () => void
}

type FilterType = 'all' | 'success' | 'partial' | 'failure' | 'stats' | 'moves' | 'custom'
type SortType = 'newest' | 'oldest' | 'result' | 'type'

const outcomeColors = {
  success: 'text-chart-2 bg-chart-2/15',
  partial: 'text-chart-4 bg-chart-4/15',
  failure: 'text-destructive bg-destructive/15'
}

const outcomeIcons = {
  success: TrendingUp,
  partial: Minus,
  failure: TrendingDown
}

export const DiceHistorySidebar: React.FC<DiceHistorySidebarProps> = ({
  characterId,
  className = '',
  collapsed = false,
  onToggleCollapse
}) => {
  const [filter, setFilter] = useState<FilterType>('all')
  const [sort, setSort] = useState<SortType>('newest')
  const [showFilters, setShowFilters] = useState(false)
  const [showExportDialog, setShowExportDialog] = useState(false)

  const {
    getHistoryForCharacter,
    clearHistoryForCharacter,
    exportHistory,
    rerollWithSameContext,
    copyRollToClipboard,
    isRolling
  } = useDiceStore()

  const rawHistory = getHistoryForCharacter(characterId)

  // Filter and sort history
  const filteredHistory = useMemo(() => {
    let filtered = rawHistory

    // Apply filter
    if (filter !== 'all') {
      filtered = filtered.filter(roll => {
        switch (filter) {
          case 'success': return roll.outcome === 'success'
          case 'partial': return roll.outcome === 'partial'
          case 'failure': return roll.outcome === 'failure'
          case 'stats': return roll.type === 'stat'
          case 'moves': return roll.type === 'move'
          case 'custom': return roll.type === 'custom'
          default: return true
        }
      })
    }

    // Apply sort
    filtered = [...filtered].sort((a, b) => {
      switch (sort) {
        case 'newest': return b.timestamp - a.timestamp
        case 'oldest': return a.timestamp - b.timestamp
        case 'result': return b.finalResult - a.finalResult
        case 'type': return a.type.localeCompare(b.type)
        default: return b.timestamp - a.timestamp
      }
    })

    return filtered
  }, [rawHistory, filter, sort])

  // Stats
  const stats = useMemo(() => {
    const total = rawHistory.length
    const successes = rawHistory.filter(r => r.outcome === 'success').length
    const partials = rawHistory.filter(r => r.outcome === 'partial').length
    const failures = rawHistory.filter(r => r.outcome === 'failure').length
    const average = total > 0 ? (rawHistory.reduce((sum, r) => sum + r.finalResult, 0) / total).toFixed(1) : '0'

    return { total, successes, partials, failures, average }
  }, [rawHistory])

  const handleReroll = async (roll: RollResult) => {
    try {
      await rerollWithSameContext(roll.id)
    } catch (error) {
      console.error('Failed to reroll:', error)
    }
  }

  const [copiedRoll, setCopiedRoll] = useState<string | null>(null)

  const handleCopy = (roll: RollResult, format: 'simple' | 'detailed' | 'notation' = 'simple') => {
    let copyText: string

    switch (format) {
      case 'detailed':
        copyText = `${roll.context.label}: ${roll.dice1} + ${roll.dice2} ${roll.modifier >= 0 ? '+' : ''}${roll.modifier} = ${roll.finalResult} (${roll.outcome})`
        break
      case 'notation':
        copyText = `[[2d6${roll.modifier >= 0 ? '+' : ''}${roll.modifier}]] = ${roll.finalResult}`
        break
      default:
        copyText = `${roll.context.label}: ${roll.finalResult} (${roll.outcome})`
    }

    navigator.clipboard.writeText(copyText)
    setCopiedRoll(roll.id)
    setTimeout(() => setCopiedRoll(null), 2000)
  }

  const handleExport = () => {
    setShowExportDialog(true)
  }

  const handleClear = () => {
    if (confirm('Clear all dice history? This cannot be undone.')) {
      clearHistoryForCharacter(characterId)
    }
  }

  if (collapsed) {
    return (
      <motion.div
        className={`bg-card border-r border-border ${className}`}
        style={{ width: '60px' }}
      >
        <div className="p-3 border-b border-border">
          <Button
            variant="ghost"
            size="sm"
            onClick={onToggleCollapse}
            className="w-full"
          >
            <ChevronRight size={16} />
          </Button>
        </div>
        <div className="p-3">
          <div className="text-center">
            <Dices size={20} className="mx-auto mb-2 text-muted-foreground" />
            <div className="text-xs text-muted-foreground writing-mode-vertical">
              {stats.total} rolls
            </div>
          </div>
        </div>
      </motion.div>
    )
  }

  return (
    <motion.div
      id="dice-history-content"
      role="complementary"
      aria-labelledby="dice-history-heading"
      className={`bg-card border-r border-border flex flex-col ${className}`}
      style={{ width: '320px', minWidth: '320px' }}
      initial={{ width: 0 }}
      animate={{ width: 320 }}
      exit={{ width: 0 }}
    >
      {/* Header */}
      <div className="p-4 border-b border-border">
        <div className="flex items-center justify-between mb-3">
          <div className="flex items-center gap-2">
            <Dices size={20} className="text-primary" aria-hidden="true" />
            <h2 id="dice-history-heading" className="text-lg font-semibold">Dice History</h2>
          </div>
          <Button
            variant="ghost"
            size="sm"
            onClick={onToggleCollapse}
            aria-label="Collapse dice history sidebar"
            aria-expanded={!collapsed}
            aria-controls="dice-history-content"
          >
            <ChevronDown size={16} aria-hidden="true" />
          </Button>
        </div>

        {/* Stats Summary */}
        <div className="grid grid-cols-4 gap-2 mb-3">
          <div className="text-center">
            <div className="text-sm font-semibold">{stats.total}</div>
            <div className="text-xs text-muted-foreground">Total</div>
          </div>
          <div className="text-center">
            <div className="text-sm font-semibold text-chart-2">{stats.successes}</div>
            <div className="text-xs text-muted-foreground">10+</div>
          </div>
          <div className="text-center">
            <div className="text-sm font-semibold text-chart-4">{stats.partials}</div>
            <div className="text-xs text-muted-foreground">7-9</div>
          </div>
          <div className="text-center">
            <div className="text-sm font-semibold text-destructive">{stats.failures}</div>
            <div className="text-xs text-muted-foreground">6-</div>
          </div>
        </div>

        {/* Filter Toggle */}
        <Button
          variant="ghost"
          size="sm"
          onClick={() => setShowFilters(!showFilters)}
          className="w-full justify-between"
        >
          <span className="flex items-center gap-2">
            <Filter size={14} />
            Filters ({filter}, {sort})
          </span>
          {showFilters ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
        </Button>
      </div>

      {/* Filters */}
      <AnimatePresence>
        {showFilters && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            className="border-b border-border p-3"
          >
            <div className="space-y-3">
              <div>
                <label className="text-xs font-medium text-muted-foreground mb-1 block">Filter</label>
                <select
                  value={filter}
                  onChange={(e) => setFilter(e.target.value as FilterType)}
                  className="w-full text-sm border border-border rounded px-2 py-1"
                >
                  <option value="all">All Rolls</option>
                  <option value="success">Success (10+)</option>
                  <option value="partial">Partial (7-9)</option>
                  <option value="failure">Failure (6-)</option>
                  <option value="stats">Stat Rolls</option>
                  <option value="moves">Move Rolls</option>
                  <option value="custom">Custom Rolls</option>
                </select>
              </div>
              <div>
                <label className="text-xs font-medium text-muted-foreground mb-1 block">Sort</label>
                <select
                  value={sort}
                  onChange={(e) => setSort(e.target.value as SortType)}
                  className="w-full text-sm border border-border rounded px-2 py-1"
                >
                  <option value="newest">Newest First</option>
                  <option value="oldest">Oldest First</option>
                  <option value="result">By Result</option>
                  <option value="type">By Type</option>
                </select>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Actions */}
      <div className="p-3 border-b border-border">
        <div className="flex gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={handleExport}
            className="flex-1"
          >
            <Download size={14} className="mr-1" />
            Export
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={handleClear}
            className="flex-1"
            disabled={stats.total === 0}
          >
            <Trash2 size={14} className="mr-1" />
            Clear
          </Button>
        </div>
      </div>

      {/* History List */}
      <div className="flex-1 overflow-y-auto">
        <AnimatePresence>
          {filteredHistory.length === 0 ? (
            <div className="p-4 text-center text-muted-foreground">
              <Dices size={32} className="mx-auto mb-2 opacity-50" />
              <div className="text-sm">No rolls yet</div>
              <div className="text-xs">Start rolling to see history</div>
            </div>
          ) : (
            filteredHistory.map((roll, index) => {
              const OutcomeIcon = outcomeIcons[roll.outcome]

              return (
                <motion.div
                  key={roll.id}
                  initial={{ opacity: 0, x: -20 }}
                  animate={{ opacity: 1, x: 0 }}
                  exit={{ opacity: 0, x: -20 }}
                  transition={{ delay: index * 0.05 }}
                  className="border-b border-border p-3 hover:bg-muted/50 hover:bg-muted group"
                  whileHover={{ scale: 1.01, x: 2 }}
                >
                  <div className="flex items-start justify-between mb-2">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-1">
                        <span className="text-sm font-medium">{roll.context.label}</span>
                        <Badge variant="secondary" className="text-xs">
                          {roll.type}
                        </Badge>
                      </div>
                      <div className="text-xs text-muted-foreground">
                        {format(roll.timestamp, 'HH:mm:ss')}
                      </div>
                    </div>
                    <div className="flex items-center gap-1">
                      <Badge className={`${outcomeColors[roll.outcome]} text-xs`}>
                        <OutcomeIcon size={10} className="mr-1" />
                        {roll.finalResult}
                      </Badge>
                    </div>
                  </div>

                  <div className="mb-3">
                    {/* Dice Visual */}
                    <div className="flex items-center gap-2 text-xs text-muted-foreground  mb-1">
                      <div className="flex items-center gap-1">
                        <motion.div
                          className="w-5 h-5 bg-gradient-to-br from-primary/12 to-primary/20 border border-primary/30 rounded shadow-sm text-primary flex items-center justify-center text-xs font-bold"
                          whileHover={{ rotate: 5, scale: 1.1 }}
                          transition={{ type: "spring", stiffness: 300 }}
                        >
                          {roll.dice1}
                        </motion.div>
                        <span className="text-muted-foreground">+</span>
                        <motion.div
                          className="w-5 h-5 bg-gradient-to-br from-primary/12 to-primary/20 border border-primary/30 rounded shadow-sm text-primary flex items-center justify-center text-xs font-bold"
                          whileHover={{ rotate: -5, scale: 1.1 }}
                          transition={{ type: "spring", stiffness: 300 }}
                        >
                          {roll.dice2}
                        </motion.div>
                        <span className="text-muted-foreground">{roll.modifier >= 0 ? '+' : ''}{roll.modifier}</span>
                        <span className="text-muted-foreground">=</span>
                        <span className={`font-semibold ${
                          roll.outcome === 'success' ? 'text-chart-2' :
                          roll.outcome === 'partial' ? 'text-chart-4' :
                          'text-destructive'
                        }`}>
                          {roll.finalResult}
                        </span>
                      </div>
                    </div>

                    {/* Roll Breakdown */}
                    <div className="text-xs text-muted-foreground ">
                      Base: {roll.dice1 + roll.dice2} {roll.modifier !== 0 && `• Modifier: ${roll.modifier >= 0 ? '+' : ''}${roll.modifier}`}
                    </div>
                  </div>

                  <div className="flex gap-1">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => handleReroll(roll)}
                      className="text-xs px-2 py-1 h-6 hover:bg-primary/10 hover:text-primary"
                      disabled={isRolling}
                    >
                      <RotateCcw size={10} className="mr-1" />
                      Reroll
                    </Button>

                    <div className="relative">
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => handleCopy(roll, 'simple')}
                        className={`text-xs px-2 py-1 h-6 hover:bg-chart-2/12 hover:text-chart-2 ${
                          copiedRoll === roll.id ? 'bg-chart-2/15 text-chart-2' : ''
                        }`}
                      >
                        {copiedRoll === roll.id ? (
                          <>
                            <Check size={10} className="mr-1" />
                            Copied
                          </>
                        ) : (
                          <>
                            <Copy size={10} className="mr-1" />
                            Copy
                          </>
                        )}
                      </Button>
                    </div>

                    {/* More Actions Dropdown */}
                    <div className="relative group">
                      <Button
                        variant="ghost"
                        size="sm"
                        className="text-xs px-1 py-1 h-6 hover:bg-muted"
                      >
                        <MoreHorizontal size={10} />
                      </Button>

                      {/* Dropdown Menu */}
                      <div className="absolute right-0 top-full mt-1 bg-card rounded-lg shadow-lg border border-border py-1 min-w-[140px] opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-200 z-50">
                        <button
                          onClick={() => handleCopy(roll, 'detailed')}
                          className="w-full text-left px-3 py-1 text-xs hover:bg-muted hover:bg-muted"
                        >
                          Copy Detailed
                        </button>
                        <button
                          onClick={() => handleCopy(roll, 'notation')}
                          className="w-full text-left px-3 py-1 text-xs hover:bg-muted hover:bg-muted"
                        >
                          Copy Dice Notation
                        </button>
                        <div className="border-t border-border my-1" />
                        <button
                          onClick={() => {
                            // Share roll result
                            if (navigator.share) {
                              navigator.share({
                                title: 'Dice Roll Result',
                                text: `${roll.context.label}: ${roll.finalResult} (${roll.outcome})`
                              })
                            }
                          }}
                          className="w-full text-left px-3 py-1 text-xs hover:bg-muted hover:bg-muted"
                        >
                          Share Result
                        </button>
                      </div>
                    </div>
                  </div>
                </motion.div>
              )
            })
          )}
        </AnimatePresence>
      </div>

      {/* Export Dialog */}
      <RollHistoryExportDialog
        isOpen={showExportDialog}
        onClose={() => setShowExportDialog(false)}
        characterId={characterId}
      />
    </motion.div>
  )
}

/**
 * Roll Display Manager Component
 * Manages dedicated display spaces for roll results across the application
 * Provides different display modes: contextual panels, persistent results, roll comparisons
 */

import React from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { BarChart3, Grid, Clock, Maximize2, Minimize2 } from 'lucide-react'
import { useDiceStore, type RollResult } from '../../stores/diceStore'
import { useCharacterStore } from '../../stores/characterStore'
import { ContextualRollPanel, useContextualRollPanel } from './ContextualRollPanel'
import { Button } from '../ui/Button'

interface RollDisplayManagerProps {
  displayMode?: 'contextual' | 'persistent' | 'comparison' | 'timeline'
  maxVisibleRolls?: number
  className?: string
}

interface PersistentRollCardProps {
  roll: RollResult
  onExpand?: () => void
  onRemove?: () => void
  isExpanded?: boolean
}

const PersistentRollCard: React.FC<PersistentRollCardProps> = ({
  roll,
  onExpand,
  onRemove,
  isExpanded = false
}) => {
  const outcomeColors = {
    success: 'border-chart-2/30 bg-chart-2/12',
    partial: 'border-chart-4/30 bg-chart-4/12',
    failure: 'border-destructive/30 bg-destructive/12'
  }

  const outcomeIcons = {
    success: '🎉',
    partial: '⚡',
    failure: '💪'
  }

  return (
    <motion.div
      className={`
        ${outcomeColors[roll.outcome]}
        border rounded-lg p-3 shadow-sm
        hover:shadow-md transition-all duration-200
      `}
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -20 }}
      whileHover={{ scale: 1.02 }}
    >
      <div className="flex items-start justify-between mb-2">
        <div className="flex-1">
          <div className="flex items-center gap-2 mb-1">
            <span className="text-lg">{outcomeIcons[roll.outcome]}</span>
            <h4 className="font-semibold text-sm truncate">{roll.description}</h4>
          </div>
          <div className="flex items-center gap-2">
            <span className="text-2xl font-bold">{roll.total}</span>
            <span className="text-sm text-muted-foreground ">
              ({roll.dice1} + {roll.dice2}
              {roll.modifiers?.map(m => ` ${m.value >= 0 ? '+' : ''}${m.value}`).join('') || ''})
            </span>
          </div>
        </div>

        <div className="flex gap-1">
          <Button
            variant="ghost"
            size="sm"
            onClick={onExpand}
            className="p-1"
            title={isExpanded ? "Minimize" : "Expand details"}
          >
            {isExpanded ? <Minimize2 size={12} /> : <Maximize2 size={12} />}
          </Button>
        </div>
      </div>

      {/* Expanded details */}
      <AnimatePresence>
        {isExpanded && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className="border-t border-border pt-2"
          >
            {/* Timestamp */}
            <div className="text-xs text-muted-foreground mb-2">
              {new Date(roll.timestamp).toLocaleString()}
            </div>

            {/* Effects */}
            {(roll.effects?.xpAwarded || roll.effects?.holdGranted) && (
              <div className="flex flex-wrap gap-1 mb-2">
                {roll.effects.xpAwarded && (
                  <div className="bg-chart-4/15 text-chart-4 text-xs px-2 py-1 rounded-full">
                    +1 XP
                  </div>
                )}
                {roll.effects.holdGranted && (
                  <div className="bg-primary/10 text-primary text-xs px-2 py-1 rounded-full">
                    +{roll.effects.holdGranted} Hold
                  </div>
                )}
              </div>
            )}

            {/* Modifiers breakdown */}
            {roll.modifiers && roll.modifiers.length > 0 && (
              <div className="space-y-1">
                <div className="text-xs font-medium text-foreground ">Modifiers:</div>
                {roll.modifiers.map((modifier, i) => (
                  <div key={i} className="text-xs text-muted-foreground  ml-2">
                    {modifier.value >= 0 ? '+' : ''}{modifier.value} from {modifier.source}
                  </div>
                ))}
              </div>
            )}
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  )
}

const TimelineView: React.FC<{ rolls: RollResult[] }> = ({ rolls }) => {
  const groupedRolls = React.useMemo(() => {
    const groups: Record<string, RollResult[]> = {}

    rolls.forEach(roll => {
      const date = new Date(roll.timestamp).toDateString()
      if (!groups[date]) groups[date] = []
      groups[date].push(roll)
    })

    return Object.entries(groups).sort(([a], [b]) =>
      new Date(b).getTime() - new Date(a).getTime()
    )
  }, [rolls])

  return (
    <div className="space-y-4">
      {groupedRolls.map(([date, dateRolls]) => (
        <div key={date} className="relative">
          {/* Date header */}
          <div className="flex items-center gap-3 mb-3">
            <div className="bg-primary/100 w-3 h-3 rounded-full" />
            <h3 className="font-semibold text-foreground ">
              {date === new Date().toDateString() ? 'Today' : date}
            </h3>
            <div className="flex-1 h-px bg-muted " />
            <span className="text-sm text-muted-foreground">{dateRolls.length} rolls</span>
          </div>

          {/* Rolls for this date */}
          <div className="ml-6 space-y-2">
            {dateRolls.map((roll) => (
              <div key={roll.id} className="flex items-center gap-3 p-2 rounded-lg hover:bg-muted/50 hover:bg-muted">
                <div className="text-xs text-muted-foreground w-16">
                  {new Date(roll.timestamp).toLocaleTimeString([], {
                    hour: '2-digit',
                    minute: '2-digit'
                  })}
                </div>
                <div className="flex-1">
                  <span className="font-medium">{roll.description}</span>
                  <span className="ml-2 font-bold">{roll.total}</span>
                </div>
                <div className={`
                  px-2 py-1 rounded-full text-xs
                  ${roll.outcome === 'success' ? 'bg-chart-2/12 text-chart-2' : ''}
                  ${roll.outcome === 'partial' ? 'bg-chart-4/12 text-chart-4' : ''}
                  ${roll.outcome === 'failure' ? 'bg-destructive/15 text-destructive' : ''}
                `}>
                  {roll.outcome}
                </div>
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>
  )
}

const ComparisonView: React.FC<{ rolls: RollResult[] }> = ({ rolls }) => {
  const stats = React.useMemo(() => {
    if (rolls.length === 0) return null

    const outcomes = rolls.reduce((acc, roll) => {
      acc[roll.outcome] = (acc[roll.outcome] || 0) + 1
      return acc
    }, {} as Record<string, number>)

    const averageRoll = rolls.reduce((sum, roll) => sum + roll.total, 0) / rolls.length
    const highestRoll = Math.max(...rolls.map(r => r.total))
    const lowestRoll = Math.min(...rolls.map(r => r.total))

    return {
      total: rolls.length,
      outcomes,
      averageRoll: averageRoll.toFixed(1),
      highestRoll,
      lowestRoll,
      successRate: ((outcomes.success || 0) / rolls.length * 100).toFixed(1)
    }
  }, [rolls])

  if (!stats) {
    return (
      <div className="text-center text-muted-foreground py-8">
        No rolls to compare yet
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Summary stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="bg-primary/10 p-3 rounded-lg text-center">
          <div className="text-2xl font-bold text-primary">{stats.total}</div>
          <div className="text-sm text-primary">Total Rolls</div>
        </div>

        <div className="bg-chart-2/12 p-3 rounded-lg text-center">
          <div className="text-2xl font-bold text-chart-2">{stats.successRate}%</div>
          <div className="text-sm text-chart-2">Success Rate</div>
        </div>

        <div className="bg-accent/12 p-3 rounded-lg text-center">
          <div className="text-2xl font-bold text-accent">{stats.averageRoll}</div>
          <div className="text-sm text-accent">Average Roll</div>
        </div>

        <div className="bg-chart-4/12 p-3 rounded-lg text-center">
          <div className="text-2xl font-bold text-chart-4">{stats.highestRoll}</div>
          <div className="text-sm text-chart-4">Highest Roll</div>
        </div>
      </div>

      {/* Outcome breakdown */}
      <div className="bg-card p-4 rounded-lg border border-border">
        <h4 className="font-semibold mb-3 flex items-center gap-2">
          <BarChart3 size={16} />
          Outcome Distribution
        </h4>

        <div className="space-y-2">
          {(['success', 'partial', 'failure'] as const).map(outcome => {
            const count = stats.outcomes[outcome] || 0
            const percentage = (count / stats.total * 100).toFixed(1)

            const colors = {
              success: 'bg-chart-2/120',
              partial: 'bg-chart-4/120',
              failure: 'bg-destructive/120'
            }

            return (
              <div key={outcome} className="flex items-center gap-3">
                <div className="w-20 text-sm capitalize">{outcome}</div>
                <div className="flex-1 bg-muted  rounded-full h-2">
                  <div
                    className={`${colors[outcome]} h-2 rounded-full transition-all duration-500`}
                    style={{ width: `${percentage}%` }}
                  />
                </div>
                <div className="text-sm text-muted-foreground w-12">{count}</div>
                <div className="text-sm text-muted-foreground w-12">{percentage}%</div>
              </div>
            )
          })}
        </div>
      </div>
    </div>
  )
}

export const RollDisplayManager: React.FC<RollDisplayManagerProps> = ({
  displayMode = 'persistent',
  maxVisibleRolls = 10,
  className = ''
}) => {
  const { getAllRolls } = useDiceStore()
  const { activeCharacterId } = useCharacterStore()
  const { PanelComponent } = useContextualRollPanel()

  const [currentMode, setCurrentMode] = React.useState(displayMode)
  const [expandedRolls, setExpandedRolls] = React.useState<Set<string>>(new Set())

  const characterId = activeCharacterId
  const allRolls = getAllRolls()
  const recentRolls = allRolls.slice(0, maxVisibleRolls)

  const toggleExpanded = (rollId: string) => {
    setExpandedRolls(prev => {
      const next = new Set(prev)
      if (next.has(rollId)) {
        next.delete(rollId)
      } else {
        next.add(rollId)
      }
      return next
    })
  }

  const modeIcons = {
    contextual: Grid,
    persistent: Maximize2,
    comparison: BarChart3,
    timeline: Clock
  }

  const ModeIcon = modeIcons[currentMode]

  return (
    <div className={`space-y-4 ${className}`}>
      {/* Mode selector */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <ModeIcon size={20} className="text-muted-foreground" />
          <h2 className="text-lg font-semibold">Roll Display</h2>
        </div>

        <div className="flex gap-1">
          {(['persistent', 'timeline', 'comparison'] as const).map(mode => (
            <Button
              key={mode}
              variant={currentMode === mode ? 'default' : 'ghost'}
              size="sm"
              onClick={() => setCurrentMode(mode)}
              className="capitalize"
            >
              {mode}
            </Button>
          ))}
        </div>
      </div>

      {/* Display content based on mode */}
      <div className="min-h-[200px]">
        {currentMode === 'persistent' && (
          <div className="grid gap-3">
            <AnimatePresence>
              {recentRolls.map(roll => (
                <PersistentRollCard
                  key={roll.id}
                  roll={roll}
                  isExpanded={expandedRolls.has(roll.id)}
                  onExpand={() => toggleExpanded(roll.id)}
                />
              ))}
            </AnimatePresence>

            {recentRolls.length === 0 && (
              <div className="text-center text-muted-foreground py-8">
                No recent rolls to display
              </div>
            )}
          </div>
        )}

        {currentMode === 'timeline' && (
          <TimelineView rolls={allRolls} />
        )}

        {currentMode === 'comparison' && (
          <ComparisonView rolls={allRolls} />
        )}
      </div>

      {/* Contextual panels overlay */}
      {PanelComponent}
    </div>
  )
}

/**
 * Roll History Export Dialog Component
 * Provides user interface for exporting dice roll history in various formats
 */

import React, { useState, useMemo } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { Download, Copy, Eye, X, Calendar, Filter, Settings, FileText } from 'lucide-react'
import { useDiceStore } from '../../stores/diceStore'
import {
  exportRollHistory,
  copyExportToClipboard,
  downloadExport,
  getExportPreview,
  filterRolls,
  type ExportFormat,
  type ExportOptions
} from '../../utils/rollHistoryExport'
import { Button } from '../ui/Button'

interface RollHistoryExportDialogProps {
  isOpen: boolean
  onClose: () => void
  characterId?: string
  className?: string
}

const formatOptions: { value: ExportFormat; label: string; description: string; icon: string }[] = [
  {
    value: 'plain',
    label: 'Plain Text',
    description: 'Simple text format for basic sharing',
    icon: '📄'
  },
  {
    value: 'markdown',
    label: 'Markdown',
    description: 'Formatted text with headers and styling',
    icon: '📝'
  },
  {
    value: 'csv',
    label: 'CSV',
    description: 'Spreadsheet-compatible data format',
    icon: '📊'
  },
  {
    value: 'json',
    label: 'JSON',
    description: 'Structured data for developers',
    icon: '🔧'
  },
  {
    value: 'discord',
    label: 'Discord',
    description: 'Optimized for Discord chat with emojis',
    icon: '💬'
  },
  {
    value: 'rptools',
    label: 'RPTools',
    description: 'MapTool/RPTools dice notation format',
    icon: '🎲'
  }
]

export const RollHistoryExportDialog: React.FC<RollHistoryExportDialogProps> = ({
  isOpen,
  onClose,
  characterId,
  className = ''
}) => {
  const { getAllRolls, getActiveCharacterId } = useDiceStore()

  const [exportOptions, setExportOptions] = useState<ExportOptions>({
    format: 'markdown',
    includeCharacterInfo: true,
    includeTimestamps: true,
    includeModifiers: true,
    includeEffects: true,
    maxRolls: 50
  })

  const [showPreview, setShowPreview] = useState(false)
  const [isExporting, setIsExporting] = useState(false)
  const [exportSuccess, setExportSuccess] = useState<string | null>(null)

  const targetCharacterId = characterId || getActiveCharacterId()
  const allRolls = getAllRolls()

  // Filter rolls for the target character if specified
  const characterRolls = useMemo(() => {
    if (!targetCharacterId) return allRolls
    return allRolls.filter(roll => roll.characterId === targetCharacterId)
  }, [allRolls, targetCharacterId])

  const filteredRolls = useMemo(() => {
    return filterRolls(characterRolls, exportOptions)
  }, [characterRolls, exportOptions])

  const exportPreview = useMemo(() => {
    if (!showPreview) return ''
    return getExportPreview(filteredRolls, exportOptions, 15)
  }, [filteredRolls, exportOptions, showPreview])

  const handleFormatChange = (format: ExportFormat) => {
    setExportOptions(prev => ({ ...prev, format }))
  }

  const handleOptionChange = (key: keyof ExportOptions, value: any) => {
    setExportOptions(prev => ({ ...prev, [key]: value }))
  }

  const handleCopyToClipboard = async () => {
    setIsExporting(true)
    setExportSuccess(null)

    try {
      const success = await copyExportToClipboard(filteredRolls, exportOptions)
      if (success) {
        setExportSuccess('Copied to clipboard!')
        setTimeout(() => setExportSuccess(null), 3000)
      } else {
        throw new Error('Copy failed')
      }
    } catch (error) {
      console.error('Export to clipboard failed:', error)
      setExportSuccess('Copy failed - please try download instead')
      setTimeout(() => setExportSuccess(null), 3000)
    } finally {
      setIsExporting(false)
    }
  }

  const handleDownload = () => {
    setIsExporting(true)
    setExportSuccess(null)

    try {
      downloadExport(filteredRolls, exportOptions)
      setExportSuccess('Download started!')
      setTimeout(() => setExportSuccess(null), 3000)
    } catch (error) {
      console.error('Download failed:', error)
      setExportSuccess('Download failed - please try again')
      setTimeout(() => setExportSuccess(null), 3000)
    } finally {
      setIsExporting(false)
    }
  }

  const handleDateRangeChange = (range: 'today' | 'week' | 'month' | 'all') => {
    const now = new Date()
    let dateRange: { start: Date; end: Date } | undefined

    switch (range) {
      case 'today':
        dateRange = {
          start: new Date(now.getFullYear(), now.getMonth(), now.getDate()),
          end: new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59)
        }
        break
      case 'week':
        const weekStart = new Date(now)
        weekStart.setDate(now.getDate() - 7)
        dateRange = { start: weekStart, end: now }
        break
      case 'month':
        const monthStart = new Date(now)
        monthStart.setDate(now.getDate() - 30)
        dateRange = { start: monthStart, end: now }
        break
      case 'all':
      default:
        dateRange = undefined
        break
    }

    setExportOptions(prev => ({ ...prev, dateRange }))
  }

  if (!isOpen) return null

  return (
    <AnimatePresence>
      <div className="fixed inset-0 z-50 flex items-center justify-center">
        {/* Backdrop */}
        <motion.div
          className="absolute inset-0 bg-black/50"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          onClick={onClose}
        />

        {/* Dialog */}
        <motion.div
          className={`
            relative w-full max-w-4xl mx-4 max-h-[90vh] overflow-hidden
            bg-card
            rounded-xl shadow-2xl
            flex flex-col
            ${className}
          `}
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={{ opacity: 0, scale: 0.95 }}
        >
          {/* Header */}
          <div className="flex items-center justify-between p-6 border-b border-border">
            <div className="flex items-center gap-3">
              <FileText className="text-primary" size={24} />
              <div>
                <h2 className="text-xl font-semibold text-foreground ">
                  Export Roll History
                </h2>
                <p className="text-sm text-muted-foreground ">
                  {filteredRolls.length} rolls • Export in your preferred format
                </p>
              </div>
            </div>

            <Button variant="ghost" size="sm" onClick={onClose} className="p-2">
              <X size={20} />
            </Button>
          </div>

          {/* Content */}
          <div className="flex-1 overflow-hidden flex">
            {/* Options Panel */}
            <div className="w-80 border-r border-border p-6 overflow-y-auto">
              <div className="space-y-6">
                {/* Format Selection */}
                <div>
                  <label className="block text-sm font-medium mb-3">Export Format</label>
                  <div className="grid grid-cols-2 gap-2">
                    {formatOptions.map(option => (
                      <button
                        key={option.value}
                        onClick={() => handleFormatChange(option.value)}
                        className={`
                          p-3 text-left rounded-lg border transition-all
                          ${exportOptions.format === option.value
                            ? 'border-primary/40 bg-primary/10'
                            : 'border-border hover:border-border'
                          }
                        `}
                      >
                        <div className="flex items-center gap-2 mb-1">
                          <span>{option.icon}</span>
                          <span className="font-medium text-sm">{option.label}</span>
                        </div>
                        <p className="text-xs text-muted-foreground ">
                          {option.description}
                        </p>
                      </button>
                    ))}
                  </div>
                </div>

                {/* Date Range */}
                <div>
                  <label className="block text-sm font-medium mb-3">
                    <Calendar size={16} className="inline mr-2" />
                    Time Period
                  </label>
                  <div className="space-y-2">
                    {[
                      { value: 'all', label: 'All Time', description: `${characterRolls.length} rolls` },
                      { value: 'month', label: 'Last 30 Days', description: 'Recent activity' },
                      { value: 'week', label: 'Last 7 Days', description: 'This week' },
                      { value: 'today', label: 'Today', description: 'Today only' }
                    ].map(option => (
                      <button
                        key={option.value}
                        onClick={() => handleDateRangeChange(option.value as any)}
                        className={`
                          w-full p-2 text-left rounded border transition-all
                          ${!exportOptions.dateRange && option.value === 'all'
                            ? 'border-primary/40 bg-primary/10'
                            : exportOptions.dateRange && option.value !== 'all'
                            ? 'border-primary/40 bg-primary/10'
                            : 'border-border hover:border-border'
                          }
                        `}
                      >
                        <div className="font-medium text-sm">{option.label}</div>
                        <div className="text-xs text-muted-foreground ">{option.description}</div>
                      </button>
                    ))}
                  </div>
                </div>

                {/* Include Options */}
                <div>
                  <label className="block text-sm font-medium mb-3">
                    <Settings size={16} className="inline mr-2" />
                    Include Data
                  </label>
                  <div className="space-y-2">
                    {[
                      { key: 'includeTimestamps' as const, label: 'Timestamps', description: 'When rolls were made' },
                      { key: 'includeModifiers' as const, label: 'Modifiers', description: 'Stat bonuses and penalties' },
                      { key: 'includeEffects' as const, label: 'Effects', description: 'XP and Hold awards' },
                      { key: 'includeCharacterInfo' as const, label: 'Character Data', description: 'Character and roll context' }
                    ].map(option => (
                      <label key={option.key} className="flex items-center gap-3 p-2 rounded hover:bg-muted/50 hover:bg-muted">
                        <input
                          type="checkbox"
                          checked={exportOptions[option.key] as boolean}
                          onChange={(e) => handleOptionChange(option.key, e.target.checked)}
                          className="rounded"
                        />
                        <div className="flex-1">
                          <div className="font-medium text-sm">{option.label}</div>
                          <div className="text-xs text-muted-foreground ">{option.description}</div>
                        </div>
                      </label>
                    ))}
                  </div>
                </div>

                {/* Max Rolls */}
                <div>
                  <label className="block text-sm font-medium mb-3">
                    <Filter size={16} className="inline mr-2" />
                    Limit Rolls
                  </label>
                  <select
                    value={exportOptions.maxRolls || ''}
                    onChange={(e) => handleOptionChange('maxRolls', e.target.value ? parseInt(e.target.value) : undefined)}
                    className="w-full p-2 border border-border rounded"
                  >
                    <option value="">All rolls</option>
                    <option value="10">Last 10 rolls</option>
                    <option value="25">Last 25 rolls</option>
                    <option value="50">Last 50 rolls</option>
                    <option value="100">Last 100 rolls</option>
                  </select>
                </div>
              </div>
            </div>

            {/* Preview Panel */}
            <div className="flex-1 flex flex-col">
              {/* Preview Header */}
              <div className="p-4 border-b border-border flex items-center justify-between">
                <div>
                  <h3 className="font-medium">Preview</h3>
                  <p className="text-sm text-muted-foreground">{filteredRolls.length} rolls will be exported</p>
                </div>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => setShowPreview(!showPreview)}
                >
                  <Eye size={16} className="mr-2" />
                  {showPreview ? 'Hide' : 'Show'} Preview
                </Button>
              </div>

              {/* Preview Content */}
              <div className="flex-1 overflow-hidden">
                {showPreview ? (
                  <div className="h-full overflow-y-auto p-4">
                    <pre className="text-sm font-mono whitespace-pre-wrap bg-muted/50  p-4 rounded border">
                      {exportPreview}
                    </pre>
                  </div>
                ) : (
                  <div className="h-full flex items-center justify-center text-muted-foreground">
                    <div className="text-center">
                      <Eye size={48} className="mx-auto mb-4 opacity-50" />
                      <p>Click "Show Preview" to see export format</p>
                    </div>
                  </div>
                )}
              </div>

              {/* Export Actions */}
              <div className="p-4 border-t border-border bg-muted/50 ">
                <div className="flex items-center justify-between">
                  <div>
                    {exportSuccess && (
                      <div className="text-sm text-chart-2 font-medium">
                        {exportSuccess}
                      </div>
                    )}
                  </div>

                  <div className="flex gap-2">
                    <Button
                      variant="outline"
                      onClick={handleCopyToClipboard}
                      disabled={isExporting || filteredRolls.length === 0}
                    >
                      <Copy size={16} className="mr-2" />
                      Copy to Clipboard
                    </Button>

                    <Button
                      onClick={handleDownload}
                      disabled={isExporting || filteredRolls.length === 0}
                    >
                      <Download size={16} className="mr-2" />
                      Download File
                    </Button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </motion.div>
      </div>
    </AnimatePresence>
  )
}

/**
 * Stat Selection Modal
 * Helps users choose which stat to use for ambiguous moves
 */

import React, { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { X, Zap, BookOpen, Eye, Users, Dumbbell, Target } from 'lucide-react'
import { Button, Badge } from '../ui'
import { type Attributes } from '../../models/Character'
import { getStatOptionsForMove, type StatOption, formatStatExplanation } from '../../utils/moveStatDetection'
import { getAttributeModifier } from '../../models/Character'

interface StatSelectionModalProps {
  isOpen: boolean
  onClose: () => void
  onSelect: (stat: keyof Attributes) => void
  moveId: string
  moveName: string
  characterStats: Record<keyof Attributes, number>
  characterClass?: string
}

const STAT_ICONS: Record<keyof Attributes, React.ComponentType<any>> = {
  STR: Dumbbell,
  DEX: Target,
  CON: Users, // Using shield-like icon
  INT: BookOpen,
  WIS: Eye,
  CHA: Zap
}

const STAT_COLORS: Record<keyof Attributes, string> = {
  STR: 'text-destructive bg-destructive/15',
  DEX: 'text-chart-2 bg-chart-2/15',
  CON: 'text-primary bg-primary/10',
  INT: 'text-accent bg-accent/15',
  WIS: 'text-chart-4 bg-chart-4/15',
  CHA: 'text-accent bg-pink-100'
}

export const StatSelectionModal: React.FC<StatSelectionModalProps> = ({
  isOpen,
  onClose,
  onSelect,
  moveId,
  moveName,
  characterStats,
  characterClass
}) => {
  const [selectedStat, setSelectedStat] = useState<keyof Attributes | null>(null)
  const [hoveredStat, setHoveredStat] = useState<keyof Attributes | null>(null)

  const analysis = getStatOptionsForMove(moveId, characterClass)

  useEffect(() => {
    // Auto-select the primary stat or best stat
    if (analysis.primaryStat) {
      setSelectedStat(analysis.primaryStat)
    } else if (analysis.alternatives.length > 0) {
      // Find the best stat based on character values
      const bestOption = analysis.alternatives.reduce((best, current) => {
        const currentValue = characterStats[current.stat]
        const bestValue = characterStats[best.stat]
        return currentValue > bestValue ? current : best
      })
      setSelectedStat(bestOption.stat)
    }
  }, [analysis, characterStats])

  if (!isOpen) return null

  const handleSelect = () => {
    if (selectedStat) {
      onSelect(selectedStat)
    }
  }

  const getStatDisplay = (option: StatOption) => {
    const statValue = characterStats[option.stat]
    const modifier = getAttributeModifier(statValue)
    const Icon = STAT_ICONS[option.stat]

    return (
      <motion.div
        key={option.stat}
        whileHover={{ scale: 1.02 }}
        whileTap={{ scale: 0.98 }}
        className={`p-4 border-2 rounded-lg cursor-pointer transition-all ${
          selectedStat === option.stat
            ? 'border-primary/40 bg-primary/10'
            : 'border-border hover:border-border'
        }`}
        onClick={() => setSelectedStat(option.stat)}
        onMouseEnter={() => setHoveredStat(option.stat)}
        onMouseLeave={() => setHoveredStat(null)}
      >
        <div className="flex items-start justify-between mb-2">
          <div className="flex items-center gap-2">
            <div className={`p-2 rounded ${STAT_COLORS[option.stat]}`}>
              <Icon size={16} />
            </div>
            <div>
              <div className="font-semibold">{option.stat}</div>
              <div className="text-sm text-muted-foreground">
                {statValue} ({modifier >= 0 ? '+' : ''}{modifier})
              </div>
            </div>
          </div>
          <Badge
            variant="outline"
            className={`text-xs ${
              option.confidence === 'high' ? 'border-chart-2/40 text-chart-2' :
              option.confidence === 'medium' ? 'border-yellow-500 text-chart-4' :
              'border-border text-foreground'
            }`}
          >
            {option.confidence}
          </Badge>
        </div>

        <div className="text-sm text-foreground  mb-2">
          {option.reason}
        </div>

        <div className="text-xs text-muted-foreground">
          Examples: {option.examples.join(', ')}
        </div>

        {(hoveredStat === option.stat || selectedStat === option.stat) && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            className="mt-2 pt-2 border-t border-border"
          >
            <div className="text-xs text-primary">
              Roll: 2d6{modifier >= 0 ? '+' : ''}{modifier} = 2d6{modifier >= 0 ? '+' : ''}{modifier}
            </div>
          </motion.div>
        )}
      </motion.div>
    )
  }

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"
        onClick={onClose}
      >
        <motion.div
          initial={{ scale: 0.9, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          exit={{ scale: 0.9, opacity: 0 }}
          className="bg-card rounded-xl shadow-2xl max-w-2xl w-full max-h-[90vh] overflow-y-auto"
          onClick={(e) => e.stopPropagation()}
        >
          {/* Header */}
          <div className="flex items-center justify-between p-6 border-b border-border">
            <div>
              <h2 className="text-xl font-semibold">Choose Your Approach</h2>
              <p className="text-sm text-muted-foreground  mt-1">
                How do you want to use <strong>{moveName}</strong>?
              </p>
            </div>
            <Button
              variant="ghost"
              size="sm"
              onClick={onClose}
              className="p-2"
            >
              <X size={16} />
            </Button>
          </div>

          {/* Content */}
          <div className="p-6">
            <div className="mb-4">
              <div className="text-sm text-muted-foreground  mb-4">
                This move can be approached in different ways. Choose the stat that best represents how your character acts:
              </div>

              <div className="grid gap-3">
                {analysis.alternatives.map(option => getStatDisplay(option))}
              </div>
            </div>

            {/* Actions */}
            <div className="flex items-center justify-between pt-4 border-t border-border">
              <div className="text-xs text-muted-foreground">
                {analysis.isAmbiguous ? 'Multiple approaches possible' : 'Standard approach'} •
                Higher stats give better modifiers
              </div>

              <div className="flex gap-3">
                <Button variant="outline" onClick={onClose}>
                  Cancel
                </Button>
                <Button
                  onClick={handleSelect}
                  disabled={!selectedStat}
                  className="px-6"
                >
                  Roll {selectedStat} {selectedStat && `(${getAttributeModifier(characterStats[selectedStat]) >= 0 ? '+' : ''}${getAttributeModifier(characterStats[selectedStat])})`}
                </Button>
              </div>
            </div>
          </div>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  )
}

