            key={stat}
            rollType="stat"
            stat={stat}
            statValue={value}
            characterId={characterId}
            onRoll={onRoll}
            className="p-3 bg-card border-2 border-border rounded-lg hover:border-primary/30 transition-colors"
          >
            <div className="text-center">
              <div className="text-xs font-medium text-muted-foreground uppercase tracking-wider mb-1">
                {stat}
              </div>
              <div className="text-2xl font-bold text-foreground mb-1">
                {modifier >= 0 ? '+' : ''}{modifier}
              </div>
              <div className="text-xs text-muted-foreground">
                ({value})
              </div>
            </div>
          </RollableElement>
        )
      })}
    </div>
  )
}

const MoveRollPanel: React.FC<{
  characterId: string
  character: any
  quickRolls: QuickRollOption[]
  onRoll?: (result: RollResult) => void
}> = ({ characterId, character, quickRolls, onRoll }) => {
  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
      {quickRolls.filter(roll => roll.type === 'move').map(roll => {
        const statValue = roll.stat ? character?.attributes?.[roll.stat] || 10 : 10

        return (
          <RollableElement
            key={roll.id}
            rollType="move"
            moveId={roll.moveId!}
            moveName={roll.label}
            stat={roll.stat!}
            characterId={characterId}
            onRoll={onRoll}
            className={`p-4 ${roll.color} text-white rounded-lg hover:opacity-90 transition-opacity`}
          >
            <div className="flex items-center gap-3">
              <div className="text-2xl">{roll.icon}</div>
              <div className="flex-1">
                <div className="font-semibold">{roll.label}</div>
                {roll.stat && (
                  <div className="text-sm opacity-90">
                    {roll.stat} • 2d6{statValue ? `${Math.floor((statValue - 10) / 2) >= 0 ? '+' : ''}${Math.floor((statValue - 10) / 2)}` : ''}
                  </div>
                )}
                <div className="text-xs opacity-75 mt-1">
                  {roll.description}
                </div>
              </div>
            </div>
          </RollableElement>
        )
      })}
    </div>
  )
}

const CustomRollPanel: React.FC<{
  characterId: string
  onRoll?: (result: RollResult) => void
}> = ({ characterId, onRoll }) => {
  const [customModifier, setCustomModifier] = useState(0)
  const [customLabel, setCustomLabel] = useState('')
  const { rollCustom } = useDiceStore()

  const handleCustomRoll = async () => {
    if (!customLabel.trim()) return

    try {
      const result = await rollCustom(
        customModifier,
        {
          type: 'custom',
          label: customLabel
        },
        characterId
      )
      onRoll?.(result)
      setCustomLabel('')
      setCustomModifier(0)
    } catch (error) {
      console.error('Custom roll failed:', error)
    }
  }

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
        <div className="sm:col-span-2">
          <label className="block text-sm font-medium text-foreground mb-2">
            Roll Description
          </label>
          <input
            type="text"
            value={customLabel}
            onChange={(e) => setCustomLabel(e.target.value)}
            placeholder="e.g., Athletics check, Investigate, etc."
            className="w-full px-3 py-2 border border-border rounded-md focus:ring-2 focus:ring-primary/40 focus:border-primary/40"
            onKeyDown={(e) => e.key === 'Enter' && handleCustomRoll()}
          />
        </div>
        <div>
          <label className="block text-sm font-medium text-foreground mb-2">
            Modifier
          </label>
          <select
            value={customModifier}
            onChange={(e) => setCustomModifier(parseInt(e.target.value))}
            className="w-full px-3 py-2 border border-border rounded-md focus:ring-2 focus:ring-primary/40 focus:border-primary/40"
          >
            {Array.from({ length: 13 }, (_, i) => i - 6).map(mod => (
              <option key={mod} value={mod}>
                {mod >= 0 ? '+' : ''}{mod}
              </option>
            ))}
          </select>
        </div>
      </div>

      <Button
        onClick={handleCustomRoll}
        disabled={!customLabel.trim()}
        className="w-full"
      >
        <Dices size={16} className="mr-2" />
        Roll 2d6{customModifier !== 0 ? `${customModifier >= 0 ? '+' : ''}${customModifier}` : ''}
      </Button>

      {/* Quick custom roll presets */}
      <div className="border-t pt-4">
        <h4 className="text-sm font-medium text-foreground mb-2">Quick Custom Rolls</h4>
        <div className="grid grid-cols-2 gap-2">
          {[
            { label: 'Advantage (+1)', mod: 1 },
            { label: 'Disadvantage (-1)', mod: -1 },
            { label: 'Blessed (+2)', mod: 2 },
            { label: 'Cursed (-2)', mod: -2 }
          ].map(preset => (
            <button
              key={preset.label}
              onClick={() => {
                setCustomModifier(preset.mod)
                setCustomLabel(preset.label)
              }}
              className="p-2 text-sm bg-muted hover:bg-muted rounded border transition-colors"
            >
              {preset.label}
            </button>
          ))}
        </div>
      </div>
    </div>
  )
}

export const UnifiedRollSystem: React.FC<UnifiedRollSystemProps> = ({
  characterId,
  layout = 'sidebar',
  showHistory = true,
  showQuickRolls = true,
  showCustomRolls = true,
  className = '',
  onClose
}) => {
  const [activeTab, setActiveTab] = useState<'stats' | 'moves' | 'custom'>('moves')
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false)
  const [lastRoll, setLastRoll] = useState<RollResult | null>(null)

  const { getCharacter } = useCharacterStore()
  const character = getCharacter(characterId)

  // Initialize keyboard shortcuts
  useDiceKeyboardShortcuts(characterId)

  // Initialize drag and drop
  const { isDragging, DropZones } = useDragAndDrop(characterId)

  const handleRollResult = (result: RollResult) => {
    setLastRoll(result)
  }

  const tabs = [
    { id: 'stats' as const, label: 'Stats', icon: Target, description: 'Roll ability scores' },
    { id: 'moves' as const, label: 'Moves', icon: Zap, description: 'Roll basic moves' },
    { id: 'custom' as const, label: 'Custom', icon: Plus, description: 'Custom dice rolls' }
  ]

  const layoutClasses = {
    sidebar: 'flex h-screen bg-muted/50',
    modal: 'fixed inset-0 z-50 flex items-center justify-center bg-black/50',
    inline: 'w-full',
    fullscreen: 'fixed inset-0 z-40 bg-card'
  }

  return (
    <div className={`${layoutClasses[layout]} ${className}`}>
      {/* History Sidebar */}
      {showHistory && layout === 'sidebar' && (
        <DiceHistorySidebar
          characterId={characterId}
          collapsed={sidebarCollapsed}
          onToggleCollapse={() => setSidebarCollapsed(!sidebarCollapsed)}
        />
      )}

      {/* Main Content */}
      <div className={`flex-1 flex flex-col ${layout === 'sidebar' ? 'overflow-hidden' : ''}`}>
        {/* Header */}
        <div className="bg-card border-b border-border px-6 py-4">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-2xl font-bold text-foreground flex items-center gap-3">
                <Dices className="text-primary" />
                Dice Rolling System
              </h1>
              <p className="text-sm text-muted-foreground">
                {character ? `Rolling for ${character.name}` : 'Select character to roll'}
              </p>
            </div>

            <div className="flex items-center gap-2">
              <Button variant="ghost" size="sm">
                <Command size={16} className="mr-2" />
                Commands
              </Button>
              <Button variant="ghost" size="sm">
                <Settings size={16} className="mr-2" />
                Settings
              </Button>
            </div>
          </div>
        </div>

        {/* Tab Navigation */}
        <div className="bg-card border-b border-border px-6">
          <nav className="flex space-x-8">
            {tabs.map(tab => {
              const Icon = tab.icon
              const isActive = activeTab === tab.id

              return (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={`
                    py-3 px-1 border-b-2 font-medium text-sm flex items-center gap-2 transition-colors
                    ${isActive
                      ? 'border-primary/40 text-primary'
                      : 'border-transparent text-muted-foreground hover:text-foreground hover:border-border'
                    }
                  `}
                  title={tab.description}
                >
                  <Icon size={16} />
                  {tab.label}
                </button>
              )
            })}
          </nav>
        </div>

        {/* Content Area */}
        <div className="flex-1 p-6 overflow-auto">
          <div className="max-w-4xl mx-auto">
            <AnimatePresence mode="wait">
              <motion.div
                key={activeTab}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                transition={{ duration: 0.2 }}
              >
                {activeTab === 'stats' && character && (
                  <div>
                    <div className="mb-6">
                      <h2 className="text-lg font-semibold text-foreground mb-2">Ability Scores</h2>
                      <p className="text-sm text-muted-foreground">Click any stat to roll 2d6 + modifier</p>
                    </div>
                    <StatRollPanel
                      characterId={characterId}
                      character={character}
                      onRoll={handleRollResult}
                    />
                  </div>
                )}

                {activeTab === 'moves' && character && (
                  <div>
                    <div className="mb-6">
                      <h2 className="text-lg font-semibold text-foreground mb-2">Basic Moves</h2>
                      <p className="text-sm text-muted-foreground">Click any move to roll with the appropriate stat</p>
                    </div>
                    <MoveRollPanel
                      characterId={characterId}
                      character={character}
                      quickRolls={defaultQuickRolls}
                      onRoll={handleRollResult}
                    />
                  </div>
                )}

                {activeTab === 'custom' && (
                  <div>
                    <div className="mb-6">
                      <h2 className="text-lg font-semibold text-foreground mb-2">Custom Rolls</h2>
                      <p className="text-sm text-muted-foreground">Create custom dice rolls with modifiers</p>
                    </div>
                    <CustomRollPanel
                      characterId={characterId}
                      onRoll={handleRollResult}
                    />
                  </div>
                )}
              </motion.div>
            </AnimatePresence>
          </div>
        </div>

        {/* Quick Roll Zones (shown during drag) */}
        <AnimatePresence>
          {isDragging && showQuickRolls && (
            <motion.div
              initial={{ opacity: 0, y: 100 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: 100 }}
              className="fixed bottom-6 left-1/2 transform -translate-x-1/2 z-20"
            >
              <DropZones />
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Roll Display (for non-sidebar layouts) */}
      {layout !== 'sidebar' && showHistory && (
        <div className="w-80 border-l border-border bg-card">
          <RollDisplayManager
            displayMode="persistent"
            maxVisibleRolls={10}
            className="h-full"
          />
        </div>
      )}
    </div>
  )
}

// Wrapper component for easy integration
export const DiceRollingInterface: React.FC<{
  characterId: string
  variant?: 'full' | 'compact' | 'modal'
}> = ({ characterId, variant = 'full' }) => {
  const [showModal, setShowModal] = useState(false)

  if (variant === 'modal') {
    return (
      <>
        <Button onClick={() => setShowModal(true)}>
          <Dices size={16} className="mr-2" />
          Open Dice System
        </Button>

        <AnimatePresence>
          {showModal && (
            <UnifiedRollSystem
              characterId={characterId}
              layout="modal"
              onClose={() => setShowModal(false)}
            />
          )}
        </AnimatePresence>
      </>
    )
  }

  return (
    <UnifiedRollSystem
      characterId={characterId}
      layout={variant === 'compact' ? 'inline' : 'sidebar'}
      showHistory={variant === 'full'}
      showQuickRolls={true}
      showCustomRolls={variant === 'full'}
    />
  )
}

/**
 * Bond Card - Individual bond display and resolution
 * Phase 4A: Essential for Dungeon World bond system
 */

import React, { useState } from 'react'
import { motion } from 'framer-motion'
import { 
  Heart, 
  Edit3, 
  Trash2, 
  Check, 
  X,
  User,
  Award,
  Calendar
} from 'lucide-react'
import { Card, CardContent, Button, Badge } from '../../ui'
import type { Bond } from '../../../models/Character'

interface BondCardProps {
  bond: Bond
  onUpdate: (updates: Partial<Bond>) => void
  onDelete: () => void
  onResolve?: () => void
  isResolved?: boolean
}

export const BondCard: React.FC<BondCardProps> = ({
  bond,
  onUpdate,
  onDelete,
  onResolve,
  isResolved = false
}) => {
  const [isEditing, setIsEditing] = useState(false)
  const [editText, setEditText] = useState(bond.text)
  const [editCharacter, setEditCharacter] = useState(bond.characterName || '')

  const handleSaveEdit = () => {
    if (!editText.trim()) return
    
    onUpdate({
      text: editText.trim(),
      characterName: editCharacter.trim() || undefined
    })
    setIsEditing(false)
  }

  const handleCancelEdit = () => {
    setEditText(bond.text)
    setEditCharacter(bond.characterName || '')
    setIsEditing(false)
  }

  return (
    <Card
      variant={isResolved ? "surface" : "magical"}
      className={`relative ${isResolved ? 'opacity-75' : ''}`}
    >
      <CardContent className="p-6 pt-6">
        {isEditing ? (
          // Edit Mode
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium mb-2">
                Bond Text
              </label>
              <textarea
                value={editText}
                onChange={(e) => setEditText(e.target.value)}
                rows={3}
                className="w-full px-3 py-2 rounded-lg border transition-colors resize-none"
                style={{
                  backgroundColor: 'var(--card)',
                  borderColor: 'var(--primary)',
                  borderOpacity: 0.2,
                  color: 'var(--foreground)'
                }}
                autoFocus
              />
            </div>

            <div>
              <label className="block text-sm font-medium mb-2">
                Character Name (optional)
              </label>
              <input
                type="text"
                value={editCharacter}
                onChange={(e) => setEditCharacter(e.target.value)}
                placeholder="Name of the character this bond is with"
                className="w-full px-3 py-2 rounded-lg border transition-colors"
                style={{
                  backgroundColor: 'var(--card)',
                  borderColor: 'var(--primary)',
                  borderOpacity: 0.2,
                  color: 'var(--foreground)'
                }}
              />
            </div>

            <div className="flex gap-2">
              <Button
                variant="primary"
                size="sm"
                onClick={handleSaveEdit}
                disabled={!editText.trim()}
                className="gap-1"
              >
                <Check size={14} />
                Save
              </Button>
              <Button
                variant="ghost"
                size="sm"
                onClick={handleCancelEdit}
                className="gap-1"
              >
                <X size={14} />
                Cancel
              </Button>
            </div>
          </div>
        ) : (
          // Display Mode
          <div>
            <div className="flex items-start justify-between mb-3">
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 mb-2">
                  {isResolved ? (
                    <Award size={16} className="text-chart-2 flex-shrink-0" />
                  ) : (
                    <Heart size={16} className="text-destructive flex-shrink-0" />
                  )}
                  {bond.characterName && (
                    <Badge variant="secondary" className="gap-1">
                      <User size={10} />
                      {bond.characterName}
                    </Badge>
                  )}
                  {isResolved && (
                    <Badge variant="default" className="gap-1 bg-chart-2/15 text-chart-2">
                      <Award size={10} />
                      +1 XP
                    </Badge>
                  )}
                </div>
                
                <p 
                  className={`text-sm leading-relaxed ${isResolved ? 'line-through' : ''}`}
                  style={{ color: isResolved ? 'var(--muted-foreground)' : 'var(--foreground)' }}
                >
                  {bond.text}
                </p>
              </div>
              
              <div className="flex items-center gap-1 ml-4">
                {!isResolved && onResolve && (
                  <Button
                    variant="ghost"
                    size="xs"
                    onClick={onResolve}
                    title="Resolve bond (+1 XP)"
                    className="gap-1 text-chart-2 hover:text-chart-2"
                  >
                    <Check size={14} />
                    Resolve
                  </Button>
                )}
                
                <Button
                  variant="ghost"
                  size="xs"
                  onClick={() => setIsEditing(true)}
                  title="Edit bond"
                >
                  <Edit3 size={14} />
                </Button>
                
                <Button
                  variant="ghost"
                  size="xs"
                  onClick={onDelete}
                  title="Delete bond"
                  className="text-destructive hover:text-destructive"
                >
                  <Trash2 size={14} />
                </Button>
              </div>
            </div>

            {/* Bond Resolution Info */}
            {!isResolved && (
              <div className="mt-3 p-3 bg-primary/10 rounded-lg">
                <p className="text-xs text-primary">
                  <strong>How to resolve:</strong> When this bond is fulfilled through roleplay, 
                  click "Resolve" to gain 1 XP and create a new bond or strengthen an existing one.
                </p>
              </div>
            )}
          </div>
        )}
      </CardContent>
    </Card>
  )
}

/**
 * Bond Tracker - Character relationship management and XP integration
 * Phase 4A: Essential for Dungeon World XP system
 */

import React, { useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { 
  Heart, 
  Plus, 
  Edit3, 
  Trash2, 
  Check,
  Star,
  Users,
  Award
} from 'lucide-react'
import { Card, CardContent, Button, Badge } from '../../ui'
import { BondCard } from './BondCard'
import { useCharacterStore } from '../../../stores'
import type { Bond } from '../../../models/Character'

interface BondTrackerProps {
  characterId?: string
  className?: string
}

export const BondTracker: React.FC<BondTrackerProps> = ({ 
  characterId,
  className = '' 
}) => {
  const { getActiveCharacter, updateCharacter, addXP } = useCharacterStore()
  const [isCreating, setIsCreating] = useState(false)
  const [newBondText, setNewBondText] = useState('')
  const [newBondCharacter, setNewBondCharacter] = useState('')

  // Get character (use active if not specified)
  const character = characterId 
    ? useCharacterStore(state => state.getCharacter(characterId))
    : getActiveCharacter()

  if (!character) {
    return (
      <Card variant="surface" className={className}>
        <CardContent className="p-6 pt-6">
          <div className="text-center py-8">
            <Users 
              size={48} 
              className="mx-auto mb-4 opacity-50 text-muted-foreground" />
            <h3 className="text-lg font-medium mb-2">No Character Selected</h3>
            <p className="text-muted-foreground">
              Select a character to manage their bonds.
            </p>
          </div>
        </CardContent>
      </Card>
    )
  }

  const bonds = character.bonds || []
  const resolvedBonds = bonds.filter(bond => bond.resolved)
  const activeBonds = bonds.filter(bond => !bond.resolved)

  const createBond = () => {
    if (!newBondText.trim()) return

    const newBond: Bond = {
      id: `bond-${Date.now()}-${Math.random().toString(36).slice(2, 11)}`,
      text: newBondText.trim(),
      characterName: newBondCharacter.trim() || undefined,
      resolved: false
    }

    const updatedBonds = [...bonds, newBond]
    updateCharacter(character.id, { bonds: updatedBonds })
    
    setNewBondText('')
    setNewBondCharacter('')
    setIsCreating(false)
  }

  const updateBond = (bondId: string, updates: Partial<Bond>) => {
    const updatedBonds = bonds.map(bond => 
      bond.id === bondId ? { ...bond, ...updates } : bond
    )
    updateCharacter(character.id, { bonds: updatedBonds })
  }

  const deleteBond = (bondId: string) => {
    const updatedBonds = bonds.filter(bond => bond.id !== bondId)
    updateCharacter(character.id, { bonds: updatedBonds })
  }

  const resolveBond = (bondId: string) => {
    // Mark bond as resolved
    updateBond(bondId, { resolved: true })
    
    // Award XP for bond resolution (official Dungeon World rule)
    addXP(character.id, 1, 'bond_resolution', 'Resolved a bond with another character')
  }

  return (
    <div className={`space-y-6 ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-display mb-2">Character Bonds</h2>
          <p className="text-muted-foreground">
            Manage relationships and earn XP through bond resolution
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Badge variant="default" className="gap-1">
            <Heart size={12} />
            {activeBonds.length} Active
          </Badge>
          <Badge variant="secondary" className="gap-1">
            <Award size={12} />
            {resolvedBonds.length} Resolved
          </Badge>
        </div>
      </div>

      {/* Statistics */}
      <Card variant="magical">
        <CardContent className="p-6">
          <div className="grid grid-cols-3 gap-4 text-center">
            <div>
              <div className="text-2xl font-bold mb-1">{bonds.length}</div>
              <div className="text-sm text-muted-foreground">
                Total Bonds
              </div>
            </div>
            <div>
              <div className="text-2xl font-bold mb-1 text-chart-2">{resolvedBonds.length}</div>
              <div className="text-sm text-muted-foreground">
                Resolved (+XP)
              </div>
            </div>
            <div>
              <div className="text-2xl font-bold mb-1 text-primary">{activeBonds.length}</div>
              <div className="text-sm text-muted-foreground">
                Active Bonds
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Create Bond Button */}
      <Card variant="surface">
        <CardContent className="p-4">
          <Button
            variant="primary"
            size="sm"
            onClick={() => setIsCreating(true)}
            className="w-full gap-2"
          >
            <Plus size={16} />
            Add New Bond
          </Button>
        </CardContent>
      </Card>

      {/* Create Bond Form */}
      <AnimatePresence>
        {isCreating && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: 0.3 }}
          >
            <Card variant="magical">
              <CardContent className="p-6">
                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium mb-2">
                      Bond Text
                    </label>
                    <textarea
                      value={newBondText}
                      onChange={(e) => setNewBondText(e.target.value)}
                      placeholder="e.g., I will prove my worth to Theron by..."
                      rows={3}
                      className="w-full px-3 py-2 rounded-lg border transition-colors resize-none"
                      style={{
                        backgroundColor: 'var(--card)',
                        borderColor: 'var(--primary)',
                        borderOpacity: 0.2,
                        color: 'var(--foreground)'
                      }}
                      autoFocus
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium mb-2">
                      Character Name (optional)
                    </label>
                    <input
                      type="text"
                      value={newBondCharacter}
                      onChange={(e) => setNewBondCharacter(e.target.value)}
                      placeholder="Name of the character this bond is with"
                      className="w-full px-3 py-2 rounded-lg border transition-colors"
                      style={{
                        backgroundColor: 'var(--card)',
                        borderColor: 'var(--primary)',
                        borderOpacity: 0.2,
                        color: 'var(--foreground)'
                      }}
                    />
                  </div>

                  <div className="flex gap-2">
                    <Button
                      variant="primary"
                      size="sm"
                      onClick={createBond}
                      disabled={!newBondText.trim()}
                    >
                      Create Bond
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => {
                        setIsCreating(false)
                        setNewBondText('')
                        setNewBondCharacter('')
                      }}
                    >
                      Cancel
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Active Bonds */}
      {activeBonds.length > 0 && (
        <div className="space-y-3">
          <h3 className="text-lg font-medium flex items-center gap-2">
            <Heart size={20} className="text-destructive" />
            Active Bonds
          </h3>
          {activeBonds.map((bond, index) => (
            <motion.div
              key={`${bond.id}-${index}`}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.3, delay: index * 0.1 }}
            >
              <BondCard
                bond={bond}
                onUpdate={(updates) => updateBond(bond.id, updates)}
                onDelete={() => deleteBond(bond.id)}
                onResolve={() => resolveBond(bond.id)}
              />
            </motion.div>
          ))}
        </div>
      )}

      {/* Resolved Bonds */}
      {resolvedBonds.length > 0 && (
        <div className="space-y-3">
          <h3 className="text-lg font-medium flex items-center gap-2">
            <Award size={20} className="text-chart-2" />
            Resolved Bonds (+{resolvedBonds.length} XP)
          </h3>
          {resolvedBonds.map((bond, index) => (
            <motion.div
              key={`${bond.id}-${index}`}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.3, delay: index * 0.05 }}
            >
              <BondCard
                bond={bond}
                onUpdate={(updates) => updateBond(bond.id, updates)}
                onDelete={() => deleteBond(bond.id)}
                isResolved
              />
            </motion.div>
          ))}
        </div>
      )}

      {/* Empty State */}
      {bonds.length === 0 && (
        <Card variant="surface">
          <CardContent className="p-6 pt-6">
            <div className="text-center py-8">
              <Heart 
                size={48} 
                className="mx-auto mb-4 opacity-50 text-muted-foreground" />
              <h3 className="text-lg font-medium mb-2">No Bonds Yet</h3>
              <p className="text-muted-foreground">
                Create bonds with other characters to earn XP through roleplay and relationships!
              </p>
              <div className="mt-4 p-4 bg-primary/10 rounded-lg">
                <p className="text-sm text-primary">
                  <strong>Dungeon World Rule:</strong> When you resolve a bond, mark XP and write a new bond or strengthen an existing one.
                </p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  )
}

/**
 * Campaign Panel - Main container for campaign management
 * Phase 4B: Campaign Management - GM Tools for long-term campaign continuity
 */

import React, { useState } from 'react'
import { motion } from 'framer-motion'
import { 
  Scroll, 
  CalendarClock, 
  BookOpenText, 
  Users, 
  MapPin,
  LayoutPanelLeft,
  Plus,
  Search,
  Filter
} from 'lucide-react'
import { Card, CardContent, Button, Badge } from '../ui'
import { CampaignOverview } from './Campaign/CampaignOverview'
import { SessionHistory } from './Campaign/SessionHistory'
import { CampaignJournal } from './Campaign/CampaignJournal'
import { NPCManager } from './Campaign/NPCManager'
import { LocationTracker } from './Campaign/LocationTracker'
import { CreateCampaignModal } from './Campaign/CreateCampaignModal'
import { CampaignSelector } from './Campaign/CampaignSelector'
import { useCampaignStore } from '../../stores/campaignStore'

type CampaignTab = 'overview' | 'sessions' | 'journal' | 'npcs' | 'locations'

interface CampaignPanelProps {
  className?: string
  initialTab?: CampaignTab
}

export const CampaignPanel: React.FC<CampaignPanelProps> = ({ 
  className = '',
  initialTab = 'overview'
}) => {
  const [activeTab, setActiveTab] = useState<CampaignTab>(initialTab)
  const [searchQuery, setSearchQuery] = useState('')
  const [showCreateModal, setShowCreateModal] = useState(false)
  
  const activeCampaign = useCampaignStore(state => state.getActiveCampaign())
  const campaigns = useCampaignStore(state => state.campaigns)
  const setActiveCampaign = useCampaignStore(state => state.setActiveCampaign)

  const tabs = [
    { 
      id: 'overview' as const, 
      label: 'Overview', 
      icon: LayoutPanelLeft,
      description: 'Campaign statistics and quick actions'
    },
    { 
      id: 'sessions' as const, 
      label: 'Sessions', 
      icon: CalendarClock,
      description: 'Session history and planning'
    },
    { 
      id: 'journal' as const, 
      label: 'Journal', 
      icon: BookOpenText,
      description: 'Campaign notes and important events'
    },
    { 
      id: 'npcs' as const, 
      label: 'NPCs', 
      icon: Users,
      description: 'Character relationships and tracking'
    },
    { 
      id: 'locations' as const, 
      label: 'Locations', 
      icon: MapPin,
      description: 'World building and exploration'
    }
  ]

  const renderContent = () => {
    if (!activeCampaign) {
      return (
        <Card variant="surface">
          <CardContent className="p-6">
            <div className="text-center space-y-6">
              <div 
                className="w-16 h-16 mx-auto rounded-full flex items-center justify-center bg-primary/20">
                <Scroll className="text-primary" 
                  size={32} />
              </div>
              <div>
                <h3 className="text-xl font-display mb-2">No Campaign Selected</h3>
                <p className="text-muted-foreground">
                  Select an existing campaign or create a new one to get started.
                </p>
              </div>
              <div className="flex flex-col sm:flex-row gap-3 justify-center items-center">
                {campaigns.length > 0 && (
                  <CampaignSelector 
                    onCampaignSelect={setActiveCampaign}
                  />
                )}
                <Button 
                  variant="primary" 
                  size="md" 
                  className="gap-2"
                  onClick={() => setShowCreateModal(true)}
                >
                  <Plus size={16} />
                  Create Campaign
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>
      )
    }

    switch (activeTab) {
      case 'overview':
        return <CampaignOverview campaignId={activeCampaign.id} />
      case 'sessions':
        return <SessionHistory campaignId={activeCampaign.id} searchQuery={searchQuery} />
      case 'journal':
        return <CampaignJournal campaignId={activeCampaign.id} searchQuery={searchQuery} />
      case 'npcs':
        return <NPCManager campaignId={activeCampaign.id} searchQuery={searchQuery} />
      case 'locations':
        return <LocationTracker campaignId={activeCampaign.id} searchQuery={searchQuery} />
      default:
        return <CampaignOverview campaignId={activeCampaign.id} />
    }
  }

  const handleCampaignCreated = (campaignId: string) => {
    // Automatically select the newly created campaign
    setActiveCampaign(campaignId)
    // Switch to overview tab to show the new campaign
    setActiveTab('overview')
  }

  return (
    <div className={`space-y-6 ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-display mb-2">Campaign Management</h2>
          <p className="text-muted-foreground">
            {activeCampaign ? `Managing: ${activeCampaign.name}` : 'GM tools for long-term campaign continuity'}
          </p>
        </div>
        <Badge variant="default" className="magical-glow">
          Phase 4B ✨
        </Badge>
      </div>

      {activeCampaign && (
        <>
          {/* Tab Navigation */}
          <Card variant="surface">
            <CardContent className="p-4">
              <div className="flex flex-wrap gap-2">
                {tabs.map((tab) => {
                  const Icon = tab.icon
                  const isActive = activeTab === tab.id
                  
                  return (
                    <Button
                      key={tab.id}
                      variant={isActive ? 'primary' : 'ghost'}
                      size="sm"
                      onClick={() => setActiveTab(tab.id)}
                      className="relative flex-1 min-w-0"
                      title={tab.description}
                    >
                      <Icon size={16} />
                      <span className="truncate">{tab.label}</span>
                      {isActive && (
                        <motion.div
                          className="absolute bottom-0 left-0 right-0 h-0.5 bg-primary"
                          
                          layoutId="campaignTab"
                          transition={{ type: "spring", stiffness: 300, damping: 30 }} />
                      )}
                    </Button>
                  )
                })}
              </div>
            </CardContent>
          </Card>

          {/* Search Bar (for applicable tabs) */}
          {(activeTab === 'sessions' || activeTab === 'journal' || activeTab === 'npcs' || activeTab === 'locations') && (
            <Card variant="surface">
              <CardContent className="p-4">
                <div className="relative">
                  <Search 
                    size={16} 
                    className="absolute left-3 top-1/2 transform -translate-y-1/2 text-muted-foreground" />
                  <input
                    type="text"
                    placeholder={`Search ${activeTab}...`}
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="w-full pl-10 pr-4 py-2 rounded-lg border transition-colors"
                    style={{
                      backgroundColor: 'var(--card)',
                      borderColor: 'var(--primary)',
                      borderOpacity: 0.2,
                      color: 'var(--foreground)'
                    }}
                  />
                </div>
              </CardContent>
            </Card>
          )}
        </>
      )}

      {/* Content */}
      <motion.div
        key={activeTab}
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        exit={{ opacity: 0, y: -20 }}
        transition={{ duration: 0.3 }}
      >
        {renderContent()}
      </motion.div>

      {/* Create Campaign Modal */}
      <CreateCampaignModal
        isOpen={showCreateModal}
        onClose={() => setShowCreateModal(false)}
        onCampaignCreated={handleCampaignCreated}
      />
    </div>
  )
}

/**
 * Campaign Journal - Rich text journal for important campaign events
 */

import React, { useState, useMemo } from 'react'
import { motion } from 'framer-motion'
import {
  BookOpen,
  Plus,
  Edit,
  Trash2,
  Star,
  Tag,
  Calendar,
  Link,
  Search
} from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle, Button, Badge } from '../../ui'
import { useCampaignStore } from '../../../stores/campaignStore'
import { formatDateRelative, JournalSortBy } from '../../../campaignManagementMockData'
import { JournalEntryModal } from './JournalEntryModal'
import type { JournalEntry } from '../../../models/Campaign'

interface CampaignJournalProps {
  campaignId: string
  searchQuery?: string
}

interface JournalEntryCardProps {
  entry: JournalEntry
  onEdit: (entry: JournalEntry) => void
  onDelete: (entryId: string) => void
}

const JournalEntryCard: React.FC<JournalEntryCardProps> = ({ entry, onEdit, onDelete }) => {
  const [expanded, setExpanded] = useState(false)

  return (
    <Card 
      variant={entry.isImportant ? "magical" : "surface"} 
      className="campaign-card campaign-card-hover"
    >
      <CardContent>
        <div className="space-y-4">
          {/* Header */}
          <div className="flex items-start justify-between">
            <div className="flex-1">
              <div className="flex items-center gap-3 mb-2">
                <h3 className="font-display text-lg font-semibold">
