          </div>

          {/* Content Preview */}
          <div>
            <p 
              
              className={expanded ? '' : 'line-clamp-3'}>
              {entry.content}
            </p>
            {entry.content.length > 200 && (
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setExpanded(!expanded)}
