}

export const CampaignJournal: React.FC<CampaignJournalProps> = ({
  campaignId,
  searchQuery = ''
}) => {
  const [sortBy, setSortBy] = useState<JournalSortBy>(JournalSortBy.DATE)
  const [filterByImportance, setFilterByImportance] = useState<boolean | null>(null)
  const [filterByTag, setFilterByTag] = useState<string>('')
  const [isModalOpen, setIsModalOpen] = useState(false)
  const [editingEntry, setEditingEntry] = useState<JournalEntry | undefined>()
  
  const campaign = useCampaignStore(state => state.getCampaign(campaignId))
  const addJournalEntry = useCampaignStore(state => state.addJournalEntry)
  const updateJournalEntry = useCampaignStore(state => state.updateJournalEntry)
  const deleteJournalEntry = useCampaignStore(state => state.deleteJournalEntry)

  const allTags = useMemo(() => {
    if (!campaign) return []
    const tagSet = new Set<string>()
    campaign.journal.forEach(entry => {
      entry.tags.forEach(tag => tagSet.add(tag))
    })
    return Array.from(tagSet).sort()
  }, [campaign])

  const filteredAndSortedEntries = useMemo(() => {
    if (!campaign) return []

    let entries = [...campaign.journal]

    // Filter by search query
    if (searchQuery) {
      const query = searchQuery.toLowerCase()
      entries = entries.filter(entry =>
        entry.title.toLowerCase().includes(query) ||
        entry.content.toLowerCase().includes(query) ||
        entry.tags.some(tag => tag.toLowerCase().includes(query))
      )
    }

    // Filter by importance
    if (filterByImportance !== null) {
      entries = entries.filter(entry => entry.isImportant === filterByImportance)
    }

    // Filter by tag
    if (filterByTag) {
      entries = entries.filter(entry => entry.tags.includes(filterByTag))
    }

    // Sort entries
    entries.sort((a, b) => {
      switch (sortBy) {
        case JournalSortBy.DATE:
          return b.date.getTime() - a.date.getTime()
        case JournalSortBy.IMPORTANCE:
          if (a.isImportant && !b.isImportant) return -1
          if (!a.isImportant && b.isImportant) return 1
          return b.date.getTime() - a.date.getTime()
        case JournalSortBy.TITLE:
          return a.title.localeCompare(b.title)
        case JournalSortBy.TAGS:
          return a.tags.length - b.tags.length
        default:
          return 0
      }
    })

    return entries
  }, [campaign, searchQuery, sortBy, filterByImportance, filterByTag])

  const handleEditEntry = (entry: JournalEntry) => {
    setEditingEntry(entry)
    setIsModalOpen(true)
  }

  const handleDeleteEntry = (entryId: string) => {
    if (confirm('Are you sure you want to delete this journal entry?')) {
      deleteJournalEntry(campaignId, entryId)
    }
  }

  const handleCreateEntry = () => {
    setEditingEntry(undefined)
    setIsModalOpen(true)
  }

  const handleModalClose = () => {
    setIsModalOpen(false)
    setEditingEntry(undefined)
  }

  const handleEntrySaved = (entryId: string) => {
    // Entry saved successfully - modal will close automatically
    console.log('Journal entry saved:', entryId)
  }

  if (!campaign) {
    return (
      <Card variant="surface">
        <CardContent>
          <div className="text-center">
            <p className="text-muted-foreground">
              Campaign not found
            </p>
          </div>
        </CardContent>
      </Card>
    )
  }

  return (
    <>
      <div className="space-y-6">
        {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-xl font-display">Campaign Journal</h3>
          <p className="text-muted-foreground">
            {filteredAndSortedEntries.length} of {campaign.journal.length} entries
          </p>
        </div>
        <Button 
          variant="primary" 
          size="sm" 
          className="gap-2"
          onClick={handleCreateEntry}
        >
          <Plus size={16} />
          Add Entry
        </Button>
      </div>

      {/* Filters */}
      <Card variant="surface">
        <CardContent>
          <div className="flex flex-wrap items-center gap-4">
            <select
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value as JournalSortBy)}
              className="px-3 py-2 rounded-lg border text-sm"
              style={{
                backgroundColor: 'var(--card)',
                borderColor: 'var(--primary)',
                color: 'var(--foreground)'
              }}
            >
              <option value={JournalSortBy.DATE}>Sort by Date</option>
              <option value={JournalSortBy.IMPORTANCE}>Sort by Importance</option>
              <option value={JournalSortBy.TITLE}>Sort by Title</option>
              <option value={JournalSortBy.TAGS}>Sort by Tags</option>
            </select>

            <select
              value={filterByImportance === null ? '' : filterByImportance.toString()}
              onChange={(e) => {
                const value = e.target.value
                setFilterByImportance(value === '' ? null : value === 'true')
              }}
              className="px-3 py-2 rounded-lg border text-sm"
              style={{
                backgroundColor: 'var(--card)',
                borderColor: 'var(--primary)',
                color: 'var(--foreground)'
              }}
            >
              <option value="">All Entries</option>
              <option value="true">Important Only</option>
              <option value="false">Regular Only</option>
            </select>

            {allTags.length > 0 && (
              <select
                value={filterByTag}
                onChange={(e) => setFilterByTag(e.target.value)}
                className="px-3 py-2 rounded-lg border text-sm"
                style={{
                  backgroundColor: 'var(--card)',
                  borderColor: 'var(--primary)',
                  color: 'var(--foreground)'
                }}
              >
                <option value="">All Tags</option>
                {allTags.map(tag => (
                  <option key={tag} value={tag}>#{tag}</option>
                ))}
              </select>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Journal Entries */}
      {filteredAndSortedEntries.length === 0 ? (
        <Card variant="surface" className="campaign-empty-state">
          <CardContent>
            <div className="text-center space-y-4">
              <BookOpen size={48} className='mx-auto text-muted-foreground' />
              <div>
                <h4 className="font-medium mb-2">
                  {campaign.journal.length === 0 ? 'No journal entries' : 'No entries match your filters'}
                </h4>
                <p className="text-muted-foreground">
                  {campaign.journal.length === 0 
                    ? 'Start writing your campaign story and important events'
                    : 'Try adjusting your search terms or filters'
                  }
                </p>
              </div>
              {campaign.journal.length === 0 && (
                <Button 
                  variant="primary" 
                  size="md" 
                  className="gap-2"
                  onClick={handleCreateEntry}
                >
                  <Plus size={16} />
                  Write First Entry
                </Button>
              )}
            </div>
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-4">
          {filteredAndSortedEntries.map((entry, index) => (
            <motion.div
              key={entry.id}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.3, delay: index * 0.1 }}
            >
              <JournalEntryCard
                entry={entry}
                onEdit={handleEditEntry}
                onDelete={handleDeleteEntry}
              />
            </motion.div>
          ))}
        </div>
      )}
      </div>

      {/* Journal Entry Modal */}
      <JournalEntryModal
        isOpen={isModalOpen}
        onClose={handleModalClose}
        campaignId={campaignId}
        entry={editingEntry}
        onSaved={handleEntrySaved}
      />
    </>
  )
}

/**
 * Create Campaign Modal - Modal dialog for creating new campaigns
 */

import React, { useState } from 'react'
import * as Dialog from '@radix-ui/react-dialog'
import { X, Scroll, Plus } from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle, Button, Input, Textarea } from '../../ui'
import { useCampaignStore } from '../../../stores/campaignStore'

interface CreateCampaignModalProps {
  isOpen: boolean
  onClose: () => void
  onCampaignCreated?: (campaignId: string) => void
}

interface CampaignFormData {
  name: string
  description: string
}

export const CreateCampaignModal: React.FC<CreateCampaignModalProps> = ({
  isOpen,
  onClose,
  onCampaignCreated
}) => {
  const [formData, setFormData] = useState<CampaignFormData>({
    name: '',
    description: ''
  })
  const [errors, setErrors] = useState<Partial<CampaignFormData>>({})
  const [isSubmitting, setIsSubmitting] = useState(false)

  const createCampaign = useCampaignStore(state => state.createCampaign)
  const campaigns = useCampaignStore(state => state.campaigns)

  const validateForm = (): boolean => {
    const newErrors: Partial<CampaignFormData> = {}

    // Validate name
    if (!formData.name.trim()) {
      newErrors.name = 'Campaign name is required'
    } else if (formData.name.trim().length < 2) {
      newErrors.name = 'Campaign name must be at least 2 characters'
    } else if (campaigns.some(c => c.name.toLowerCase() === formData.name.trim().toLowerCase())) {
      newErrors.name = 'A campaign with this name already exists'
    }

    // Description is optional, but if provided should have minimum length
    if (formData.description.trim() && formData.description.trim().length < 10) {
      newErrors.description = 'Description should be at least 10 characters if provided'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    
    if (!validateForm()) {
      return
    }

    setIsSubmitting(true)

    try {
      const campaign = createCampaign(
        formData.name.trim(),
        formData.description.trim() || undefined
      )

      // Reset form
      setFormData({ name: '', description: '' })
      setErrors({})
      
      // Notify parent component
      onCampaignCreated?.(campaign.id)
      
      // Close modal
      onClose()
    } catch (error) {
      console.error('Failed to create campaign:', error)
      setErrors({ name: 'Failed to create campaign. Please try again.' })
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleInputChange = (field: keyof CampaignFormData, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }))
    
    // Clear error when user starts typing
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: undefined }))
    }
  }

  const handleClose = () => {
    if (!isSubmitting) {
      setFormData({ name: '', description: '' })
      setErrors({})
      onClose()
    }
  }

  return (
    <Dialog.Root open={isOpen} onOpenChange={handleClose}>
      <Dialog.Portal>
        <Dialog.Overlay 
          className="fixed inset-0 z-50 bg-black/50 backdrop-blur-sm"
          style={{ backgroundColor: 'rgba(0, 0, 0, 0.5)' }}
        />
        <Dialog.Content className="fixed left-1/2 top-1/2 z-50 w-full max-w-md -translate-x-1/2 -translate-y-1/2 p-4">
          <Card variant="magical">
            <CardHeader>
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div 
                    className="w-10 h-10 rounded-lg flex items-center justify-center bg-primary/20">
                    <Scroll className="text-primary" 
                      size={20} />
                  </div>
                  <CardTitle>Create New Campaign</CardTitle>
                </div>
                <Dialog.Close asChild>
                  <Button 
                    variant="ghost" 
                    size="sm"
                    disabled={isSubmitting}
                  >
                    <X size={16} />
                  </Button>
                </Dialog.Close>
              </div>
            </CardHeader>
            
            <CardContent>
              <form onSubmit={handleSubmit} className="space-y-6">
                <div>
                  <Input
                    label="Campaign Name"
                    placeholder="Enter campaign name..."
                    value={formData.name}
                    onChange={(e) => handleInputChange('name', e.target.value)}
                    error={errors.name}
                    disabled={isSubmitting}
                    required
                    maxLength={100}
                  />
                </div>

                <div>
                  <Textarea
                    label="Description (Optional)"
                    placeholder="Describe your campaign world, themes, or goals..."
                    value={formData.description}
                    onChange={(e) => handleInputChange('description', e.target.value)}
                    error={errors.description}
                    disabled={isSubmitting}
                    rows={4}
                    maxLength={500}
                  />
                </div>

                <div className="flex items-center justify-end gap-3 pt-4">
                  <Button
                    type="button"
                    variant="outline"
                    onClick={handleClose}
                    disabled={isSubmitting}
                  >
                    Cancel
                  </Button>
                  <Button
                    type="submit"
                    variant="primary"
                    disabled={isSubmitting || !formData.name.trim()}
                    className="gap-2"
                  >
                    {isSubmitting ? (
                      <>
                        <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                        Creating...
                      </>
                    ) : (
                      <>
                        <Plus size={16} />
                        Create Campaign
                      </>
                    )}
                  </Button>
                </div>
              </form>
            </CardContent>
          </Card>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  )
}

/**
 * Journal Entry Modal - Modal dialog for creating and editing journal entries
 */

import React, { useState, useEffect } from 'react'
import * as Dialog from '@radix-ui/react-dialog'
import { X, BookOpen, Plus, Tag as TagIcon, Star } from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle, Button, Badge } from '../../ui'
import { Input } from '../../ui/Input'
import { Textarea } from '../../ui/Textarea'
import { useCampaignStore } from '../../../stores/campaignStore'
import type { JournalEntry } from '../../../models/Campaign'

interface JournalEntryModalProps {
  isOpen: boolean
  onClose: () => void
  campaignId: string
  entry?: JournalEntry // If provided, we're editing; otherwise creating
  onSaved?: (entryId: string) => void
}

interface JournalEntryFormData {
  title: string
  content: string
  tags: string[]
  isImportant: boolean
  relatedSessionId?: string
  relatedNpcId?: string
  relatedLocationId?: string
}

export const JournalEntryModal: React.FC<JournalEntryModalProps> = ({
  isOpen,
  onClose,
  campaignId,
  entry,
  onSaved
}) => {
  const [formData, setFormData] = useState<JournalEntryFormData>({
    title: '',
    content: '',
    tags: [],
    isImportant: false
  })
  const [errors, setErrors] = useState<Partial<JournalEntryFormData>>({})
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [newTag, setNewTag] = useState('')

  const addJournalEntry = useCampaignStore(state => state.addJournalEntry)
  const updateJournalEntry = useCampaignStore(state => state.updateJournalEntry)

  // Initialize form data when modal opens or entry changes
  useEffect(() => {
    if (entry) {
      setFormData({
        title: entry.title,
        content: entry.content,
        tags: [...entry.tags],
        isImportant: entry.isImportant,
        relatedSessionId: entry.relatedSessionId,
        relatedNpcId: entry.relatedNpcId,
        relatedLocationId: entry.relatedLocationId
      })
    } else {
      setFormData({
        title: '',
        content: '',
        tags: [],
        isImportant: false
      })
    }
    setErrors({})
    setNewTag('')
  }, [entry, isOpen])

  const validateForm = (): boolean => {
    const newErrors: Partial<JournalEntryFormData> = {}

    // Validate title
    if (!formData.title.trim()) {
      newErrors.title = 'Title is required'
    } else if (formData.title.trim().length < 3) {
      newErrors.title = 'Title must be at least 3 characters'
    }

    // Validate content
    if (!formData.content.trim()) {
      newErrors.content = 'Content is required'
    } else if (formData.content.trim().length < 10) {
      newErrors.content = 'Content must be at least 10 characters'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!validateForm()) {
      return
    }

    setIsSubmitting(true)

    try {
      const trimmedData = {
        ...formData,
        title: formData.title.trim(),
        content: formData.content.trim()
      }

      let entryId: string

      if (entry) {
        // Editing existing entry
        updateJournalEntry(campaignId, entry.id, trimmedData)
        entryId = entry.id
      } else {
        // Creating new entry
        entryId = crypto.randomUUID()
        const newEntry: JournalEntry = {
          id: entryId,
          date: new Date(),
          ...trimmedData
        }
        addJournalEntry(campaignId, newEntry)
      }

      onSaved?.(entryId)
      onClose()
    } catch (error) {
      console.error('Error saving journal entry:', error)
      // In a real app, you'd show an error toast or message
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleAddTag = () => {
    const tag = newTag.trim().toLowerCase()
    if (tag && !formData.tags.includes(tag) && formData.tags.length < 10) {
      setFormData(prev => ({
        ...prev,
        tags: [...prev.tags, tag]
      }))
      setNewTag('')
    }
  }

  const handleRemoveTag = (tagToRemove: string) => {
    setFormData(prev => ({
      ...prev,
      tags: prev.tags.filter(tag => tag !== tagToRemove)
    }))
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && newTag.trim()) {
      e.preventDefault()
      handleAddTag()
    }
  }

  return (
    <Dialog.Root open={isOpen} onOpenChange={onClose}>
      <Dialog.Portal>
        <Dialog.Overlay className="fixed inset-0 z-50 bg-black/80 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0" />
        <Dialog.Content className="fixed left-1/2 top-1/2 z-50 w-full max-w-2xl -translate-x-1/2 -translate-y-1/2 border shadow-lg duration-200 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[state=closed]:slide-out-to-left-1/2 data-[state=closed]:slide-out-to-top-[48%] data-[state=open]:slide-in-from-left-1/2 data-[state=open]:slide-in-from-top-[48%] rounded-lg max-h-[90vh] overflow-y-auto">
          <Card variant="surface">
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-4">
              <div className="flex items-center gap-3">
                <BookOpen className="h-5 w-5 text-primary" />
                <CardTitle className="text-xl">
                  {entry ? 'Edit Journal Entry' : 'New Journal Entry'}
                </CardTitle>
              </div>
              <Dialog.Close asChild>
                <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
                  <X className="h-4 w-4" />
                </Button>
              </Dialog.Close>
            </CardHeader>

            <CardContent>
              <form onSubmit={handleSubmit} className="space-y-6">
                {/* Title Field */}
                <div className="space-y-2">
                  <div className="flex items-center justify-between">
                    <label className="text-sm font-medium">
                      Title
                    </label>
                    <button
                      type="button"
                      onClick={() => setFormData(prev => ({ ...prev, isImportant: !prev.isImportant }))}
                      className={`flex items-center gap-1 px-2 py-1 rounded text-xs transition-colors ${
                        formData.isImportant
                          ? 'bg-chart-4/120/20 text-chart-4 border border-yellow-500/30'
                          : 'bg-muted/500/20 text-muted-foreground border border-border/30'
                      }`}
                    >
                      <Star size={12} className={formData.isImportant ? 'fill-current' : ''} />
                      {formData.isImportant ? 'Important' : 'Mark Important'}
                    </button>
                  </div>
                  <Input
                    value={formData.title}
                    onChange={(e) => setFormData(prev => ({ ...prev, title: e.target.value }))}
                    placeholder="Enter a descriptive title..."
                    className={errors.title ? 'border-destructive/40' : ''}
                  />
                  {errors.title && (
                    <p className="text-destructive text-sm">{errors.title}</p>
                  )}
                </div>

                {/* Content Field */}
                <div className="space-y-2">
                  <label className="text-sm font-medium">
                    Content
                  </label>
                  <Textarea
                    value={formData.content}
                    onChange={(e) => setFormData(prev => ({ ...prev, content: e.target.value }))}
                    placeholder="Write about what happened, key decisions, important discoveries..."
                    className={`min-h-32 ${errors.content ? 'border-destructive/40' : ''}`}
                  />
                  {errors.content && (
                    <p className="text-destructive text-sm">{errors.content}</p>
                  )}
                </div>

                {/* Tags Field */}
                <div className="space-y-3">
                  <label className="text-sm font-medium flex items-center gap-2">
                    <TagIcon size={16} />
                    Tags
                  </label>

                  {/* Existing Tags */}
                  {formData.tags.length > 0 && (
                    <div className="flex flex-wrap gap-2">
                      {formData.tags.map(tag => (
                        <Badge
                          key={tag}
                          variant="secondary"
                          className="text-xs cursor-pointer hover:bg-destructive/20"
                          onClick={() => handleRemoveTag(tag)}
                        >
                          #{tag} ×
                        </Badge>
                      ))}
                    </div>
                  )}

                  {/* Add New Tag */}
                  <div className="flex gap-2">
                    <Input
                      value={newTag}
                      onChange={(e) => setNewTag(e.target.value)}
                      onKeyPress={handleKeyPress}
                      placeholder="Add a tag..."
                      className="flex-1"
                    />
                    <Button
                      type="button"
                      onClick={handleAddTag}
                      variant="ghost"
                      size="sm"
                      disabled={!newTag.trim() || formData.tags.length >= 10}
                    >
                      <Plus size={16} />
                    </Button>
                  </div>
                  <p className="text-xs text-muted-foreground">
                    Press Enter or click + to add tags. Click tags to remove them. ({formData.tags.length}/10)
                  </p>
                </div>

                {/* Actions */}
                <div className="flex items-center justify-between pt-4">
                  <div className="text-sm text-muted-foreground">
                    {entry ? `Last updated: ${  entry.date.toLocaleDateString()}` : 'Will be created today'}
                  </div>
                  <div className="flex gap-3">
                    <Button
                      type="button"
                      variant="ghost"
                      onClick={onClose}
                      disabled={isSubmitting}
                    >
                      Cancel
                    </Button>
                    <Button
                      type="submit"
                      variant="primary"
                      disabled={isSubmitting}
                      className="min-w-20"
                    >
                      {isSubmitting ? 'Saving...' : (entry ? 'Update' : 'Create')}
                    </Button>
                  </div>
                </div>
              </form>
            </CardContent>
          </Card>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  )
}

/**
 * Location Modal - Modal dialog for creating and editing locations
 */

import React, { useState, useEffect } from 'react'
import * as Dialog from '@radix-ui/react-dialog'
import { X, MapPin, Plus, Trash2, Building, Home, Castle, Mountain, Trees, HelpCircle, AlertTriangle, Package } from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle, Button, Badge } from '../../ui'
import { Input } from '../../ui/Input'
import { Textarea } from '../../ui/Textarea'
import { useCampaignStore } from '../../../stores/campaignStore'
import { LocationType } from '../../../campaignManagementMockData'
import type { Location } from '../../../models/Campaign'

interface LocationModalProps {
  isOpen: boolean
  onClose: () => void
  campaignId: string
  location?: Location // If provided, we're editing; otherwise creating
  onSaved?: (locationId: string) => void
}

interface LocationFormData {
  name: string
  description: string
  type: 'city' | 'town' | 'village' | 'dungeon' | 'wilderness' | 'other'
  notes: string
  dangers: string[]
  resources: string[]
  connections: string[]
}

const LOCATION_TYPES = [
  { value: 'city' as const, label: 'City', icon: <Building size={16} /> },
  { value: 'town' as const, label: 'Town', icon: <Home size={16} /> },
  { value: 'village' as const, label: 'Village', icon: <Home size={14} /> },
  { value: 'dungeon' as const, label: 'Dungeon', icon: <Castle size={16} /> },
  { value: 'wilderness' as const, label: 'Wilderness', icon: <Trees size={16} /> },
  { value: 'other' as const, label: 'Other', icon: <HelpCircle size={16} /> }
]

const getLocationIcon = (type: string) => {
  const locationType = LOCATION_TYPES.find(t => t.value === type)
  return locationType?.icon || <HelpCircle size={16} />
}

export const LocationModal: React.FC<LocationModalProps> = ({
  isOpen,
  onClose,
  campaignId,
  location,
  onSaved
}) => {
  const [formData, setFormData] = useState<LocationFormData>({
    name: '',
    description: '',
    type: 'town',
    notes: '',
    dangers: [],
    resources: [],
    connections: []
  })
  const [errors, setErrors] = useState<Partial<LocationFormData>>({})
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [newDanger, setNewDanger] = useState('')
  const [newResource, setNewResource] = useState('')

  const addLocation = useCampaignStore(state => state.addLocation)
  const updateLocation = useCampaignStore(state => state.updateLocation)
  const campaign = useCampaignStore(state => state.getCampaign(campaignId))

  // Initialize form data when modal opens or location changes
  useEffect(() => {
    if (location) {
      setFormData({
        name: location.name,
        description: location.description,
        type: location.type,
        notes: location.notes,
        dangers: [...(location.dangers || [])],
        resources: [...(location.resources || [])],
        connections: [...(location.connections || [])]
      })
    } else {
      setFormData({
        name: '',
        description: '',
        type: 'town',
        notes: '',
        dangers: [],
        resources: [],
        connections: []
      })
    }
    setErrors({})
    setNewDanger('')
    setNewResource('')
  }, [location, isOpen])

  const validateForm = (): boolean => {
    const newErrors: Partial<LocationFormData> = {}

    // Validate name
    if (!formData.name.trim()) {
      newErrors.name = 'Name is required'
    } else if (formData.name.trim().length < 2) {
      newErrors.name = 'Name must be at least 2 characters'
    }

    // Validate description
    if (!formData.description.trim()) {
      newErrors.description = 'Description is required'
    } else if (formData.description.trim().length < 10) {
      newErrors.description = 'Description must be at least 10 characters'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!validateForm()) {
      return
    }

    setIsSubmitting(true)

    try {
      const trimmedData = {
        ...formData,
        name: formData.name.trim(),
        description: formData.description.trim(),
        notes: formData.notes.trim()
      }

      let locationId: string

      if (location) {
        // Editing existing location
        updateLocation(campaignId, location.id, trimmedData)
        locationId = location.id
      } else {
        // Creating new location
        locationId = crypto.randomUUID()
        const newLocation: Location = {
          id: locationId,
          discovered: new Date(),
          visited: [new Date()],
          ...trimmedData
        }
        addLocation(campaignId, newLocation)
      }

      onSaved?.(locationId)
      onClose()
    } catch (error) {
      console.error('Error saving location:', error)
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleAddDanger = () => {
    const danger = newDanger.trim()
    if (danger && !formData.dangers.includes(danger) && formData.dangers.length < 5) {
      setFormData(prev => ({
        ...prev,
        dangers: [...prev.dangers, danger]
      }))
      setNewDanger('')
    }
  }

  const handleRemoveDanger = (dangerToRemove: string) => {
    setFormData(prev => ({
      ...prev,
      dangers: prev.dangers.filter(danger => danger !== dangerToRemove)
    }))
  }

  const handleAddResource = () => {
    const resource = newResource.trim()
    if (resource && !formData.resources.includes(resource) && formData.resources.length < 5) {
      setFormData(prev => ({
        ...prev,
        resources: [...prev.resources, resource]
      }))
      setNewResource('')
    }
  }

  const handleRemoveResource = (resourceToRemove: string) => {
    setFormData(prev => ({
      ...prev,
      resources: prev.resources.filter(resource => resource !== resourceToRemove)
    }))
  }

  const handleKeyPress = (e: React.KeyboardEvent, type: 'danger' | 'resource') => {
    if (e.key === 'Enter') {
      e.preventDefault()
      if (type === 'danger' && newDanger.trim()) {
        handleAddDanger()
      } else if (type === 'resource' && newResource.trim()) {
        handleAddResource()
      }
    }
  }

  return (
    <Dialog.Root open={isOpen} onOpenChange={onClose}>
      <Dialog.Portal>
        <Dialog.Overlay className="fixed inset-0 z-50 bg-black/80 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0" />
        <Dialog.Content className="fixed left-1/2 top-1/2 z-50 w-full max-w-2xl -translate-x-1/2 -translate-y-1/2 border shadow-lg duration-200 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[state=closed]:slide-out-to-left-1/2 data-[state=closed]:slide-out-to-top-[48%] data-[state=open]:slide-in-from-left-1/2 data-[state=open]:slide-in-from-top-[48%] rounded-lg max-h-[90vh] overflow-y-auto">
          <Card variant="surface">
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-4">
              <div className="flex items-center gap-3">
                <MapPin className="h-5 w-5 text-primary" />
                <CardTitle className="text-xl">
                  {location ? 'Edit Location' : 'New Location'}
                </CardTitle>
              </div>
              <Dialog.Close asChild>
                <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
                  <X className="h-4 w-4" />
                </Button>
              </Dialog.Close>
            </CardHeader>

            <CardContent>
              <form onSubmit={handleSubmit} className="space-y-6">
                {/* Name and Type Row */}
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-sm font-medium">Name</label>
                    <Input
                      value={formData.name}
                      onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
                      placeholder="Enter location name..."
                      className={errors.name ? 'border-destructive/40' : ''}
                    />
                    {errors.name && (
                      <p className="text-destructive text-sm">{errors.name}</p>
                    )}
                  </div>

                  <div className="space-y-2">
                    <label className="text-sm font-medium">Type</label>
                    <div className="grid grid-cols-3 gap-2">
                      {LOCATION_TYPES.map(locationType => (
                        <button
                          key={locationType.value}
                          type="button"
                          onClick={() => setFormData(prev => ({ ...prev, type: locationType.value }))}
                          className={`flex items-center gap-1 px-2 py-2 rounded-lg border text-xs transition-colors ${
                            formData.type === locationType.value
                              ? 'bg-primary/100/20 text-primary border-primary/40/30'
                              : 'bg-muted/500/10 text-muted-foreground border-border/20 hover:bg-muted/500/20'
                          }`}
                        >
                          {locationType.icon}
                          {locationType.label}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>

                {/* Description */}
                <div className="space-y-2">
                  <label className="text-sm font-medium">Description</label>
                  <Textarea
                    value={formData.description}
                    onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
                    placeholder="Describe the location's appearance, atmosphere, and notable features..."
                    className={`min-h-20 ${errors.description ? 'border-destructive/40' : ''}`}
                  />
                  {errors.description && (
                    <p className="text-destructive text-sm">{errors.description}</p>
                  )}
                </div>

                {/* Notes */}
                <div className="space-y-2">
                  <label className="text-sm font-medium">Notes</label>
                  <Textarea
                    value={formData.notes}
                    onChange={(e) => setFormData(prev => ({ ...prev, notes: e.target.value }))}
                    placeholder="Additional notes, history, important NPCs, quests..."
                    className="min-h-20"
                  />
                </div>

                {/* Dangers */}
                <div className="space-y-3">
                  <label className="text-sm font-medium flex items-center gap-2">
                    <AlertTriangle size={16} className="text-destructive" />
                    Dangers & Threats
                  </label>

                  {/* Existing Dangers */}
                  {formData.dangers.length > 0 && (
                    <div className="flex flex-wrap gap-2">
                      {formData.dangers.map((danger, index) => (
                        <Badge
                          key={index}
                          variant="secondary"
                          className="text-xs cursor-pointer hover:bg-destructive/20 bg-destructive/15 text-destructive"
                          onClick={() => handleRemoveDanger(danger)}
                        >
                          ⚠️ {danger} ×
                        </Badge>
                      ))}
                    </div>
                  )}

                  {/* Add New Danger */}
                  <div className="flex gap-2">
                    <Input
                      value={newDanger}
                      onChange={(e) => setNewDanger(e.target.value)}
                      onKeyPress={(e) => handleKeyPress(e, 'danger')}
                      placeholder="Add a danger or threat..."
                      className="flex-1"
                    />
                    <Button
                      type="button"
                      onClick={handleAddDanger}
                      variant="ghost"
                      size="sm"
                      disabled={!newDanger.trim() || formData.dangers.length >= 5}
                    >
                      <Plus size={16} />
                    </Button>
                  </div>
                  <p className="text-xs text-muted-foreground">
                    ({formData.dangers.length}/5 dangers)
                  </p>
                </div>

                {/* Resources */}
                <div className="space-y-3">
                  <label className="text-sm font-medium flex items-center gap-2">
                    <Package size={16} className="text-chart-2" />
                    Resources & Services
                  </label>

                  {/* Existing Resources */}
                  {formData.resources.length > 0 && (
                    <div className="flex flex-wrap gap-2">
                      {formData.resources.map((resource, index) => (
                        <Badge
                          key={index}
                          variant="secondary"
                          className="text-xs cursor-pointer hover:bg-chart-2/20 bg-chart-2/15 text-chart-2"
                          onClick={() => handleRemoveResource(resource)}
                        >
                          📦 {resource} ×
                        </Badge>
                      ))}
                    </div>
                  )}

                  {/* Add New Resource */}
                  <div className="flex gap-2">
                    <Input
                      value={newResource}
                      onChange={(e) => setNewResource(e.target.value)}
                      onKeyPress={(e) => handleKeyPress(e, 'resource')}
                      placeholder="Add a resource or service..."
                      className="flex-1"
                    />
                    <Button
                      type="button"
                      onClick={handleAddResource}
                      variant="ghost"
                      size="sm"
                      disabled={!newResource.trim() || formData.resources.length >= 5}
                    >
                      <Plus size={16} />
                    </Button>
                  </div>
                  <p className="text-xs text-muted-foreground">
                    ({formData.resources.length}/5 resources)
                  </p>
                </div>

                {/* Actions */}
                <div className="flex items-center justify-between pt-4">
                  <div className="flex items-center gap-2">
                    <div className="flex items-center gap-1 text-sm text-muted-foreground">
                      {getLocationIcon(formData.type)}
                      {LOCATION_TYPES.find(t => t.value === formData.type)?.label}
                    </div>
                    {formData.dangers.length > 0 && (
                      <Badge variant="secondary" className="text-xs bg-destructive/15 text-destructive">
                        {formData.dangers.length} danger{formData.dangers.length !== 1 ? 's' : ''}
                      </Badge>
                    )}
                    {formData.resources.length > 0 && (
                      <Badge variant="secondary" className="text-xs bg-chart-2/15 text-chart-2">
                        {formData.resources.length} resource{formData.resources.length !== 1 ? 's' : ''}
                      </Badge>
                    )}
                  </div>
                  <div className="flex gap-3">
                    <Button
                      type="button"
                      variant="ghost"
                      onClick={onClose}
                      disabled={isSubmitting}
                    >
                      Cancel
                    </Button>
                    <Button
                      type="submit"
                      variant="primary"
                      disabled={isSubmitting}
                      className="min-w-20"
                    >
                      {isSubmitting ? 'Saving...' : (location ? 'Update' : 'Create')}
                    </Button>
                  </div>
                </div>
              </form>
            </CardContent>
          </Card>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  )
}

/**
 * Location Tracker - World building interface for tracking discovered locations
 */

import React, { useState, useMemo } from 'react'
import { motion } from 'framer-motion'
import { 
  MapPin,
  Plus,
  Edit,
  Trash2,
  Building,
  Home,
  Castle,
  Mountain,
  Trees,
  HelpCircle,
  Calendar,
  Eye,
  AlertTriangle,
  Package,
  Route
} from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle, Button, Badge } from '../../ui'
import { useCampaignStore } from '../../../stores/campaignStore'
import { formatDateRelative, formatLocationType, LocationType } from '../../../campaignManagementMockData'
import { LocationModal } from './LocationModal'
import type { Location } from '../../../models/Campaign'

interface LocationTrackerProps {
  campaignId: string
  searchQuery?: string
}

interface LocationCardProps {
  location: Location
  onEdit: (location: Location) => void
  onDelete: (locationId: string) => void
}

const getLocationTypeIcon = (type: LocationType) => {
  switch (type) {
    case LocationType.CITY:
      return <Building className="text-chart-3" size={16} />
    case LocationType.TOWN:
      return <Home className="text-chart-4" size={16} />
    case LocationType.VILLAGE:
      return <Home className="text-chart-2" size={14} />
    case LocationType.DUNGEON:
      return <Castle className="text-[color:var(--muted)]" size={16} />
    case LocationType.WILDERNESS:
      return <Trees className="text-chart-2" size={16} />
    case LocationType.OTHER:
      return <HelpCircle className="text-accent" size={16} />
    default:
      return <MapPin size={16} />
  }
}

const LocationCard: React.FC<LocationCardProps> = ({ location, onEdit, onDelete }) => {
  const [expanded, setExpanded] = useState(false)

  return (
    <Card 
      variant="surface" 
      className="campaign-card campaign-card-hover"
    >
      <CardContent>
        <div className="space-y-4">
          {/* Header */}
          <div className="flex items-start justify-between">
            <div className="flex-1">
              <div className="flex items-center gap-3 mb-2">
                <h3 className="font-display text-lg font-semibold">
                  {location.name}
                </h3>
                <div className="flex items-center gap-1">
                  {getLocationTypeIcon(location.type)}
                  <Badge variant="outline" className="text-xs">
                    {formatLocationType(location.type)}
                  </Badge>
                </div>
              </div>
              <div className="flex items-center gap-4 text-sm text-muted-foreground">
                <div className="flex items-center gap-1">
                  <Calendar size={14} />
                  Discovered {formatDateRelative(location.discovered)}
                </div>
                <div className="flex items-center gap-1">
                  <Eye size={14} />
                  Visited {location.visited.length} time{location.visited.length !== 1 ? 's' : ''}
                </div>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <Button 
                variant="ghost" 
                size="sm"
                onClick={() => onEdit(location)}
              >
                <Edit size={16} />
              </Button>
              <Button 
                variant="ghost" 
                size="sm"
                onClick={() => onDelete(location.id)}
              >
                <Trash2 size={16} />
              </Button>
            </div>
          </div>

          {/* Description */}
          <div>
            <p className="text-muted-foreground">
              {location.description}
            </p>
          </div>

          {/* Last Visited */}
          {location.visited.length > 0 && (
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <Eye size={14} />
