export const NPCManager: React.FC<NPCManagerProps> = ({
  campaignId,
  searchQuery = ''
}) => {
  const [filterByImportance, setFilterByImportance] = useState<NPCImportance | ''>('')
  const [filterByDisposition, setFilterByDisposition] = useState<NPCDisposition | ''>('')
  const [isModalOpen, setIsModalOpen] = useState(false)
  const [editingNPC, setEditingNPC] = useState<NPC | undefined>()
  const [sortBy, setSortBy] = useState<'name' | 'importance' | 'firstMet' | 'lastSeen'>('name')
  
  const campaign = useCampaignStore(state => state.getCampaign(campaignId))
  const addNPC = useCampaignStore(state => state.addNPC)
  const updateNPC = useCampaignStore(state => state.updateNPC)
  const deleteNPC = useCampaignStore(state => state.deleteNPC)

  const filteredAndSortedNPCs = useMemo(() => {
    if (!campaign) return []

    let npcs = [...campaign.npcs]

    // Filter by search query
    if (searchQuery) {
      const query = searchQuery.toLowerCase()
      npcs = npcs.filter(npc =>
        npc.name.toLowerCase().includes(query) ||
        npc.description.toLowerCase().includes(query) ||
        npc.role.toLowerCase().includes(query) ||
        npc.notes.toLowerCase().includes(query) ||
        (npc.location && npc.location.toLowerCase().includes(query)) ||
        (npc.secrets && npc.secrets.some(s => s.toLowerCase().includes(query)))
      )
    }

    // Filter by importance
    if (filterByImportance) {
      npcs = npcs.filter(npc => npc.importance === filterByImportance)
    }

    // Filter by disposition
    if (filterByDisposition) {
      npcs = npcs.filter(npc => npc.disposition === filterByDisposition)
    }

    // Sort NPCs
    npcs.sort((a, b) => {
      switch (sortBy) {
        case 'name':
          return a.name.localeCompare(b.name)
        case 'importance':
          const importanceOrder = { high: 3, medium: 2, low: 1 }
          return importanceOrder[b.importance] - importanceOrder[a.importance]
        case 'firstMet':
          return b.firstMet.getTime() - a.firstMet.getTime()
        case 'lastSeen':
          if (!a.lastSeen && !b.lastSeen) return 0
          if (!a.lastSeen) return 1
          if (!b.lastSeen) return -1
          return b.lastSeen.getTime() - a.lastSeen.getTime()
        default:
          return 0
      }
    })

    return npcs
  }, [campaign, searchQuery, filterByImportance, filterByDisposition, sortBy])

  const handleEditNPC = (npc: NPC) => {
    setEditingNPC(npc)
    setIsModalOpen(true)
  }

  const handleDeleteNPC = (npcId: string) => {
    if (confirm('Are you sure you want to delete this NPC?')) {
      deleteNPC(campaignId, npcId)
    }
  }

  const handleCreateNPC = () => {
    setEditingNPC(undefined)
    setIsModalOpen(true)
  }

  const handleModalClose = () => {
    setIsModalOpen(false)
    setEditingNPC(undefined)
  }

  const handleNPCSaved = (npcId: string) => {
    console.log('NPC saved:', npcId)
  }

  if (!campaign) {
    return (
      <Card variant="surface">
        <CardContent>
          <div className="text-center">
            <p className="text-muted-foreground">
              Campaign not found
            </p>
          </div>
        </CardContent>
      </Card>
    )
  }

  return (
    <>
      <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-xl font-display">NPC Management</h3>
          <p className="text-muted-foreground">
            {filteredAndSortedNPCs.length} of {campaign.npcs.length} NPCs
          </p>
        </div>
        <Button 
          variant="primary" 
          size="sm" 
          className="gap-2"
          onClick={handleCreateNPC}
        >
          <Plus size={16} />
          Add NPC
        </Button>
      </div>

      {/* Filters */}
      <Card variant="surface">
        <CardContent>
          <div className="flex flex-wrap items-center gap-4">
            <select
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value as any)}
              className="px-3 py-2 rounded-lg border text-sm"
              style={{
                backgroundColor: 'var(--card)',
                borderColor: 'var(--primary)',
                color: 'var(--foreground)'
              }}
            >
              <option value="name">Sort by Name</option>
              <option value="importance">Sort by Importance</option>
              <option value="firstMet">Sort by First Met</option>
              <option value="lastSeen">Sort by Last Seen</option>
            </select>

            <select
              value={filterByImportance}
              onChange={(e) => setFilterByImportance(e.target.value as any)}
              className="px-3 py-2 rounded-lg border text-sm"
              style={{
                backgroundColor: 'var(--card)',
                borderColor: 'var(--primary)',
                color: 'var(--foreground)'
              }}
            >
              <option value="">All Importance</option>
              <option value={NPCImportance.HIGH}>High</option>
              <option value={NPCImportance.MEDIUM}>Medium</option>
              <option value={NPCImportance.LOW}>Low</option>
            </select>

            <select
              value={filterByDisposition}
              onChange={(e) => setFilterByDisposition(e.target.value as any)}
              className="px-3 py-2 rounded-lg border text-sm"
              style={{
                backgroundColor: 'var(--card)',
                borderColor: 'var(--primary)',
                color: 'var(--foreground)'
              }}
            >
              <option value="">All Dispositions</option>
              <option value={NPCDisposition.FRIENDLY}>Friendly</option>
              <option value={NPCDisposition.NEUTRAL}>Neutral</option>
              <option value={NPCDisposition.HOSTILE}>Hostile</option>
              <option value={NPCDisposition.UNKNOWN}>Unknown</option>
            </select>
          </div>
        </CardContent>
      </Card>

      {/* NPCs List */}
      {filteredAndSortedNPCs.length === 0 ? (
        <Card variant="surface" className="campaign-empty-state">
          <CardContent>
            <div className="text-center space-y-4">
              <Users size={48} className='mx-auto text-muted-foreground' />
              <div>
                <h4 className="font-medium mb-2">
                  {campaign.npcs.length === 0 ? 'No NPCs added' : 'No NPCs match your filters'}
                </h4>
                <p className="text-muted-foreground">
                  {campaign.npcs.length === 0 
                    ? 'Add memorable characters you meet during your adventures'
                    : 'Try adjusting your search terms or filters'
                  }
                </p>
              </div>
              {campaign.npcs.length === 0 && (
                <Button 
                  variant="primary" 
                  size="md" 
                  className="gap-2"
                  onClick={handleCreateNPC}
                >
                  <Plus size={16} />
                  Add First NPC
                </Button>
              )}
            </div>
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {filteredAndSortedNPCs.map((npc, index) => (
            <motion.div
              key={npc.id}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.3, delay: index * 0.1 }}
            >
              <NPCCard
                npc={npc}
                onEdit={handleEditNPC}
                onDelete={handleDeleteNPC}
              />
            </motion.div>
          ))}
        </div>
      )}
      </div>

      {/* NPC Modal */}
      <NPCModal
        isOpen={isModalOpen}
        onClose={handleModalClose}
        campaignId={campaignId}
        npc={editingNPC}
        onSaved={handleNPCSaved}
      />
    </>
  )
}

/**
 * NPC Modal - Modal dialog for creating and editing NPCs
 */

import React, { useState, useEffect } from 'react'
import * as Dialog from '@radix-ui/react-dialog'
import * as Select from '@radix-ui/react-select'
import { X, Users, Plus, Trash2, Heart, Shield, Skull, HelpCircle, MapPin, ChevronDown } from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle, Button, Badge } from '../../ui'
import { Input } from '../../ui/Input'
import { Textarea } from '../../ui/Textarea'
import { useCampaignStore } from '../../../stores/campaignStore'
import { NPCImportance, NPCDisposition } from '../../../campaignManagementMockData'
import type { NPC } from '../../../models/Campaign'

interface NPCModalProps {
  isOpen: boolean
  onClose: () => void
  campaignId: string
  npc?: NPC // If provided, we're editing; otherwise creating
  onSaved?: (npcId: string) => void
}

interface NPCFormData {
  name: string
  description: string
  role: string
  location: string
  notes: string
  importance: 'low' | 'medium' | 'high'
  disposition: 'friendly' | 'neutral' | 'hostile' | 'unknown'
  secrets: string[]
}

const ROLE_SUGGESTIONS = [
  'Merchant', 'Quest Giver', 'Villain', 'Ally', 'Guard', 'Noble',
  'Scholar', 'Innkeeper', 'Blacksmith', 'Priest', 'Thief', 'Hunter',
  'Farmer', 'Sailor', 'Soldier', 'Mage', 'Healer', 'Leader'
]

const getDispositionIcon = (disposition: string) => {
  switch (disposition) {
    case 'friendly': return <Heart size={16} className="text-chart-2" />
    case 'neutral': return <Shield size={16} className="text-primary" />
    case 'hostile': return <Skull size={16} className="text-destructive" />
    case 'unknown': return <HelpCircle size={16} className="text-muted-foreground" />
    default: return <HelpCircle size={16} />
  }
}

const getImportanceColor = (importance: string) => {
  switch (importance) {
    case 'high': return 'bg-destructive/20 text-destructive border-destructive/40/30'
    case 'medium': return 'bg-chart-4/120/20 text-chart-4 border-yellow-500/30'
    case 'low': return 'bg-muted/500/20 text-muted-foreground border-border/30'
    default: return 'bg-muted/500/20 text-muted-foreground border-border/30'
  }
}

export const NPCModal: React.FC<NPCModalProps> = ({
  isOpen,
  onClose,
  campaignId,
  npc,
  onSaved
}) => {
  const [formData, setFormData] = useState<NPCFormData>({
    name: '',
    description: '',
    role: '',
    location: '',
    notes: '',
    importance: 'medium',
    disposition: 'neutral',
    secrets: []
  })
  const [errors, setErrors] = useState<Partial<NPCFormData>>({})
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [newSecret, setNewSecret] = useState('')

  const addNPC = useCampaignStore(state => state.addNPC)
  const updateNPC = useCampaignStore(state => state.updateNPC)

  // Initialize form data when modal opens or NPC changes
  useEffect(() => {
    if (npc) {
      setFormData({
        name: npc.name,
        description: npc.description,
        role: npc.role,
        location: npc.location || '',
        notes: npc.notes,
        importance: npc.importance,
        disposition: npc.disposition,
        secrets: [...(npc.secrets || [])]
      })
    } else {
      setFormData({
        name: '',
        description: '',
        role: '',
        location: '',
        notes: '',
        importance: 'medium',
        disposition: 'neutral',
        secrets: []
      })
    }
    setErrors({})
    setNewSecret('')
  }, [npc, isOpen])

  const validateForm = (): boolean => {
    const newErrors: Partial<NPCFormData> = {}

    // Validate name
    if (!formData.name.trim()) {
      newErrors.name = 'Name is required'
    } else if (formData.name.trim().length < 2) {
      newErrors.name = 'Name must be at least 2 characters'
    }

    // Validate description
    if (!formData.description.trim()) {
      newErrors.description = 'Description is required'
    } else if (formData.description.trim().length < 10) {
      newErrors.description = 'Description must be at least 10 characters'
    }

    // Validate role
    if (!formData.role.trim()) {
      newErrors.role = 'Role is required'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!validateForm()) {
      return
    }

    setIsSubmitting(true)

    try {
      const trimmedData = {
        ...formData,
        name: formData.name.trim(),
        description: formData.description.trim(),
        role: formData.role.trim(),
        location: formData.location.trim(),
        notes: formData.notes.trim()
      }

      let npcId: string

      if (npc) {
        // Editing existing NPC
        updateNPC(campaignId, npc.id, trimmedData)
        npcId = npc.id
      } else {
        // Creating new NPC
        npcId = crypto.randomUUID()
        const newNPC: NPC = {
          id: npcId,
          firstMet: new Date(),
          ...trimmedData
        }
        addNPC(campaignId, newNPC)
      }

      onSaved?.(npcId)
      onClose()
    } catch (error) {
      console.error('Error saving NPC:', error)
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleAddSecret = () => {
    const secret = newSecret.trim()
    if (secret && !formData.secrets.includes(secret) && formData.secrets.length < 5) {
      setFormData(prev => ({
        ...prev,
        secrets: [...prev.secrets, secret]
      }))
      setNewSecret('')
    }
  }

  const handleRemoveSecret = (secretToRemove: string) => {
    setFormData(prev => ({
      ...prev,
      secrets: prev.secrets.filter(secret => secret !== secretToRemove)
    }))
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && newSecret.trim()) {
      e.preventDefault()
      handleAddSecret()
    }
  }

  return (
    <Dialog.Root open={isOpen} onOpenChange={onClose}>
      <Dialog.Portal>
        <Dialog.Overlay className="fixed inset-0 z-50 bg-black/80 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0" />
        <Dialog.Content className="fixed left-1/2 top-1/2 z-50 w-full max-w-2xl -translate-x-1/2 -translate-y-1/2 border shadow-lg duration-200 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[state=closed]:slide-out-to-left-1/2 data-[state=closed]:slide-out-to-top-[48%] data-[state=open]:slide-in-from-left-1/2 data-[state=open]:slide-in-from-top-[48%] rounded-lg max-h-[90vh] overflow-y-auto">
          <Card variant="surface">
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-4">
              <div className="flex items-center gap-3">
                <Users className="h-5 w-5 text-primary" />
                <CardTitle className="text-xl">
                  {npc ? 'Edit NPC' : 'New NPC'}
                </CardTitle>
              </div>
              <Dialog.Close asChild>
                <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
                  <X className="h-4 w-4" />
                </Button>
              </Dialog.Close>
            </CardHeader>

            <CardContent>
              <form onSubmit={handleSubmit} className="space-y-6">
                {/* Name and Role Row */}
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-sm font-medium">Name</label>
                    <Input
                      value={formData.name}
                      onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
                      placeholder="Enter NPC name..."
                      className={errors.name ? 'border-destructive/40' : ''}
                    />
                    {errors.name && (
                      <p className="text-destructive text-sm">{errors.name}</p>
                    )}
                  </div>

                  <div className="space-y-2">
                    <label className="text-sm font-medium">Role</label>
                    <div className="relative">
                      <Input
                        value={formData.role}
                        onChange={(e) => setFormData(prev => ({ ...prev, role: e.target.value }))}
                        placeholder="Enter or select role..."
                        list="role-suggestions"
                        className={errors.role ? 'border-destructive/40' : ''}
                      />
                      <datalist id="role-suggestions">
                        {ROLE_SUGGESTIONS.map(role => (
                          <option key={role} value={role} />
                        ))}
                      </datalist>
                    </div>
                    {errors.role && (
                      <p className="text-destructive text-sm">{errors.role}</p>
                    )}
                  </div>
                </div>

                {/* Description */}
                <div className="space-y-2">
                  <label className="text-sm font-medium">Description</label>
                  <Textarea
                    value={formData.description}
                    onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
                    placeholder="Describe the NPC's appearance, personality, and notable characteristics..."
                    className={`min-h-20 ${errors.description ? 'border-destructive/40' : ''}`}
                  />
                  {errors.description && (
                    <p className="text-destructive text-sm">{errors.description}</p>
                  )}
                </div>

                {/* Location and Importance Row */}
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-sm font-medium flex items-center gap-2">
                      <MapPin size={16} />
                      Location
                    </label>
                    <Input
                      value={formData.location}
                      onChange={(e) => setFormData(prev => ({ ...prev, location: e.target.value }))}
                      placeholder="Where can they be found?"
                    />
                  </div>

                  <div className="space-y-2">
                    <label className="text-sm font-medium">Importance</label>
                    <select
                      value={formData.importance}
                      onChange={(e) => setFormData(prev => ({ ...prev, importance: e.target.value as any }))}
                      className="w-full px-3 py-2 rounded-lg border text-sm"
                      style={{
                        backgroundColor: 'var(--card)',
                        borderColor: 'var(--primary)',
                        color: 'var(--foreground)'
                      }}
                    >
                      <option value="low">Low</option>
                      <option value="medium">Medium</option>
                      <option value="high">High</option>
                    </select>
                  </div>
                </div>

                {/* Disposition */}
                <div className="space-y-2">
                  <label className="text-sm font-medium">Disposition toward Party</label>
                  <div className="flex gap-3">
                    {(['friendly', 'neutral', 'hostile', 'unknown'] as const).map(disp => (
                      <button
                        key={disp}
                        type="button"
                        onClick={() => setFormData(prev => ({ ...prev, disposition: disp }))}
                        className={`flex items-center gap-2 px-3 py-2 rounded-lg border text-sm transition-colors ${
                          formData.disposition === disp
                            ? 'bg-primary/100/20 text-primary border-primary/40/30'
                            : 'bg-muted/500/10 text-muted-foreground border-border/20 hover:bg-muted/500/20'
                        }`}
                      >
                        {getDispositionIcon(disp)}
                        {disp.charAt(0).toUpperCase() + disp.slice(1)}
                      </button>
                    ))}
                  </div>
                </div>

                {/* Notes */}
                <div className="space-y-2">
                  <label className="text-sm font-medium">Notes</label>
                  <Textarea
                    value={formData.notes}
                    onChange={(e) => setFormData(prev => ({ ...prev, notes: e.target.value }))}
                    placeholder="Additional notes, interactions, quest connections..."
                    className="min-h-20"
                  />
                </div>

                {/* Secrets */}
                <div className="space-y-3">
                  <label className="text-sm font-medium">Secrets & Hidden Information</label>

                  {/* Existing Secrets */}
                  {formData.secrets.length > 0 && (
                    <div className="space-y-2">
                      {formData.secrets.map((secret, index) => (
                        <div key={index} className="flex items-start gap-2 p-3 bg-muted/500/10 rounded-lg">
                          <div className="flex-1 text-sm">{secret}</div>
                          <Button
                            type="button"
                            variant="ghost"
                            size="sm"
                            className="h-6 w-6 p-0"
                            onClick={() => handleRemoveSecret(secret)}
                          >
                            <Trash2 size={12} />
                          </Button>
                        </div>
                      ))}
                    </div>
                  )}

                  {/* Add New Secret */}
                  <div className="flex gap-2">
                    <Input
                      value={newSecret}
                      onChange={(e) => setNewSecret(e.target.value)}
                      onKeyPress={handleKeyPress}
                      placeholder="Add a secret or hidden info..."
                      className="flex-1"
                    />
                    <Button
                      type="button"
                      onClick={handleAddSecret}
                      variant="ghost"
                      size="sm"
                      disabled={!newSecret.trim() || formData.secrets.length >= 5}
                    >
                      <Plus size={16} />
                    </Button>
                  </div>
                  <p className="text-xs text-muted-foreground">
                    Press Enter or click + to add secrets. ({formData.secrets.length}/5)
                  </p>
                </div>

                {/* Actions */}
                <div className="flex items-center justify-between pt-4">
                  <div className="flex items-center gap-3">
                    <div className={`px-2 py-1 rounded text-xs border ${getImportanceColor(formData.importance)}`}>
                      {formData.importance.charAt(0).toUpperCase() + formData.importance.slice(1)} Importance
                    </div>
                    <div className="flex items-center gap-1 text-sm text-muted-foreground">
                      {getDispositionIcon(formData.disposition)}
                      {formData.disposition.charAt(0).toUpperCase() + formData.disposition.slice(1)}
                    </div>
                  </div>
                  <div className="flex gap-3">
                    <Button
                      type="button"
                      variant="ghost"
                      onClick={onClose}
                      disabled={isSubmitting}
                    >
                      Cancel
                    </Button>
                    <Button
                      type="submit"
                      variant="primary"
                      disabled={isSubmitting}
                      className="min-w-20"
                    >
                      {isSubmitting ? 'Saving...' : (npc ? 'Update' : 'Create')}
                    </Button>
                  </div>
                </div>
              </form>
            </CardContent>
          </Card>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  )
}

/**
 * Session History - Comprehensive session tracking and management
 */

import React, { useState, useMemo } from 'react'
import { motion } from 'framer-motion'
import { 
  Calendar,
  Clock,
  Trophy,
  Plus,
  Edit,
  Trash2,
  ChevronDown,
  ChevronUp,
  Star,
  AlertTriangle
} from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle, Button, Badge } from '../../ui'
import { useCampaignStore } from '../../../stores/campaignStore'
import { formatSessionDuration, formatXPTotal, formatDateRelative, SessionSortBy } from '../../../campaignManagementMockData'
import { SessionModal } from './SessionModal'
import type { CampaignSession } from '../../../models/Campaign'

interface SessionHistoryProps {
  campaignId: string
  searchQuery?: string
}

interface SessionCardProps {
  session: CampaignSession
  onEdit: (session: CampaignSession) => void
  onDelete: (sessionId: string) => void
}

const SessionCard: React.FC<SessionCardProps> = ({ session, onEdit, onDelete }) => {
  const [expanded, setExpanded] = useState(false)

  return (
    <Card variant="surface" className="campaign-card campaign-card-hover">
      <CardContent>
        <div className="space-y-4">
          {/* Header */}
          <div className="flex items-start justify-between">
            <div className="flex-1">
              <div className="flex items-center gap-3 mb-2">
                <h3 className="font-display text-lg font-semibold">
                  {session.title}
                </h3>
                <Badge variant="default" className="text-xs">
                  {formatXPTotal(session.xpGained)}
                </Badge>
              </div>
              <div className="flex items-center gap-4 text-sm text-muted-foreground">
                <div className="flex items-center gap-1">
                  <Calendar size={14} />
                  {formatDateRelative(session.date)}
                </div>
                {session.duration && (
                  <div className="flex items-center gap-1">
                    <Clock size={14} />
                    {formatSessionDuration(session.duration)}
                  </div>
                )}
              </div>
            </div>
            <div className="flex items-center gap-2">
              <Button 
                variant="ghost" 
                size="sm"
                onClick={() => setExpanded(!expanded)}
              >
                {expanded ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
              </Button>
              <Button 
                variant="ghost" 
                size="sm"
                onClick={() => onEdit(session)}
              >
                <Edit size={16} />
              </Button>
              <Button 
                variant="ghost" 
                size="sm"
                onClick={() => onDelete(session.id)}
              >
                <Trash2 size={16} />
              </Button>
            </div>
          </div>

          {/* Summary */}
          <div>
            <p className="text-muted-foreground">
              {session.summary}
            </p>
          </div>

          {/* Expanded Content */}
          {expanded && (
            <motion.div
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: 'auto' }}
              exit={{ opacity: 0, height: 0 }}
              transition={{ duration: 0.3 }}
              className="space-y-4 pt-4 border-t border-primary/20">
              {/* Notes */}
              {session.notes && (
                <div>
                  <h4 className="font-medium mb-2">Session Notes</h4>
                  <p 
                    className="text-sm p-3 rounded-lg"
                    style={{ 
                      backgroundColor: 'var(--card)',
                      color: 'var(--muted-foreground)' 
                    }}
                  >
                    {session.notes}
                  </p>
                </div>
              )}

              {/* Highlights */}
              {session.highlights && session.highlights.length > 0 && (
                <div>
                  <h4 className="font-medium mb-2 flex items-center gap-2">
                    <Star className="text-[color:var(--gold-500)]" size={16} />
                    Highlights
                  </h4>
                  <div className="space-y-2">
                    {session.highlights.map((highlight, index) => (
                      <div 
                        key={index}
                        className="text-sm p-2 rounded-lg flex items-start gap-2 bg-card">
                        <Star size={12} className='mt-[2px] text-[color:var(--gold-500)]' />
                        <span className="text-muted-foreground">
                          {highlight}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Challenges */}
              {session.challenges && session.challenges.length > 0 && (
                <div>
                  <h4 className="font-medium mb-2 flex items-center gap-2">
                    <AlertTriangle className="text-chart-4" size={16} />
                    Challenges
                  </h4>
                  <div className="space-y-2">
                    {session.challenges.map((challenge, index) => (
                      <div 
                        key={index}
                        className="text-sm p-2 rounded-lg flex items-start gap-2 bg-card">
                        <AlertTriangle size={12} className='mt-[2px] text-chart-4' />
                        <span className="text-muted-foreground">
                          {challenge}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Next Session Prep */}
              {session.nextSession && (
                <div>
                  <h4 className="font-medium mb-2">Next Session Prep</h4>
                  <p 
                    className="text-sm p-3 rounded-lg"
                    style={{ 
                      backgroundColor: 'var(--card)',
                      color: 'var(--muted-foreground)' 
                    }}
                  >
                    {session.nextSession}
                  </p>
                </div>
              )}
            </motion.div>
          )}
        </div>
      </CardContent>
    </Card>
  )
}

export const SessionHistory: React.FC<SessionHistoryProps> = ({ 
  campaignId, 
  searchQuery = '' 
}) => {
  const [sortBy, setSortBy] = useState<SessionSortBy>(SessionSortBy.DATE)
  const [showCreateForm, setShowCreateForm] = useState(false)
  const [isModalOpen, setIsModalOpen] = useState(false)
  const [editingSession, setEditingSession] = useState<CampaignSession | undefined>()
  
  const campaign = useCampaignStore(state => state.getCampaign(campaignId))
  const addSession = useCampaignStore(state => state.addSession)
  const updateSession = useCampaignStore(state => state.updateSession)
  const deleteSession = useCampaignStore(state => state.deleteSession)

  const filteredAndSortedSessions = useMemo(() => {
    if (!campaign) return []

    let sessions = [...campaign.sessions]

    // Filter by search query
    if (searchQuery) {
      const query = searchQuery.toLowerCase()
      sessions = sessions.filter(session =>
        session.title.toLowerCase().includes(query) ||
        session.summary.toLowerCase().includes(query) ||
        session.notes.toLowerCase().includes(query) ||
        session.highlights.some(h => h.toLowerCase().includes(query)) ||
        session.challenges.some(c => c.toLowerCase().includes(query))
      )
    }

    // Sort sessions
    sessions.sort((a, b) => {
      switch (sortBy) {
        case SessionSortBy.DATE:
          return b.date.getTime() - a.date.getTime()
        case SessionSortBy.XP_GAINED:
          return b.xpGained - a.xpGained
        case SessionSortBy.DURATION:
          return (b.duration || 0) - (a.duration || 0)
        case SessionSortBy.TITLE:
          return a.title.localeCompare(b.title)
        default:
          return 0
      }
    })

    return sessions
  }, [campaign, searchQuery, sortBy])

  const handleEditSession = (session: CampaignSession) => {
    setEditingSession(session)
    setIsModalOpen(true)
  }

  const handleDeleteSession = (sessionId: string) => {
    if (confirm('Are you sure you want to delete this session?')) {
      deleteSession(campaignId, sessionId)
    }
  }

  const handleCreateSession = () => {
    setEditingSession(undefined)
    setIsModalOpen(true)
  }

  const handleModalClose = () => {
    setIsModalOpen(false)
    setEditingSession(undefined)
  }

  const handleSessionSaved = (sessionId: string) => {
    console.log('Session saved:', sessionId)
  }

  if (!campaign) {
    return (
      <Card variant="surface">
        <CardContent>
          <div className="text-center">
            <p className="text-muted-foreground">
              Campaign not found
            </p>
          </div>
        </CardContent>
      </Card>
    )
  }

  return (
    <>
      <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-xl font-display">Session History</h3>
          <p className="text-muted-foreground">
            {filteredAndSortedSessions.length} of {campaign.sessions.length} sessions
          </p>
        </div>
        <div className="flex items-center gap-3">
          <select
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value as SessionSortBy)}
            className="px-3 py-2 rounded-lg border text-sm"
            style={{
              backgroundColor: 'var(--card)',
              borderColor: 'var(--primary)',
              color: 'var(--foreground)'
            }}
          >
            <option value={SessionSortBy.DATE}>Sort by Date</option>
            <option value={SessionSortBy.XP_GAINED}>Sort by XP</option>
            <option value={SessionSortBy.DURATION}>Sort by Duration</option>
            <option value={SessionSortBy.TITLE}>Sort by Title</option>
          </select>
          <Button 
            variant="primary" 
            size="sm" 
            className="gap-2"
            onClick={handleCreateSession}
          >
            <Plus size={16} />
            Add Session
          </Button>
        </div>
      </div>

      {/* Sessions List */}
      {filteredAndSortedSessions.length === 0 ? (
        <Card variant="surface" className="campaign-empty-state">
          <CardContent>
            <div className="text-center space-y-4">
              <Calendar size={48} className='mx-auto text-muted-foreground' />
              <div>
                <h4 className="font-medium mb-2">
                  {campaign.sessions.length === 0 ? 'No sessions recorded' : 'No sessions match your search'}
                </h4>
                <p className="text-muted-foreground">
                  {campaign.sessions.length === 0 
                    ? 'Add your first session to start tracking your campaign progress'
                    : 'Try adjusting your search terms or filters'
                  }
                </p>
              </div>
              {campaign.sessions.length === 0 && (
                <Button 
                  variant="primary" 
                  size="md" 
                  className="gap-2"
                  onClick={handleCreateSession}
                >
                  <Plus size={16} />
                  Add First Session
                </Button>
              )}
            </div>
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-4">
          {filteredAndSortedSessions.map((session, index) => (
            <motion.div
              key={session.id}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.3, delay: index * 0.1 }}
            >
              <SessionCard
                session={session}
                onEdit={handleEditSession}
                onDelete={handleDeleteSession}
              />
            </motion.div>
          ))}
        </div>
      )}
      </div>

      {/* Session Modal */}
      <SessionModal
        isOpen={isModalOpen}
        onClose={handleModalClose}
        campaignId={campaignId}
        session={editingSession}
        onSaved={handleSessionSaved}
      />
    </>
  )
}

/**
 * Session Modal - Modal dialog for creating and editing campaign sessions
 */

import React, { useState, useEffect } from 'react'
import * as Dialog from '@radix-ui/react-dialog'
import { X, Calendar, Clock, Trophy, Plus, Trash2, Star, AlertTriangle } from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle, Button, Badge } from '../../ui'
import { Input } from '../../ui/Input'
import { Textarea } from '../../ui/Textarea'
import { useCampaignStore } from '../../../stores/campaignStore'
import type { CampaignSession } from '../../../models/Campaign'

interface SessionModalProps {
  isOpen: boolean
  onClose: () => void
  campaignId: string
  session?: CampaignSession // If provided, we're editing; otherwise creating
  onSaved?: (sessionId: string) => void
}

interface SessionFormData {
  title: string
  date: string // ISO date string for input
  duration: number // in minutes
  summary: string
  notes: string
  xpGained: number
  highlights: string[]
  challenges: string[]
  nextSession: string
}

export const SessionModal: React.FC<SessionModalProps> = ({
  isOpen,
  onClose,
  campaignId,
  session,
  onSaved
}) => {
  const [formData, setFormData] = useState<SessionFormData>({
    title: '',
    date: new Date().toISOString().split('T')[0], // Today's date
    duration: 180, // 3 hours default
    summary: '',
    notes: '',
    xpGained: 0,
    highlights: [],
    challenges: [],
    nextSession: ''
  })
  const [errors, setErrors] = useState<Partial<SessionFormData>>({})
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [newHighlight, setNewHighlight] = useState('')
  const [newChallenge, setNewChallenge] = useState('')

  const addSession = useCampaignStore(state => state.addSession)
  const updateSession = useCampaignStore(state => state.updateSession)

  // Initialize form data when modal opens or session changes
  useEffect(() => {
    if (session) {
      setFormData({
        title: session.title,
        date: session.date.toISOString().split('T')[0],
        duration: session.duration || 180,
        summary: session.summary,
        notes: session.notes,
        xpGained: session.xpGained,
        highlights: [...session.highlights],
        challenges: [...session.challenges],
        nextSession: session.nextSession || ''
      })
    } else {
      setFormData({
        title: '',
        date: new Date().toISOString().split('T')[0],
        duration: 180,
        summary: '',
        notes: '',
        xpGained: 0,
        highlights: [],
        challenges: [],
        nextSession: ''
      })
    }
    setErrors({})
    setNewHighlight('')
    setNewChallenge('')
  }, [session, isOpen])

  const validateForm = (): boolean => {
    const newErrors: Partial<SessionFormData> = {}

    // Validate title
    if (!formData.title.trim()) {
      newErrors.title = 'Session title is required'
    } else if (formData.title.trim().length < 3) {
      newErrors.title = 'Title must be at least 3 characters'
    }

    // Validate summary
    if (!formData.summary.trim()) {
      newErrors.summary = 'Session summary is required'
    } else if (formData.summary.trim().length < 10) {
      newErrors.summary = 'Summary must be at least 10 characters'
    }

    // Validate duration
    if (formData.duration < 30) {
      newErrors.duration = 'Duration must be at least 30 minutes'
    } else if (formData.duration > 960) { // 16 hours
      newErrors.duration = 'Duration cannot exceed 16 hours'
    }

    // Validate XP
    if (formData.xpGained < 0) {
      newErrors.xpGained = 'XP gained cannot be negative'
    } else if (formData.xpGained > 10) {
      newErrors.xpGained = 'XP gained seems unusually high (max 10)'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!validateForm()) {
      return
    }

    setIsSubmitting(true)

    try {
      const trimmedData = {
        ...formData,
        title: formData.title.trim(),
        summary: formData.summary.trim(),
        notes: formData.notes.trim(),
        nextSession: formData.nextSession.trim()
      }

      let sessionId: string

      if (session) {
        // Editing existing session
        const updatedSession: CampaignSession = {
          ...session,
          ...trimmedData,
          date: new Date(trimmedData.date)
        }
        updateSession(campaignId, session.id, updatedSession)
        sessionId = session.id
      } else {
        // Creating new session
        sessionId = crypto.randomUUID()
        const newSession: CampaignSession = {
          id: sessionId,
          ...trimmedData,
          date: new Date(trimmedData.date)
        }
        addSession(campaignId, newSession)
      }

      onSaved?.(sessionId)
      onClose()
    } catch (error) {
      console.error('Error saving session:', error)
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleAddHighlight = () => {
    const highlight = newHighlight.trim()
    if (highlight && !formData.highlights.includes(highlight) && formData.highlights.length < 5) {
      setFormData(prev => ({
        ...prev,
        highlights: [...prev.highlights, highlight]
      }))
      setNewHighlight('')
    }
  }

  const handleRemoveHighlight = (highlightToRemove: string) => {
    setFormData(prev => ({
      ...prev,
      highlights: prev.highlights.filter(highlight => highlight !== highlightToRemove)
    }))
  }

  const handleAddChallenge = () => {
    const challenge = newChallenge.trim()
    if (challenge && !formData.challenges.includes(challenge) && formData.challenges.length < 5) {
      setFormData(prev => ({
        ...prev,
        challenges: [...prev.challenges, challenge]
      }))
      setNewChallenge('')
    }
  }

  const handleRemoveChallenge = (challengeToRemove: string) => {
    setFormData(prev => ({
      ...prev,
      challenges: prev.challenges.filter(challenge => challenge !== challengeToRemove)
    }))
  }

  const handleKeyPress = (e: React.KeyboardEvent, type: 'highlight' | 'challenge') => {
    if (e.key === 'Enter') {
      e.preventDefault()
      if (type === 'highlight' && newHighlight.trim()) {
        handleAddHighlight()
      } else if (type === 'challenge' && newChallenge.trim()) {
        handleAddChallenge()
      }
    }
  }

  const formatDuration = (minutes: number): string => {
    const hours = Math.floor(minutes / 60)
    const mins = minutes % 60
    if (hours === 0) return `${mins}min`
    if (mins === 0) return `${hours}h`
    return `${hours}h ${mins}min`
  }

  return (
    <Dialog.Root open={isOpen} onOpenChange={onClose}>
      <Dialog.Portal>
        <Dialog.Overlay className="fixed inset-0 z-50 bg-black/80 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0" />
        <Dialog.Content className="fixed left-1/2 top-1/2 z-50 w-full max-w-2xl -translate-x-1/2 -translate-y-1/2 border shadow-lg duration-200 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[state=closed]:slide-out-to-left-1/2 data-[state=closed]:slide-out-to-top-[48%] data-[state=open]:slide-in-from-left-1/2 data-[state=open]:slide-in-from-top-[48%] rounded-lg max-h-[90vh] overflow-y-auto">
          <Card variant="surface">
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-4">
              <div className="flex items-center gap-3">
                <Calendar className="h-5 w-5 text-primary" />
                <CardTitle className="text-xl">
                  {session ? 'Edit Session' : 'New Session'}
                </CardTitle>
              </div>
              <Dialog.Close asChild>
                <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
                  <X className="h-4 w-4" />
                </Button>
              </Dialog.Close>
            </CardHeader>

            <CardContent>
              <form onSubmit={handleSubmit} className="space-y-6">
                {/* Title and Date Row */}
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-sm font-medium">Session Title</label>
                    <Input
                      value={formData.title}
                      onChange={(e) => setFormData(prev => ({ ...prev, title: e.target.value }))}
                      placeholder="Enter session title..."
                      className={errors.title ? 'border-destructive/40' : ''}
                    />
                    {errors.title && (
                      <p className="text-destructive text-sm">{errors.title}</p>
                    )}
                  </div>

                  <div className="space-y-2">
                    <label className="text-sm font-medium">Date</label>
                    <Input
                      type="date"
                      value={formData.date}
                      onChange={(e) => setFormData(prev => ({ ...prev, date: e.target.value }))}
                    />
                  </div>
                </div>

                {/* Duration and XP Row */}
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-sm font-medium flex items-center gap-2">
                      <Clock size={16} />
                      Duration (minutes)
                    </label>
                    <Input
                      type="number"
                      value={formData.duration}
                      onChange={(e) => setFormData(prev => ({ ...prev, duration: parseInt(e.target.value) || 0 }))}
                      min="30"
                      max="960"
                      className={errors.duration ? 'border-destructive/40' : ''}
                    />
                    {errors.duration && (
                      <p className="text-destructive text-sm">{errors.duration}</p>
                    )}
                    <p className="text-xs text-muted-foreground">
                      Duration: {formatDuration(formData.duration)}
                    </p>
                  </div>

                  <div className="space-y-2">
                    <label className="text-sm font-medium flex items-center gap-2">
                      <Trophy size={16} />
                      XP Gained
                    </label>
                    <Input
                      type="number"
                      value={formData.xpGained}
                      onChange={(e) => setFormData(prev => ({ ...prev, xpGained: parseInt(e.target.value) || 0 }))}
                      min="0"
                      max="10"
                      className={errors.xpGained ? 'border-destructive/40' : ''}
                    />
                    {errors.xpGained && (
                      <p className="text-destructive text-sm">{errors.xpGained}</p>
                    )}
                  </div>
                </div>

                {/* Summary */}
                <div className="space-y-2">
                  <label className="text-sm font-medium">Session Summary</label>
                  <Textarea
                    value={formData.summary}
                    onChange={(e) => setFormData(prev => ({ ...prev, summary: e.target.value }))}
                    placeholder="What happened during this session? Key events, decisions, plot progression..."
                    className={`min-h-20 ${errors.summary ? 'border-destructive/40' : ''}`}
                  />
                  {errors.summary && (
                    <p className="text-destructive text-sm">{errors.summary}</p>
                  )}
                </div>

                {/* Highlights */}
                <div className="space-y-3">
                  <label className="text-sm font-medium flex items-center gap-2">
                    <Star size={16} className="text-chart-4" />
                    Session Highlights
                  </label>

                  {/* Existing Highlights */}
                  {formData.highlights.length > 0 && (
                    <div className="flex flex-wrap gap-2">
                      {formData.highlights.map((highlight, index) => (
                        <Badge
                          key={index}
                          variant="secondary"
                          className="text-xs cursor-pointer hover:bg-chart-4/120/20 bg-chart-4/120/10 text-chart-4"
                          onClick={() => handleRemoveHighlight(highlight)}
                        >
                          ⭐ {highlight} ×
                        </Badge>
                      ))}
                    </div>
                  )}

                  {/* Add New Highlight */}
                  <div className="flex gap-2">
                    <Input
                      value={newHighlight}
                      onChange={(e) => setNewHighlight(e.target.value)}
                      onKeyPress={(e) => handleKeyPress(e, 'highlight')}
                      placeholder="Add a session highlight..."
                      className="flex-1"
                    />
                    <Button
                      type="button"
                      onClick={handleAddHighlight}
                      variant="ghost"
                      size="sm"
                      disabled={!newHighlight.trim() || formData.highlights.length >= 5}
                    >
                      <Plus size={16} />
                    </Button>
                  </div>
                  <p className="text-xs text-muted-foreground">
                    ({formData.highlights.length}/5 highlights)
                  </p>
                </div>

                {/* Challenges */}
                <div className="space-y-3">
                  <label className="text-sm font-medium flex items-center gap-2">
                    <AlertTriangle size={16} className="text-destructive" />
                    Challenges & Issues
                  </label>

                  {/* Existing Challenges */}
                  {formData.challenges.length > 0 && (
                    <div className="flex flex-wrap gap-2">
                      {formData.challenges.map((challenge, index) => (
                        <Badge
                          key={index}
                          variant="secondary"
                          className="text-xs cursor-pointer hover:bg-destructive/20 bg-destructive/15 text-destructive"
                          onClick={() => handleRemoveChallenge(challenge)}
                        >
                          ⚠️ {challenge} ×
                        </Badge>
                      ))}
                    </div>
                  )}

                  {/* Add New Challenge */}
                  <div className="flex gap-2">
                    <Input
                      value={newChallenge}
                      onChange={(e) => setNewChallenge(e.target.value)}
                      onKeyPress={(e) => handleKeyPress(e, 'challenge')}
                      placeholder="Add a challenge or issue..."
                      className="flex-1"
                    />
                    <Button
                      type="button"
                      onClick={handleAddChallenge}
                      variant="ghost"
                      size="sm"
                      disabled={!newChallenge.trim() || formData.challenges.length >= 5}
                    >
                      <Plus size={16} />
                    </Button>
                  </div>
                  <p className="text-xs text-muted-foreground">
                    ({formData.challenges.length}/5 challenges)
                  </p>
                </div>

                {/* Notes */}
                <div className="space-y-2">
                  <label className="text-sm font-medium">Additional Notes</label>
                  <Textarea
                    value={formData.notes}
                    onChange={(e) => setFormData(prev => ({ ...prev, notes: e.target.value }))}
                    placeholder="Private GM notes, observations, things to remember..."
                    className="min-h-20"
                  />
                </div>

                {/* Next Session */}
                <div className="space-y-2">
                  <label className="text-sm font-medium">Next Session Preparation</label>
                  <Textarea
                    value={formData.nextSession}
                    onChange={(e) => setFormData(prev => ({ ...prev, nextSession: e.target.value }))}
                    placeholder="What to prepare for next session? Plot hooks, NPCs to review, etc..."
                    className="min-h-20"
                  />
                </div>

                {/* Actions */}
                <div className="flex items-center justify-between pt-4">
                  <div className="flex items-center gap-3 text-sm text-muted-foreground">
                    <span>Duration: {formatDuration(formData.duration)}</span>
                    {formData.xpGained > 0 && (
                      <span className="flex items-center gap-1">
                        <Trophy size={14} />
                        {formData.xpGained} XP
                      </span>
                    )}
                  </div>
                  <div className="flex gap-3">
                    <Button
                      type="button"
                      variant="ghost"
                      onClick={onClose}
                      disabled={isSubmitting}
                    >
                      Cancel
                    </Button>
                    <Button
                      type="submit"
                      variant="primary"
                      disabled={isSubmitting}
                      className="min-w-20"
                    >
                      {isSubmitting ? 'Saving...' : (session ? 'Update' : 'Create')}
                    </Button>
                  </div>
                </div>
              </form>
            </CardContent>
          </Card>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  )
}

import React, { useState } from 'react'
import {
  Card,
  CardContent,
  Button,
  Input,
  Progress,
  Badge
} from '../ui'
import { cn } from '@/lib/utils'
import { Heart, Star, Eye, Brain, BicepsFlexed, Users, Edit3, AlertTriangle, Scale } from 'lucide-react'
import { getXPThreshold, type Attributes } from '../../models/Character'
import { useXPStore } from '../../stores/xpStore'
import { useCharacterStore } from '../../stores/characterStore'

// Use the standard Attributes from Character model
type CharacterStats = Attributes

interface CharacterData {
  id: string
  name: string
  class: string
  level: number
  hp: { current: number; max: number }
  xp: number // Dungeon World uses simple XP, not current/max
  stats: CharacterStats
}

const mockCharacter: CharacterData = {
  id: "eldara-moonwhisper",
  name: "Eldara Moonwhisper",
  class: "Wizard",
  level: 5,
  hp: { current: 16, max: 18 }, // Corrected: Base 4 + Constitution 14 = 18
  xp: 11, // Corrected: Level 5 character with 11 XP (needs 12 to level up: 5+7)
  stats: {
    STR: 8,
    DEX: 12,
    CON: 14,
    INT: 18,
    WIS: 16,
    CHA: 10
  }
}

const statIcons = {
  STR: BicepsFlexed,
  DEX: Eye,
  CON: Heart,
  INT: Brain,
  WIS: Eye,
  CHA: Users
}

// Helper function to get active debilities
const getActiveDebilities = (character: any) => {
  if (!character.debilities) return []

  const debilityList = [
    { key: 'weak', name: 'Weak', color: 'text-error' },
    { key: 'shaky', name: 'Shaky', color: 'text-(--orange-600)' },
    { key: 'sick', name: 'Sick', color: 'text-success' },
    { key: 'stunned', name: 'Stunned', color: 'text-(--magic-600)' },
    { key: 'confused', name: 'Confused', color: 'text-info' },
    { key: 'scarred', name: 'Scarred', color: 'text-muted-foreground' }
  ]

  return debilityList.filter(debility => character.debilities[debility.key])
}

// Helper function to get active bonds summary
const getActiveBonds = (character: any) => {
  if (!character.bonds) return []
  return character.bonds.filter((bond: any) => !bond.resolved).slice(0, 3) // Show max 3
}

export const CharacterSheet: React.FC = () => {
  // Connect to character store
  const { getActiveCharacter, updateCharacter } = useCharacterStore()
  const activeCharacter = getActiveCharacter()

  // Convert store character to display format if needed
  const character = activeCharacter ? {
    id: activeCharacter.id,
    name: activeCharacter.name,
    class: activeCharacter.class,
    level: activeCharacter.level,
    hp: activeCharacter.hp,
    xp: activeCharacter.xp,
    stats: activeCharacter.attributes // Use attributes from store
  } : mockCharacter // Fallback to mock for demo

  // Ensure stats are numbers, not {value, modifier} objects
  const normalizedStats = React.useMemo(() => {
    const stats = character.stats || {}
    const normalized: Attributes = {
      STR: typeof stats.STR === 'object' ? stats.STR.value : stats.STR || 10,
      DEX: typeof stats.DEX === 'object' ? stats.DEX.value : stats.DEX || 10,
      CON: typeof stats.CON === 'object' ? stats.CON.value : stats.CON || 10,
      INT: typeof stats.INT === 'object' ? stats.INT.value : stats.INT || 10,
      WIS: typeof stats.WIS === 'object' ? stats.WIS.value : stats.WIS || 10,
      CHA: typeof stats.CHA === 'object' ? stats.CHA.value : stats.CHA || 10,
    }
    return normalized
  }, [character.stats])

  // Use normalized stats for display
  const displayCharacter = { ...character, stats: normalizedStats }

  const [isEditing, setIsEditing] = useState(false)

  // Connect to XP store for display only
  const { characterXP, characterLevel } = useXPStore()

  // Use real-time data if available, otherwise fall back to character data
  const realTimeXP = characterXP[displayCharacter.id] !== undefined ? characterXP[displayCharacter.id] : displayCharacter.xp
  const realTimeLevel = characterLevel[displayCharacter.id] !== undefined ? characterLevel[displayCharacter.id] : displayCharacter.level

  // Get essential info for display
  const activeDebilities = getActiveDebilities(character)
  const activeBonds = getActiveBonds(character)
  const alignment = character.alignment || 'Neutral'

  const getStatModifier = (stat: number): string => {
    const modifier = Math.floor((stat - 10) / 2)
    return modifier >= 0 ? `+${modifier}` : `${modifier}`
  }

  const handleStatChange = (stat: keyof Attributes, value: number) => {
    const clampedValue = Math.max(1, Math.min(20, value))
    if (activeCharacter) {
      updateCharacter(displayCharacter.id, {
        attributes: {
          ...activeCharacter.attributes,
          [stat]: clampedValue
        }
      })
    }
  }

  return (
    <div className="space-y-4">
      {/* Compact Header with Key Info */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
        {/* Character Identity */}
        <Card variant="magical" className="lg:col-span-2">
          <CardContent className="p-4 pt-4">
            <div className="flex items-center justify-between">
              <div>
                <h1 className="text-xl font-display font-bold flex items-center gap-2">
                  {displayCharacter.name}
                <Button
                  variant={isEditing ? "secondary" : "ghost"}
                  size="sm"
                  onClick={() => setIsEditing(!isEditing)}
                  className="opacity-60 hover:opacity-100 h-6 w-6 p-0"
                >
                  <Edit3 size={12} />
                </Button>
              </h1>
              <div className="text-sm text-muted-foreground flex items-center gap-2">
                Level {realTimeLevel} {displayCharacter.class}
                {/* Alignment indicator */}
                <Badge variant="secondary" className="gap-1 text-xs">
                  <Scale size={10} />
                  {alignment}
                </Badge>
                {/* Debility warnings */}
                {activeDebilities.length > 0 && (
                  <Badge variant="destructive" className="gap-1 text-xs">
                    <AlertTriangle size={10} />
                    {activeDebilities.length} Debil{activeDebilities.length === 1 ? 'ity' : 'ities'}
                  </Badge>
                )}
              </div>
            </div>
            <Badge variant="experience" className="shrink-0">
              <Star size={12} />
              Level {realTimeLevel}
            </Badge>
            </div>
          </CardContent>
        </Card>

        {/* Health & XP */}
        <Card variant="surface">
          <CardContent className="p-4 pt-4 space-y-3">
            <div className="flex items-center justify-between">
