              <span className="text-xs font-medium">Experience</span>
              <span className="text-xs font-mono">{realTimeXP}/{getXPThreshold(realTimeLevel)}</span>
            </div>
            <Progress
              variant="experience"
              value={realTimeXP}
              max={getXPThreshold(realTimeLevel)}
              className="h-2"
            />
