                          Context: {timelineEntry.context}
                        </div>
                      </div>
                    </motion.div>
                  ))}
                </div>
              </div>
            )}

            {/* Relationships */}
            {displayWikiPage.relationshipSummary && (
              <div>
                <h3 className="font-medium mb-3 flex items-center gap-2">
                  <Users size={16} />
                  Relationships
                </h3>
                <div
                  className="p-4 rounded-lg border"
                  style={{
                    backgroundColor: 'var(--card)',
                    borderColor: 'var(--border)'
                  }}
                >
                  <p className="text-sm leading-relaxed">
                    {displayWikiPage.relationshipSummary}
                  </p>
                </div>
              </div>
            )}

            {/* Mysteries */}
            {displayWikiPage.mysteries.length > 0 && (
              <div>
                <h3 className="font-medium mb-3 flex items-center gap-2">
                  <HelpCircle size={16} />
                  Mysteries & Questions
                </h3>
                <div className="space-y-2">
                  {displayWikiPage.mysteries.map((mystery, index) => (
                    <div
                      key={index}
                      className="p-3 rounded-lg border border-purple-200 bg-accent/12"
                    >
                      <p className="text-sm text-accent leading-relaxed">
                        {mystery}
                      </p>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* User Content Section */}
            {displayWikiPage.userContent && (
              <div>
                <h3 className="font-medium mb-3 flex items-center gap-2">
                  <Edit size={16} />
                  Your Notes
                </h3>
                <div
                  className="p-4 rounded-lg border"
                  style={{
                    backgroundColor: 'var(--card)',
                    borderColor: 'var(--border)'
                  }}
                >
                  <p className="text-sm leading-relaxed whitespace-pre-wrap">
                    {displayWikiPage.userContent}
                  </p>
                </div>
              </div>
            )}

            {/* Empty state for new entities */}
            {displayWikiPage.timeline.length === 0 && displayWikiPage.keyFacts.length === 0 && (
              <div className="text-center py-8">
                <div className="opacity-50 mb-4">
                  <BookOpen size={48} />
                </div>
                <h3 className="text-lg font-medium mb-2">Wiki Page Generated</h3>
                <p className="text-muted-foreground">
                  As you mention {entity.name} in your chronicle entries, this wiki will automatically populate with facts, timeline events, and relationships.
                </p>
              </div>
            )}
          </CardContent>
        </Card>
      </motion.div>
    </motion.div>
  )
}

/**
 * Context-Aware System for ZimboMate V2
 * Provides intelligent suggestions based on character state, game context, and current situation
 * Phase 4C: Desktop Power Features - Smart Integration System
 */

import React, { useState, useEffect, useMemo } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { 
  Lightbulb, 
  Zap, 
  Shield, 
  Heart, 
  Sword, 
  BookOpen, 
  AlertTriangle, 
  TrendingUp,
  Target,
  Clock,
  X,
  ChevronRight,
  Sparkles
} from 'lucide-react'
import { Card, CardContent, Button, Badge } from '../ui'
import { useCharacterStore } from '../../stores/characterStore'
import { useSessionStore } from '../../stores/sessionStore'
import { useGameStateStore } from '../../stores/gameStateStore'
import { type Character, getEffectiveModifier, shouldLevelUp } from '../../models/Character'
import type { Move } from '../../models/Move'

// Suggestion types
export type SuggestionType = 
  | 'move' 
  | 'equipment' 
  | 'health' 
  | 'resource' 
  | 'advancement' 
  | 'tactical' 
  | 'roleplay'
  | 'warning'

export type SuggestionPriority = 'low' | 'medium' | 'high' | 'critical'

export interface ContextSuggestion {
  id: string
  type: SuggestionType
  priority: SuggestionPriority
  title: string
  description: string
  reason: string
  action?: {
    label: string
    onClick: () => void
  }
  dismissible: boolean
  timestamp: Date
}

interface ContextAwareSystemProps {
  characterId?: string
  context?: 'character' | 'dice' | 'moves' | 'equipment' | 'session' | 'campaign'
  maxSuggestions?: number
  showDismissed?: boolean
  compact?: boolean
}

export const ContextAwareSystem: React.FC<ContextAwareSystemProps> = ({
  characterId,
  context = 'character',
  maxSuggestions = 5,
  showDismissed = false,
  compact = false
}) => {
  const { getActiveCharacter, getCharacter, healCharacter, levelUpCharacter } = useCharacterStore()
  const { rollHistory, combat, currentSession } = useSessionStore()
  const { gameTime, environment, globalModifiers } = useGameStateStore()
  
  const [dismissedSuggestions, setDismissedSuggestions] = useState<Set<string>>(new Set())
  const [expandedSuggestion, setExpandedSuggestion] = useState<string | null>(null)

  // Get the target character
  const character = characterId ? getCharacter(characterId) : getActiveCharacter()

  // Generate context-aware suggestions
  const suggestions = useMemo(() => {
    if (!character) return []

    const suggestions: ContextSuggestion[] = []
    const now = new Date()

    // Health-related suggestions
    if (character.hp.current <= character.hp.max * 0.25) {
      suggestions.push({
        id: 'critical-health',
        type: 'health',
        priority: 'critical',
        title: 'Critical Health!',
        description: `${character.name} has only ${character.hp.current}/${character.hp.max} HP remaining.`,
        reason: 'Character is in immediate danger',
        action: {
          label: 'Heal Character',
          onClick: () => healCharacter(character.id, Math.ceil(character.hp.max * 0.5))
        },
        dismissible: false,
        timestamp: now
      })
    } else if (character.hp.current <= character.hp.max * 0.5) {
      suggestions.push({
        id: 'low-health',
        type: 'health',
        priority: 'high',
        title: 'Low Health',
        description: `Consider healing or resting. Current HP: ${character.hp.current}/${character.hp.max}`,
        reason: 'Character health is below 50%',
        action: {
          label: 'Heal Character',
          onClick: () => healCharacter(character.id, Math.ceil(character.hp.max * 0.25))
        },
        dismissible: true,
        timestamp: now
      })
    }

    // Advancement suggestions
    if (shouldLevelUp(character)) {
      suggestions.push({
        id: 'level-up-ready',
        type: 'advancement',
        priority: 'high',
        title: 'Ready to Level Up!',
        description: `${character.name} has enough XP to advance to level ${character.level + 1}.`,
        reason: `Has ${character.xp} XP, needs ${character.level + 7}`,
        action: {
          label: 'Level Up',
          onClick: () => levelUpCharacter(character.id)
        },
        dismissible: false,
        timestamp: now
      })
    }

    // Load/encumbrance suggestions
    if (character.load.current > character.load.max) {
      suggestions.push({
        id: 'overencumbered',
        type: 'warning',
        priority: 'high',
        title: 'Overencumbered!',
        description: `Carrying ${character.load.current}/${character.load.max} load. Take -1 ongoing until fixed.`,
        reason: 'Load exceeds maximum capacity',
        dismissible: true,
        timestamp: now
      })
    } else if (character.load.current >= character.load.max * 0.8) {
      suggestions.push({
        id: 'heavy-load',
        type: 'equipment',
        priority: 'medium',
        title: 'Heavy Load',
        description: `Nearing max load (${character.load.current}/${character.load.max}). Consider dropping items.`,
        reason: 'Load is at 80% capacity',
        dismissible: true,
        timestamp: now
      })
    }

    // Debility warnings
    const activeDebilities = Object.entries(character.debilities).filter(([_, active]) => active)
    if (activeDebilities.length > 0) {
      suggestions.push({
        id: 'active-debilities',
        type: 'warning',
        priority: 'high',
        title: 'Active Debilities',
        description: `${activeDebilities.map(([name]) => name).join(', ')} affecting dice rolls.`,
        reason: 'Debilities reduce attribute modifiers',
        dismissible: true,
        timestamp: now
      })
    }

    // Combat-specific suggestions
    if (combat.isActive && context === 'dice') {
      const recentRolls = rollHistory.slice(0, 3)
      const recentFailures = recentRolls.filter(roll => roll.result === 'failure').length
      
      if (recentFailures >= 2) {
        suggestions.push({
          id: 'combat-struggling',
          type: 'tactical',
          priority: 'medium',
          title: 'Consider Different Tactics',
          description: 'Recent failures suggest trying a different approach or using Aid/Interfere.',
          reason: `${recentFailures} failures in last 3 rolls`,
          dismissible: true,
          timestamp: now
        })
      }

      // Suggest defensive moves if health is low
      if (character.hp.current <= character.hp.max * 0.4) {
        suggestions.push({
          id: 'combat-defensive',
          type: 'tactical',
          priority: 'high',
          title: 'Consider Defensive Actions',
          description: 'Low health in combat - consider Defend or retreating to safety.',
          reason: 'Low health during active combat',
          dismissible: true,
          timestamp: now
        })
      }
    }

    // Move suggestions based on context
    if (context === 'moves') {
      // Suggest contextual moves based on character state
      if (character.class === 'Wizard' && character.hp.current <= character.hp.max * 0.3) {
        suggestions.push({
          id: 'wizard-defensive-spells',
          type: 'move',
          priority: 'medium',
          title: 'Defensive Spells Available',
          description: 'Consider casting Shield or other protective spells.',
          reason: 'Wizard with low health should use defensive magic',
          dismissible: true,
          timestamp: now
        })
      }

      if (character.class === 'Cleric' && character.hp.current <= character.hp.max * 0.6) {
        suggestions.push({
          id: 'cleric-healing',
          type: 'move',
          priority: 'medium',
          title: 'Healing Magic Available',
          description: 'Use Cure Light Wounds or other healing spells.',
          reason: 'Cleric should consider self-healing',
          dismissible: true,
          timestamp: now
        })
      }
    }

    // Equipment suggestions
    if (context === 'equipment') {
      // Suggest equipment optimization based on class and stats
      const strMod = getEffectiveModifier('STR', character.attributes, character.debilities)
      const dexMod = getEffectiveModifier('DEX', character.attributes, character.debilities)

      if (character.class === 'Fighter' && strMod >= 2 && character.load.current < character.load.max * 0.7) {
        suggestions.push({
          id: 'fighter-heavy-armor',
          type: 'equipment',
          priority: 'low',
          title: 'Consider Heavier Armor',
          description: 'High STR allows for better armor without encumbrance issues.',
          reason: `STR modifier is +${strMod}, load capacity available`,
          dismissible: true,
          timestamp: now
        })
      }

      if (dexMod >= 2 && character.class === 'Thief') {
        suggestions.push({
          id: 'thief-ranged-weapons',
          type: 'equipment',
          priority: 'low',
          title: 'Ranged Weapons Recommended',
          description: 'High DEX makes ranged combat very effective.',
          reason: `DEX modifier is +${dexMod}`,
          dismissible: true,
          timestamp: now
        })
      }
    }

    // Session-specific suggestions
    if (currentSession && context === 'session') {
      const sessionDuration = Date.now() - currentSession.startTime.getTime()
      const hoursPlayed = sessionDuration / (1000 * 60 * 60)

      if (hoursPlayed > 3 && character.hp.current === character.hp.max) {
        suggestions.push({
          id: 'long-session-rest',
          type: 'roleplay',
          priority: 'low',
          title: 'Consider Taking a Rest',
          description: 'Long session - characters might want to rest and recover.',
          reason: `Session running for ${Math.floor(hoursPlayed)} hours`,
          dismissible: true,
          timestamp: now
        })
      }
    }

    // Environmental suggestions
    if (environment.lighting === 'dark' && character.race !== 'Elf' && character.race !== 'Dwarf') {
      suggestions.push({
        id: 'darkness-penalty',
        type: 'warning',
        priority: 'medium',
        title: 'Darkness Affects Vision',
        description: 'Poor lighting may impose penalties on sight-based actions.',
        reason: 'Current environment is dark',
        dismissible: true,
        timestamp: now
      })
    }

    // XP opportunity suggestions
    const recentFailures = rollHistory.slice(0, 5).filter(roll => roll.result === 'failure').length
    if (recentFailures === 0 && rollHistory.length >= 5) {
      suggestions.push({
        id: 'xp-opportunity',
        type: 'roleplay',
        priority: 'low',
        title: 'XP Opportunity',
        description: 'No recent failures - consider taking risks for XP and story development.',
        reason: 'No failures in last 5 rolls',
        dismissible: true,
        timestamp: now
      })
    }

    // Sort by priority and filter dismissed
    return suggestions
      .sort((a, b) => {
        const priorityOrder = { critical: 4, high: 3, medium: 2, low: 1 }
        return priorityOrder[b.priority] - priorityOrder[a.priority]
      })
      .filter(suggestion => showDismissed || !dismissedSuggestions.has(suggestion.id))
      .slice(0, maxSuggestions)
  }, [
    character,
    context,
    rollHistory,
    combat,
    currentSession,
    environment,
    dismissedSuggestions,
    showDismissed,
    maxSuggestions,
    healCharacter,
    levelUpCharacter
  ])

  const handleDismiss = (suggestionId: string) => {
    setDismissedSuggestions(prev => new Set([...prev, suggestionId]))
  }

  const getSuggestionIcon = (type: SuggestionType) => {
    switch (type) {
      case 'move': return BookOpen
      case 'equipment': return Shield
      case 'health': return Heart
      case 'resource': return Zap
      case 'advancement': return TrendingUp
      case 'tactical': return Target
      case 'roleplay': return Sparkles
      case 'warning': return AlertTriangle
      default: return Lightbulb
    }
  }

  const getPriorityColor = (priority: SuggestionPriority) => {
    switch (priority) {
      case 'critical': return 'var(--destructive)'
      case 'high': return 'var(--chart-4)'
      case 'medium': return 'var(--primary)'
      case 'low': return 'var(--muted-foreground)'
    }
  }

  if (!character || suggestions.length === 0) {
    return null
  }

  return (
    <Card variant="magical">
      <CardContent>
        <div className="space-y-4">
          <div className="flex items-center gap-2">
            <Lightbulb className="text-primary" 
              size={20} />
            <h3 className="font-display text-lg">Smart Suggestions</h3>
            <Badge variant="secondary" size="sm">
              {suggestions.length}
            </Badge>
          </div>

          <AnimatePresence>
            {suggestions.map((suggestion, index) => {
              const Icon = getSuggestionIcon(suggestion.type)
              const isExpanded = expandedSuggestion === suggestion.id

              return (
                <motion.div
                  key={suggestion.id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -20 }}
                  transition={{ duration: 0.3, delay: index * 0.1 }}
                >
                  <Card 
                    variant="outline"
                    className={`cursor-pointer transition-all duration-200 ${
                      isExpanded ? 'ring-2' : 'hover:shadow-md'
                    }`}
                    style={{
                      ringColor: isExpanded ? getPriorityColor(suggestion.priority) : undefined
                    }}
                    onClick={() => setExpandedSuggestion(
                      isExpanded ? null : suggestion.id
                    )}
                  >
                    <CardContent>
                      <div className="flex items-start gap-3">
                        <div 
                          className="w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0"
                          style={{ 
                            backgroundColor: getPriorityColor(suggestion.priority),
                            opacity: 0.2 
                          }}
                        >
                          <Icon 
                            size={16} 
                            style={{ color: getPriorityColor(suggestion.priority) }}
                          />
                        </div>

                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 mb-1">
                            <h4 className="font-medium text-sm truncate">
                              {suggestion.title}
                            </h4>
                            <Badge 
                              variant={suggestion.priority === 'critical' ? 'destructive' : 'secondary'}
                              size="xs"
                            >
                              {suggestion.priority}
                            </Badge>
                          </div>

                          <p 
                            className="text-sm mb-2 text-muted-foreground">
                            {suggestion.description}
                          </p>

                          <AnimatePresence>
                            {isExpanded && (
                              <motion.div
                                initial={{ opacity: 0, height: 0 }}
                                animate={{ opacity: 1, height: 'auto' }}
                                exit={{ opacity: 0, height: 0 }}
                                transition={{ duration: 0.2 }}
                                className="space-y-3"
                              >
                                <div 
                                  className="text-xs p-2 rounded"
                                  style={{ 
                                    backgroundColor: 'var(--card)',
                                    color: 'var(--muted-foreground)'
                                  }}
                                >
                                  <strong>Why:</strong> {suggestion.reason}
                                </div>

                                <div className="flex items-center gap-2">
                                  {suggestion.action && (
                                    <Button
                                      variant="primary"
                                      size="xs"
                                      onClick={(e) => {
                                        e.stopPropagation()
                                        suggestion.action!.onClick()
                                      }}
                                    >
                                      {suggestion.action.label}
                                    </Button>
                                  )}

                                  {suggestion.dismissible && (
                                    <Button
                                      variant="ghost"
                                      size="xs"
                                      onClick={(e) => {
                                        e.stopPropagation()
                                        handleDismiss(suggestion.id)
                                      }}
                                    >
                                      <X size={12} />
                                      Dismiss
                                    </Button>
                                  )}
                                </div>
                              </motion.div>
                            )}
                          </AnimatePresence>
                        </div>

                        <div className="flex items-center gap-1 flex-shrink-0">
                          {!compact && (
                            <span 
                              className="text-xs text-muted-foreground">
                              <Clock size={10} className="inline mr-1" />
                              {suggestion.timestamp.toLocaleTimeString([], { 
                                hour: '2-digit', 
                                minute: '2-digit' 
                              })}
                            </span>
                          )}
                          
                          <ChevronRight 
                            size={16}
                            className={`transition-transform duration-200 ${
                              isExpanded ? 'rotate-90' : ''
                            }`} />
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                </motion.div>
              )
            })}
          </AnimatePresence>

          {dismissedSuggestions.size > 0 && (
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setDismissedSuggestions(new Set())}
              className="w-full"
            >
              Show {dismissedSuggestions.size} Dismissed Suggestion{dismissedSuggestions.size !== 1 ? 's' : ''}
            </Button>
          )}
        </div>
      </CardContent>
    </Card>
  )
}

export default ContextAwareSystem

/**
 * Debility Card - Individual debility toggle and display
 * Phase 4A: Essential for managing individual debilities
 */

import React from 'react'
import { motion } from 'framer-motion'
import { 
  Zap, 
  Skull, 
  AlertTriangle, 
  HelpCircle,
  Heart,
  User,
  Activity
} from 'lucide-react'
import * as Switch from '@radix-ui/react-switch'
import { Card, CardContent, Badge } from '../../ui'
import type { Debilities, Attribute } from '../../../models/Character'

interface DebilityDefinition {
  key: keyof Debilities
  name: string
  attribute: Attribute
  description: string
  effect: string
  color: string
  active: boolean
}

interface DebilityCardProps {
  debility: DebilityDefinition
  onToggle: (active: boolean) => void
}

export const DebilityCard: React.FC<DebilityCardProps> = ({
  debility,
  onToggle
}) => {
  const getDebilityIcon = (debilityKey: keyof Debilities) => {
    switch (debilityKey) {
      case 'weak':
        return <Activity size={20} className="text-destructive" />
      case 'shaky':
        return <Zap size={20} className="text-chart-4" />
      case 'sick':
        return <AlertTriangle size={20} className="text-chart-2" />
      case 'stunned':
        return <HelpCircle size={20} className="text-primary" />
      case 'confused':
        return <HelpCircle size={20} className="text-accent" />
      case 'scarred':
        return <Heart size={20} className="text-accent" />
      default:
        return <AlertTriangle size={20} className="text-muted-foreground" />
    }
  }

  const getAttributeIcon = (attribute: Attribute) => {
    switch (attribute) {
      case 'STR':
        return <Activity size={16} />
      case 'DEX':
        return <Zap size={16} />
      case 'CON':
        return <Heart size={16} />
      case 'INT':
        return <User size={16} />
      case 'WIS':
        return <HelpCircle size={16} />
      case 'CHA':
        return <User size={16} />
      default:
        return <AlertTriangle size={16} />
    }
  }

  return (
    <Card 
      variant={debility.active ? "magical" : "surface"}
      className={`relative transition-all duration-300 ${
        debility.active ? 'ring-2 ring-red-200' : ''
      }`}
    >
      <CardContent>
        <div className="space-y-4">
          {/* Header */}
          <div className="flex items-start justify-between">
            <div className="flex items-center gap-3">
              {getDebilityIcon(debility.key)}
              <div>
                <h4 className="font-medium">{debility.name}</h4>
                <Badge variant="secondary" className={`gap-1 text-xs ${debility.color}`}>
                  {getAttributeIcon(debility.attribute)}
                  {debility.attribute}
                </Badge>
              </div>
            </div>
            
            {/* Toggle Switch */}
            <Switch.Root
              checked={debility.active}
              onCheckedChange={onToggle}
              className={`
                relative inline-flex h-6 w-11 items-center rounded-full transition-colors
                ${debility.active 
                  ? 'bg-destructive/120' 
                  : 'bg-muted'
                }
              `}
            >
              <Switch.Thumb
                className={`
                  inline-block h-4 w-4 transform rounded-full bg-card transition-transform
                  ${debility.active ? 'translate-x-6' : 'translate-x-1'}
                `}
              />
            </Switch.Root>
          </div>

          {/* Description */}
          <div className="space-y-2">
            <p 
              className="text-sm text-muted-foreground">
              {debility.description}
            </p>
            
            <div className="flex items-center gap-2">
              <Badge 
                variant={debility.active ? "default" : "secondary"}
                className={`text-xs ${debility.active ? 'bg-destructive/15 text-destructive' : ''}`}
              >
                {debility.effect}
              </Badge>
            </div>
          </div>

          {/* Active State Indicator */}
          {debility.active && (
            <motion.div
              initial={{ opacity: 0, scale: 0.8 }}
              animate={{ opacity: 1, scale: 1 }}
              className="p-3 bg-destructive/12 rounded-lg border border-destructive/30"
            >
              <div className="flex items-center gap-2 text-sm text-destructive">
                <AlertTriangle size={14} />
                <span className="font-medium">Active Debility</span>
              </div>
              <p className="text-xs text-destructive mt-1">
                This debility is currently affecting your {debility.attribute} rolls.
              </p>
            </motion.div>
          )}
        </div>
      </CardContent>
    </Card>
  )
}

/**
 * Debility Effects - Shows how debilities affect dice rolls and modifiers
 * Phase 4A: Essential for understanding debility impact
 */

import React from 'react'
import { motion } from 'framer-motion'
import { 
  TrendingDown,
  Dice6,
  Activity,
  Zap,
  Heart,
  HelpCircle,
  User
} from 'lucide-react'
import { Card, CardContent, Badge } from '../../ui'
import type { Character, Attribute, Debilities } from '../../../models/Character'
import { getAttributeModifier, getEffectiveModifier } from '../../../models/Character'

interface DebilityEffectsProps {
  character: Character
  debilities: Debilities
}

export const DebilityEffects: React.FC<DebilityEffectsProps> = ({
  character,
  debilities
}) => {
  const getScore = (v: any): number => {
    if (typeof v === 'number') return v
    if (v && typeof v.value === 'number') return v.value
    return 10
  }

  // Normalize attributes to numeric scores in case store holds { value, modifier }
  const normalizedAttributes = (Object.keys(character.attributes) as Attribute[]).reduce((acc, key) => {
    ;(acc as any)[key] = getScore((character.attributes as any)[key])
    return acc
  }, {} as Record<Attribute, number>) as any
  const getAttributeIcon = (attribute: Attribute) => {
    switch (attribute) {
      case 'STR':
        return <Activity size={16} />
      case 'DEX':
        return <Zap size={16} />
      case 'CON':
        return <Heart size={16} />
      case 'INT':
        return <User size={16} />
      case 'WIS':
        return <HelpCircle size={16} />
      case 'CHA':
        return <User size={16} />
      default:
        return <Activity size={16} />
    }
  }

  const attributeEffects = (Object.keys(character.attributes) as Attribute[]).map(attr => {
    const score = getScore((character.attributes as any)[attr])
    const baseModifier = getAttributeModifier(score)
    const effectiveModifier = getEffectiveModifier(attr, normalizedAttributes as any, debilities)
    const penalty = baseModifier - effectiveModifier
    
    return {
      attribute: attr,
      score,
      baseModifier,
      effectiveModifier,
      penalty,
      hasDebility: penalty > 0
    }
  }).filter(effect => effect.hasDebility)

  const totalPenalty = attributeEffects.reduce((sum, effect) => sum + effect.penalty, 0)

  if (attributeEffects.length === 0) {
    return null
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.3 }}
    >
      <Card variant="magical">
        <CardContent>
          <div className="space-y-4">
            {/* Header */}
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <TrendingDown size={20} className="text-destructive" />
                <h3 className="text-lg font-medium">Debility Effects</h3>
              </div>
              <Badge variant="default" className="gap-1 bg-destructive/15 text-destructive">
                <Dice6 size={12} />
                -{totalPenalty} to rolls
              </Badge>
            </div>

            {/* Affected Attributes */}
            <div className="grid gap-3 md:grid-cols-2">
              {attributeEffects.map((effect, index) => (
                <motion.div
                  key={effect.attribute}
                  initial={{ opacity: 0, x: -20 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ duration: 0.3, delay: index * 0.1 }}
                  className="p-4 bg-destructive/12 rounded-lg border border-destructive/30"
                >
                  <div className="flex items-center justify-between mb-2">
                    <div className="flex items-center gap-2">
                      {getAttributeIcon(effect.attribute)}
                      <span className="font-medium">{effect.attribute}</span>
                      <Badge variant="secondary" className="text-xs">
                        Score: {effect.score}
                      </Badge>
                    </div>
                    <div className="text-right">
                      <div className="text-sm text-destructive">
                        <span className="line-through">+{effect.baseModifier}</span>
                        {' → '}
                        <span className="font-bold">
                          {effect.effectiveModifier >= 0 ? '+' : ''}{effect.effectiveModifier}
                        </span>
                      </div>
                    </div>
                  </div>
                  
                  <div className="flex items-center gap-2 text-sm text-destructive">
                    <TrendingDown size={14} />
                    <span>-{effect.penalty} penalty from debility</span>
                  </div>
                </motion.div>
              ))}
            </div>

            {/* Summary */}
            <div className="p-4 bg-chart-4/12 rounded-lg border border-chart-4/30">
              <div className="flex items-start gap-3">
                <Dice6 size={20} className="text-chart-4 flex-shrink-0 mt-0.5" />
                <div>
                  <h4 className="font-medium text-chart-4 mb-1">
                    Dice Roll Impact
                  </h4>
                  <p className="text-sm text-chart-4">
                    When making moves that use affected attributes, you'll roll 2d6 with reduced modifiers. 
                    This makes success (10+) harder to achieve and increases the chance of failure (6-).
                  </p>
                  {totalPenalty >= 3 && (
                    <p className="text-sm text-destructive mt-2 font-medium">
                      ⚠️ Warning: Multiple debilities are severely impacting your character's effectiveness!
                    </p>
                  )}
                </div>
              </div>
            </div>

            {/* Healing Reminder */}
            <div className="text-center p-3 bg-primary/10 rounded-lg">
              <p className="text-sm text-primary">
                <strong>Remember:</strong> Debilities can be healed through rest, medical attention, 
                magical healing, or specific moves. Work with your GM to find ways to recover!
              </p>
            </div>
          </div>
        </CardContent>
      </Card>
    </motion.div>
  )
}

/**
 * Equipment3DViewer - Interactive 3D item renderer with rotation and zoom
 * Provides immersive 3D visualization for equipment items
 */

import React, { useRef, useState, useMemo } from 'react'
import { Canvas, useFrame } from '@react-three/fiber'
import { OrbitControls, Environment, ContactShadows } from '@react-three/drei'
import { motion } from 'framer-motion'
import * as THREE from 'three'
import { Item } from '../../models/Equipment'
import { Card, CardContent, Button } from '../ui'
import { RotateCcw, ZoomIn, ZoomOut, Maximize2 } from 'lucide-react'

interface Equipment3DViewerProps {
  item: Item
  width?: number
  height?: number
  autoRotate?: boolean
  showControls?: boolean
  onInspect?: () => void
  className?: string
}

// 3D Item Model Component
const ItemModel3D: React.FC<{ item: Item; autoRotate: boolean }> = ({ item, autoRotate }) => {
  const meshRef = useRef<THREE.Mesh>(null)
  const [hovered, setHovered] = useState(false)

  useFrame((state) => {
    if (meshRef.current) {
      if (autoRotate) {
        meshRef.current.rotation.y += 0.01
      }
      
      // Subtle floating animation
      meshRef.current.position.y = Math.sin(state.clock.elapsedTime) * 0.1
      
      // Hover effect
      if (hovered) {
        meshRef.current.scale.setScalar(1.1)
      } else {
        meshRef.current.scale.setScalar(1)
      }
    }
  })

  // Generate procedural 3D model based on item type
  const geometry = useMemo(() => {
    switch (item.category) {
      case 'weapon':
        if (item.name.toLowerCase().includes('sword')) {
          return (
            <group ref={meshRef}>
              {/* Blade */}
              <mesh position={[0, 0.5, 0]}>
                <boxGeometry args={[0.1, 2, 0.05]} />
                <meshStandardMaterial 
                  color="#c0c0c0" 
                  metalness={0.8} 
                  roughness={0.2} 
                />
              </mesh>
              {/* Guard */}
              <mesh position={[0, -0.3, 0]}>
                <boxGeometry args={[0.6, 0.1, 0.1]} />
                <meshStandardMaterial 
                  color="#8b4513" 
                  metalness={0.3} 
                  roughness={0.7} 
                />
              </mesh>
              {/* Handle */}
              <mesh position={[0, -0.7, 0]}>
                <cylinderGeometry args={[0.05, 0.05, 0.6]} />
                <meshStandardMaterial 
                  color="#654321" 
                  metalness={0.1} 
                  roughness={0.8} 
                />
              </mesh>
            </group>
          )
        } else if (item.name.toLowerCase().includes('bow')) {
          return (
            <group ref={meshRef}>
              {/* Bow body */}
              <mesh>
                <torusGeometry args={[0.8, 0.05, 8, 16, Math.PI]} />
                <meshStandardMaterial 
                  color="#8b4513" 
                  metalness={0.1} 
                  roughness={0.8} 
                />
              </mesh>
              {/* String */}
              <mesh position={[0, 0, 0]}>
                <cylinderGeometry args={[0.01, 0.01, 1.6]} />
                <meshStandardMaterial 
                  color="#f5f5dc" 
                  metalness={0} 
                  roughness={0.9} 
                />
              </mesh>
            </group>
          )
        }
        break
        
      case 'armor':
        return (
          <group ref={meshRef}>
            {/* Chest piece */}
            <mesh>
              <boxGeometry args={[1.2, 1.5, 0.3]} />
              <meshStandardMaterial 
                color="#696969" 
                metalness={0.7} 
                roughness={0.3} 
              />
            </mesh>
            {/* Shoulder guards */}
            <mesh position={[-0.7, 0.5, 0]}>
              <sphereGeometry args={[0.3, 8, 8]} />
              <meshStandardMaterial 
                color="#696969" 
                metalness={0.7} 
                roughness={0.3} 
              />
            </mesh>
            <mesh position={[0.7, 0.5, 0]}>
              <sphereGeometry args={[0.3, 8, 8]} />
              <meshStandardMaterial 
                color="#696969" 
                metalness={0.7} 
                roughness={0.3} 
              />
            </mesh>
          </group>
        )
        
      case 'consumable':
        return (
          <group ref={meshRef}>
            {/* Bottle */}
            <mesh>
              <cylinderGeometry args={[0.2, 0.3, 0.8, 8]} />
              <meshStandardMaterial 
                color="#ff6b6b" 
                transparent 
                opacity={0.8} 
                metalness={0} 
                roughness={0.1} 
              />
            </mesh>
            {/* Cork */}
            <mesh position={[0, 0.5, 0]}>
              <cylinderGeometry args={[0.15, 0.15, 0.2]} />
              <meshStandardMaterial 
                color="#8b4513" 
                metalness={0} 
                roughness={0.9} 
              />
            </mesh>
          </group>
        )
        
      default:
        return (
          <group ref={meshRef}>
            {/* Generic item - treasure chest */}
            <mesh>
              <boxGeometry args={[0.8, 0.5, 0.6]} />
              <meshStandardMaterial 
                color="#8b4513" 
                metalness={0.2} 
                roughness={0.8} 
              />
            </mesh>
            {/* Lock */}
            <mesh position={[0, 0, 0.31]}>
              <cylinderGeometry args={[0.1, 0.1, 0.1]} />
              <meshStandardMaterial 
                color="#ffd700" 
                metalness={0.8} 
                roughness={0.2} 
              />
            </mesh>
          </group>
        )
    }
  }, [item])

  return (
    <group
      onPointerEnter={() => setHovered(true)}
      onPointerLeave={() => setHovered(false)}
    >
      {geometry}
    </group>
  )
}

export const Equipment3DViewer: React.FC<Equipment3DViewerProps> = ({
  item,
  width = 300,
  height = 300,
  autoRotate = true,
  showControls = true,
  onInspect,
  className = ''
}) => {
  const [isAutoRotating, setIsAutoRotating] = useState(autoRotate)
  const [zoom, setZoom] = useState(1)
  const controlsRef = useRef<any>(null)

  const handleReset = () => {
    if (controlsRef.current) {
      controlsRef.current.reset()
    }
    setZoom(1)
  }

  const handleZoomIn = () => {
    setZoom(prev => Math.min(prev + 0.2, 3))
  }

  const handleZoomOut = () => {
    setZoom(prev => Math.max(prev - 0.2, 0.5))
  }

  return (
    <div className={`relative ${className}`}>
      <Card variant="surface" className="overflow-hidden">
        <div 
          className="relative bg-gradient-to-br from-(--parchment-100) to-(--parchment-200)"
          style={{ width, height }}
        >
          <Canvas
            camera={{ position: [0, 0, 5], fov: 45 }}
            shadows
          >
            <ambientLight intensity={0.4} />
            <directionalLight
              position={[5, 5, 5]}
              intensity={1}
              castShadow
              shadow-mapSize={[1024, 1024]}
            />
            <pointLight position={[-5, -5, -5]} intensity={0.3} />
            
            <ItemModel3D item={item} autoRotate={isAutoRotating} />
            
            <ContactShadows
              position={[0, -2, 0]}
              opacity={0.4}
              scale={10}
              blur={2}
              far={4}
            />
            
            <Environment preset="studio" />
            
            <OrbitControls
              ref={controlsRef}
              enablePan={false}
              enableZoom={true}
              minDistance={2}
              maxDistance={8}
              autoRotate={isAutoRotating}
              autoRotateSpeed={2}
            />
          </Canvas>

          {/* Loading overlay */}
          <div className="absolute inset-0 bg-(--parchment-100)/80 flex items-center justify-center opacity-0 transition-opacity duration-300">
            <div className="animate-spin w-8 h-8 border-2 border-primary border-t-transparent rounded-full" />
          </div>
        </div>

        {showControls && (
          <CardContent className="p-3 border-t border-(--parchment-300)">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={() => setIsAutoRotating(!isAutoRotating)}
                  className={`h-8 w-8 ${isAutoRotating ? 'text-primary' : 'text-muted-foreground'}`}
                >
                  <RotateCcw size={16} />
                </Button>
                
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={handleZoomIn}
                  className="h-8 w-8"
                >
                  <ZoomIn size={16} />
                </Button>
                
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={handleZoomOut}
                  className="h-8 w-8"
                >
                  <ZoomOut size={16} />
                </Button>
                
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={handleReset}
                  className="h-8 w-8"
                >
                  <RotateCcw size={16} />
                </Button>
              </div>

              {onInspect && (
                <Button
                  variant="outline"
                  size="sm"
                  onClick={onInspect}
                  className="gap-2"
                >
                  <Maximize2 size={14} />
                  Inspect
                </Button>
              )}
            </div>
          </CardContent>
        )}
      </Card>

      {/* Item info overlay */}
      <motion.div
        className="absolute top-2 left-2 right-2"
        initial={{ opacity: 0, y: -10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.3 }}
      >
        <div className="bg-black/60 backdrop-blur-sm rounded-lg px-3 py-2">
          <h4 className="text-white text-sm font-medium truncate">
            {item.name}
          </h4>
          <p className="text-white/70 text-xs capitalize">
            {item.category}
          </p>
        </div>
      </motion.div>
    </div>
  )
}

import React, { useState } from 'react'
import { motion } from 'framer-motion'
import { Download, FileText, Settings, Users, NotebookPen, Package } from 'lucide-react'
import * as Select from '@radix-ui/react-select'
import * as Checkbox from '@radix-ui/react-checkbox'
import { Card, CardContent, CardHeader, CardTitle } from '../ui/Card'
import { Button } from '../ui/Button'
import { cn } from '@/lib/utils'
import { Badge } from '../ui/Badge'
import { ExportFormat } from '../../fileManagementMockData'

interface ExportOptions {
  format: ExportFormat
  includeCharacters: boolean
  includeCampaigns: boolean
  includeNotes: boolean
  includeSettings: boolean
  dateRange?: {
    from: Date
    to: Date
  }
}

interface ExportPanelProps {
  onExport: (data: any, format: ExportFormat) => void
  operationInProgress: boolean
}

export const ExportPanel: React.FC<ExportPanelProps> = ({
  onExport,
  operationInProgress
}) => {
  const [exportOptions, setExportOptions] = useState<ExportOptions>({
    format: ExportFormat.JSON,
    includeCharacters: true,
    includeCampaigns: true,
    includeNotes: false,
    includeSettings: false
  })

  const [selectedPreset, setSelectedPreset] = useState<string>('custom')

  const exportPresets = [
    {
      id: 'all',
      name: 'Export All Data',
      description: 'Complete backup of all your data',
      icon: Package,
      options: {
        includeCharacters: true,
        includeCampaigns: true,
        includeNotes: true,
        includeSettings: true
      }
    },
    {
      id: 'characters',
      name: 'Characters Only',
      description: 'Export only character data',
      icon: Users,
      options: {
        includeCharacters: true,
        includeCampaigns: false,
        includeNotes: false,
        includeSettings: false
      }
    },
    {
      id: 'campaigns',
      name: 'Campaign Data',
      description: 'Export campaigns and related notes',
      icon: NotebookPen,
      options: {
        includeCharacters: false,
        includeCampaigns: true,
        includeNotes: true,
        includeSettings: false
      }
    }
  ]

  const formatOptions = [
    { value: ExportFormat.JSON, label: 'JSON', description: 'JavaScript Object Notation' },
    { value: ExportFormat.CSV, label: 'CSV', description: 'Comma Separated Values' },
    { value: ExportFormat.XML, label: 'XML', description: 'Extensible Markup Language' },
    { value: ExportFormat.PDF, label: 'PDF', description: 'Portable Document Format' }
  ]

  const handlePresetSelect = (presetId: string) => {
    setSelectedPreset(presetId)
    const preset = exportPresets.find(p => p.id === presetId)
    if (preset) {
      setExportOptions(prev => ({
        ...prev,
        ...preset.options
      }))
    }
  }

  const handleExport = () => {
    const exportData = {
      characters: exportOptions.includeCharacters ? ['character1', 'character2'] : [],
      campaigns: exportOptions.includeCampaigns ? ['campaign1'] : [],
      notes: exportOptions.includeNotes ? ['notes1', 'notes2'] : [],
      settings: exportOptions.includeSettings ? { theme: 'fantasy' } : null,
      exportedAt: new Date().toISOString(),
      format: exportOptions.format
    }

    onExport(exportData, exportOptions.format)
  }

  const getEstimatedSize = (): string => {
    let size = 0
    if (exportOptions.includeCharacters) size += 50 // KB
    if (exportOptions.includeCampaigns) size += 200
    if (exportOptions.includeNotes) size += 30
    if (exportOptions.includeSettings) size += 5
    
    return size > 1000 ? `${(size / 1000).toFixed(1)} MB` : `${size} KB`
  }

  return (
    <div className="space-y-6">
      {/* Export Presets */}
      <Card variant="default">
        <CardHeader>
          <CardTitle>Quick Export Presets</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {exportPresets.map((preset) => {
              const Icon = preset.icon
              const isSelected = selectedPreset === preset.id
              
              return (
                <motion.div
                  key={preset.id}
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                >
                  <button
                    onClick={() => handlePresetSelect(preset.id)}
                    className={cn(
                      'w-full p-4 rounded-lg border-2 transition-all duration-200 text-left border-border bg-card hover:border-primary/50 hover:bg-popover/60',
                      isSelected && 'border-primary bg-primary/10'
                    )}
                  >
                    <div className="flex items-center gap-3 mb-2">
                      <Icon
                        size={20}
                        className={cn(isSelected ? 'text-primary' : 'text-muted-foreground')}
                      />
                      <h3 className="font-medium">{preset.name}</h3>
                    </div>
                    <p 
                      className="text-sm text-muted-foreground">
                      {preset.description}
                    </p>
                  </button>
                </motion.div>
              )
            })}
          </div>
        </CardContent>
      </Card>

      {/* Export Configuration */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Data Selection */}
        <Card variant="default">
          <CardHeader>
            <CardTitle>Select Data to Export</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              {[
                { key: 'includeCharacters', label: 'Characters', icon: Users, count: 3 },
                { key: 'includeCampaigns', label: 'Campaigns', icon: NotebookPen, count: 2 },
                { key: 'includeNotes', label: 'Session Notes', icon: FileText, count: 15 },
                { key: 'includeSettings', label: 'App Settings', icon: Settings, count: 1 }
              ].map((item) => {
                const Icon = item.icon
                const isChecked = exportOptions[item.key as keyof ExportOptions] as boolean
                
                return (
                  <div key={item.key} className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <Checkbox.Root
                        checked={isChecked}
                        onCheckedChange={(checked) => {
                          setExportOptions(prev => ({
                            ...prev,
                            [item.key]: checked
                          }))
                          setSelectedPreset('custom')
                        }}
                        className="w-5 h-5 border-2 rounded flex items-center justify-center"
                        style={{
                          borderColor: 'var(--primary)',
                          backgroundColor: isChecked ? 'var(--primary)' : 'transparent'
                        }}
                      >
                        <Checkbox.Indicator>
                          <motion.div
                            initial={{ scale: 0 }}
                            animate={{ scale: 1 }}
                            className="text-white"
                          >
                            ✓
                          </motion.div>
                        </Checkbox.Indicator>
                      </Checkbox.Root>
                      <Icon className="text-muted-foreground" size={18} />
                      <span className="font-medium">{item.label}</span>
                    </div>
                    <Badge variant="secondary">{item.count} items</Badge>
                  </div>
                )
              })}
            </div>
          </CardContent>
        </Card>

        {/* Export Format & Options */}
        <Card variant="default">
          <CardHeader>
            <CardTitle>Export Format</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              <div>
                <label className="text-sm font-medium mb-2 block">File Format</label>
                <Select.Root 
                  value={exportOptions.format} 
                  onValueChange={(value) => setExportOptions(prev => ({ ...prev, format: value as ExportFormat }))}
                >
                  <Select.Trigger 
                    className="w-full p-3 border rounded-lg flex items-center justify-between"
                    style={{ 
                      borderColor: 'var(--border)',
                      backgroundColor: 'var(--card)'
                    }}
                  >
                    <Select.Value />
                  </Select.Trigger>
                  <Select.Content 
                    className="bg-surface border border-border rounded-lg shadow-lg z-50 bg-card">
                    {formatOptions.map((format) => (
                      <Select.Item 
                        key={format.value} 
                        value={format.value}
                        className="p-3 hover:bg-surface-elevated cursor-pointer"
                      >
                        <div>
                          <div className="font-medium">{format.label}</div>
                          <div 
                            className="text-sm text-muted-foreground">
                            {format.description}
                          </div>
                        </div>
                      </Select.Item>
                    ))}
                  </Select.Content>
                </Select.Root>
              </div>

              <div className="p-4 rounded-lg bg-popover">
                <h4 className="font-medium mb-2">Export Summary</h4>
                <div className="space-y-1 text-sm text-muted-foreground">
                  <div>Estimated size: <span className="font-medium">{getEstimatedSize()}</span></div>
                  <div>Format: <span className="font-medium">{exportOptions.format.toUpperCase()}</span></div>
                  <div>
                    Items: <span className="font-medium">
                      {[
                        exportOptions.includeCharacters && 'Characters',
                        exportOptions.includeCampaigns && 'Campaigns',
                        exportOptions.includeNotes && 'Notes',
                        exportOptions.includeSettings && 'Settings'
                      ].filter(Boolean).join(', ') || 'None selected'}
                    </span>
                  </div>
                </div>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Export Actions */}
      <Card variant="magical">
        <CardContent>
          <div className="flex items-center justify-between">
            <div>
              <h3 className="font-medium mb-1">Ready to Export</h3>
              <p 
                className="text-sm text-muted-foreground">
                Your data will be packaged and downloaded as a {exportOptions.format.toUpperCase()} file
              </p>
            </div>
            <Button
              variant="primary"
              size="lg"
              onClick={handleExport}
              disabled={operationInProgress || (!exportOptions.includeCharacters && !exportOptions.includeCampaigns && !exportOptions.includeNotes && !exportOptions.includeSettings)}
              className="gap-2"
            >
              <Download size={20} />
              {operationInProgress ? 'Exporting...' : 'Export Data'}
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  )
}

import React, { useState, useCallback } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import * as Tabs from '@radix-ui/react-tabs'
import { FileUp, Download, ShieldCheck, FolderOpen } from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle } from '../ui/Card'
import { ImportPanel } from './ImportPanel'
import { ExportPanel } from './ExportPanel'
import { BackupPanel } from './BackupPanel'
import { FileBrowserPanel } from './FileBrowserPanel'
import { FileType, FileOperation } from '../../fileManagementMockData'

interface FileManagementPanelProps {
  onFileOperation?: (operation: FileOperation, data: any) => void
  onClose?: () => void
}

export const FileManagementPanel: React.FC<FileManagementPanelProps> = ({
  onFileOperation,
  onClose
}) => {
  const [activeTab, setActiveTab] = useState('import')
  const [operationInProgress, setOperationInProgress] = useState<FileOperation | null>(null)

  const handleFileOperation = useCallback((operation: FileOperation, data: any) => {
    setOperationInProgress(operation)
    onFileOperation?.(operation, data)
    
    // Simulate operation completion
    setTimeout(() => {
      setOperationInProgress(null)
    }, 2000)
  }, [onFileOperation])

  const tabs = [
    {
      id: 'import',
      label: 'Import Files',
      icon: FileUp,
      description: 'Upload and import character, campaign, and settings files'
    },
    {
      id: 'export',
      label: 'Export Data',
      icon: Download,
      description: 'Export your data in various formats'
    },
    {
      id: 'backup',
      label: 'Backup & Restore',
      icon: ShieldCheck,
      description: 'Manage backups and restore data'
    },
    {
      id: 'browser',
      label: 'File Browser',
      icon: FolderOpen,
      description: 'Browse and manage your files'
    }
  ]

  const tabVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: { 
      opacity: 1, 
      y: 0,
      transition: {
        duration: 0.3,
        ease: "easeOut"
      }
    },
    exit: { 
      opacity: 0, 
      y: -20,
      transition: {
        duration: 0.2,
        ease: "easeIn"
      }
    }
  }

  const renderTabContent = () => {
    switch (activeTab) {
      case 'import':
        return (
          <ImportPanel
            onFileImport={(files) => handleFileOperation(FileOperation.IMPORT, files)}
            operationInProgress={operationInProgress === FileOperation.IMPORT}
          />
        )
      case 'export':
        return (
          <ExportPanel
            onExport={(data, format) => handleFileOperation(FileOperation.EXPORT, { data, format })}
            operationInProgress={operationInProgress === FileOperation.EXPORT}
          />
        )
      case 'backup':
        return (
          <BackupPanel
            onBackup={(options) => handleFileOperation(FileOperation.BACKUP, options)}
            onRestore={(backupId) => handleFileOperation(FileOperation.RESTORE, backupId)}
            operationInProgress={operationInProgress === FileOperation.BACKUP || operationInProgress === FileOperation.RESTORE}
          />
        )
      case 'browser':
        return (
          <FileBrowserPanel
            onFileOperation={handleFileOperation}
            operationInProgress={operationInProgress}
          />
        )
      default:
        return null
    }
  }

  return (
    <Card variant="magical" className="w-full max-w-6xl mx-auto">
      <CardHeader className="pb-0">
        <div className="flex items-center justify-between">
          <div>
            <CardTitle className="flex items-center gap-3">
              <motion.div
                className="w-8 h-8 rounded-lg flex items-center justify-center bg-primary/20"
                
                whileHover={{ scale: 1.1, rotate: 5 }}>
                <FolderOpen className="text-primary" 
                  size={20} />
              </motion.div>
              File Management
            </CardTitle>
            <p 
              className="text-sm mt-2 text-muted-foreground">
              Import, export, backup, and manage your ZimboMate data files
            </p>
          </div>
          {onClose && (
            <button
              onClick={onClose}
              className="text-muted-foreground hover:text-muted-foreground transition-colors"
            >
              ✕
            </button>
          )}
        </div>
      </CardHeader>

      <CardContent>
        <Tabs.Root value={activeTab} onValueChange={setActiveTab}>
          {/* Tab Navigation */}
          <Tabs.List className="grid grid-cols-4 gap-2 mb-6">
            {tabs.map((tab, index) => {
              const Icon = tab.icon
              const isActive = activeTab === tab.id
              
              return (
                <motion.div
                  key={tab.id}
                  initial={{ opacity: 0, y: -10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.3, delay: index * 0.1 }}
                >
                  <Tabs.Trigger
                    value={tab.id}
                    className={`
                      relative w-full p-4 rounded-lg border transition-all duration-200
                      flex flex-col items-center gap-2 text-center
                      hover:scale-105 hover:shadow-md
                      ${isActive 
                        ? 'border-primary bg-primary/10 shadow-md' 
                        : 'border-border bg-surface hover:bg-surface-elevated'
                      }
                    `}
                    style={{
                      backgroundColor: isActive ? 'var(--primary)' : 'var(--card)',
                      borderColor: isActive ? 'var(--primary)' : 'var(--border)',
                      opacity: isActive ? 1 : 0.8,
                      color: isActive ? 'white' : 'var(--foreground)'
                    }}
                  >
                    <Icon size={20} />
                    <div>
                      <div className="font-medium text-sm">{tab.label}</div>
                      <div 
                        className="text-xs mt-1 opacity-80"
                        style={{ 
                          color: isActive ? 'rgba(255,255,255,0.8)' : 'var(--muted-foreground)' 
                        }}
                      >
                        {tab.description}
                      </div>
                    </div>
                    {isActive && (
                      <motion.div
                        className="absolute inset-0 rounded-lg"
                        style={{ 
                          background: 'linear-gradient(135deg, var(--primary), var(--secondary))',
                          opacity: 0.1
                        }}
                        layoutId="activeFileTab"
                        transition={{ type: "spring", stiffness: 300, damping: 30 }}
                      />
                    )}
                  </Tabs.Trigger>
                </motion.div>
              )
            })}
          </Tabs.List>

          {/* Tab Content */}
          <AnimatePresence mode="wait">
            {tabs.map((tab) => (
              <Tabs.Content key={tab.id} value={tab.id}>
                <motion.div
                  variants={tabVariants}
                  initial="hidden"
                  animate="visible"
                  exit="exit"
                >
                  {renderTabContent()}
                </motion.div>
              </Tabs.Content>
            ))}
          </AnimatePresence>
        </Tabs.Root>
      </CardContent>
    </Card>
  )
}

/**
 * Hold Manager Component
 * Displays and manages hold points from various Dungeon World moves
 */

import React, { useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { Shield, Eye, BookOpen, Minus, Plus, ChevronDown, ChevronRight } from 'lucide-react'
import { useHoldStore, HOLD_MOVES, type HoldEntry, type HoldOption } from '../../stores/holdStore'
import { Button, Card, CardContent, CardHeader, Badge } from '../ui'

interface HoldManagerProps {
  characterId: string
  className?: string
  compact?: boolean
}

const MOVE_ICONS: Record<string, React.ComponentType<any>> = {
  'defend': Shield,
  'discern-realities': Eye,
  'spout-lore': BookOpen,
}

export const HoldManager: React.FC<HoldManagerProps> = ({
  characterId,
  className = '',
  compact = false
}) => {
  const { getHoldsForCharacter, spendHold } = useHoldStore()
  const holds = getHoldsForCharacter(characterId)
  const [expandedHolds, setExpandedHolds] = useState<Set<string>>(new Set())

  const toggleHoldExpansion = (holdId: string) => {
    setExpandedHolds(prev => {
      const next = new Set(prev)
      if (next.has(holdId)) {
        next.delete(holdId)
      } else {
        next.add(holdId)
      }
      return next
    })
  }

  const handleSpendHold = (hold: HoldEntry, optionId: string, amount: number = 1) => {
    const success = spendHold(characterId, hold.id, optionId, amount)
    if (success) {
      console.log(`Spent ${amount} hold on ${optionId}`)
    }
  }

  if (holds.length === 0) {
    return (
      <Card className={`${className} opacity-75`}>
        <CardContent className="p-4 text-center">
          <div className="text-muted-foreground  text-sm">
            No active holds
          </div>
          <div className="text-xs text-muted-foreground mt-1">
            Use Defend, Discern Realities, or Spout Lore to gain hold
          </div>
        </CardContent>
      </Card>
    )
  }

  if (compact) {
    const totalHold = holds.reduce((sum, hold) => sum + hold.amount, 0)

    return (
      <div className={`flex items-center gap-2 ${className}`}>
        <Shield size={16} className="text-primary" />
        <span className="text-sm font-medium">
          {totalHold} Hold
        </span>
        <div className="flex gap-1">
          {holds.map(hold => {
            const Icon = MOVE_ICONS[hold.moveId] || Shield
            return (
              <Badge key={hold.id} variant="secondary" className="text-xs">
                <Icon size={10} className="mr-1" />
                {hold.amount}
              </Badge>
            )
          })}
        </div>
      </div>
    )
  }

  return (
    <Card className={className}>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Shield size={18} className="text-primary" />
            <h3 className="font-semibold">Hold Management</h3>
          </div>
          <Badge variant="outline">
            {holds.reduce((sum, hold) => sum + hold.amount, 0)} total
          </Badge>
        </div>
      </CardHeader>

      <CardContent>
        <div className="space-y-3">
          <AnimatePresence>
            {holds.map((hold) => {
              const Icon = MOVE_ICONS[hold.moveId] || Shield
              const isExpanded = expandedHolds.has(hold.id)
              const moveInfo = HOLD_MOVES[hold.moveId]

              return (
                <motion.div
                  key={hold.id}
                  initial={{ opacity: 0, y: -10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -10, height: 0 }}
                  className="border rounded-lg p-3 bg-muted/50 "
                >
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <Icon size={16} className="text-primary" />
                      <div>
                        <div className="font-medium text-sm">{hold.moveName}</div>
                        <div className="text-xs text-muted-foreground">
                          {hold.amount} / {hold.maxAmount} hold
                        </div>
                      </div>
                    </div>

                    <div className="flex items-center gap-2">
                      <div className="flex items-center gap-1">
                        {Array.from({ length: hold.maxAmount }, (_, i) => (
                          <div
                            key={i}
                            className={`w-2 h-2 rounded-full ${
                              i < hold.amount
                                ? 'bg-primary'
                                : 'bg-gray-300 '
                            }`}
                          />
                        ))}
                      </div>

                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => toggleHoldExpansion(hold.id)}
                        className="p-1"
                        disabled={hold.amount === 0}
                      >
                        {isExpanded ? (
                          <ChevronDown size={14} />
                        ) : (
                          <ChevronRight size={14} />
                        )}
                      </Button>
                    </div>
                  </div>

                  <AnimatePresence>
                    {isExpanded && moveInfo && (
                      <motion.div
                        initial={{ height: 0, opacity: 0 }}
                        animate={{ height: 'auto', opacity: 1 }}
                        exit={{ height: 0, opacity: 0 }}
                        className="mt-3 pt-3 border-t border-border"
                      >
                        <div className="text-xs text-muted-foreground  mb-3">
                          {hold.description}
                        </div>

                        <div className="space-y-2">
                          {moveInfo.options.map((option) => (
                            <div
                              key={option.id}
                              className="flex items-start justify-between p-2 bg-card rounded border"
                            >
                              <div className="flex-1">
                                <div className="text-sm font-medium">
                                  {option.label}
                                </div>
                                <div className="text-xs text-muted-foreground mt-1">
                                  {option.description}
                                </div>
                              </div>

                              <Button
                                variant="outline"
                                size="sm"
                                onClick={() => handleSpendHold(hold, option.id, option.cost)}
                                disabled={hold.amount < option.cost}
                                className="ml-3 text-xs px-2 py-1"
                              >
                                <Minus size={12} className="mr-1" />
                                {option.cost}
                              </Button>
                            </div>
                          ))}
                        </div>
                      </motion.div>
                    )}
                  </AnimatePresence>
                </motion.div>
              )
            })}
          </AnimatePresence>
        </div>

        {holds.length > 0 && (
          <div className="mt-4 pt-3 border-t border-border">
            <div className="text-xs text-muted-foreground text-center">
              Click expand to spend hold • Hold is granted by successful moves
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  )
}

// Compact hold display for character sheets
export const HoldDisplay: React.FC<{
  characterId: string
  className?: string
}> = ({ characterId, className = '' }) => {
  return <HoldManager characterId={characterId} className={className} compact />
}

import React, { useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import * as Collapsible from '@radix-ui/react-collapsible'
import { Card, CardHeader, CardTitle, CardContent, Button } from '../ui'
import { Container, Inventory, getContainerItems } from '../../models/Inventory'
import { ItemCard } from './ItemCard'
import { useInventoryStore } from '../../stores/inventoryStore'
import { 
  ChevronDown, 
  ChevronRight, 
  Backpack, 
  Wine, 
  Gem, 
  Package,
  Plus
} from 'lucide-react'

interface InventoryContainerProps {
  container: Container
  inventory: Inventory
  onItemEquip: (itemId: string) => void
  onItemUse: (itemId: string) => void
  onItemDrop: (itemId: string) => void
}

const getCategoryIcon = (category: string) => {
  switch (category) {
    case 'carried':
      return Backpack
    case 'consumables':
      return Wine
    case 'treasure':
      return Gem
    default:
      return Package
  }
}

const containerVariants = {
  hidden: { opacity: 0, y: 20 },
  visible: { 
    opacity: 1, 
    y: 0,
    transition: {
      type: "spring",
      stiffness: 100,
      damping: 15
    }
  }
}

const contentVariants = {
  closed: { 
    opacity: 0,
    height: 0,
    transition: {
      duration: 0.3,
      ease: "easeInOut"
    }
  },
  open: { 
    opacity: 1,
    height: 'auto',
    transition: {
      duration: 0.3,
      ease: "easeInOut"
    }
  }
}

const itemsGridVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.05
    }
  }
}

const itemVariants = {
  hidden: { opacity: 0, scale: 0.8 },
  visible: { 
    opacity: 1, 
    scale: 1,
    transition: {
      type: "spring",
      stiffness: 200,
      damping: 20
    }
  }
}

export const InventoryContainer: React.FC<InventoryContainerProps> = ({
  container,
  inventory,
  onItemEquip,
  onItemUse,
  onItemDrop
}) => {
  const [isOpen, setIsOpen] = useState(true)
  const { inventoryView, filterBy, searchQuery, sortBy } = useInventoryStore()
  
  const items = getContainerItems(inventory, container.id)
  const CategoryIcon = getCategoryIcon(container.category)

  // Filter and sort items
  let filteredItems = items

  // Apply search filter
  if (searchQuery) {
    filteredItems = filteredItems.filter(item =>
      item.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      (item.description && item.description.toLowerCase().includes(searchQuery.toLowerCase()))
    )
  }

  // Apply category filter
  if (filterBy !== 'all') {
    filteredItems = filteredItems.filter(item => {
      switch (filterBy) {
        case 'weapons':
          return item.category === 'weapon'
        case 'armor':
          return item.category === 'armor'
        case 'consumables':
          return item.category === 'consumable'
        case 'treasure':
          return item.category === 'treasure'
        case 'magical':
          return item.tags.some(tag => tag.name === 'magical')
        case 'equipped':
          return item.equipped
        default:
          return true
      }
    })
  }

  // Apply sorting
  filteredItems.sort((a, b) => {
    switch (sortBy) {
      case 'name':
        return a.name.localeCompare(b.name)
      case 'weight':
        return (b.weight * b.quantity) - (a.weight * a.quantity)
      case 'value':
        return (b.value || 0) - (a.value || 0)
      case 'category':
        return a.category.localeCompare(b.category)
      default:
        return 0
    }
  })

  const getGridClass = () => {
    switch (inventoryView) {
      case 'list':
        return 'inventory-list'
      case 'compact':
        return 'inventory-compact'
      default:
        return 'inventory-grid'
    }
  }

  return (
    <motion.div
      variants={containerVariants}
      initial="hidden"
      animate="visible"
    >
      <Card variant="surface">
        <Collapsible.Root open={isOpen} onOpenChange={setIsOpen}>
          <Collapsible.Trigger asChild>
            <CardHeader className="cursor-pointer hover:bg-(--parchment-100) transition-colors">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <CategoryIcon size={20} className="text-(--parchment-800)" />
                  <div>
                    <CardTitle className="text-lg font-display text-(--parchment-900)">
                      {container.name}
                    </CardTitle>
                    <p className="text-sm text-(--parchment-600) font-ui">
                      {filteredItems.length} {filteredItems.length === 1 ? 'item' : 'items'}
                      {container.maxWeight && (
                        <span className="ml-2">
                          • Max: {container.maxWeight} lbs
                        </span>
                      )}
                    </p>
                  </div>
                </div>
                
                <motion.div
                  animate={{ rotate: isOpen ? 90 : 0 }}
                  transition={{ duration: 0.2 }}
                >
                  <ChevronRight size={16} className="text-(--parchment-600)" />
                </motion.div>
              </div>
            </CardHeader>
          </Collapsible.Trigger>

          <Collapsible.Content asChild>
            <motion.div
              variants={contentVariants}
              initial="closed"
              animate={isOpen ? "open" : "closed"}
            >
              <CardContent className="pt-0">
                {filteredItems.length > 0 ? (
                  <motion.div
                    className={getGridClass()}
                    variants={itemsGridVariants}
                    initial="hidden"
                    animate="visible"
                  >
                    {filteredItems.map((item) => (
                      <motion.div
                        key={item.id}
                        variants={itemVariants}
                      >
                        <ItemCard
                          item={item}
                          isEquipped={item.equipped}
                          onEquip={onItemEquip}
                          onUnequip={(itemId) => {
                            // Handle unequip logic here
                            console.log('Unequipping:', itemId)
                          }}
                          onUse={onItemUse}
                          onDrop={onItemDrop}
                          showActions={true}
                          compact={inventoryView === 'compact'}
                        />
                      </motion.div>
                    ))}
                  </motion.div>
                ) : (
                  <motion.div
                    className="text-center py-8"
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    transition={{ delay: 0.2 }}
                  >
                    <CategoryIcon size={48} className="text-(--parchment-400) mx-auto mb-4" />
                    <h3 className="text-lg font-semibold text-(--parchment-700) mb-2 font-display">
                      {searchQuery || filterBy !== 'all' ? 'No matching items' : `No ${container.name.toLowerCase()}`}
                    </h3>
                    <p className="text-(--parchment-600) font-body mb-4">
                      {searchQuery || filterBy !== 'all' 
                        ? 'Try adjusting your search or filter criteria.'
                        : `Add items to your ${container.name.toLowerCase()} to see them here.`
                      }
                    </p>
                    
                    {container.category === 'carried' && !searchQuery && filterBy === 'all' && (
                      <Button variant="outline" size="sm">
                        <Plus size={16} />
                        Add Item
                      </Button>
                    )}
                  </motion.div>
                )}
              </CardContent>
            </motion.div>
          </Collapsible.Content>
        </Collapsible.Root>
      </Card>
    </motion.div>
  )
}

import React, { useState } from 'react'
import { motion } from 'framer-motion'
import * as Tooltip from '@radix-ui/react-tooltip'
import * as DropdownMenu from '@radix-ui/react-dropdown-menu'
import { Card, CardContent, Button, Badge } from '../ui'
import { Item, isWeapon, isArmor, formatTags } from '../../models/Equipment'
import { formatWeight, formatValue, formatItemQuantity } from '../../equipmentSystemMockData'
import { 
  Sword, 
  Shield, 
  Wine, 
  Gem, 
  Package, 
  MoreHorizontal,
  Eye,
  Trash2,
  ArrowUpRight,
  ArrowDownRight
} from 'lucide-react'

interface ItemCardProps {
  item: Item
  isEquipped: boolean
  onEquip?: (itemId: string) => void
  onUnequip?: (itemId: string) => void
  onUse?: (itemId: string) => void
  onDrop?: (itemId: string) => void
  onInspect?: (itemId: string) => void
  showActions?: boolean
  compact?: boolean
  isDragging?: boolean
}

const getItemIcon = (item: Item) => {
  switch (item.category) {
    case 'weapon':
      return Sword
    case 'armor':
      return Shield
    case 'consumable':
      return Wine
    case 'treasure':
      return Gem
    default:
      return Package
  }
}

const getRarityColor = (item: Item) => {
  // Simple rarity detection based on value
  if (!item.value) return 'item-common'
  if (item.value > 200) return 'item-legendary'
  if (item.value > 100) return 'item-rare'
  if (item.value > 50) return 'item-uncommon'
  return 'item-common'
}

export const ItemCard: React.FC<ItemCardProps> = ({
  item,
  isEquipped,
  onEquip,
  onUnequip,
  onUse,
  onDrop,
  onInspect,
  showActions = true,
  compact = false,
  isDragging = false
}) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false)
  const ItemIcon = getItemIcon(item)
  const rarityClass = getRarityColor(item)

  const cardVariants = {
    hover: {
      scale: 1.02,
      y: -2,
      transition: {
        type: "spring",
        stiffness: 400,
        damping: 25
      }
    },
    tap: {
      scale: 0.98
    }
  }

  const handleEquipToggle = () => {
    if (isEquipped && onUnequip) {
      onUnequip(item.id)
    } else if (!isEquipped && onEquip) {
      onEquip(item.id)
    }
  }

  const handleUse = () => {
    if (onUse) {
      onUse(item.id)
    }
  }

  const handleDrop = () => {
    if (onDrop) {
      onDrop(item.id)
    }
  }

  const handleInspect = () => {
    if (onInspect) {
      onInspect(item.id)
    }
  }

  const ItemTooltipContent = () => (
    <div className="space-y-3 max-w-sm">
      <div className="flex items-start gap-3">
        <ItemIcon size={20} className="text-(--parchment-800) mt-0.5" />
        <div className="flex-1">
          <h4 className="font-semibold text-(--parchment-900) font-display">
            {item.name}
            {formatItemQuantity(item.quantity) && (
              <span className="ml-2 text-sm text-(--parchment-600)">
                {formatItemQuantity(item.quantity)}
              </span>
            )}
          </h4>
          <p className="text-xs text-(--parchment-600) capitalize font-ui">
            {item.category}
            {isEquipped && (
              <Badge variant="success" className="ml-2 text-xs">
                Equipped
              </Badge>
            )}
          </p>
        </div>
      </div>

      {item.description && (
        <p className="text-sm text-(--parchment-700) font-body">
          {item.description}
        </p>
      )}

      <div className="grid grid-cols-2 gap-2 text-xs">
        <div>
          <span className="text-(--parchment-600)">Weight:</span>
          <span className="ml-1 text-(--parchment-800) font-medium">
            {formatWeight(item.weight)}
          </span>
        </div>
        {item.value && (
          <div>
            <span className="text-(--parchment-600)">Value:</span>
            <span className="ml-1 text-(--parchment-800) font-medium">
              {formatValue(item.value)}
            </span>
          </div>
        )}
      </div>

      {isWeapon(item) && item.damage && (
        <div className="text-xs">
          <span className="text-(--parchment-600)">Damage:</span>
          <span className="ml-1 text-(--parchment-800) font-medium">
            {item.damage}
          </span>
        </div>
      )}

      {isArmor(item) && (
        <div className="text-xs">
          <span className="text-(--parchment-600)">Armor:</span>
          <span className="ml-1 text-(--parchment-800) font-medium">
            {item.armorValue} AC
          </span>
        </div>
      )}

      {item.tags.length > 0 && (
        <div className="text-xs">
          <span className="text-(--parchment-600)">Tags:</span>
          <p className="text-(--parchment-700) mt-1">
            {formatTags(item.tags)}
          </p>
        </div>
      )}

      {item.uses && (
        <div className="text-xs">
          <span className="text-(--parchment-600)">Uses:</span>
          <span className="ml-1 text-(--parchment-800) font-medium">
            {item.uses.current}/{item.uses.max}
          </span>
        </div>
      )}
    </div>
  )

  if (compact) {
    return (
      <Tooltip.Root>
        <Tooltip.Trigger asChild>
          <motion.div
            className={`item-card ${isEquipped ? 'item-card-equipped' : ''} ${rarityClass} ${
              isDragging ? 'item-card-dragging' : ''
            } cursor-pointer h-full flex items-center justify-center p-2`}
            variants={cardVariants}
            whileHover="hover"
            whileTap="tap"
          >
            <ItemIcon size={16} className="text-(--parchment-800)" />
          </motion.div>
        </Tooltip.Trigger>

        <Tooltip.Portal>
          <Tooltip.Content
            className="bg-card border border-(--parchment-300) rounded-lg p-3 shadow-lg z-50"
            sideOffset={5}
          >
            <ItemTooltipContent />
            <Tooltip.Arrow className="fill-card" />
          </Tooltip.Content>
        </Tooltip.Portal>
      </Tooltip.Root>
    )
  }

  return (
    <Tooltip.Root>
      <Tooltip.Trigger asChild>
        <motion.div
          className={`item-card ${isEquipped ? 'item-card-equipped' : ''} ${rarityClass} ${
            isDragging ? 'item-card-dragging' : ''
          }`}
          variants={cardVariants}
          whileHover="hover"
          whileTap="tap"
        >
          <div className="flex items-start gap-3">
            <div className="flex-shrink-0">
              <ItemIcon size={20} className="text-(--parchment-800)" />
            </div>

            <div className="flex-1 min-w-0">
              <div className="flex items-start justify-between">
                <div className="flex-1">
                  <h4 className="font-semibold text-(--parchment-900) font-display text-sm truncate">
                    {item.name}
                  </h4>
                  <div className="flex items-center gap-2 mt-1">
                    <span className="text-xs text-(--parchment-600) capitalize font-ui">
                      {item.category}
                    </span>
                    {formatItemQuantity(item.quantity) && (
                      <Badge variant="secondary" className="text-xs">
                        {formatItemQuantity(item.quantity)}
                      </Badge>
                    )}
                    {isEquipped && (
                      <Badge variant="success" className="text-xs">
                        Equipped
                      </Badge>
                    )}
                  </div>
                </div>

                {showActions && (
                  <DropdownMenu.Root open={isMenuOpen} onOpenChange={setIsMenuOpen}>
                    <DropdownMenu.Trigger asChild>
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-6 w-6 text-(--parchment-600) hover:text-(--parchment-800)"
                      >
                        <MoreHorizontal size={14} />
                      </Button>
                    </DropdownMenu.Trigger>

                    <DropdownMenu.Portal>
                      <DropdownMenu.Content
                        className="bg-card border border-(--parchment-300) rounded-lg p-1 shadow-lg z-50 min-w-[160px]"
                        sideOffset={5}
                      >
                        {!isEquipped && onEquip && (
                          <DropdownMenu.Item
                            className="flex items-center gap-2 px-3 py-2 text-sm rounded-md hover:bg-(--parchment-100) cursor-pointer"
                            onClick={handleEquipToggle}
                          >
                            <ArrowUpRight size={14} />
                            Equip
                          </DropdownMenu.Item>
                        )}

                        {isEquipped && onUnequip && (
                          <DropdownMenu.Item
                            className="flex items-center gap-2 px-3 py-2 text-sm rounded-md hover:bg-(--parchment-100) cursor-pointer"
                            onClick={handleEquipToggle}
                          >
                            <ArrowDownRight size={14} />
                            Unequip
                          </DropdownMenu.Item>
                        )}

                        {item.category === 'consumable' && onUse && (
                          <DropdownMenu.Item
                            className="flex items-center gap-2 px-3 py-2 text-sm rounded-md hover:bg-(--parchment-100) cursor-pointer"
                            onClick={handleUse}
                          >
                            <Wine size={14} />
                            Use
                          </DropdownMenu.Item>
                        )}

                        {onInspect && (
                          <DropdownMenu.Item
                            className="flex items-center gap-2 px-3 py-2 text-sm rounded-md hover:bg-(--parchment-100) cursor-pointer"
                            onClick={handleInspect}
                          >
                            <Eye size={14} />
                            Inspect
                          </DropdownMenu.Item>
                        )}

                        <DropdownMenu.Separator className="h-px bg-(--parchment-300) my-1" />

                        {onDrop && (
                          <DropdownMenu.Item
                            className="flex items-center gap-2 px-3 py-2 text-sm rounded-md hover:bg-(--danger-100) text-(--danger-600) cursor-pointer"
                            onClick={handleDrop}
                          >
                            <Trash2 size={14} />
                            Drop
                          </DropdownMenu.Item>
                        )}
                      </DropdownMenu.Content>
                    </DropdownMenu.Portal>
                  </DropdownMenu.Root>
                )}
              </div>

              <div className="flex items-center gap-3 mt-2 text-xs text-(--parchment-600)">
                <span>{formatWeight(item.weight)}</span>
                {item.value && <span>{formatValue(item.value)}</span>}
              </div>
            </div>
          </div>
        </motion.div>
      </Tooltip.Trigger>

      <Tooltip.Portal>
        <Tooltip.Content
          className="bg-card border border-(--parchment-300) rounded-lg p-3 shadow-lg z-50"
          sideOffset={5}
        >
          <ItemTooltipContent />
          <Tooltip.Arrow className="fill-card" />
        </Tooltip.Content>
      </Tooltip.Portal>
    </Tooltip.Root>
  )
}

/**
 * Move3DIntegration - Seamless integration between moves and 3D dice system
 * Provides enhanced visual feedback for move execution with particle effects
 */

import React, { useCallback, useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { Canvas } from '@react-three/fiber'
import { Card, CardContent, Button } from '../ui'
import { useDiceRoll } from '../../hooks/useDiceRoll'
import { useAnimations } from '../../hooks/useAnimations'
import { Dice1, Dice2, Dice3, Dice4, Dice5, Dice6, Sparkles, Zap } from 'lucide-react'

interface Move3DIntegrationProps {
  moveId: string
  moveName: string
  stat: string
  modifier: number
  onRollComplete: (result: any) => void
  onCancel: () => void
  isVisible: boolean
}

interface ParticleEffect {
  id: string
  type: 'success' | 'partial' | 'failure' | 'critical'
  position: { x: number; y: number; z: number }
  color: string
  intensity: number
}

const MoveParticles: React.FC<{ effects: ParticleEffect[] }> = ({ effects }) => {
  return (
    <>
      {effects.map(effect => (
        <group key={effect.id} position={[effect.position.x, effect.position.y, effect.position.z]}>
          <pointLight
            color={effect.color}
            intensity={effect.intensity}
            distance={5}
            decay={2}
          />
          
          {/* Particle system would go here - simplified for demo */}
          <mesh>
            <sphereGeometry args={[0.1, 8, 8]} />
            <meshBasicMaterial 
              color={effect.color} 
              transparent 
              opacity={0.6}
            />
          </mesh>
        </group>
      ))}
    </>
  )
}

const getDiceIcon = (value: number) => {
  const icons = [Dice1, Dice2, Dice3, Dice4, Dice5, Dice6]
  return icons[Math.max(0, Math.min(5, value - 1))] || Dice1
}

const getOutcomeColor = (total: number) => {
  if (total >= 10) return 'text-chart-2'
  if (total >= 7) return 'text-chart-4'
  return 'text-destructive'
}

const getOutcomeText = (total: number) => {
  if (total >= 10) return 'Success!'
  if (total >= 7) return 'Partial Success'
  return 'Failure'
}

export const Move3DIntegration: React.FC<Move3DIntegrationProps> = ({
  moveId,
  moveName,
  stat,
  modifier,
  onRollComplete,
  onCancel,
  isVisible
}) => {
  const { rollWithStat, isRolling, lastRoll } = useDiceRoll()
  const { triggerParticleEffect } = useAnimations()
  const [rollResult, setRollResult] = useState<any>(null)
  const [particleEffects, setParticleEffects] = useState<ParticleEffect[]>([])
  const [showResult, setShowResult] = useState(false)

  const handleRoll = useCallback(async () => {
    try {
      const result = await rollWithStat(stat as any, modifier)
      setRollResult(result)
      setShowResult(true)

      // Create particle effects based on outcome
      const effectType = result.total >= 10 ? 'success' : 
                        result.total >= 7 ? 'partial' : 'failure'
      
      const newEffect: ParticleEffect = {
        id: `move-${Date.now()}`,
        type: effectType,
        position: { x: 0, y: 0, z: 0 },
        color: result.total >= 10 ? '#22c55e' : 
               result.total >= 7 ? '#eab308' : '#ef4444',
        intensity: result.total >= 10 ? 2 : 1
      }

      setParticleEffects([newEffect])

      // Trigger screen particle effect
      triggerParticleEffect(effectType, {
        x: window.innerWidth / 2,
        y: window.innerHeight / 2
      })

      // Auto-complete after showing result
      setTimeout(() => {
        onRollComplete(result)
      }, 2000)

    } catch (error) {
      console.error('Roll failed:', error)
    }
  }, [rollWithStat, stat, modifier, onRollComplete, triggerParticleEffect])

  const handleComplete = () => {
    if (rollResult) {
      onRollComplete(rollResult)
    }
  }

  return (
    <AnimatePresence>
      {isVisible && (
        <motion.div
          className="fixed inset-0 bg-black/50 flex items-center justify-center z-50"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          onClick={onCancel}
        >
          <motion.div
            className="w-full max-w-2xl mx-4"
            initial={{ scale: 0.9, opacity: 0, y: 20 }}
            animate={{ scale: 1, opacity: 1, y: 0 }}
            exit={{ scale: 0.9, opacity: 0, y: 20 }}
            onClick={e => e.stopPropagation()}
          >
            <Card variant="magical" className="relative overflow-hidden">
              {/* Background 3D Scene */}
              <div className="absolute inset-0 opacity-20">
                <Canvas camera={{ position: [0, 0, 5] }}>
                  <ambientLight intensity={0.5} />
                  <pointLight position={[10, 10, 10]} />
                  <MoveParticles effects={particleEffects} />
                </Canvas>
              </div>

              <CardContent className="relative z-10 p-6">
                <div className="text-center space-y-6">
                  {/* Move Header */}
                  <motion.div
                    initial={{ opacity: 0, y: -20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.4 }}
                  >
                    <div className="flex items-center justify-center gap-3 mb-4">
                      <Zap size={32} className="text-primary" />
                      <h2 className="text-display-lg text-foreground">
                        {moveName}
                      </h2>
                    </div>
                    
                    <p className="text-body-lg text-muted-foreground">
                      Rolling 2d6 + {stat.toUpperCase()} 
                      {modifier !== 0 && ` ${modifier >= 0 ? '+' : ''}${modifier}`}
                    </p>
                  </motion.div>

                  {/* Dice Display */}
                  {!showResult && (
                    <motion.div
                      className="flex items-center justify-center gap-4"
                      initial={{ opacity: 0, scale: 0.8 }}
                      animate={{ opacity: 1, scale: 1 }}
                      transition={{ duration: 0.4, delay: 0.2 }}
                    >
                      {isRolling ? (
                        <>
                          <motion.div
                            animate={{ rotateY: 360 }}
                            transition={{ duration: 0.5, repeat: Infinity, ease: "linear" }}
                          >
                            <Dice1 size={48} className="text-primary" />
                          </motion.div>
                          <motion.div
                            animate={{ rotateY: -360 }}
                            transition={{ duration: 0.7, repeat: Infinity, ease: "linear" }}
                          >
                            <Dice1 size={48} className="text-primary" />
                          </motion.div>
                        </>
                      ) : (
                        <>
                          <Dice1 size={48} className="text-muted-foreground" />
                          <Dice1 size={48} className="text-muted-foreground" />
                        </>
                      )}
                    </motion.div>
                  )}

                  {/* Roll Result */}
                  {showResult && rollResult && (
                    <motion.div
                      className="space-y-4"
                      initial={{ opacity: 0, scale: 0.8 }}
                      animate={{ opacity: 1, scale: 1 }}
                      transition={{ duration: 0.5 }}
                    >
                      {/* Dice Results */}
                      <div className="flex items-center justify-center gap-4">
                        {rollResult.dice.map((die: number, index: number) => {
                          const DiceIcon = getDiceIcon(die)
                          return (
                            <motion.div
                              key={index}
                              initial={{ rotateY: 0 }}
                              animate={{ rotateY: 360 }}
                              transition={{ duration: 0.6, delay: index * 0.1 }}
                            >
                              <DiceIcon size={48} className="text-primary" />
                            </motion.div>
                          )
                        })}
                      </div>

                      {/* Total and Outcome */}
                      <div className="text-center">
                        <motion.div
                          className="text-4xl font-bold mb-2"
                          initial={{ scale: 0 }}
                          animate={{ scale: 1 }}
                          transition={{ type: "spring", stiffness: 200, delay: 0.3 }}
                        >
                          <span className={getOutcomeColor(rollResult.total)}>
                            {rollResult.total}
                          </span>
                        </motion.div>
                        
                        <motion.div
                          className="text-lg font-medium"
                          initial={{ opacity: 0 }}
                          animate={{ opacity: 1 }}
                          transition={{ delay: 0.5 }}
                        >
                          <span className={getOutcomeColor(rollResult.total)}>
                            {getOutcomeText(rollResult.total)}
                          </span>
                        </motion.div>

                        {/* Breakdown */}
                        <motion.p
                          className="text-sm text-muted-foreground mt-2"
                          initial={{ opacity: 0 }}
                          animate={{ opacity: 1 }}
                          transition={{ delay: 0.7 }}
                        >
                          {rollResult.dice.join(' + ')} + {rollResult.modifier} = {rollResult.total}
                        </motion.p>
                      </div>
                    </motion.div>
                  )}

                  {/* Action Buttons */}
                  <motion.div
                    className="flex gap-4 justify-center"
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.4, delay: 0.4 }}
                  >
                    {!showResult ? (
                      <>
                        <Button
                          variant="primary"
                          size="lg"
                          onClick={handleRoll}
                          disabled={isRolling}
                          className="gap-2 magical-glow"
                        >
                          <Sparkles size={20} />
                          {isRolling ? 'Rolling...' : 'Roll Dice'}
                        </Button>
                        
                        <Button
                          variant="outline"
                          size="lg"
                          onClick={onCancel}
                          disabled={isRolling}
                        >
                          Cancel
                        </Button>
                      </>
                    ) : (
                      <Button
                        variant="primary"
                        size="lg"
                        onClick={handleComplete}
                        className="gap-2"
                      >
                        Continue
                      </Button>
                    )}
                  </motion.div>
                </div>
              </CardContent>
            </Card>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  )
}

/**
 * MoveContextAnalyzer - Intelligent move suggestions based on game state
 * Analyzes current situation and suggests optimal moves for the player
 */

import React, { useMemo } from 'react'
import { motion } from 'framer-motion'
import { Card, CardContent, Badge } from '../ui'
import { Character } from '../../models/Character'
import { Brain, Target, Users, Eye, Zap, AlertTriangle } from 'lucide-react'

interface GameContext {
  inCombat: boolean
  hasEnemiesNearby: boolean
  lowHealth: boolean
  hasSpellsReady: boolean
  hasAllies: boolean
  inDanger: boolean
  exploringNew: boolean
  socialSituation: boolean
}

interface MoveSuggestion {
  moveId: string
  name: string
  reason: string
  priority: 'high' | 'medium' | 'low'
  contextMatch: number
  icon: React.ComponentType<{ size?: number; className?: string }>
}

interface MoveContextAnalyzerProps {
  character: Character
  gameContext: GameContext
  onMoveSuggestion: (moveId: string) => void
  className?: string
}

const getStatScore = (stat: any): number => {
  if (stat == null) return 0
  if (typeof stat === 'number') return stat
  if (typeof stat === 'object') {
    if (typeof (stat as any).value === 'number') return (stat as any).value
    if (typeof (stat as any).score === 'number') return (stat as any).score
  }
  return 0
}

const analyzeContext = (character: Character, context: GameContext): MoveSuggestion[] => {
  const suggestions: MoveSuggestion[] = []

  // Combat context analysis
  if (context.inCombat) {
    if (character.hp.current < character.hp.max * 0.3) {
      suggestions.push({
        moveId: 'defend',
        name: 'Defend',
        reason: 'Low health - prioritize defense',
        priority: 'high',
        contextMatch: 0.9,
        icon: Target
      })
    }

    if (context.hasEnemiesNearby && getStatScore((character as any).stats?.strength) >= 13) {
      suggestions.push({
        moveId: 'hack-and-slash',
        name: 'Hack and Slash',
        reason: 'Strong character in melee range',
        priority: 'high',
        contextMatch: 0.85,
        icon: Target
      })
    }

    if (getStatScore((character as any).stats?.dexterity) >= 13) {
      suggestions.push({
        moveId: 'volley',
        name: 'Volley',
        reason: 'High dexterity for ranged attacks',
        priority: 'medium',
        contextMatch: 0.7,
        icon: Target
      })
    }
  }

  // Exploration context
  if (context.exploringNew) {
    if (getStatScore((character as any).stats?.wisdom) >= 13) {
      suggestions.push({
        moveId: 'discern-realities',
        name: 'Discern Realities',
        reason: 'High wisdom for understanding new areas',
        priority: 'high',
        contextMatch: 0.8,
        icon: Eye
      })
    }

    if (getStatScore((character as any).stats?.intelligence) >= 13) {
      suggestions.push({
        moveId: 'spout-lore',
        name: 'Spout Lore',
        reason: 'Use knowledge to understand situation',
        priority: 'medium',
        contextMatch: 0.75,
        icon: Brain
      })
    }
  }

  // Social context
  if (context.socialSituation) {
    if (getStatScore((character as any).stats?.charisma) >= 13) {
      suggestions.push({
        moveId: 'parley',
        name: 'Parley',
        reason: 'High charisma for social manipulation',
        priority: 'high',
        contextMatch: 0.85,
        icon: Users
      })
    }
  }

  // Spellcasting context
  if (context.hasSpellsReady && character.class === 'wizard') {
    suggestions.push({
      moveId: 'cast-spell',
      name: 'Cast a Spell',
      reason: 'Spells prepared and ready to cast',
      priority: 'medium',
      contextMatch: 0.8,
      icon: Zap
    })
  }

  // Danger context
  if (context.inDanger) {
    suggestions.push({
      moveId: 'defy-danger',
      name: 'Defy Danger',
      reason: 'Immediate danger requires action',
      priority: 'high',
      contextMatch: 0.95,
      icon: AlertTriangle
    })
  }

  // Sort by priority and context match
  return suggestions.sort((a, b) => {
    const priorityWeight = { high: 3, medium: 2, low: 1 }
    const aPriority = priorityWeight[a.priority]
    const bPriority = priorityWeight[b.priority]
    
    if (aPriority !== bPriority) {
      return bPriority - aPriority
    }
    
    return b.contextMatch - a.contextMatch
  }).slice(0, 3) // Top 3 suggestions
}

const getPriorityColor = (priority: MoveSuggestion['priority']) => {
  switch (priority) {
    case 'high': return 'text-destructive bg-destructive/15'
    case 'medium': return 'text-chart-4 bg-chart-4/15'
    case 'low': return 'text-primary bg-primary/10'
  }
}

export const MoveContextAnalyzer: React.FC<MoveContextAnalyzerProps> = ({
  character,
  gameContext,
  onMoveSuggestion,
  className = ''
}) => {
  const suggestions = useMemo(() => 
    analyzeContext(character, gameContext), 
    [character, gameContext]
  )

  if (suggestions.length === 0) {
    return null
  }

  return (
    <motion.div
      className={`space-y-3 ${className}`}
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.4 }}
    >
      <div className="flex items-center gap-2 mb-4">
        <Brain size={20} className="text-primary" />
        <h3 className="text-body-lg font-display text-foreground">
          Suggested Moves
        </h3>
      </div>

      <div className="space-y-2">
        {suggestions.map((suggestion, index) => {
          const Icon = suggestion.icon
          
          return (
            <motion.div
              key={suggestion.moveId}
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.3, delay: index * 0.1 }}
            >
              <Card
                variant="surface"
                className="cursor-pointer hover:shadow-md transition-all duration-200 hover:scale-[1.02]"
                onClick={() => onMoveSuggestion(suggestion.moveId)}
              >
                <CardContent className="p-4 pt-4">
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 rounded-lg bg-primary/20 flex items-center justify-center flex-shrink-0">
                      <Icon size={16} className="text-primary" />
                    </div>
                    
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                        <h4 className="text-ui-small font-medium text-foreground truncate">
                          {suggestion.name}
                        </h4>
                        <Badge 
                          variant="secondary" 
                          className={`text-xs px-2 py-0.5 ${getPriorityColor(suggestion.priority)}`}
                        >
                          {suggestion.priority}
                        </Badge>
                      </div>
                      
                      <p className="text-xs text-muted-foreground leading-relaxed">
                        {suggestion.reason}
                      </p>
                    </div>
                    
                    <div className="flex-shrink-0">
                      <div className="text-xs text-muted-foreground font-mono">
                        {Math.round(suggestion.contextMatch * 100)}%
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>
            </motion.div>
          )
        })}
      </div>

      <motion.div
        className="text-center mt-4"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 0.4, delay: 0.5 }}
      >
        <p className="text-xs text-muted-foreground">
          Suggestions based on current game context and character abilities
        </p>
      </motion.div>
    </motion.div>
  )
}

import React, { useState, useMemo } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { Card, CardHeader, CardTitle, CardDescription, CardContent, Button, Badge } from '../ui'
import { Sword, Shield, Eye, Brain, Users, Zap, Book, Target, BicepsFlexed, Sparkles } from 'lucide-react'
import { MoveContextAnalyzer } from './MoveContextAnalyzer'
import { Move3DIntegration } from './Move3DIntegration'
import { RollableMove } from '../common/RollableElement'
import { Character, type Attributes } from '../../models/Character'
import { getMovesForClass, getStartingMovesForClass } from '../../models/ClassMoves'
import { BASIC_MOVES } from '../../models/Move'

interface Move {
  id: string
  name: string
  description: string
  trigger: string
  stat: keyof Attributes
  category: 'basic' | 'special' | 'class'
  icon: React.ComponentType<{ size?: number; className?: string }>
}

const basicMoves: Move[] = [
  {
    id: 'hack-and-slash',
    name: 'Hack and Slash',
    description: 'When you attack an enemy in melee, roll+Str. On a 10+, you deal your damage to the enemy and avoid their attack. On a 7-9, you deal your damage to the enemy and the enemy makes an attack against you.',
    trigger: 'When you attack an enemy in melee',
    stat: 'STR',
    category: 'basic',
    icon: Sword
  },
  {
    id: 'volley',
    name: 'Volley',
    description: 'When you take aim and shoot at an enemy at range, roll+Dex. On a 10+, you have a clear shot—deal your damage. On a 7-9, choose one: you have to move to get the shot placing you in danger, you have to take what you can get (reduce damage), or you have to take several shots (reduce ammo).',
    trigger: 'When you take aim and shoot at an enemy at range',
    stat: 'DEX',
    category: 'basic',
    icon: Target
  },
  {
    id: 'defend',
    name: 'Defend',
    description: 'When you stand in defense of a person, item, or location under attack, roll+Con. On a 10+, hold 3. On a 7-9, hold 1. Spend hold to redirect an attack from the thing you defend to yourself, or deal damage to the attacker equal to your level.',
    trigger: 'When you stand in defense of a person, item, or location under attack',
    stat: 'CON',
    category: 'basic',
    icon: Shield
  },
  {
    id: 'spout-lore',
    name: 'Spout Lore',
    description: 'When you consult your accumulated knowledge about something, roll+Int. On a 10+, the GM will tell you something interesting and useful about the subject relevant to your situation. On a 7-9, the GM will only tell you something interesting—it\'s on you to make it useful.',
    trigger: 'When you consult your accumulated knowledge about something',
    stat: 'INT',
    category: 'basic',
    icon: Brain
  },
  {
    id: 'discern-realities',
    name: 'Discern Realities',
    description: 'When you closely study a situation or person, roll+Wis. On a 10+, ask the GM 3 questions from the list below. On a 7-9, ask 1. Take +1 forward when acting on the answers.',
    trigger: 'When you closely study a situation or person',
    stat: 'WIS',
    category: 'basic',
    icon: Eye
  },
  {
    id: 'parley',
    name: 'Parley',
    description: 'When you have leverage on a GM character and manipulate them, roll+Cha. Leverage is something they need or want. On a 10+, they do what you ask if you first promise what they ask of you. On a 7-9, they will do what you ask, but need some concrete assurance of your promise, right now.',
    trigger: 'When you have leverage on a GM character and manipulate them',
    stat: 'CHA',
    category: 'basic',
    icon: Users
  }
]

// Convert our comprehensive moves to the local Move interface format
const convertMoveFormat = (move: any): Move => ({
  id: move.id || move.name.toLowerCase().replace(/\s+/g, '-'),
  name: move.name,
  description: move.description + (move.onSuccess ? ` On 10+: ${move.onSuccess}` : '') + (move.onPartial ? ` On 7-9: ${move.onPartial}` : ''),
  trigger: move.trigger,
  stat: move.rollStat?.toLowerCase() || 'strength',
  category: move.category,
  icon: getIconForMove(move)
})

const getIconForMove = (move: any) => {
  if (move.name.includes('Spell') || move.name.includes('Magic')) return Zap
  if (move.name.includes('Slash') || move.name.includes('Attack')) return Sword
  if (move.name.includes('Defend') || move.name.includes('Shield')) return Shield
  if (move.name.includes('Lore') || move.name.includes('Knowledge')) return Brain
  if (move.name.includes('Track') || move.name.includes('Hunt')) return Eye
  if (move.name.includes('Parley') || move.name.includes('Charm')) return Users
  return Sparkles
}

const statIcons = {
  STR: BicepsFlexed,
  DEX: Target,
  CON: Shield,
  INT: Brain,
  WIS: Eye,
  CHA: Users
}

interface MovesPanelProps {
  character: Character
  characterClass?: string
  onMoveSelect?: (move: Move) => void
  onRollComplete?: (result: any) => void
}

interface GameContext {
  inCombat: boolean
  hasEnemiesNearby: boolean
  lowHealth: boolean
  hasSpellsReady: boolean
  hasAllies: boolean
  inDanger: boolean
  exploringNew: boolean
  socialSituation: boolean
}

export const MovesPanel: React.FC<MovesPanelProps> = ({
  character,
  characterClass = 'wizard',
  onMoveSelect,
  onRollComplete
}) => {
  const [selectedCategory, setSelectedCategory] = useState<'basic' | 'class'>('basic')
  const [selectedMove, setSelectedMove] = useState<Move | null>(null)
  const [showMoveIntegration, setShowMoveIntegration] = useState(false)
  const [showContextAnalyzer, setShowContextAnalyzer] = useState(true)

  // Get moves based on character class and category
  const moves = useMemo(() => {
    if (selectedCategory === 'basic') {
      return basicMoves
    } else {
      const classMoves = getMovesForClass(character.class || characterClass)
      return classMoves.map(convertMoveFormat)
    }
  }, [selectedCategory, character.class, characterClass])

  // Analyze current game context
  const gameContext = useMemo((): GameContext => {
    const healthPercentage = character.hp.current / character.hp.max
    
    return {
      inCombat: false, // This would come from game state
      hasEnemiesNearby: false, // This would come from game state
      lowHealth: healthPercentage < 0.5,
      hasSpellsReady: character.class === 'wizard', // Simplified check
      hasAllies: false, // This would come from game state
      inDanger: healthPercentage < 0.3,
      exploringNew: true, // This would come from game state
      socialSituation: false // This would come from game state
    }
  }, [character])

  const handleMoveClick = (move: Move) => {
    setSelectedMove(move)
    onMoveSelect?.(move)
  }

  const handleMoveSuggestion = (moveId: string) => {
    const allMoves = [
      ...basicMoves,
      ...getMovesForClass(character.class || characterClass).map(convertMoveFormat)
    ]
    const move = allMoves.find(m => m.id === moveId)
    if (move) {
      setSelectedMove(move)
      onMoveSelect?.(move)
    }
  }

  const handleExecuteMove = () => {
    if (selectedMove) {
      setShowMoveIntegration(true)
    }
  }

  const handleRollComplete = (result: any) => {
    setShowMoveIntegration(false)
    setSelectedMove(null)
    onRollComplete?.(result)
  }

  const handleCancelMove = () => {
    setShowMoveIntegration(false)
  }

  return (
    <div className="space-y-6">
      {/* Context Analyzer */}
      {showContextAnalyzer && (
        <motion.div
          initial={{ opacity: 0, height: 0 }}
          animate={{ opacity: 1, height: 'auto' }}
          exit={{ opacity: 0, height: 0 }}
        >
          <MoveContextAnalyzer
            character={character}
            gameContext={gameContext}
            onMoveSuggestion={handleMoveSuggestion}
          />
        </motion.div>
      )}

      {/* Category Selector */}
      <Card variant="surface">
        <CardContent>
          <div className="flex items-center justify-between">
            <div className="flex gap-2">
              <Button
                variant={selectedCategory === 'basic' ? 'primary' : 'outline'}
                size="sm"
                onClick={() => setSelectedCategory('basic')}
              >
                Basic Moves
              </Button>
              <Button
                variant={selectedCategory === 'class' ? 'primary' : 'outline'}
                size="sm"
                onClick={() => setSelectedCategory('class')}
              >
                {(character.class || characterClass).charAt(0).toUpperCase() + (character.class || characterClass).slice(1)} Moves
              </Button>
            </div>
            
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setShowContextAnalyzer(!showContextAnalyzer)}
              className="gap-2"
            >
              <Brain size={16} />
              {showContextAnalyzer ? 'Hide' : 'Show'} Suggestions
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Moves List */}
      <motion.div
        className="grid gap-4"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        key={selectedCategory}
      >
        {moves.map((move, index) => {
          const StatIcon = statIcons[move.stat]
          const MoveIcon = move.icon
          
          return (
            <motion.div
              key={move.id}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.1 }}
            >
              <RollableMove
                moveId={move.id}
                moveName={move.name}
                stat={move.stat}
                characterId="eldara-moonwhisper" // TODO: Use actual character ID
                onRoll={handleRollComplete}
                enableRightClick={true}
                showHoverDice={true}
                className={`cursor-pointer transition-all duration-300 hover:shadow-lg ${
                  selectedMove?.id === move.id ? 'ring-2 ring-primary/50' : ''
                }`}
              >
                <Card
                  variant="parchment"
                  onClick={() => handleMoveClick(move)}
                >
                <CardHeader>
                  <div className="flex items-start justify-between">
                    <div className="flex items-center gap-3">
                      <motion.div
                        className="w-10 h-10 rounded-lg bg-primary/20 flex items-center justify-center"
                        whileHover={{ scale: 1.1 }}
                        whileTap={{ scale: 0.95 }}
                      >
                        <MoveIcon size={20} className="text-primary" />
                      </motion.div>
                      <div>
                        <CardTitle className="text-lg">{move.name}</CardTitle>
                        <div className="flex items-center gap-2 mt-1">
                          <Badge variant="secondary" className="text-xs">
                            <StatIcon size={12} className="mr-1" />
                            {move.stat.slice(0, 3).toUpperCase()}
                          </Badge>
                          <Badge 
                            variant={move.category === 'basic' ? 'default' : 'magical'} 
                            className="text-xs"
                          >
                            {move.category}
                          </Badge>
                        </div>
                      </div>
                    </div>
                  </div>
                </CardHeader>
                
                <CardContent>
                  <div className="space-y-3">
                    <div>
                      <p className="text-sm font-medium text-primary mb-1">
                        Trigger:
                      </p>
                      <p className="text-sm text-muted-foreground italic">
                        {move.trigger}
                      </p>
                    </div>
                    
                    <div>
                      <p className="text-sm font-medium text-primary mb-1">
                        Effect:
                      </p>
                      <p className="text-sm text-foreground leading-relaxed">
                        {move.description}
                      </p>
                    </div>

                    <div className="flex justify-end pt-2">
                      <Button
                        variant="primary"
                        size="sm"
                        onClick={(e) => {
                          e.stopPropagation()
                          handleMoveClick(move)
                        }}
                        className="min-w-[80px]"
                      >
                        {move.name}
                      </Button>
                    </div>
                  </div>
                </CardContent>
                </Card>
              </RollableMove>
            </motion.div>
          )
        })}
      </motion.div>

      {/* Selected Move Action */}
      <AnimatePresence key={selectedMove?.id || 'no-move'}>
        {selectedMove && (
          <motion.div
            key={`selected-move-${selectedMove.id}`}
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 0.95 }}
            className="fixed bottom-6 left-1/2 transform -translate-x-1/2 z-50"
          >
            <Card variant="magical" className="shadow-2xl">
              <CardContent>
                <div className="flex items-center gap-4">
                  <div className="text-sm font-medium">
                    Ready to use <span className="text-primary">{selectedMove.name}</span>?
                  </div>
                  <Button
                    variant="primary"
                    size="sm"
                    onClick={handleExecuteMove}
                    className="gap-2 magical-glow"
                  >
                    <Sparkles size={16} />
                    Execute Move
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => setSelectedMove(null)}
                  >
                    Cancel
                  </Button>
                </div>
              </CardContent>
            </Card>
          </motion.div>
        )}
      </AnimatePresence>

      {/* 3D Move Integration */}
      {selectedMove && (
        <Move3DIntegration
          moveId={selectedMove.id}
          moveName={selectedMove.name}
          stat={selectedMove.stat}
          modifier={(() => {
            const s: any = (character as any).stats?.[selectedMove.stat as any]
            if (typeof s === 'number') return Math.floor((s - 10) / 2)
            if (s && typeof s.modifier === 'number') return s.modifier
            if (s && typeof s.value === 'number') return Math.floor(((s.value as number) - 10) / 2)
            return 0
          })()}
          onRollComplete={handleRollComplete}
          onCancel={handleCancelMove}
          isVisible={showMoveIntegration}
        />
      )}
    </div>
  )
}

