export const PlayTab: React.FC<PlayTabProps> = ({ className = '' }) => {
  const { getActiveCharacter } = useCharacterStore()
  const activeCharacter = getActiveCharacter()
  const { isOverlayEnabled: _isOverlayEnabled } = useChronicle()
  const chronicleTextareaRef = useRef<HTMLTextAreaElement>(null)

  // New state for Immersive Storyteller Mode
  const [activeTab, setActiveTab] = useState<ActiveTab>('chronicle')
  const [toolsSubTab, setToolsSubTab] = useState<ToolsSubTab>('items')
  const [characterPanelCollapsed, setCharacterPanelCollapsed] = useState(true)
  const [campaignVibe, setCampaignVibe] = useState<CampaignVibe>('fantasy')

  // Chronicle state
  const [chronicleText, setChronicleText] = useState('')
  const [chronicleEntries, setChronicleEntries] = useState<ChronicleEntry[]>([])
  const [pendingDiceContext, setPendingDiceContext] = useState<DiceRollContext | null>(null)

  // Tool creation state
  const [itemInput, setItemInput] = useState('')
  const [npcInput, setNpcInput] = useState('')
  const [monsterInput, setMonsterInput] = useState('')
  const [createdItems, setCreatedItems] = useState<CreatedItem[]>([])
  const [createdNPCs, setCreatedNPCs] = useState<CreatedNPC[]>([])
  const [createdMonsters, setCreatedMonsters] = useState<CreatedMonster[]>([])

  // Session management
  const [sessionStartTime, setSessionStartTime] = useState<Date | null>(null)
  const [isSessionActive, setIsSessionActive] = useState(false)
  const [sessionTime, setSessionTime] = useState(0)

  // AI Enhancement state
  const [aiEnhancer, setAiEnhancer] = useState<OllamaAiNoteEnhancer | null>(null)
  const [aiStatus, setAiStatus] = useState<'loading' | 'ready' | 'fallback' | 'error'>('loading')
  const [isEnhancing, setIsEnhancing] = useState(false)
  const [aiProgress, setAiProgress] = useState<AIProgress>({ progress: 0, text: "Starting AI...", stage: "loading" })

  // Initialize AI enhancer
  useEffect(() => {
    const initializeAI = async () => {
      try {
        const enhancer = new OllamaAiNoteEnhancer()
        setAiStatus('loading')
        setAiProgress({ progress: 0, text: "Starting AI...", stage: "loading" })
        logger.info('🤖 Starting AI initialization...')

        // Set up progress callback
        enhancer.onProgress = (progress) => {
          setAiProgress(progress)
        }

        // Set a timeout for AI initialization
        const timeout = setTimeout(() => {
          logger.warn('⏰ AI taking longer than expected, falling back to pattern mode')
          setAiStatus('fallback')
          setAiProgress({ progress: 0, text: "Timed out - using pattern mode", stage: "error" })
        }, 120000) // 2 minutes timeout

        await enhancer.initialize()
        clearTimeout(timeout)

        setAiEnhancer(enhancer)
        setAiStatus('ready')
        setAiProgress({ progress: 100, text: "AI ready!", stage: "ready" })
        logger.info('🎉 AI Note Enhancer ready!')
      } catch (error) {
        logger.warn('⚠️ AI unavailable, using pattern fallback:', error)
        setAiStatus('fallback')
        setAiProgress({ progress: 0, text: "AI failed - using pattern mode", stage: "error" })
      }
    }

    initializeAI()

    return () => {
      if (aiEnhancer) {
        aiEnhancer.dispose()
      }
    }
  }, [])

  useEffect(() => {
    let interval: NodeJS.Timeout
    if (isSessionActive && sessionStartTime) {
      interval = setInterval(() => {
        setSessionTime(Math.floor((Date.now() - sessionStartTime.getTime()) / 60000))
      }, 60000)
    }
    return () => clearInterval(interval)
  }, [isSessionActive, sessionStartTime])

  const startSession = () => {
    setIsSessionActive(true)
    setSessionStartTime(new Date())
  }

  const endSession = () => {
    setIsSessionActive(false)
    setSessionStartTime(null)
    setSessionTime(0)
  }

  // Character action handlers for AI function calls
  const handleCharacterAction = (action: CharacterAction) => {
    const { type, params } = action

    switch (type) {
      case 'apply_debility':
        logger.info(`Applying debility: ${params.debility} (${params.reason})`)
        // TODO: Integrate with character store
        // characterStore.applyDebility(params.debility, params.reason)
        break

      case 'modify_hp':
        logger.info(`Modifying HP: ${params.change > 0 ? '+' : ''}${params.change} (${params.reason})`)
        // TODO: Integrate with character store
        // characterStore.modifyHP(params.change, params.reason)
        break

      case 'add_gear':
        logger.info(`Adding gear: ${params.name} - ${params.description}`)
        // TODO: Integrate with character store
        // characterStore.addGear(params.name, params.tags || [], params.description, params.weight, params.uses)
        break

      case 'spend_resource':
        logger.info(`Spending resource: ${params.amount} ${params.resource} (${params.reason})`)
        // TODO: Integrate with character store
        // characterStore.spendResource(params.resource, params.amount, params.reason)
        break

      case 'gain_xp':
        logger.info(`Gaining XP: ${params.amount} from ${params.trigger} (${params.description})`)
        // TODO: Integrate with character store
        // characterStore.gainXP(params.amount, params.trigger, params.description)
        break

      case 'update_bonds':
        logger.info(`Updating bonds with ${params.character}: ${params.new_bond} (${params.action})`)
        // TODO: Integrate with character store
        // characterStore.updateBonds(params.character, params.new_bond, params.action)
        break

      default:
        logger.warn('Unknown character action type:', type)
    }
  }

  // Chronicle management functions
  const addChronicleEntry = async (rawText: string) => {
    if (!rawText.trim()) return

    let enhanced = rawText
    let actions: CharacterAction[] = []

    setIsEnhancing(true)
    logger.info(`🎭 Processing chronicle entry: "${rawText}"`)
    logger.info(`🤖 AI Status: ${aiStatus}, AI Ready: ${!!aiEnhancer}`)

    try {
      // Try AI enhancement first
      if (aiStatus === 'ready' && aiEnhancer) {
        logger.info('✨ Using AI enhancement...')
        const result = await aiEnhancer.enhance(rawText, campaignVibe)
        enhanced = result.enhancedText
        actions = result.actions
        logger.info(`📝 Enhanced text: "${enhanced}"`)
        logger.info(`⚡ Actions detected:`, actions)

        // Execute character actions
        actions.forEach(action => handleCharacterAction(action))
      } else if (aiStatus === 'fallback') {
        logger.info('🔄 Using pattern-based fallback enhancement')
        // Fallback to pattern-based enhancement
        enhanced = enhanceNote(rawText, campaignVibe)
        logger.info(`📝 Pattern enhanced: "${enhanced}"`)
      } else {
        logger.info(`⚠️ No enhancement - AI status: ${aiStatus}, enhancer: ${!!aiEnhancer}`)
      }
    } catch (error) {
      logger.warn('AI enhancement failed, using fallback:', error)
      enhanced = enhanceNote(rawText, campaignVibe)
    } finally {
      setIsEnhancing(false)
    }

    const entry: ChronicleEntry = {
      id: Math.random().toString(36).substr(2, 9),
      content: enhanced,
      timestamp: new Date(),
      enhanced: enhanced !== rawText,
      originalNote: enhanced !== rawText ? rawText : undefined
    }

    setChronicleEntries(prev => [...prev, entry])
    setChronicleText('')

    // Auto-scroll chronicle
    setTimeout(() => {
      if (chronicleTextareaRef.current) {
        chronicleTextareaRef.current.scrollTop = chronicleTextareaRef.current.scrollHeight
      }
    }, 100)
  }

  const handleDiceRoll = (roll: { finalResult: number; modifier: number; outcome: string }) => {
    const diceContext: DiceRollContext = {
      id: Math.random().toString(36).substr(2, 9),
      result: roll.finalResult,
      modifier: roll.modifier,
      stat: 'move',
      timestamp: new Date(),
      outcome: roll.outcome
    }
    setPendingDiceContext(diceContext)
  }

  const completeDiceContext = (context: string, outcome: string) => {
    if (pendingDiceContext) {
      const rollText = `${context} (${pendingDiceContext.stat} roll: ${pendingDiceContext.result}) - ${outcome}`
      addChronicleEntry(rollText)
      setPendingDiceContext(null)
    }
  }

  // Tool creation functions
  const handleCreateItem = () => {
    if (!itemInput.trim()) return
    const item = createItem(itemInput)
    setCreatedItems(prev => [...prev, item])
    setItemInput('')
  }

  const handleCreateNPC = () => {
    if (!npcInput.trim()) return
    const npc = createNPC(npcInput)
    setCreatedNPCs(prev => [...prev, npc])
    setNpcInput('')
  }

  const handleCreateMonster = () => {
    if (!monsterInput.trim()) return
    const monster = createMonster(monsterInput)
    setCreatedMonsters(prev => [...prev, monster])
    setMonsterInput('')
  }

  if (!activeCharacter) {
    return (
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        className={`p-4 ${className}`}
      >
        <Card variant="magical">
          <CardContent className="p-6 pt-6">
            <div className="text-center space-y-4">
              <div className="w-12 h-12 mx-auto rounded-full bg-muted  flex items-center justify-center">
                <BookOpen size={24} className="text-muted-foreground" />
              </div>
              <div>
                <h2 className="text-lg font-display mb-2">Ready to Chronicle?</h2>
                <p className="text-muted-foreground  text-sm mb-4">
                  Create or select a character to begin your storytelling adventure
                </p>
                <Button variant="primary" size="sm">
                  Create Character
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>
      </motion.div>
    )
  }

  const xpNeeded = getXPThreshold(activeCharacter.level)

  return (
    <div className={`flex h-screen overflow-hidden ${className}`}>
      {/* Collapsible Character Panel */}
      <motion.div
        initial={false}
        animate={{ width: characterPanelCollapsed ? 60 : 300 }}
        className="bg-muted/50  border-r border-border flex-shrink-0"
      >
        <div className="p-4">
          <div className="flex items-center justify-between mb-4">
            {!characterPanelCollapsed && (
              <h3 className="text-lg font-semibold">{activeCharacter.name}</h3>
            )}
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setCharacterPanelCollapsed(!characterPanelCollapsed)}
              className="p-2"
            >
              {characterPanelCollapsed ? <ChevronRight size={16} /> : <ChevronLeft size={16} />}
            </Button>
          </div>

          {!characterPanelCollapsed && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className="space-y-4"
            >
              <div className="text-sm text-muted-foreground">
                Level {activeCharacter.level} {activeCharacter.class}
              </div>

              {/* Campaign Vibe Selector */}
              <div className="space-y-2">
                <label htmlFor="campaign-setting" className="text-xs font-medium text-foreground ">
                  Campaign Setting
                </label>
                <select
                  id="campaign-setting"
                  value={campaignVibe}
                  onChange={(e) => setCampaignVibe(e.target.value as CampaignVibe)}
                  className="w-full text-xs p-2 rounded border border-border bg-card"
                >
                  {Object.entries(campaignVibes).map(([key, config]) => (
                    <option key={key} value={key}>
                      {config.name}
                    </option>
                  ))}
                </select>
                <div className="text-xs text-muted-foreground">
                  Current: {campaignVibes[campaignVibe].name}
                </div>
              </div>

              <div className="space-y-3">
                <div>
                  <div className="flex justify-between text-xs mb-1">
                    <span>Health</span>
                    <span>{activeCharacter.hp.current}/{activeCharacter.hp.max}</span>
                  </div>
                  <Progress
                    value={activeCharacter.hp.current}
                    max={activeCharacter.hp.max}
                    variant="health"
                    className="h-2"
                  />
                </div>

                <div>
                  <div className="flex justify-between text-xs mb-1">
                    <span>XP</span>
                    <span>{activeCharacter.xp}/{xpNeeded}</span>
                  </div>
                  <Progress
                    value={activeCharacter.xp}
                    max={xpNeeded}
                    variant="experience"
                    className="h-2"
                  />
                </div>
              </div>

              <div className="pt-2 border-t border-border">
                <div className="flex items-center gap-2 mb-2">
                  <div className={`w-2 h-2 rounded-full ${isSessionActive ? 'bg-chart-2' : 'bg-gray-400'}`} />
                  <span className="text-xs font-medium">
                    {isSessionActive ? `${sessionTime}m` : 'Paused'}
                  </span>
                </div>
                <Button
                  variant={isSessionActive ? "destructive" : "primary"}
                  size="sm"
                  onClick={isSessionActive ? endSession : startSession}
                  className="w-full text-xs"
                >
                  {isSessionActive ? 'End Session' : 'Start Session'}
                </Button>
              </div>
            </motion.div>
          )}
        </div>
      </motion.div>

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col overflow-hidden">
        {/* Tab Navigation */}
        <div className="border-b border-border bg-card">
          <div className="flex">
            <Button
              variant={activeTab === 'chronicle' ? 'primary' : 'ghost'}
              onClick={() => setActiveTab('chronicle')}
              className="rounded-none border-b-2 border-transparent data-[active]:border-primary"
              data-active={activeTab === 'chronicle'}
            >
              <BookOpen size={16} />
              Chronicle
            </Button>
            <Button
              variant={activeTab === 'tools' ? 'primary' : 'ghost'}
              onClick={() => setActiveTab('tools')}
              className="rounded-none border-b-2 border-transparent data-[active]:border-primary"
              data-active={activeTab === 'tools'}
            >
              <Wrench size={16} />
              Tools
            </Button>
          </div>
        </div>

        {/* Tab Content */}
        <div className="flex-1 overflow-hidden">
          <AnimatePresence mode="wait">
            {activeTab === 'chronicle' && (
              <motion.div
                key="chronicle"
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -20 }}
                className="h-full flex flex-col p-6"
              >
                {/* Chronicle Canvas - 60% of available space */}
                <div className="flex-1 mb-6">
                  <Card variant="parchment" className="h-full">
                    <CardContent className="p-6 h-full flex flex-col">
                      <div className="flex items-center justify-between mb-4">
                        <h2 className="text-xl font-display flex items-center gap-2">
                          <Scroll size={20} className="text-primary" />
                          Your Story
                          {aiStatus === 'loading' && (
                            <PremiumProgressBar
                              progress={aiProgress.progress}
                              text={aiProgress.text}
                              stage={aiProgress.stage as 'downloading' | 'loading' | 'ready' | 'error'}
                              timeRemaining={aiProgress.time_remaining}
                              modelSize="~4GB"
                              showDetails={true}
                              className="max-w-md"
                            />
                          )}
                          {aiStatus === 'ready' && (
                            <Badge variant="default" className="text-xs">
                              🧠 AI Enhanced
                            </Badge>
                          )}
                          {aiStatus === 'fallback' && (
                            <Badge variant="outline" className="text-xs">
                              📝 Pattern Mode
                            </Badge>
                          )}
                          {aiStatus === 'error' && (
                            <Badge variant="destructive" className="text-xs">
                              ⚠️ AI Error
                            </Badge>
                          )}
                        </h2>
                        <Badge variant="secondary" className="text-xs">
                          {chronicleEntries.length} entries
                        </Badge>
                      </div>

                      {/* Chronicle Text Area */}
                      <div className="flex-1 flex flex-col">
                        <Textarea
                          ref={chronicleTextareaRef}
                          value={chronicleText}
                          onChange={(e) => setChronicleText(e.target.value)}
                          placeholder="What happens in your adventure? Write your story here...

Tip: Write naturally - 'fought goblins, got hurt' becomes 'You battled the goblin raiders, suffering wounds in the fierce struggle.'"
                          className="flex-1 resize-none text-base leading-relaxed font-serif"
                          style={{ minHeight: '400px' }}
                        />

                        <div className="flex justify-between items-center mt-4">
                          <div className="flex items-center gap-2">
                            <Sparkles size={14} className="text-primary" />
                            <span className="text-xs text-muted-foreground">AI enhancing your notes</span>
                          </div>
                          <Button
                            onClick={() => addChronicleEntry(chronicleText)}
                            disabled={!chronicleText.trim() || isEnhancing}
                            className="gap-2"
                          >
                            {isEnhancing ? (
                              <>
                                <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                                Enhancing...
                              </>
                            ) : (
                              <>
                                <Send size={16} />
                                Add to Chronicle
                              </>
                            )}
                          </Button>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                </div>

                {/* Recent Entries & Dice Context */}
                <div className="grid grid-cols-2 gap-6">
                  {/* Recent Chronicle Entries */}
                  <Card variant="surface">
                    <CardContent className="p-4">
                      <h3 className="font-semibold mb-3 flex items-center gap-2">
                        <BookOpen size={16} />
                        Recent Story
                      </h3>
                      <div className="space-y-3 max-h-60 overflow-y-auto">
                        {chronicleEntries.slice(-5).map((entry) => (
                          <div key={entry.id} className="p-3 bg-card rounded border-l-4 border-primary/30">
                            <div className="text-sm leading-relaxed">
                              {entry.content}
                            </div>
                            <div className="flex justify-between items-center mt-2">
                              <div className="text-xs text-muted-foreground">
                                {entry.timestamp.toLocaleTimeString()}
                              </div>
                              {entry.enhanced && (
                                <Badge variant="secondary" className="text-xs">
                                  Enhanced
                                </Badge>
                              )}
                            </div>
                          </div>
                        ))}
                        {chronicleEntries.length === 0 && (
                          <div className="text-center text-muted-foreground py-8">
                            <BookOpen size={32} className="mx-auto mb-2 opacity-50" />
                            <p className="text-sm">Your chronicle awaits...</p>
                          </div>
                        )}
                      </div>
                    </CardContent>
                  </Card>

                  {/* Dice Context & Floating Dice */}
                  <Card variant="magical">
                    <CardContent className="p-4">
                      <h3 className="font-semibold mb-3 flex items-center gap-2">
                        <Dice6 size={16} />
                        Dice & Actions
                      </h3>

                      {pendingDiceContext ? (
                        <div className="space-y-4">
                          <div className="p-3 bg-primary/10 rounded border border-primary/30 ">
                            <div className="text-sm font-medium mb-2">Last Roll: {pendingDiceContext.result}</div>
                            <Input
                              placeholder="What were you trying to do?"
                              onKeyDown={(e) => {
                                if (e.key === 'Enter') {
                                  const context = (e.target as HTMLInputElement).value
                                  const outcome = pendingDiceContext.result >= 10 ? 'Success!' :
                                    pendingDiceContext.result >= 7 ? 'Partial success' : 'Things went wrong'
                                  completeDiceContext(context, outcome)
                                }
                              }}
                              className="mb-2"
                            />
                            <Input
                              placeholder="What happened?"
                              onKeyDown={(e) => {
                                if (e.key === 'Enter') {
                                  const contextInput = e.target.parentElement?.querySelector('input') as HTMLInputElement
                                  const context = contextInput?.value || 'Something happened'
                                  const outcome = (e.target as HTMLInputElement).value
                                  completeDiceContext(context, outcome)
                                }
                              }}
                            />
                          </div>
                        </div>
                      ) : (
                        <div className="space-y-4">
                          <ChronicleEnabledDiceRoller
                            move="Story Roll"
                            characterName={activeCharacter.name}
                            onRoll={handleDiceRoll}
                          />
                          <div className="text-xs text-center text-muted-foreground">
                            Roll dice, then describe what happens
                          </div>
                        </div>
                      )}
                    </CardContent>
                  </Card>
                </div>
              </motion.div>
            )}

            {activeTab === 'tools' && (
              <motion.div
                key="tools"
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -20 }}
                className="h-full p-6"
              >
                {/* Tools Sub-navigation */}
                <div className="flex gap-2 mb-6">
                  <Button
                    variant={toolsSubTab === 'items' ? 'primary' : 'outline'}
                    onClick={() => setToolsSubTab('items')}
                    size="sm"
                  >
                    <Sword size={16} />
                    Items
                  </Button>
                  <Button
                    variant={toolsSubTab === 'monsters' ? 'primary' : 'outline'}
                    onClick={() => setToolsSubTab('monsters')}
                    size="sm"
                  >
                    <Crown size={16} />
                    Monsters
                  </Button>
                  <Button
                    variant={toolsSubTab === 'npcs' ? 'primary' : 'outline'}
                    onClick={() => setToolsSubTab('npcs')}
                    size="sm"
                  >
                    <User size={16} />
                    NPCs
                  </Button>
                </div>

                {/* Tools Content */}
                <div className="grid grid-cols-2 gap-6">
                  {/* Creator Panel */}
                  <Card variant="elevated">
                    <CardContent className="p-4">
                      <h3 className="font-semibold mb-3">
                        Create {toolsSubTab === 'items' ? 'Item' : toolsSubTab === 'monsters' ? 'Monster' : 'NPC'}
                      </h3>
                      <div className="space-y-3">
                        <Input
                          value={toolsSubTab === 'items' ? itemInput : toolsSubTab === 'monsters' ? monsterInput : npcInput}
                          onChange={(e) => {
                            if (toolsSubTab === 'items') setItemInput(e.target.value)
                            else if (toolsSubTab === 'monsters') setMonsterInput(e.target.value)
                            else setNpcInput(e.target.value)
                          }}
                          placeholder={`Describe your ${toolsSubTab.slice(0, -1)}...`}
                        />
                        <Button
                          onClick={toolsSubTab === 'items' ? handleCreateItem : toolsSubTab === 'monsters' ? handleCreateMonster : handleCreateNPC}
                          className="w-full gap-2"
                        >
                          <Sparkles size={16} />
                          Create with AI
                        </Button>
                      </div>
                    </CardContent>
                  </Card>

                  {/* Created Items List */}
                  <Card variant="surface">
                    <CardContent className="p-4">
                      <h3 className="font-semibold mb-3">
                        Your {toolsSubTab.charAt(0).toUpperCase() + toolsSubTab.slice(1)}
                      </h3>
                      <div className="space-y-3 max-h-96 overflow-y-auto">
                        {toolsSubTab === 'items' && createdItems.map(item => (
                          <div key={item.id} className="p-3 bg-card rounded border">
                            <div className="font-medium">{item.name}</div>
                            <div className="text-xs text-muted-foreground">{item.tags.join(', ')}</div>
                            <div className="text-sm mt-1">{item.description}</div>
                            <div className="text-xs font-mono mt-1">{item.stats}</div>
                          </div>
                        ))}

                        {toolsSubTab === 'monsters' && createdMonsters.map(monster => (
                          <div key={monster.id} className="p-3 bg-card rounded border">
                            <div className="font-medium">{monster.name}</div>
                            <div className="text-xs text-muted-foreground">{monster.hp} HP, {monster.armor} armor</div>
                            <div className="text-sm mt-1">{monster.instinct}</div>
                            <ul className="text-xs mt-1 list-disc list-inside">
                              {monster.moves.map((move, i) => <li key={i}>{move}</li>)}
                            </ul>
                          </div>
                        ))}

                        {toolsSubTab === 'npcs' && createdNPCs.map(npc => (
                          <div key={npc.id} className="p-3 bg-card rounded border">
                            <div className="font-medium">{npc.name}</div>
                            <div className="text-xs text-muted-foreground">{npc.quirk}</div>
                            <div className="text-sm mt-1">{npc.appearance}</div>
                            <div className="text-xs mt-1"><strong>Drive:</strong> {npc.drive}</div>
                            <div className="text-xs"><strong>Knows:</strong> {npc.knows}</div>
                          </div>
                        ))}
                      </div>
                    </CardContent>
                  </Card>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>
    </div>
  )
}

export default PlayTab

/**
 * CharacterStatusWidget - At-a-Glance Character Vitals
 *
 * Always-visible character status including animated health orb,
 * load meter, XP progress, active bonds, and debilities.
 */

import React, { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import {
  Heart,
  Shield,
  Package,
  Star,
  AlertTriangle,
  Zap,
  Eye,
  Users,
  Award,
  Flame,
  Droplets,
  Wind
} from 'lucide-react'
import { Card, CardContent, Badge, Button } from '../../ui'
import type { Character } from '../../../models/Character'
import type { GameMode, PlayTabTheme } from '../PlayTab'

interface CharacterStatusWidgetProps {
  character: Character
  gameMode: GameMode
  theme: PlayTabTheme
  className?: string
}

interface HealthOrbProps {
  current: number
  max: number
  size?: number
  variant?: 'primary' | 'danger' | 'warning'
}

const HealthOrb: React.FC<HealthOrbProps> = ({
  current,
  max,
  size = 80,
  variant = 'primary'
}) => {
  const percentage = Math.max(0, Math.min(100, (current / max) * 100))
  const strokeDasharray = 2 * Math.PI * (size / 2 - 8)
  const strokeDashoffset = strokeDasharray - (strokeDasharray * percentage) / 100

  const getColor = () => {
    if (percentage <= 25) return 'text-destructive'
    if (percentage <= 50) return 'text-chart-4'
    return 'text-chart-2'
  }

  const getPulseIntensity = () => {
    if (percentage <= 25) return 'animate-pulse'
    return ''
  }

  return (
    <div className="relative flex items-center justify-center">
      <svg
        width={size}
        height={size}
        className={`transform -rotate-90 ${getPulseIntensity()}`}
      >
        {/* Background circle */}
        <circle
          cx={size / 2}
          cy={size / 2}
          r={size / 2 - 8}
          stroke="currentColor"
          strokeWidth="4"
          fill="none"
          className="text-muted-foreground"
        />
        {/* Progress circle */}
        <motion.circle
          cx={size / 2}
          cy={size / 2}
          r={size / 2 - 8}
          stroke="currentColor"
          strokeWidth="6"
          fill="none"
          className={getColor()}
          strokeDasharray={strokeDasharray}
          strokeDashoffset={strokeDashoffset}
          strokeLinecap="round"
          initial={{ strokeDashoffset: strokeDasharray }}
          animate={{ strokeDashoffset }}
          transition={{ duration: 1, ease: "easeOut" }}
        />
      </svg>

      {/* Center content */}
      <div className="absolute inset-0 flex flex-col items-center justify-center">
        <Heart size={16} className={`${getColor()} mb-1`} />
        <span className="text-lg font-bold font-display">
          {current}
        </span>
        <span className="text-xs text-muted-foreground">/ {max}</span>
      </div>
    </div>
  )
}

const LoadMeter: React.FC<{ current: number; max: number }> = ({ current, max }) => {
  const percentage = Math.max(0, Math.min(100, (current / max) * 100))
  const isNearCapacity = percentage >= 80
  const isOverloaded = current > max

  return (
    <div className="space-y-2">
      <div className="flex items-center justify-between text-sm">
        <span className="flex items-center gap-1">
          <Package size={14} />
          Load
        </span>
        <span className={`font-mono ${isOverloaded ? 'text-destructive' : ''}`}>
          {current}/{max}
        </span>
      </div>

      <div className="relative h-2 bg-muted  rounded-full overflow-hidden">
        <motion.div
          className={`h-full rounded-full ${
            isOverloaded ? 'bg-destructive/120' :
            isNearCapacity ? 'bg-chart-4/120' :
            'bg-chart-2'
          }`}
          initial={{ width: 0 }}
          animate={{ width: `${Math.min(100, percentage)}%` }}
          transition={{ duration: 0.8, ease: "easeOut" }}
        />

        {isOverloaded && (
          <motion.div
            className="absolute top-0 right-0 h-full bg-destructive"
            style={{ width: `${(current - max) / max * 100}%` }}
            animate={{ opacity: [0.6, 1, 0.6] }}
            transition={{ duration: 1, repeat: Infinity }}
          />
        )}
      </div>
    </div>
  )
}

const XPTracker: React.FC<{ xp: number; level: number }> = ({ xp, level }) => {
  const xpToNext = (level + 1) * 7 - xp
  const progress = xp - (level * 7)
  const progressMax = 7

  return (
    <div className="space-y-2">
      <div className="flex items-center justify-between text-sm">
        <span className="flex items-center gap-1">
          <Star size={14} />
          Level {level}
        </span>
        <span className="text-xs text-muted-foreground">
          {xpToNext} XP to next
        </span>
      </div>

      <div className="relative h-1.5 bg-muted  rounded-full overflow-hidden">
        <motion.div
          className="h-full bg-gradient-to-r from-accent to-primary rounded-full"
          initial={{ width: 0 }}
          animate={{ width: `${(progress / progressMax) * 100}%` }}
          transition={{ duration: 0.6, ease: "easeOut" }}
        />
      </div>
    </div>
  )
}

const StatusEffect: React.FC<{
  type: 'debility' | 'condition' | 'buff'
  name: string
  icon: React.ReactNode
  color: string
}> = ({ type, name, icon, color }) => {
  return (
    <motion.div
      initial={{ scale: 0 }}
      animate={{ scale: 1 }}
      className={`p-1.5 rounded-full ${color} text-white text-xs flex items-center justify-center`}
      title={name}
      whileHover={{ scale: 1.1 }}
    >
      {icon}
    </motion.div>
  )
}

export const CharacterStatusWidget: React.FC<CharacterStatusWidgetProps> = ({
  character,
  gameMode,
  theme,
  className = ''
}) => {
  const [isExpanded, setIsExpanded] = useState(false)
  const [recentDamage, setRecentDamage] = useState<number | null>(null)

  // Calculate derived stats
  const armorTotal = character.armor || 0
  const loadCurrent = character.load?.current || 0
  const loadMax = character.load?.max || 10
  const xp = character.xp || 0
  const level = character.level || 1

  // Animate damage feedback
  useEffect(() => {
    if (recentDamage !== null) {
      const timer = setTimeout(() => setRecentDamage(null), 2000)
      return () => clearTimeout(timer)
    }
  }, [recentDamage])

  // Mock status effects (replace with real character state)
  const statusEffects = [
    // Example debilities
    ...(character.debilities?.weak ? [{ type: 'debility', name: 'Weak', icon: <Droplets size={12} />, color: 'bg-destructive/120' }] : []),
    ...(character.debilities?.shaky ? [{ type: 'debility', name: 'Shaky', icon: <Wind size={12} />, color: 'bg-chart-4/120' }] : []),
    // Add more status effects as needed
  ]

  const cardVariant =
    theme === 'combat' ? 'elevated' :
    theme === 'dungeon' ? 'parchment' :
    theme === 'tavern' ? 'magical' :
    'glass'

  return (
    <Card
      variant={cardVariant}
      className={`h-full relative overflow-hidden ${className}`}
    >
      <CardContent className="h-full flex flex-col">
        {/* Character Name & Portrait */}
        <div className="text-center mb-4">
          <motion.div
            className="w-12 h-12 mx-auto mb-2 rounded-full bg-gradient-to-br from-primary to-accent flex items-center justify-center text-white font-bold text-lg"
            whileHover={{ scale: 1.05 }}
            onClick={() => setIsExpanded(!isExpanded)}
          >
            {character.name.charAt(0).toUpperCase()}
          </motion.div>
          <h3 className="font-display text-sm font-medium truncate">
            {character.name}
          </h3>
          <p className="text-xs text-muted-foreground capitalize">
            {character.class} • Level {level}
          </p>
        </div>

        {/* Health Orb */}
        <div className="flex justify-center mb-4">
          <HealthOrb
            current={character.hitPoints?.current || 0}
            max={character.hitPoints?.max || 1}
            size={64}
          />
        </div>

        {/* Damage Feedback */}
        <AnimatePresence>
          {recentDamage && (
            <motion.div
              initial={{ opacity: 0, y: -20, scale: 0.8 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: -40, scale: 0.6 }}
              className="absolute top-4 right-4 bg-destructive/120 text-white px-2 py-1 rounded text-xs font-bold"
            >
              -{recentDamage}
            </motion.div>
          )}
        </AnimatePresence>

        {/* Core Stats */}
        <div className="space-y-3 flex-1">
          {/* Armor */}
          <div className="flex items-center justify-between text-sm">
            <span className="flex items-center gap-1">
              <Shield size={14} />
              Armor
            </span>
            <span className="font-mono">{armorTotal}</span>
          </div>

          {/* Load */}
          <LoadMeter current={loadCurrent} max={loadMax} />

          {/* XP Progress */}
          <XPTracker xp={xp} level={level} />
        </div>

        {/* Status Effects */}
        {statusEffects.length > 0 && (
          <div className="mt-4">
            <div className="text-xs text-muted-foreground mb-2">Status Effects</div>
            <div className="flex flex-wrap gap-1">
              {statusEffects.map((effect, index) => (
