                        key={item.id}
                        item={item}
                        isActive={false}
                        onClick={item.action}
                      />
                    ))}
                  </div>
                )}
              </motion.div>
            )}

            {/* Equipment */}
            {selectedCategory === 'equipment' && (
              <motion.div
                key="equipment"
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                className="space-y-3"
              >
                {quickEquipment.length === 0 ? (
                  <div className="text-center text-xs text-muted-foreground py-8">
                    <Sword size={24} className="mx-auto mb-2 opacity-50" />
                    <p>No equipped items</p>
                  </div>
                ) : (
                  <div className="space-y-2">
                    {quickEquipment.map(item => (
                      <QuickItemCard
                        key={item.id}
                        item={item}
                        isActive={false}
                        onClick={item.action}
                      />
                    ))}
                  </div>
                )}
              </motion.div>
            )}

            {/* Emergency Actions */}
            {selectedCategory === 'emergency' && (
              <motion.div
                key="emergency"
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                className="space-y-2"
              >
                {emergencyActions.map(action => (
                  <EmergencyButton
                    key={action.id}
                    action={action}
                    disabled={false}
                  />
                ))}
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        {/* Game Mode Specific Quick Tips */}
        <div className="pt-2 border-t border-border">
          <div className="text-xs text-muted-foreground text-center">
            {gameMode === 'combat' && '⚔️ Combat: Use items strategically'}
            {gameMode === 'exploration' && '🗺️ Exploration: Conserve resources'}
            {gameMode === 'social' && '🤝 Social: Items can be conversation tools'}
            {gameMode === 'rest' && '🏕️ Rest: Perfect time to organize gear'}
          </div>
        </div>
      </CardContent>
    </Card>
  )
}

