/**
 * SessionFlowControls - Session Management Tools
 *
 * Handles session timing, break reminders, and session flow controls.
 */

import React, { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import {
  Pause,
  Play,
  Square,
  Timer,
  Coffee,
  Clock,
  BarChart3
} from 'lucide-react'
import { Button, Badge } from '../../ui'

interface SessionFlowControlsProps {
  sessionStartTime: Date | null
  onEndSession: () => void
  className?: string
}

export const SessionFlowControls: React.FC<SessionFlowControlsProps> = ({
  sessionStartTime,
  onEndSession,
  className = ''
}) => {
  const [sessionDuration, setSessionDuration] = useState(0)
  const [isPaused, setIsPaused] = useState(false)
  const [pausedTime, setPausedTime] = useState(0)

  // Update session duration every minute
  useEffect(() => {
    if (!sessionStartTime || isPaused) return

    const interval = setInterval(() => {
      const now = new Date()
      const duration = Math.floor((now.getTime() - sessionStartTime.getTime()) / 60000) - pausedTime
      setSessionDuration(Math.max(0, duration))
    }, 60000) // Update every minute

    // Initial calculation
    const now = new Date()
    const duration = Math.floor((now.getTime() - sessionStartTime.getTime()) / 60000) - pausedTime
    setSessionDuration(Math.max(0, duration))

    return () => clearInterval(interval)
  }, [sessionStartTime, isPaused, pausedTime])

  const formatDuration = (minutes: number) => {
    const hours = Math.floor(minutes / 60)
    const mins = minutes % 60

    if (hours > 0) {
      return `${hours}h ${mins}m`
    }
    return `${mins}m`
  }

  const getSessionStatus = () => {
    if (sessionDuration >= 180) return { status: 'Long session', color: 'text-destructive' }
    if (sessionDuration >= 120) return { status: 'Extended play', color: 'text-chart-4' }
    if (sessionDuration >= 60) return { status: 'Good session', color: 'text-chart-2' }
    return { status: 'Getting started', color: 'text-primary' }
  }

  const handlePauseToggle = () => {
    if (isPaused) {
      // Resuming - don't add to paused time yet
      setIsPaused(false)
    } else {
      // Pausing - start tracking pause time
      setIsPaused(true)
      // In a real implementation, we'd track the pause start time
    }
  }

  const suggestBreak = sessionDuration > 0 && sessionDuration % 90 === 0 && !isPaused

  const sessionInfo = getSessionStatus()

  return (
    <div className={`flex items-center gap-3 ${className}`}>
      {/* Session Duration */}
      <div className="flex items-center gap-2">
        <Clock size={16} className="text-muted-foreground" />
        <span className="font-mono text-sm">
          {formatDuration(sessionDuration)}
        </span>
        <Badge
          variant="secondary"
          className={`text-xs ${sessionInfo.color}`}
        >
          {sessionInfo.status}
        </Badge>
      </div>

      {/* Session Controls */}
      <div className="flex items-center gap-1">
        <Button
          variant="ghost"
          size="sm"
          onClick={handlePauseToggle}
          className="gap-1"
        >
          {isPaused ? (
            <Play size={14} />
          ) : (
            <Pause size={14} />
          )}
          {isPaused ? 'Resume' : 'Pause'}
        </Button>

        <Button
          variant="outline"
          size="sm"
          onClick={onEndSession}
          className="gap-1 text-destructive hover:text-destructive"
        >
          <Square size={14} />
          End Session
        </Button>
      </div>

      {/* Break Suggestion */}
      {suggestBreak && (
        <motion.div
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          className="flex items-center gap-1 text-xs text-chart-4"
        >
          <Coffee size={12} />
          <span>Consider a break</span>
        </motion.div>
      )}
    </div>
  )
}

export default SessionFlowControls

/**
 * SmartContextPanel - AI Game Assistant
 *
 * Provides contextual suggestions, situation awareness, and smart
 * recommendations based on current game state and recent actions.
 */

import React, { useState, useEffect, useMemo } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import {
  Brain,
  Lightbulb,
  AlertTriangle,
  Info,
  TrendingUp,
  Clock,
  Target,
  BookOpen,
  Zap,
  Shield,
  Heart,
  Star,
  ArrowRight,
  Eye,
  Users
} from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle, Button, Badge } from '../../ui'
import type { Character } from '../../../models/Character'
import type { GameMode, PlayTabTheme } from '../PlayTab'

interface SmartContextPanelProps {
  character: Character
  gameMode: GameMode
  theme: PlayTabTheme
  chronicleEnabled: boolean
  className?: string
}

interface Suggestion {
  id: string
  type: 'tip' | 'warning' | 'opportunity' | 'chronicle'
  title: string
  description: string
  icon: React.ComponentType<{ size?: number; className?: string }>
  priority: 'high' | 'medium' | 'low'
  action?: {
    label: string
    onClick: () => void
  }
}

interface SiturationAlert {
  id: string
  type: 'danger' | 'opportunity' | 'reminder'
  message: string
  icon: React.ComponentType<{ size?: number; className?: string }>
  timestamp: Date
}

const SuggestionCard: React.FC<{
  suggestion: Suggestion
  onDismiss: (id: string) => void
}> = ({ suggestion, onDismiss }) => {
  const Icon = suggestion.icon

  const priorityColor = {
    high: 'border-destructive/30 bg-destructive/12',
    medium: 'border-chart-4/30 bg-chart-4/12 bg-chart-4/20',
    low: 'border-primary/30 bg-primary/10'
  }

  const iconColor = {
    tip: 'text-primary',
    warning: 'text-destructive',
    opportunity: 'text-chart-2',
    chronicle: 'text-accent'
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -10 }}
      className={`p-3 rounded-lg border ${priorityColor[suggestion.priority]} relative`}
    >
      <button
        onClick={() => onDismiss(suggestion.id)}
        className="absolute top-2 right-2 w-4 h-4 text-muted-foreground hover:text-muted-foreground text-xs"
      >
        ×
      </button>

      <div className="flex items-start gap-3 pr-6">
        <Icon size={16} className={iconColor[suggestion.type]} />
        <div className="flex-1 min-w-0">
          <h4 className="text-sm font-medium mb-1">{suggestion.title}</h4>
          <p className="text-xs text-muted-foreground  mb-2">
            {suggestion.description}
          </p>
          {suggestion.action && (
            <Button
              size="sm"
              variant="ghost"
              onClick={suggestion.action.onClick}
              className="text-xs px-2 py-1 h-auto"
            >
              {suggestion.action.label}
              <ArrowRight size={10} className="ml-1" />
            </Button>
          )}
        </div>
      </div>
    </motion.div>
  )
}

const SituationBar: React.FC<{
  situation: string
  confidence: number
  gameMode: GameMode
}> = ({ situation, confidence, gameMode }) => {
  const modeColor = {
    combat: 'bg-destructive/120',
    exploration: 'bg-chart-2',
    social: 'bg-primary/100',
    rest: 'bg-accent'
  }

  return (
    <div className="space-y-2">
      <div className="flex items-center justify-between text-sm">
        <span className="font-medium">Current Situation</span>
        <Badge variant="secondary" className="text-xs">
          {confidence}% confident
        </Badge>
      </div>
      <div className={`p-3 rounded-lg ${modeColor[gameMode]} text-white`}>
        <p className="text-sm">{situation}</p>
      </div>
    </div>
  )
}

const QuickStats: React.FC<{ character: Character }> = ({ character }) => {
  const hp = character.hitPoints?.current || 0
  const maxHP = character.hitPoints?.max || 1
  const armor = character.armor || 0
  const load = character.load?.current || 0
  const maxLoad = character.load?.max || 10

  const hpPercentage = (hp / maxHP) * 100
  const loadPercentage = (load / maxLoad) * 100

  return (
    <div className="space-y-3">
      <div className="text-sm font-medium">Quick Status</div>

      {/* HP Status */}
      <div className="flex items-center justify-between text-xs">
        <div className="flex items-center gap-1">
          <Heart size={12} className={
            hpPercentage <= 25 ? 'text-destructive' :
            hpPercentage <= 50 ? 'text-chart-4' :
            'text-chart-2'
          } />
          <span>Health</span>
        </div>
        <span className="font-mono">{hp}/{maxHP}</span>
      </div>

      {/* Armor */}
      <div className="flex items-center justify-between text-xs">
        <div className="flex items-center gap-1">
          <Shield size={12} className="text-primary" />
          <span>Armor</span>
        </div>
        <span className="font-mono">{armor}</span>
      </div>

      {/* Load Warning */}
      {loadPercentage >= 80 && (
        <div className="flex items-center gap-2 text-xs text-chart-4">
          <AlertTriangle size={12} />
          <span>Heavy load ({load}/{maxLoad})</span>
        </div>
      )}
    </div>
  )
}

export const SmartContextPanel: React.FC<SmartContextPanelProps> = ({
  character,
  gameMode,
  theme,
  chronicleEnabled,
  className = ''
}) => {
  const [suggestions, setSuggestions] = useState<Suggestion[]>([])
  const [currentSituation, setCurrentSituation] = useState('')
  const [confidence, setConfidence] = useState(75)

  // Generate contextual suggestions based on game state
  const generateSuggestions = useMemo(() => {
    const newSuggestions: Suggestion[] = []

    // Health-based suggestions
    const hpPercentage = ((character.hitPoints?.current || 0) / (character.hitPoints?.max || 1)) * 100
    if (hpPercentage <= 25) {
      newSuggestions.push({
        id: 'low-hp-warning',
        type: 'warning',
        title: 'Low Health!',
        description: 'Consider healing or defensive actions',
        icon: Heart,
        priority: 'high',
        action: {
          label: 'Find Healing',
          onClick: () => console.log('Look for healing options')
        }
      })
    }

    // Load-based suggestions
    const loadPercentage = ((character.load?.current || 0) / (character.load?.max || 10)) * 100
    if (loadPercentage >= 80) {
      newSuggestions.push({
        id: 'heavy-load-tip',
        type: 'tip',
        title: 'Heavy Load',
        description: 'You may want to drop some items or find storage',
        icon: AlertTriangle,
        priority: 'medium'
      })
    }

    // Game mode specific suggestions
    switch (gameMode) {
      case 'combat':
        newSuggestions.push({
          id: 'combat-tip',
          type: 'tip',
          title: 'In Combat',
          description: 'Consider your positioning and action economy',
          icon: Target,
          priority: 'medium'
        })
        break

      case 'exploration':
        newSuggestions.push({
          id: 'exploration-opportunity',
          type: 'opportunity',
          title: 'Explore Wisely',
          description: 'Look for secrets and gather information',
          icon: Eye,
          priority: 'low'
        })
        break

      case 'social':
        newSuggestions.push({
          id: 'social-tip',
          type: 'opportunity',
          title: 'Social Interaction',
          description: 'This could be a chance to build bonds or gather intel',
          icon: Users,
          priority: 'medium'
        })
        break
    }

    // Chronicle suggestions
    if (chronicleEnabled) {
      newSuggestions.push({
        id: 'chronicle-reminder',
        type: 'chronicle',
        title: 'Chronicle Opportunity',
        description: 'Recent actions deserve a story entry',
        icon: BookOpen,
        priority: 'low',
        action: {
          label: 'Add to Chronicle',
          onClick: () => console.log('Open Chronicle')
        }
      })
    }

    return newSuggestions
  }, [character, gameMode, chronicleEnabled])

  // Update suggestions when game state changes
  useEffect(() => {
    setSuggestions(generateSuggestions)
  }, [generateSuggestions])

  // Update situation analysis
  useEffect(() => {
    const situations = {
      combat: 'Engaged in dangerous combat',
      exploration: 'Exploring unknown territory',
      social: 'In conversation with NPCs',
      rest: 'Taking time to rest and recover'
    }

    setCurrentSituation(situations[gameMode])

    // Mock confidence calculation based on character state
    const hpPercentage = ((character.hitPoints?.current || 0) / (character.hitPoints?.max || 1)) * 100
    const baseConfidence = hpPercentage > 50 ? 80 : 60
    setConfidence(baseConfidence + Math.floor(Math.random() * 20))
  }, [gameMode, character])

  const dismissSuggestion = (id: string) => {
    setSuggestions(prev => prev.filter(s => s.id !== id))
  }

  const cardVariant =
    theme === 'combat' ? 'elevated' :
    theme === 'dungeon' ? 'parchment' :
    theme === 'tavern' ? 'magical' :
    'glass'

  return (
    <Card
      variant={cardVariant}
      className={`h-full overflow-y-auto ${className}`}
    >
      <CardHeader className="pb-3">
        <CardTitle className="flex items-center gap-2 text-sm">
          <Brain size={16} className="text-primary" />
          Smart Assistant
        </CardTitle>
      </CardHeader>

      <CardContent className="space-y-4">
        {/* Situation Analysis */}
        <SituationBar
          situation={currentSituation}
          confidence={confidence}
          gameMode={gameMode}
        />

        {/* Quick Character Stats */}
        <QuickStats character={character} />

        {/* Contextual Suggestions */}
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <span className="text-sm font-medium">Suggestions</span>
            <Badge variant="secondary" className="text-xs">
              {suggestions.length}
            </Badge>
          </div>

          <div className="space-y-2 max-h-64 overflow-y-auto">
            <AnimatePresence>
              {suggestions.length === 0 ? (
                <motion.div
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  className="text-center text-xs text-muted-foreground py-4"
                >
                  <Lightbulb size={16} className="mx-auto mb-2 opacity-50" />
                  <p>No suggestions at the moment</p>
                  <p>Keep playing to get smart tips!</p>
                </motion.div>
              ) : (
                suggestions.map(suggestion => (
                  <SuggestionCard
                    key={suggestion.id}
                    suggestion={suggestion}
                    onDismiss={dismissSuggestion}
                  />
                ))
              )}
            </AnimatePresence>
          </div>
        </div>

        {/* Chronicle Integration Status */}
        <div className="pt-3 border-t border-border">
          <div className="flex items-center justify-between text-xs">
            <span className="text-muted-foreground ">Chronicle</span>
            <div className="flex items-center gap-1">
              <div className={`w-2 h-2 rounded-full ${chronicleEnabled ? 'bg-chart-2' : 'bg-gray-400'}`} />
              <span className="text-muted-foreground">
                {chronicleEnabled ? 'Active' : 'Disabled'}
              </span>
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  )
}

export default SmartContextPanel

/**
 * Session Flow Manager for ZimboMate V2
 * Manages integrated play session workflow and automatic state tracking
 * Phase 4C: Desktop Power Features - Smart Integration System
 */

import React, { useState, useEffect, useCallback } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import {
  Play,
  Square,
  SkipForward,
  Sword,
  Shield,
  Clock,
  CheckCircle,
  TrendingUp,
  BookOpen,
  Settings,
  ChevronDown,
  ChevronUp
} from 'lucide-react'
import { Card, CardContent, Button, Badge, Progress } from '../ui'
import { useCharacterStore } from '../../stores/characterStore'
import { useSessionStore } from '../../stores/sessionStore'
import { useGameStateStore } from '../../stores/gameStateStore'
import { XPAwardModal } from './XPAwardModal'

// Session phases
export type SessionPhase = 
  | 'setup'      // Pre-session setup
  | 'opening'    // Opening scene
  | 'exploration' // General exploration/roleplay
  | 'encounter'  // Combat or major challenge
  | 'resolution' // Post-encounter resolution
  | 'transition' // Moving between scenes
  | 'closing'    // Session wrap-up
  | 'ended'      // Session ended

// Flow state for tracking session progress
interface SessionFlow {
  phase: SessionPhase
  sceneCount: number
  encounterCount: number
  turnCount: number
  lastAction: string
  suggestedNextActions: string[]
  milestones: Array<{
    id: string
    phase: SessionPhase
    timestamp: Date
    description: string
    xpAwarded?: number
  }>
}

// Auto-tracking events
interface SessionEvent {
  id: string
  type: 'roll' | 'move' | 'damage' | 'heal' | 'xp' | 'advancement' | 'scene_change'
  timestamp: Date
  characterId?: string
  description: string
  data?: any
}

interface SessionFlowManagerProps {
  compact?: boolean
  autoAdvance?: boolean
  showSuggestions?: boolean
}

export const SessionFlowManager: React.FC<SessionFlowManagerProps> = ({
  compact = false,
  autoAdvance = true,
  showSuggestions = true
}) => {
  const { characters } = useCharacterStore()
  const { isSessionActive, startSession, combat, rollHistory, startCombat, endCombat } = useSessionStore()
  const { advanceTime } = useGameStateStore()

  const [sessionFlow, setSessionFlow] = useState<SessionFlow>({
    phase: 'setup',
    sceneCount: 1,
    encounterCount: 0,
    turnCount: 0,
    lastAction: 'Session initialized',
    suggestedNextActions: ['Start session', 'Set opening scene'],
    milestones: []
  })

  const [sessionEvents, setSessionEvents] = useState<SessionEvent[]>([])
  const [isExpanded, setIsExpanded] = useState(!compact)
  const [autoTrackingEnabled, setAutoTrackingEnabled] = useState(true)
  const [showXPModal, setShowXPModal] = useState(false)

  // Handle XP award completion
  const handleXPAwarded = (totalXPAwarded: number, charactersAffected: number) => {
    // Add to session events for tracking
    const event: SessionEvent = {
      id: crypto.randomUUID(),
      type: 'xp-awarded',
      timestamp: new Date(),
      description: `Awarded ${totalXPAwarded} XP to ${charactersAffected} character${charactersAffected !== 1 ? 's' : ''}`,
      metadata: {
        totalXP: totalXPAwarded,
        charactersCount: charactersAffected
      }
    }
    setSessionEvents(prev => [...prev, event])

    // Update session flow
    setSessionFlow(prev => ({
      ...prev,
      suggestedNextActions: prev.suggestedNextActions.filter(action => action !== 'Award XP')
    }))
  }

  // Auto-track session events
  useEffect(() => {
    if (!isSessionActive || !autoTrackingEnabled) return

    // Track roll events
    if (rollHistory.length > 0) {
      const latestRoll = rollHistory[0]
      const existingEvent = sessionEvents.find(e => 
        e.type === 'roll' && 
        e.timestamp.getTime() === latestRoll.timestamp.getTime()
      )

      if (!existingEvent) {
        const rollEvent: SessionEvent = {
          id: `roll-${Date.now()}`,
          type: 'roll',
          timestamp: latestRoll.timestamp,
          characterId: latestRoll.characterId,
          description: `${latestRoll.moveName || 'Dice roll'}: ${latestRoll.total} (${latestRoll.result})`,
          data: latestRoll
        }

        setSessionEvents(prev => [rollEvent, ...prev.slice(0, 49)]) // Keep last 50 events

        // Auto-advance session flow based on rolls
        if (autoAdvance) {
          handleAutoAdvance('roll')
        }
      }
    }
  }, [rollHistory, isSessionActive, autoTrackingEnabled, autoAdvance, sessionEvents])

  // Auto-advance session flow
  const handleAutoAdvance = useCallback((eventType: string) => {
    setSessionFlow(prev => {
      const newFlow = { ...prev }
      
      switch (eventType) {
        case 'roll':
          // If we're in setup and someone rolls, move to opening
          if (prev.phase === 'setup') {
            newFlow.phase = 'opening'
            newFlow.lastAction = 'Session started with first roll'
            newFlow.suggestedNextActions = ['Continue opening scene', 'Introduce characters']
            newFlow.milestones.push({
              id: `milestone-${Date.now()}`,
              phase: 'opening',
              timestamp: new Date(),
              description: 'Session began with first dice roll'
            })
          }
          
          // Track turn progression
          newFlow.turnCount += 1
          
          // If multiple combat rolls, suggest encounter phase
          if (prev.phase === 'exploration') {
            const recentCombatRolls = rollHistory.slice(0, 3).filter(roll => 
              roll.moveName?.includes('Hack and Slash') || 
              roll.moveName?.includes('Volley') ||
              roll.moveName?.includes('Defend')
            ).length
            
            if (recentCombatRolls >= 2) {
              newFlow.phase = 'encounter'
              newFlow.encounterCount += 1
              newFlow.lastAction = 'Combat encounter detected'
              newFlow.suggestedNextActions = ['Start combat tracker', 'Roll initiative', 'Track HP']
            }
          }
          break

        case 'combat_start':
          newFlow.phase = 'encounter'
          newFlow.encounterCount += 1
          newFlow.lastAction = 'Combat encounter started'
          newFlow.suggestedNextActions = ['Roll initiative', 'Track turn order', 'Monitor HP']
          break

        case 'combat_end':
          newFlow.phase = 'resolution'
          newFlow.lastAction = 'Combat encounter resolved'
          newFlow.suggestedNextActions = ['Award XP', 'Heal characters', 'Loot and rewards']
          break

        case 'scene_change':
          newFlow.phase = 'transition'
          newFlow.sceneCount += 1
          newFlow.lastAction = 'Scene transition'
          newFlow.suggestedNextActions = ['Set new scene', 'Update environment', 'Continue exploration']
          break
      }

      return newFlow
    })
  }, [rollHistory])

  // Manual phase advancement
  const advancePhase = (newPhase: SessionPhase) => {
    setSessionFlow(prev => ({
      ...prev,
      phase: newPhase,
      lastAction: `Manually advanced to ${newPhase}`,
      suggestedNextActions: getPhaseActions(newPhase),
      milestones: [
        ...prev.milestones,
        {
          id: `milestone-${Date.now()}`,
          phase: newPhase,
          timestamp: new Date(),
          description: `Advanced to ${newPhase} phase`
        }
      ]
    }))

    // Trigger appropriate store actions
    switch (newPhase) {
      case 'encounter':
        if (!combat.isActive) {
          const characterIds = characters.map(c => c.id)
          startCombat(characterIds)
        }
        break
      case 'resolution':
        if (combat.isActive) {
          endCombat()
        }
        break
      case 'transition':
        advanceTime('scene')
        break
    }
  }

  // Get suggested actions for each phase
  const getPhaseActions = (phase: SessionPhase): string[] => {
    switch (phase) {
      case 'setup':
        return ['Start session', 'Set opening scene', 'Review character sheets']
      case 'opening':
        return ['Introduce scene', 'Set the mood', 'Ask opening questions']
      case 'exploration':
        return ['Describe environment', 'Encourage roleplay', 'Present opportunities']
      case 'encounter':
        return ['Start combat tracker', 'Roll initiative', 'Track HP and conditions']
      case 'resolution':
        return ['Award XP', 'Heal characters', 'Distribute rewards', 'Wrap up encounter']
      case 'transition':
        return ['Change scene', 'Update environment', 'Advance time', 'Set new stakes']
      case 'closing':
        return ['Wrap up storylines', 'Award end-of-session XP', 'Plan next session']
      case 'ended':
        return ['Review session', 'Save progress', 'Schedule next session']
      default:
        return []
    }
  }

  // Get phase color
  const getPhaseColor = (phase: SessionPhase) => {
    switch (phase) {
      case 'setup': return 'var(--muted-foreground)'
      case 'opening': return 'var(--primary)'
      case 'exploration': return 'var(--chart-2)'
      case 'encounter': return 'var(--destructive)'
      case 'resolution': return 'var(--accent)'
      case 'transition': return 'var(--chart-4)'
      case 'closing': return 'var(--chart-3)'
      case 'ended': return 'var(--muted)'
      default: return 'var(--primary)'
    }
  }

  // Get phase icon
  const getPhaseIcon = (phase: SessionPhase) => {
    switch (phase) {
      case 'setup': return Settings
      case 'opening': return Play
      case 'exploration': return BookOpen
      case 'encounter': return Sword
      case 'resolution': return CheckCircle
      case 'transition': return SkipForward
      case 'closing': return Square
      case 'ended': return Square
      default: return Play
    }
  }

  // Calculate session progress
  const getSessionProgress = () => {
    const phaseOrder: SessionPhase[] = ['setup', 'opening', 'exploration', 'encounter', 'resolution', 'transition', 'closing', 'ended']
    const currentIndex = phaseOrder.indexOf(sessionFlow.phase)
    return (currentIndex / (phaseOrder.length - 1)) * 100
  }

  // Quick actions
  const quickActions = [
    {
      label: 'Start Combat',
      icon: Sword,
      onClick: () => {
        const characterIds = characters.map(c => c.id)
        startCombat(characterIds)
        advancePhase('encounter')
      },
      disabled: combat.isActive
    },
    {
      label: 'End Combat',
      icon: Shield,
      onClick: () => {
        endCombat()
        advancePhase('resolution')
      },
      disabled: !combat.isActive
    },
    {
      label: 'Next Scene',
      icon: SkipForward,
      onClick: () => {
        advanceTime('scene')
        advancePhase('transition')
      },
      disabled: false
    },
    {
      label: 'Award XP',
      icon: TrendingUp,
      onClick: () => {
        setShowXPModal(true)
      },
      disabled: false
    }
  ]

  if (!isSessionActive) {
    return (
      <Card variant="outline">
        <CardContent>
          <div className="text-center space-y-4">
            <div 
              className="w-12 h-12 mx-auto rounded-full flex items-center justify-center bg-primary/20">
              <Play className="text-primary" size={24} />
            </div>
            <div>
              <h3 className="font-display text-lg mb-2">No Active Session</h3>
              <p className="text-muted-foreground">
                Start a session to enable flow management and auto-tracking.
              </p>
            </div>
            <Button
              variant="primary"
              onClick={() => {
                const characterIds = characters.map(c => c.id)
                startSession('New Session', characterIds)
                setSessionFlow(prev => ({ ...prev, phase: 'opening' }))
              }}
            >
              Start Session
            </Button>
          </div>
        </CardContent>
      </Card>
    )
  }

  const PhaseIcon = getPhaseIcon(sessionFlow.phase)

  return (
    <>
      <Card variant="magical">
      <CardContent>
        <div className="space-y-4">
          {/* Header */}
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div 
                className="w-10 h-10 rounded-full flex items-center justify-center"
                style={{ 
                  backgroundColor: getPhaseColor(sessionFlow.phase),
                  opacity: 0.2 
                }}
              >
                <PhaseIcon 
                  size={20} 
                  style={{ color: getPhaseColor(sessionFlow.phase) }}
                />
              </div>
              <div>
                <h3 className="font-display text-lg">Session Flow</h3>
                <p 
                  className="text-sm text-muted-foreground">
                  {sessionFlow.phase.charAt(0).toUpperCase() + sessionFlow.phase.slice(1)} Phase
                </p>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <Badge variant="secondary">
                Scene {sessionFlow.sceneCount}
              </Badge>
              {combat.isActive && (
                <Badge variant="destructive">
                  Combat Round {combat.round}
                </Badge>
              )}
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setIsExpanded(!isExpanded)}
              >
                {isExpanded ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
              </Button>
            </div>
          </div>

          {/* Progress Bar */}
          <div className="space-y-2">
            <div className="flex justify-between text-sm">
              <span className="text-muted-foreground">
                Session Progress
              </span>
              <span className="text-muted-foreground">
                {Math.round(getSessionProgress())}%
              </span>
            </div>
            <Progress 
              value={getSessionProgress()} 
              className="h-2"
            />
          </div>

          <AnimatePresence>
            {isExpanded && (
              <motion.div
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: 'auto' }}
                exit={{ opacity: 0, height: 0 }}
                transition={{ duration: 0.3 }}
                className="space-y-4"
              >
                {/* Current Status */}
                <div 
                  className="p-3 rounded-lg bg-card">
                  <div className="flex items-center gap-2 mb-2">
                    <Clock className="text-muted-foreground" size={16} />
                    <span className="text-sm font-medium">Last Action</span>
                  </div>
                  <p 
                    className="text-sm text-muted-foreground">
                    {sessionFlow.lastAction}
                  </p>
                </div>

                {/* Suggested Actions */}
                {showSuggestions && sessionFlow.suggestedNextActions.length > 0 && (
                  <div>
                    <h4 className="text-sm font-medium mb-2">Suggested Next Actions</h4>
                    <div className="space-y-1">
                      {sessionFlow.suggestedNextActions.map((action, index) => (
                        <div 
                          key={index}
                          className="flex items-center gap-2 text-sm p-2 rounded bg-card">
                          <CheckCircle className="text-chart-2" 
                            size={14} />
                          {action}
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Quick Actions */}
                <div>
                  <h4 className="text-sm font-medium mb-2">Quick Actions</h4>
                  <div className="grid grid-cols-2 gap-2">
                    {quickActions.map((action, index) => {
                      const ActionIcon = action.icon
                      return (
                        <Button
                          key={index}
                          variant="outline"
                          size="sm"
                          onClick={action.onClick}
                          disabled={action.disabled}
                          className="justify-start gap-2"
                        >
                          <ActionIcon size={14} />
                          {action.label}
                        </Button>
                      )
                    })}
                  </div>
                </div>

                {/* Phase Navigation */}
                <div>
                  <h4 className="text-sm font-medium mb-2">Phase Control</h4>
                  <div className="flex flex-wrap gap-1">
                    {(['setup', 'opening', 'exploration', 'encounter', 'resolution', 'transition', 'closing'] as SessionPhase[]).map((phase) => (
                      <Button
                        key={phase}
                        variant={sessionFlow.phase === phase ? 'primary' : 'ghost'}
                        size="xs"
                        onClick={() => advancePhase(phase)}
                      >
                        {phase.charAt(0).toUpperCase() + phase.slice(1)}
                      </Button>
                    ))}
                  </div>
                </div>

                {/* Session Stats */}
                <div className="grid grid-cols-3 gap-4 text-center">
                  <div>
                    <div className="text-lg font-bold">{sessionFlow.sceneCount}</div>
                    <div 
                      className="text-xs text-muted-foreground">
                      Scenes
                    </div>
                  </div>
                  <div>
                    <div className="text-lg font-bold">{sessionFlow.encounterCount}</div>
                    <div 
                      className="text-xs text-muted-foreground">
                      Encounters
                    </div>
                  </div>
                  <div>
                    <div className="text-lg font-bold">{rollHistory.length}</div>
                    <div 
                      className="text-xs text-muted-foreground">
                      Rolls
                    </div>
                  </div>
                </div>

                {/* Auto-tracking Toggle */}
                <div className="flex items-center justify-between p-2 rounded bg-card">
                  <span className="text-sm">Auto-tracking</span>
                  <Button
                    variant={autoTrackingEnabled ? 'primary' : 'outline'}
                    size="xs"
                    onClick={() => setAutoTrackingEnabled(!autoTrackingEnabled)}
                  >
                    {autoTrackingEnabled ? 'On' : 'Off'}
                  </Button>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </CardContent>
      </Card>

      {/* XP Award Modal */}
      <XPAwardModal
        isOpen={showXPModal}
        onClose={() => setShowXPModal(false)}
        onAwarded={handleXPAwarded}
      />
    </>
  )
}

