/**
 * SessionManager - Create/join session interface for multiplayer functionality
 * Provides UI for managing multiplayer game sessions
 */

import React, { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { Card, CardHeader, CardTitle, CardContent, Button, Input, Badge } from '../ui'
import { multiplayerService, GameSession, SessionSettings } from '../../services/MultiplayerService'
import { 
  Users, 
  Plus, 
  LogIn, 
  Settings, 
  Crown, 
  Wifi, 
  WifiOff,
  Copy,
  Check,
  X
} from 'lucide-react'

interface SessionManagerProps {
  onSessionJoined: (session: GameSession) => void
  onClose: () => void
  isVisible: boolean
}

interface CreateSessionForm {
  name: string
  playerName: string
  maxPlayers: number
  allowSpectators: boolean
  shareRolls: boolean
  requireApproval: boolean
}

interface JoinSessionForm {
  sessionId: string
  playerName: string
}

export const SessionManager: React.FC<SessionManagerProps> = ({
  onSessionJoined,
  onClose,
  isVisible
}) => {
  const [mode, setMode] = useState<'menu' | 'create' | 'join'>('menu')
  const [isConnected, setIsConnected] = useState(false)
  const [isConnecting, setIsConnecting] = useState(false)
  const [connectionError, setConnectionError] = useState<string | null>(null)
  const [copiedSessionId, setCopiedSessionId] = useState(false)

  const [createForm, setCreateForm] = useState<CreateSessionForm>({
    name: '',
    playerName: '',
    maxPlayers: 6,
    allowSpectators: true,
    shareRolls: true,
    requireApproval: false
  })

  const [joinForm, setJoinForm] = useState<JoinSessionForm>({
    sessionId: '',
    playerName: ''
  })

  const [availableSessions, setAvailableSessions] = useState<GameSession[]>([])

  useEffect(() => {
    if (isVisible) {
      checkConnection()
    }

    // Set up event listeners
    const handleConnected = () => {
      setIsConnected(true)
      setIsConnecting(false)
      setConnectionError(null)
    }

    const handleDisconnected = () => {
      setIsConnected(false)
      setIsConnecting(false)
    }

    const handleError = (event: CustomEvent) => {
      const error = event.detail
      setConnectionError(error?.message || 'Connection failed')
      setIsConnecting(false)
    }

    const handleSessionCreated = (event: CustomEvent) => {
      const session = event.detail
      onSessionJoined(session)
    }

    const handleSessionJoined = (event: CustomEvent) => {
      const session = event.detail
      onSessionJoined(session)
    }

    multiplayerService.on('connected', handleConnected)
    multiplayerService.on('disconnected', handleDisconnected)
    multiplayerService.on('error', handleError)
    multiplayerService.on('session_created', handleSessionCreated)
    multiplayerService.on('session_joined', handleSessionJoined)

    return () => {
      multiplayerService.off('connected', handleConnected)
      multiplayerService.off('disconnected', handleDisconnected)
      multiplayerService.off('error', handleError)
      multiplayerService.off('session_created', handleSessionCreated)
      multiplayerService.off('session_joined', handleSessionJoined)
    }
  }, [isVisible, onSessionJoined])

  const checkConnection = async () => {
    if (multiplayerService.isConnected) {
      setIsConnected(true)
      return
    }

    setIsConnecting(true)
    setConnectionError(null)

    try {
      await multiplayerService.connect()
    } catch (error: any) {
      setConnectionError(error.message || 'Failed to connect to server')
    }
  }

  const handleCreateSession = async () => {
    if (!createForm.name.trim() || !createForm.playerName.trim()) {
      return
    }

    try {
      const settings: Partial<SessionSettings> = {
        maxPlayers: createForm.maxPlayers,
        allowSpectators: createForm.allowSpectators,
        shareRolls: createForm.shareRolls,
        requireApproval: createForm.requireApproval
      }

      await multiplayerService.createSession(
        createForm.name.trim(),
        createForm.playerName.trim(),
        settings
      )
    } catch (error: any) {
      setConnectionError(error.message || 'Failed to create session')
    }
  }

  const handleJoinSession = async (sessionId?: string) => {
    const id = sessionId || joinForm.sessionId.trim()
    const playerName = joinForm.playerName.trim()

    if (!id || !playerName) {
      return
    }

    try {
      await multiplayerService.joinSession(id, playerName)
    } catch (error: any) {
      setConnectionError(error.message || 'Failed to join session')
    }
  }

  const copySessionId = (sessionId: string) => {
    navigator.clipboard.writeText(sessionId)
    setCopiedSessionId(true)
    setTimeout(() => setCopiedSessionId(false), 2000)
  }

  const ConnectionStatus = () => (
    <div className="flex items-center gap-2 mb-4">
      {isConnected ? (
        <>
          <Wifi size={16} className="text-chart-2" />
          <span className="text-sm text-chart-2">Connected to server</span>
        </>
      ) : isConnecting ? (
        <>
          <div className="animate-spin w-4 h-4 border-2 border-primary border-t-transparent rounded-full" />
          <span className="text-sm text-muted-foreground">Connecting...</span>
        </>
      ) : (
        <>
          <WifiOff size={16} className="text-destructive" />
          <span className="text-sm text-destructive">Disconnected</span>
        </>
      )}
    </div>
  )

  const MenuView = () => (
    <motion.div
      className="space-y-4"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -20 }}
    >
      <ConnectionStatus />

      {connectionError && (
        <div className="p-3 bg-destructive/15 border border-destructive/30 rounded-lg text-destructive text-sm">
          {connectionError}
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <Button
          variant="primary"
          size="lg"
          onClick={() => setMode('create')}
          disabled={!isConnected}
          className="gap-2 h-20 flex-col"
        >
          <Plus size={24} />
          <span>Create Session</span>
        </Button>

        <Button
          variant="outline"
          size="lg"
          onClick={() => setMode('join')}
          disabled={!isConnected}
          className="gap-2 h-20 flex-col"
        >
          <LogIn size={24} />
          <span>Join Session</span>
        </Button>
      </div>

      {!isConnected && (
        <Button
          variant="outline"
          onClick={checkConnection}
          disabled={isConnecting}
          className="w-full gap-2"
        >
          <Wifi size={16} />
          {isConnecting ? 'Connecting...' : 'Connect to Server'}
        </Button>
      )}
    </motion.div>
  )

  const CreateSessionView = () => (
    <motion.div
      className="space-y-4"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -20 }}
    >
      <div className="flex items-center gap-2 mb-4">
        <Plus size={20} className="text-primary" />
        <h3 className="text-lg font-display">Create New Session</h3>
      </div>

      <div className="space-y-4">
        <div>
          <label className="block text-sm font-medium mb-2">Session Name</label>
          <Input
            value={createForm.name}
            onChange={(e) => setCreateForm(prev => ({ ...prev, name: e.target.value }))}
            placeholder="Epic Adventure Session"
            className="w-full"
          />
        </div>

        <div>
          <label className="block text-sm font-medium mb-2">Your Name</label>
          <Input
            value={createForm.playerName}
            onChange={(e) => setCreateForm(prev => ({ ...prev, playerName: e.target.value }))}
            placeholder="Game Master"
            className="w-full"
          />
        </div>

        <div>
          <label className="block text-sm font-medium mb-2">Max Players</label>
          <Input
            type="number"
            min="2"
            max="12"
            value={createForm.maxPlayers}
            onChange={(e) => setCreateForm(prev => ({ ...prev, maxPlayers: parseInt(e.target.value) || 6 }))}
            className="w-full"
          />
        </div>

        <div className="space-y-3">
          <label className="flex items-center gap-2">
            <input
              type="checkbox"
              checked={createForm.allowSpectators}
              onChange={(e) => setCreateForm(prev => ({ ...prev, allowSpectators: e.target.checked }))}
              className="rounded"
            />
            <span className="text-sm">Allow spectators</span>
          </label>

          <label className="flex items-center gap-2">
            <input
              type="checkbox"
              checked={createForm.shareRolls}
              onChange={(e) => setCreateForm(prev => ({ ...prev, shareRolls: e.target.checked }))}
              className="rounded"
            />
            <span className="text-sm">Share dice rolls</span>
          </label>

          <label className="flex items-center gap-2">
            <input
              type="checkbox"
              checked={createForm.requireApproval}
              onChange={(e) => setCreateForm(prev => ({ ...prev, requireApproval: e.target.checked }))}
              className="rounded"
            />
            <span className="text-sm">Require approval to join</span>
          </label>
        </div>
      </div>

      <div className="flex gap-3 pt-4">
        <Button
          variant="primary"
          onClick={handleCreateSession}
          disabled={!createForm.name.trim() || !createForm.playerName.trim()}
          className="flex-1"
        >
          Create Session
        </Button>
        <Button
          variant="outline"
          onClick={() => setMode('menu')}
        >
          Back
        </Button>
      </div>
    </motion.div>
  )

  const JoinSessionView = () => (
    <motion.div
      className="space-y-4"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -20 }}
    >
      <div className="flex items-center gap-2 mb-4">
        <LogIn size={20} className="text-primary" />
        <h3 className="text-lg font-display">Join Session</h3>
      </div>

      <div className="space-y-4">
        <div>
          <label className="block text-sm font-medium mb-2">Session ID</label>
          <Input
            value={joinForm.sessionId}
            onChange={(e) => setJoinForm(prev => ({ ...prev, sessionId: e.target.value }))}
            placeholder="Enter session ID"
            className="w-full"
          />
        </div>

        <div>
          <label className="block text-sm font-medium mb-2">Your Name</label>
          <Input
            value={joinForm.playerName}
            onChange={(e) => setJoinForm(prev => ({ ...prev, playerName: e.target.value }))}
            placeholder="Player Name"
            className="w-full"
          />
        </div>
      </div>

      {availableSessions.length > 0 && (
        <div>
          <h4 className="text-sm font-medium mb-2">Available Sessions</h4>
          <div className="space-y-2">
            {availableSessions.map(session => (
              <Card
                key={session.id}
                variant="outline"
                className="cursor-pointer hover:shadow-md transition-shadow"
                onClick={() => handleJoinSession(session.id)}
              >
                <CardContent>
                  <div className="flex items-center justify-between">
                    <div>
                      <h5 className="font-medium">{session.name}</h5>
                      <div className="flex items-center gap-2 mt-1">
                        <Badge variant="secondary" className="text-xs">
                          <Users size={10} className="mr-1" />
                          {session.players.length}/{session.settings.maxPlayers}
                        </Badge>
                        {session.players.some(p => p.isHost) && (
                          <Crown size={12} className="text-chart-4" />
                        )}
                      </div>
                    </div>
                    <Button variant="ghost" size="sm">
                      Join
                    </Button>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        </div>
      )}

      <div className="flex gap-3 pt-4">
        <Button
          variant="primary"
          onClick={() => handleJoinSession()}
          disabled={!joinForm.sessionId.trim() || !joinForm.playerName.trim()}
          className="flex-1"
        >
          Join Session
        </Button>
        <Button
          variant="outline"
          onClick={() => setMode('menu')}
        >
          Back
        </Button>
      </div>
    </motion.div>
  )

  return (
    <AnimatePresence>
      {isVisible && (
        <motion.div
          className="fixed inset-0 bg-black/50 flex items-center justify-center z-50"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          onClick={onClose}
        >
          <motion.div
            className="w-full max-w-md mx-4"
            initial={{ scale: 0.9, opacity: 0, y: 20 }}
            animate={{ scale: 1, opacity: 1, y: 0 }}
            exit={{ scale: 0.9, opacity: 0, y: 20 }}
            onClick={e => e.stopPropagation()}
          >
            <Card variant="magical">
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Users size={24} className="text-primary" />
                  Multiplayer Sessions
                </CardTitle>
              </CardHeader>

              <CardContent>
                <AnimatePresence mode="wait">
                  {mode === 'menu' && <MenuView key="menu" />}
                  {mode === 'create' && <CreateSessionView key="create" />}
                  {mode === 'join' && <JoinSessionView key="join" />}
                </AnimatePresence>
              </CardContent>
            </Card>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  )
}

/**
 * Notes Widget - Persistent note-taking with search and organization
 * Phase 4A: Essential for actual Dungeon World gameplay sessions
 */

import React, { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { 
  NotebookPen, 
  Plus, 
  Edit3, 
  Trash2, 
  Tag,
  Star,
  Clock,
  Search,
  Filter
} from 'lucide-react'
import { Card, CardContent, Button, Badge } from '../../ui'
import { useSessionStore } from '../../../stores'

export interface Note {
  id: string
  content: string
  timestamp: Date
  tags: string[]
  importance: 'normal' | 'important' | 'critical'
  lastModified: Date
}

interface NotesWidgetProps {
  searchQuery?: string
  className?: string
}

export const NotesWidget: React.FC<NotesWidgetProps> = ({ 
  searchQuery = '',
  className = '' 
}) => {
  const { sessionNotes, addNote, updateNote, deleteNote } = useSessionStore()
  const [isCreating, setIsCreating] = useState(false)
  const [editingId, setEditingId] = useState<string | null>(null)
  const [newNote, setNewNote] = useState({
    content: '',
    tags: [] as string[],
    importance: 'normal' as const
  })
  const [tagInput, setTagInput] = useState('')
  const [filterImportance, setFilterImportance] = useState<string>('all')

  // Filter notes based on search query and importance
  const filteredNotes = sessionNotes.filter(note => {
    const matchesSearch = !searchQuery || 
      note.content.toLowerCase().includes(searchQuery.toLowerCase()) ||
      note.tags.some(tag => tag.toLowerCase().includes(searchQuery.toLowerCase()))
    
    const matchesImportance = filterImportance === 'all' || note.importance === filterImportance
    
    return matchesSearch && matchesImportance
  })

  // Sort notes by importance and timestamp
  const sortedNotes = [...filteredNotes].sort((a, b) => {
    const importanceOrder = { critical: 3, important: 2, normal: 1 }
    const importanceDiff = importanceOrder[b.importance] - importanceOrder[a.importance]
    if (importanceDiff !== 0) return importanceDiff
    return new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
  })

  const createNote = () => {
    if (!newNote.content.trim()) return

    const note: Note = {
      id: `note-${Date.now()}-${Math.random().toString(36).slice(2, 11)}`,
      content: newNote.content.trim(),
      timestamp: new Date(),
      tags: newNote.tags,
      importance: newNote.importance,
      lastModified: new Date()
    }

    addNote(note)
    setNewNote({ content: '', tags: [], importance: 'normal' })
    setTagInput('')
    setIsCreating(false)
  }

  const startEditing = (note: Note) => {
    setEditingId(note.id)
    setNewNote({
      content: note.content,
      tags: note.tags,
      importance: note.importance
    })
    setTagInput(note.tags.join(', '))
  }

  const saveEdit = () => {
    if (!editingId || !newNote.content.trim()) return

    updateNote(editingId, {
      content: newNote.content.trim(),
      tags: newNote.tags,
      importance: newNote.importance,
      lastModified: new Date()
    })

    setEditingId(null)
    setNewNote({ content: '', tags: [], importance: 'normal' })
    setTagInput('')
  }

  const cancelEdit = () => {
    setEditingId(null)
    setIsCreating(false)
    setNewNote({ content: '', tags: [], importance: 'normal' })
    setTagInput('')
  }

  const handleTagInput = (value: string) => {
    setTagInput(value)
    const tags = value.split(',').map(tag => tag.trim()).filter(tag => tag.length > 0)
    setNewNote(prev => ({ ...prev, tags }))
  }

  const getImportanceColor = (importance: Note['importance']) => {
    switch (importance) {
      case 'critical':
        return 'bg-destructive/15 text-destructive border-destructive/30'
      case 'important':
        return 'bg-chart-4/15 text-chart-4 border-chart-4/30'
      default:
        return 'bg-muted text-foreground border-border'
    }
  }

  const getImportanceIcon = (importance: Note['importance']) => {
    switch (importance) {
      case 'critical':
        return <Star size={12} className="text-destructive fill-current" />
      case 'important':
        return <Star size={12} className="text-chart-4 fill-current" />
      default:
        return <Star size={12} className="text-muted-foreground" />
    }
  }

  const formatTimestamp = (date: Date) => {
    const now = new Date()
    const diffMs = now.getTime() - date.getTime()
    const diffMins = Math.floor(diffMs / 60000)
    const diffHours = Math.floor(diffMs / 3600000)
    
    if (diffMins < 1) return 'Just now'
    if (diffMins < 60) return `${diffMins}m ago`
    if (diffHours < 24) return `${diffHours}h ago`
    return date.toLocaleDateString()
  }

  return (
    <div className={`space-y-4 ${className}`}>
      {/* Header with Stats */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <NotebookPen size={20} />
          <span className="font-medium">Session Notes</span>
          <Badge variant="secondary">{sessionNotes.length}</Badge>
        </div>
        
        {/* Importance Filter */}
        <div className="flex items-center gap-2">
          <Filter size={14} />
          <select
            value={filterImportance}
            onChange={(e) => setFilterImportance(e.target.value)}
            className="text-sm px-2 py-1 rounded border"
            style={{
              backgroundColor: 'var(--card)',
              borderColor: 'var(--border)',
              color: 'var(--foreground)'
            }}
          >
            <option value="all">All Notes</option>
            <option value="critical">Critical</option>
            <option value="important">Important</option>
            <option value="normal">Normal</option>
          </select>
        </div>
      </div>

      {/* Add Note Button */}
      <Button
        variant="primary"
        size="sm"
        onClick={() => setIsCreating(true)}
        className="w-full gap-2"
      >
        <Plus size={16} />
        Add Note
      </Button>

      {/* Create/Edit Note Form */}
      <AnimatePresence>
        {(isCreating || editingId) && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: 0.3 }}
          >
            <Card variant="magical">
              <CardContent className="p-6">
                <div className="space-y-4">
                  {/* Note Content */}
                  <div>
                    <label className="block text-sm font-medium mb-2">
                      Note Content
                    </label>
                    <textarea
                      value={newNote.content}
                      onChange={(e) => setNewNote(prev => ({ ...prev, content: e.target.value }))}
                      placeholder="What happened in the session? Important NPCs, discoveries, plot developments..."
                      rows={4}
                      className="w-full px-3 py-2 rounded-lg border transition-colors resize-none"
                      style={{
                        backgroundColor: 'var(--card)',
                        borderColor: 'var(--primary)',
                        borderOpacity: 0.2,
                        color: 'var(--foreground)'
                      }}
                      autoFocus
                    />
                  </div>

                  {/* Tags */}
                  <div>
                    <label className="block text-sm font-medium mb-2">
                      Tags (comma-separated)
                    </label>
                    <input
                      type="text"
                      value={tagInput}
                      onChange={(e) => handleTagInput(e.target.value)}
                      placeholder="combat, npc, location, plot, treasure"
                      className="w-full px-3 py-2 rounded-lg border transition-colors"
                      style={{
                        backgroundColor: 'var(--card)',
                        borderColor: 'var(--primary)',
                        borderOpacity: 0.2,
                        color: 'var(--foreground)'
                      }}
                    />
                    {newNote.tags.length > 0 && (
                      <div className="flex flex-wrap gap-1 mt-2">
                        {newNote.tags.map((tag, index) => (
                          <Badge key={index} variant="secondary" className="text-xs">
                            #{tag}
                          </Badge>
                        ))}
                      </div>
                    )}
                  </div>

                  {/* Importance */}
                  <div>
                    <label className="block text-sm font-medium mb-2">
                      Importance Level
                    </label>
                    <select
                      value={newNote.importance}
                      onChange={(e) => setNewNote(prev => ({ 
                        ...prev, 
                        importance: e.target.value as Note['importance'] 
                      }))}
                      className="w-full px-3 py-2 rounded-lg border transition-colors"
                      style={{
                        backgroundColor: 'var(--card)',
                        borderColor: 'var(--primary)',
                        borderOpacity: 0.2,
                        color: 'var(--foreground)'
                      }}
                    >
                      <option value="normal">Normal</option>
                      <option value="important">Important</option>
                      <option value="critical">Critical</option>
                    </select>
                  </div>

                  {/* Actions */}
                  <div className="flex gap-2">
                    <Button
                      variant="primary"
                      size="sm"
                      onClick={editingId ? saveEdit : createNote}
                      disabled={!newNote.content.trim()}
                    >
                      {editingId ? 'Save Changes' : 'Add Note'}
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={cancelEdit}
                    >
                      Cancel
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Notes List */}
      <div className="space-y-3">
        <AnimatePresence>
          {sortedNotes.map((note, index) => (
            <motion.div
              key={note.id}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
              transition={{ duration: 0.3, delay: index * 0.05 }}
            >
              <Card variant="surface">
                <CardContent className="p-4 pt-4">
                  <div className="space-y-3">
                    {/* Header */}
                    <div className="flex items-start justify-between gap-2">
                      <div className="flex items-center gap-2">
                        {getImportanceIcon(note.importance)}
                        <Badge 
                          variant="secondary" 
                          className={`text-xs ${getImportanceColor(note.importance)}`}
                        >
                          {note.importance}
                        </Badge>
                        <div className="flex items-center gap-1 text-xs text-muted-foreground">
                          <Clock size={12} />
                          {formatTimestamp(note.timestamp)}
                        </div>
                      </div>
                      
                      <div className="flex items-center gap-1">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => startEditing(note)}
                          className="p-1"
                        >
                          <Edit3 size={14} />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => deleteNote(note.id)}
                          className="p-1 text-destructive hover:text-destructive"
                        >
                          <Trash2 size={14} />
                        </Button>
                      </div>
                    </div>

                    {/* Content */}
                    <div className="text-sm leading-relaxed">
                      {note.content}
                    </div>

                    {/* Tags */}
                    {note.tags.length > 0 && (
                      <div className="flex flex-wrap gap-1">
                        {note.tags.map((tag, tagIndex) => (
                          <Badge key={tagIndex} variant="secondary" className="text-xs gap-1">
                            <Tag size={10} />
                            {tag}
                          </Badge>
                        ))}
                      </div>
                    )}
                  </div>
                </CardContent>
              </Card>
            </motion.div>
          ))}
        </AnimatePresence>
      </div>

      {/* Empty State */}
      {sortedNotes.length === 0 && (
        <Card variant="surface">
          <CardContent className="p-6 pt-6">
            <div className="text-center py-8">
              <NotebookPen 
                size={48} 
                className="mx-auto mb-4 opacity-50 text-muted-foreground" />
              <h3 className="text-lg font-medium mb-2">
                {searchQuery || filterImportance !== 'all' ? 'No Matching Notes' : 'No Notes Yet'}
              </h3>
              <p className="text-muted-foreground">
                {searchQuery || filterImportance !== 'all' 
                  ? 'Try adjusting your search or filter criteria.'
                  : 'Start documenting your Dungeon World adventure! Add notes about NPCs, discoveries, and important events.'
                }
              </p>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Quick Stats */}
      {sessionNotes.length > 0 && (
        <Card variant="surface">
          <CardContent className="p-4">
            <div className="grid grid-cols-4 gap-4 text-center text-sm">
              <div>
                <div className="font-medium">{sessionNotes.length}</div>
                <div className="text-muted-foreground">Total</div>
              </div>
              <div>
                <div className="font-medium text-destructive">
                  {sessionNotes.filter(n => n.importance === 'critical').length}
                </div>
                <div className="text-muted-foreground">Critical</div>
              </div>
              <div>
                <div className="font-medium text-chart-4">
                  {sessionNotes.filter(n => n.importance === 'important').length}
                </div>
                <div className="text-muted-foreground">Important</div>
              </div>
              <div>
                <div className="font-medium">
                  {new Set(sessionNotes.flatMap(n => n.tags)).size}
                </div>
                <div className="text-muted-foreground">Tags</div>
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  )
}

/**
 * Session Tools Panel - Main container for session management tools
 * Phase 4A: Core Gameplay Features - Essential for actual play
 */

import React, { useState } from 'react'
import { motion } from 'framer-motion'
import { 
  NotebookPen, 
  Timer, 
  Target, 
  History, 
  Plus,
  Search,
  Filter
} from 'lucide-react'
import { Card, CardContent, Button, Badge } from '../../ui'
import { NotesWidget } from './NotesWidget'
import { TrackersWidget } from './TrackersWidget'
import { TimersWidget } from './TimersWidget'
import { RollHistoryWidget } from './RollHistoryWidget'

type SessionToolTab = 'notes' | 'trackers' | 'timers' | 'history'

interface SessionToolsPanelProps {
  className?: string
}

export const SessionToolsPanel: React.FC<SessionToolsPanelProps> = ({ 
  className = '' 
}) => {
  const [activeTab, setActiveTab] = useState<SessionToolTab>('notes')
  const [searchQuery, setSearchQuery] = useState('')

  const tabs = [
    { 
      id: 'notes' as const, 
      label: 'Notes', 
      icon: NotebookPen,
      description: 'Session notes and important information'
    },
    { 
      id: 'trackers' as const, 
      label: 'Trackers', 
      icon: Target,
      description: 'Custom counters and progress trackers'
    },
    { 
      id: 'timers' as const, 
      label: 'Timers', 
      icon: Timer,
      description: 'Session timers and bookmarks'
    },
    { 
      id: 'history' as const, 
      label: 'History', 
      icon: History,
      description: 'Roll history and event log'
    }
  ]

  const renderContent = () => {
    switch (activeTab) {
      case 'notes':
        return <NotesWidget searchQuery={searchQuery} />
      case 'trackers':
        return <TrackersWidget />
      case 'timers':
        return <TimersWidget />
      case 'history':
        return <RollHistoryWidget searchQuery={searchQuery} />
      default:
        return <NotesWidget searchQuery={searchQuery} />
    }
  }

  return (
    <div className={`space-y-6 ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-display mb-2">Session Tools</h2>
          <p className="text-muted-foreground">
            Essential tools for managing your Dungeon World sessions
          </p>
        </div>
        <Badge variant="default" className="magical-glow">
          Phase 4A ✨
        </Badge>
      </div>

      {/* Tab Navigation */}
      <Card variant="surface">
        <CardContent className="p-4">
          <div className="flex flex-wrap gap-2">
            {tabs.map((tab) => {
              const Icon = tab.icon
              const isActive = activeTab === tab.id
              
              return (
                <Button
                  key={tab.id}
                  variant={isActive ? 'primary' : 'ghost'}
                  size="sm"
                  onClick={() => setActiveTab(tab.id)}
                  className="relative flex-1 min-w-0"
                  title={tab.description}
                >
                  <Icon size={16} />
                  <span className="truncate">{tab.label}</span>
                  {isActive && (
                    <motion.div
                      className="absolute bottom-0 left-0 right-0 h-0.5 bg-primary"
                      
                      layoutId="sessionToolTab"
                      transition={{ type: "spring", stiffness: 300, damping: 30 }} />
                  )}
                </Button>
              )
            })}
          </div>
        </CardContent>
      </Card>

      {/* Search Bar (for notes and history) */}
      {(activeTab === 'notes' || activeTab === 'history') && (
        <Card variant="surface">
          <CardContent className="p-4">
            <div className="relative">
              <Search 
                size={16} 
                className="absolute left-3 top-1/2 transform -translate-y-1/2 text-muted-foreground" />
              <input
                type="text"
                placeholder={`Search ${activeTab}...`}
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-2 rounded-lg border transition-colors"
                style={{
                  backgroundColor: 'var(--card)',
                  borderColor: 'var(--primary)',
                  borderOpacity: 0.2,
                  color: 'var(--foreground)'
                }}
              />
            </div>
          </CardContent>
        </Card>
      )}

      {/* Content */}
      <motion.div
        key={activeTab}
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        exit={{ opacity: 0, y: -20 }}
        transition={{ duration: 0.3 }}
      >
        {renderContent()}
      </motion.div>
    </div>
  )
}

/**
 * Timers Widget - Session timing and bookmarks
 * Phase 4A: Essential for tracking session duration and important moments
 */

import React, { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { 
  Timer, 
  Play, 
  Pause,
  Square,
  RotateCcw,
  Plus,
  Bookmark,
  Clock,
  Edit3,
  Trash2,
  Bell
} from 'lucide-react'
import { Card, CardContent, Button, Badge } from '../../ui'
import { useSessionStore } from '../../../stores'

export interface SessionTimer {
  id: string
  name: string
  type: 'stopwatch' | 'countdown'
  duration: number // in seconds
  remaining: number // in seconds
  isRunning: boolean
  startTime?: Date
  endTime?: Date
  description?: string
}

export interface TimeBookmark {
  id: string
  name: string
  timestamp: Date
  sessionTime: number // seconds from session start
  description?: string
}

interface TimersWidgetProps {
  className?: string
}

export const TimersWidget: React.FC<TimersWidgetProps> = ({ 
  className = '' 
}) => {
  const { sessionTimers, timeBookmarks, sessionStartTime, addTimer, updateTimer, deleteTimer, addBookmark, deleteBookmark } = useSessionStore()
  const [isCreatingTimer, setIsCreatingTimer] = useState(false)
  const [isCreatingBookmark, setIsCreatingBookmark] = useState(false)
  const [newTimer, setNewTimer] = useState({
    name: '',
    type: 'countdown' as const,
    duration: 300, // 5 minutes default
    description: ''
  })
  const [newBookmark, setNewBookmark] = useState({
    name: '',
    description: ''
  })

  // Update timers every second
  useEffect(() => {
    const interval = setInterval(() => {
      sessionTimers.forEach(timer => {
        if (timer.isRunning) {
          if (timer.type === 'countdown' && timer.remaining > 0) {
            updateTimer(timer.id, { remaining: timer.remaining - 1 })
          } else if (timer.type === 'stopwatch') {
            updateTimer(timer.id, { remaining: timer.remaining + 1 })
          }
        }
      })
    }, 1000)

    return () => clearInterval(interval)
  }, [sessionTimers, updateTimer])

  const createTimer = () => {
    if (!newTimer.name.trim()) return

    const timer: SessionTimer = {
      id: `timer-${Date.now()}-${Math.random().toString(36).slice(2, 11)}`,
      name: newTimer.name.trim(),
      type: newTimer.type,
      duration: newTimer.duration,
      remaining: newTimer.type === 'countdown' ? newTimer.duration : 0,
      isRunning: false,
      description: newTimer.description.trim() || undefined
    }

    addTimer(timer)
    setNewTimer({
      name: '',
      type: 'countdown',
      duration: 300,
      description: ''
    })
    setIsCreatingTimer(false)
  }

  const createBookmark = () => {
    if (!newBookmark.name.trim()) return

    const sessionTime = sessionStartTime 
      ? Math.floor((Date.now() - sessionStartTime.getTime()) / 1000)
      : 0

    const bookmark: TimeBookmark = {
      id: `bookmark-${Date.now()}-${Math.random().toString(36).slice(2, 11)}`,
      name: newBookmark.name.trim(),
      timestamp: new Date(),
      sessionTime,
      description: newBookmark.description.trim() || undefined
    }

    addBookmark(bookmark)
    setNewBookmark({ name: '', description: '' })
    setIsCreatingBookmark(false)
  }

  const toggleTimer = (timerId: string) => {
    const timer = sessionTimers.find(t => t.id === timerId)
    if (!timer) return

    if (timer.isRunning) {
      updateTimer(timerId, { 
        isRunning: false,
        endTime: new Date()
      })
    } else {
      updateTimer(timerId, { 
        isRunning: true,
        startTime: new Date()
      })
    }
  }

  const resetTimer = (timerId: string) => {
    const timer = sessionTimers.find(t => t.id === timerId)
    if (!timer) return

    updateTimer(timerId, {
      remaining: timer.type === 'countdown' ? timer.duration : 0,
      isRunning: false,
      startTime: undefined,
      endTime: undefined
    })
  }

  const formatTime = (seconds: number) => {
    const hours = Math.floor(seconds / 3600)
    const minutes = Math.floor((seconds % 3600) / 60)
    const secs = seconds % 60

    if (hours > 0) {
      return `${hours}:${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`
    }
    return `${minutes}:${secs.toString().padStart(2, '0')}`
  }

  const formatDuration = (seconds: number) => {
    const hours = Math.floor(seconds / 3600)
    const minutes = Math.floor((seconds % 3600) / 60)
    
    if (hours > 0) {
      return `${hours}h ${minutes}m`
    }
    return `${minutes}m`
  }

  const getCurrentSessionTime = () => {
    if (!sessionStartTime) return 0
    return Math.floor((Date.now() - sessionStartTime.getTime()) / 1000)
  }

  const getTimerProgress = (timer: SessionTimer) => {
    if (timer.type === 'stopwatch') return 0
    return timer.duration > 0 ? ((timer.duration - timer.remaining) / timer.duration) * 100 : 0
  }

  const isTimerExpired = (timer: SessionTimer) => {
    return timer.type === 'countdown' && timer.remaining <= 0
  }

  return (
    <div className={`space-y-4 ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Timer size={20} />
          <span className="font-medium">Session Timers</span>
          <Badge variant="secondary">{sessionTimers.length}</Badge>
        </div>
      </div>

      {/* Session Time */}
      <Card variant="magical">
        <CardContent className="text-center space-y-2 p-6 pt-6">
          <div className="text-center space-y-2">
            <div className="flex items-center justify-center gap-2">
              <Clock size={20} />
              <span className="font-medium">Session Duration</span>
            </div>
            <div className="text-3xl font-bold">
              {formatTime(getCurrentSessionTime())}
            </div>
            <div className="text-sm text-muted-foreground">
              Started: {sessionStartTime ? sessionStartTime.toLocaleTimeString() : 'Not started'}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Add Timer/Bookmark Buttons */}
      <div className="grid grid-cols-2 gap-2">
        <Button
          variant="primary"
          size="sm"
          onClick={() => setIsCreatingTimer(true)}
          className="gap-2"
        >
          <Plus size={16} />
          Add Timer
        </Button>
        <Button
          variant="outline"
          size="sm"
          onClick={() => setIsCreatingBookmark(true)}
          className="gap-2"
        >
          <Bookmark size={16} />
          Bookmark
        </Button>
      </div>

      {/* Create Timer Form */}
      <AnimatePresence>
        {isCreatingTimer && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: 0.3 }}
          >
        <Card variant="magical">
          <CardContent className="p-6">
                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium mb-2">
                      Timer Name
                    </label>
                    <input
                      type="text"
                      value={newTimer.name}
                      onChange={(e) => setNewTimer(prev => ({ ...prev, name: e.target.value }))}
                      placeholder="Combat Round, Torch Duration, etc."
                      className="w-full px-3 py-2 rounded-lg border transition-colors"
                      style={{
                        backgroundColor: 'var(--card)',
                        borderColor: 'var(--primary)',
                        borderOpacity: 0.2,
                        color: 'var(--foreground)'
                      }}
                      autoFocus
                    />
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium mb-2">
                        Type
                      </label>
                      <select
                        value={newTimer.type}
                        onChange={(e) => setNewTimer(prev => ({ 
                          ...prev, 
                          type: e.target.value as 'countdown' | 'stopwatch' 
                        }))}
                        className="w-full px-3 py-2 rounded-lg border transition-colors"
                        style={{
                          backgroundColor: 'var(--card)',
                          borderColor: 'var(--primary)',
                          borderOpacity: 0.2,
                          color: 'var(--foreground)'
                        }}
                      >
                        <option value="countdown">Countdown</option>
                        <option value="stopwatch">Stopwatch</option>
                      </select>
                    </div>
                    <div>
                      <label className="block text-sm font-medium mb-2">
                        Duration (minutes)
                      </label>
                      <input
                        type="number"
                        value={Math.floor(newTimer.duration / 60)}
                        onChange={(e) => setNewTimer(prev => ({ 
                          ...prev, 
                          duration: (parseInt(e.target.value) || 5) * 60 
                        }))}
                        min="1"
                        className="w-full px-3 py-2 rounded-lg border transition-colors"
                        style={{
                          backgroundColor: 'var(--card)',
                          borderColor: 'var(--primary)',
                          borderOpacity: 0.2,
                          color: 'var(--foreground)'
                        }}
                      />
                    </div>
                  </div>

                  <div>
                    <label className="block text-sm font-medium mb-2">
                      Description (optional)
                    </label>
                    <input
                      type="text"
                      value={newTimer.description}
                      onChange={(e) => setNewTimer(prev => ({ ...prev, description: e.target.value }))}
                      placeholder="What is this timer for?"
                      className="w-full px-3 py-2 rounded-lg border transition-colors"
                      style={{
                        backgroundColor: 'var(--card)',
                        borderColor: 'var(--primary)',
                        borderOpacity: 0.2,
                        color: 'var(--foreground)'
                      }}
                    />
                  </div>

                  <div className="flex gap-2">
                    <Button
                      variant="primary"
                      size="sm"
                      onClick={createTimer}
                      disabled={!newTimer.name.trim()}
                    >
                      Create Timer
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => setIsCreatingTimer(false)}
                    >
                      Cancel
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Create Bookmark Form */}
      <AnimatePresence>
        {isCreatingBookmark && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: 0.3 }}
          >
            <Card variant="magical">
              <CardContent className="p-6">
                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium mb-2">
                      Bookmark Name
                    </label>
                    <input
                      type="text"
                      value={newBookmark.name}
                      onChange={(e) => setNewBookmark(prev => ({ ...prev, name: e.target.value }))}
                      placeholder="Important Discovery, Boss Fight, etc."
                      className="w-full px-3 py-2 rounded-lg border transition-colors"
                      style={{
                        backgroundColor: 'var(--card)',
                        borderColor: 'var(--primary)',
                        borderOpacity: 0.2,
                        color: 'var(--foreground)'
                      }}
                      autoFocus
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium mb-2">
                      Description (optional)
                    </label>
                    <textarea
                      value={newBookmark.description}
                      onChange={(e) => setNewBookmark(prev => ({ ...prev, description: e.target.value }))}
                      placeholder="What happened at this moment?"
                      rows={2}
                      className="w-full px-3 py-2 rounded-lg border transition-colors resize-none"
                      style={{
                        backgroundColor: 'var(--card)',
                        borderColor: 'var(--primary)',
                        borderOpacity: 0.2,
                        color: 'var(--foreground)'
                      }}
                    />
                  </div>

                  <div className="flex gap-2">
                    <Button
                      variant="primary"
                      size="sm"
                      onClick={createBookmark}
                      disabled={!newBookmark.name.trim()}
                    >
                      Create Bookmark
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => setIsCreatingBookmark(false)}
                    >
                      Cancel
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Active Timers */}
      {sessionTimers.length > 0 && (
        <div className="space-y-3">
          <h4 className="font-medium">Active Timers</h4>
          <AnimatePresence>
            {sessionTimers.map((timer, index) => (
              <motion.div
                key={timer.id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -20 }}
                transition={{ duration: 0.3, delay: index * 0.05 }}
              >
                <Card variant={isTimerExpired(timer) ? "magical" : "surface"}>
                  <CardContent className="p-4 pt-4">
                    <div className="space-y-3">
                      {/* Header */}
                      <div className="flex items-start justify-between gap-2">
                        <div>
                          <div className="flex items-center gap-2">
                            <div className="font-medium">{timer.name}</div>
                            <Badge variant={timer.type === 'countdown' ? 'default' : 'secondary'}>
                              {timer.type}
                            </Badge>
                            {isTimerExpired(timer) && (
                              <Badge variant="default" className="bg-destructive/15 text-destructive gap-1">
                                <Bell size={10} />
                                Expired
                              </Badge>
                            )}
                          </div>
                          {timer.description && (
                            <div className="text-xs mt-1 text-muted-foreground">
                              {timer.description}
                            </div>
                          )}
                        </div>
                        
                        <div className="flex items-center gap-1">
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => deleteTimer(timer.id)}
                            className="p-1 text-destructive hover:text-destructive"
                          >
                            <Trash2 size={14} />
                          </Button>
                        </div>
                      </div>

                      {/* Time Display */}
                      <div className="text-center">
                        <div className={`text-2xl font-bold ${isTimerExpired(timer) ? 'text-destructive' : ''}`}>
                          {formatTime(Math.abs(timer.remaining))}
                        </div>
                        {timer.type === 'countdown' && (
                          <div className="text-xs text-muted-foreground">
                            of {formatTime(timer.duration)}
                          </div>
                        )}
                      </div>

                      {/* Progress Bar (countdown only) */}
                      {timer.type === 'countdown' && (
                        <div className="w-full bg-muted rounded-full h-2">
                          <div 
                            className={`h-2 rounded-full transition-all duration-300 ${
                              isTimerExpired(timer) ? 'bg-destructive/120' : 'bg-primary/100'
                            }`}
                            style={{ width: `${Math.min(100, getTimerProgress(timer))}%` }}
                          />
                        </div>
                      )}

                      {/* Controls */}
                      <div className="flex items-center justify-center gap-2">
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => toggleTimer(timer.id)}
                          className="gap-1"
                        >
                          {timer.isRunning ? <Pause size={14} /> : <Play size={14} />}
                          {timer.isRunning ? 'Pause' : 'Start'}
                        </Button>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => resetTimer(timer.id)}
                          className="gap-1"
                        >
                          <RotateCcw size={14} />
                          Reset
                        </Button>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              </motion.div>
            ))}
          </AnimatePresence>
        </div>
      )}

      {/* Time Bookmarks */}
      {timeBookmarks.length > 0 && (
        <div className="space-y-3">
          <h4 className="font-medium">Time Bookmarks</h4>
          <div className="space-y-2">
            <AnimatePresence>
              {timeBookmarks.map((bookmark, index) => (
                <motion.div
                  key={bookmark.id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -20 }}
                  transition={{ duration: 0.3, delay: index * 0.02 }}
                >
                  <Card variant="surface">
                    <CardContent className="p-4 pt-4">
                      <div className="flex items-start justify-between gap-2">
                        <div className="flex items-center gap-2">
                          <Bookmark size={14} className="text-primary" />
                          <div>
                            <div className="font-medium text-sm">{bookmark.name}</div>
                            <div className="text-xs text-muted-foreground">
                              {formatTime(bookmark.sessionTime)} into session
                            </div>
                            {bookmark.description && (
                              <div className="text-xs mt-1 text-muted-foreground">
                                {bookmark.description}
                              </div>
                            )}
                          </div>
                        </div>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => deleteBookmark(bookmark.id)}
                          className="p-1 text-destructive hover:text-destructive"
                        >
                          <Trash2 size={12} />
                        </Button>
                      </div>
                    </CardContent>
                  </Card>
                </motion.div>
              ))}
            </AnimatePresence>
          </div>
        </div>
      )}

      {/* Empty State */}
      {sessionTimers.length === 0 && timeBookmarks.length === 0 && (
        <Card variant="surface">
          <CardContent className="p-6 pt-6">
            <div className="text-center py-8">
              <Timer 
                size={48} 
                className="mx-auto mb-4 opacity-50 text-muted-foreground" />
              <h3 className="text-lg font-medium mb-2">No Timers or Bookmarks</h3>
              <p className="text-muted-foreground">
                Create timers for combat rounds, torch duration, or other time-sensitive events. 
                Add bookmarks to mark important moments in your session!
              </p>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  )
}

/**
 * MagicalEffects Component for ZimboMate V2
 * Ambient magical particles and effects around the spell book
 */

import React, { useEffect, useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { Sparkles } from 'lucide-react'

interface Particle {
  id: string
  x: number
  y: number
  size: number
  color: string
  duration: number
  delay: number
}

interface MagicalEffectsProps {
  isActive?: boolean
  intensity?: 'low' | 'medium' | 'high'
  spellSchool?: string
  className?: string
}

export function MagicalEffects({ 
  isActive = true, 
  intensity = 'medium',
  spellSchool,
  className = '' 
}: MagicalEffectsProps) {
  const [particles, setParticles] = useState<Particle[]>([])

  const getSchoolColor = (school?: string) => {
    const colors = {
      abjuration: '#3b82f6',
      conjuration: '#10b981',
      divination: '#f59e0b',
      enchantment: '#ec4899',
      evocation: '#ef4444',
      illusion: '#8b5cf6',
      necromancy: '#6b7280',
      transmutation: '#f97316'
    }
    return school ? colors[school.toLowerCase()] || '#d4af37' : '#d4af37'
  }

  const getParticleCount = () => {
    switch (intensity) {
      case 'low': return 8
      case 'medium': return 15
      case 'high': return 25
      default: return 15
    }
  }

  useEffect(() => {
    if (!isActive) {
      setParticles([])
      return
    }

    const generateParticles = () => {
      const newParticles: Particle[] = []
      const count = getParticleCount()
      const color = getSchoolColor(spellSchool)

      for (let i = 0; i < count; i++) {
        newParticles.push({
          id: `particle-${i}-${Date.now()}`,
          x: Math.random() * 100,
          y: Math.random() * 100,
          size: Math.random() * 4 + 2,
          color,
          duration: Math.random() * 3 + 2,
          delay: Math.random() * 2
        })
      }

      setParticles(newParticles)
    }

    generateParticles()
    const interval = setInterval(generateParticles, 5000)

    return () => clearInterval(interval)
  }, [isActive, intensity, spellSchool])

  if (!isActive) return null

  return (
    <div className={`absolute inset-0 pointer-events-none overflow-hidden ${className}`}>
      {/* Ambient magical glow */}
      <motion.div
        className="absolute inset-0 opacity-30"
        animate={{
          background: [
            `radial-gradient(circle at 20% 20%, ${getSchoolColor(spellSchool)}20 0%, transparent 50%)`,
            `radial-gradient(circle at 80% 80%, ${getSchoolColor(spellSchool)}20 0%, transparent 50%)`,
            `radial-gradient(circle at 50% 50%, ${getSchoolColor(spellSchool)}20 0%, transparent 50%)`,
          ]
        }}
        transition={{
          duration: 8,
          repeat: Infinity,
          ease: 'easeInOut'
        }}
      />

      {/* Floating particles */}
      <AnimatePresence>
        {particles.map(particle => (
          <motion.div
            key={particle.id}
            className="absolute"
            style={{
              left: `${particle.x}%`,
              top: `${particle.y}%`,
            }}
            initial={{ 
              opacity: 0, 
              scale: 0,
              rotate: 0
            }}
            animate={{ 
              opacity: [0, 1, 1, 0],
              scale: [0, 1, 1.2, 0],
              rotate: 360,
              x: [0, Math.random() * 40 - 20],
              y: [0, Math.random() * 40 - 20]
            }}
            transition={{
              duration: particle.duration,
              delay: particle.delay,
              repeat: Infinity,
              ease: 'easeInOut'
            }}
          >
            <Sparkles 
              size={particle.size} 
              style={{ color: particle.color }}
            />
          </motion.div>
        ))}
      </AnimatePresence>

      {/* Corner magical effects */}
      <motion.div
        className="absolute top-4 left-4"
        animate={{
          rotate: [0, 360],
          scale: [1, 1.1, 1]
        }}
        transition={{
          duration: 6,
          repeat: Infinity,
          ease: 'easeInOut'
        }}
      >
        <Sparkles 
          size={24} 
          style={{ color: getSchoolColor(spellSchool) }}
          className="opacity-60"
        />
      </motion.div>

      <motion.div
        className="absolute top-4 right-4"
        animate={{
          rotate: [360, 0],
          scale: [1, 1.2, 1]
        }}
        transition={{
          duration: 8,
          repeat: Infinity,
          ease: 'easeInOut',
          delay: 1
        }}
      >
        <Sparkles 
          size={20} 
          style={{ color: getSchoolColor(spellSchool) }}
          className="opacity-50"
        />
      </motion.div>

      <motion.div
        className="absolute bottom-4 left-4"
        animate={{
          rotate: [0, -360],
          scale: [1, 1.15, 1]
        }}
        transition={{
          duration: 7,
          repeat: Infinity,
          ease: 'easeInOut',
          delay: 2
        }}
      >
        <Sparkles 
          size={18} 
          style={{ color: getSchoolColor(spellSchool) }}
          className="opacity-40"
        />
      </motion.div>

      <motion.div
        className="absolute bottom-4 right-4"
        animate={{
          rotate: [360, 0],
          scale: [1, 1.3, 1]
        }}
        transition={{
          duration: 9,
          repeat: Infinity,
          ease: 'easeInOut',
          delay: 3
        }}
      >
        <Sparkles 
          size={22} 
          style={{ color: getSchoolColor(spellSchool) }}
          className="opacity-70"
        />
      </motion.div>

      {/* Pulsing magical aura */}
      <motion.div
        className="absolute inset-4 border border-current rounded-lg opacity-20"
        style={{ color: getSchoolColor(spellSchool) }}
        animate={{
          opacity: [0.1, 0.3, 0.1],
          scale: [1, 1.02, 1]
        }}
        transition={{
          duration: 4,
          repeat: Infinity,
          ease: 'easeInOut'
        }}
      />
    </div>
  )
}

/**
 * SpellBook Component for ZimboMate V2
 * Main animated spell book interface with magical effects
 */

import React, { useState, useCallback, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import * as Dialog from '@radix-ui/react-dialog'
import { useSpells } from '../../../hooks/useSpells'
import { useKeyboardShortcuts } from '../../../hooks/useKeyboardShortcuts'
import { SpellBookPage } from './SpellBookPage'
import { PageNavigation } from './PageNavigation'
import { SpellSearch } from './SpellSearch'
import { SpellList } from './SpellList'
import { SpellDetails } from './SpellDetails'
import { SpellSlotTracker } from './SpellSlotTracker'
import { MagicalEffects } from './MagicalEffects'

interface SpellBookProps {
  characterId?: string
  isOpen: boolean
  onClose: () => void
  theme?: 'fantasy' | 'dark' | 'light'
  enableAnimations?: boolean
  enableAudio?: boolean
  onSpellCast?: (spell: any, level: number) => void
  onSpellPrepared?: (spell: any) => void
  onSpellUnprepared?: (spell: any) => void
}

export function SpellBook({
  characterId,
  isOpen,
  onClose,
  theme = 'fantasy',
  enableAnimations = true,
  enableAudio = true,
  onSpellCast,
  onSpellPrepared,
  onSpellUnprepared
}: SpellBookProps) {
  // Spell management
  const {
    allSpells,
    preparedSpells,
    spellSlots,
    castSpell,
    prepareSpell,
    unprepareSpell,
    longRest,
    shortRest,
    isCasting,
    character
  } = useSpells(characterId)

  // UI state
  const [currentPage, setCurrentPage] = useState(0)
  const [selectedSpell, setSelectedSpell] = useState<any>(null)
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedSchool, setSelectedSchool] = useState<string | null>(null)
  const [selectedLevel, setSelectedLevel] = useState<number | null>(null)
  const [isAnimating, setIsAnimating] = useState(false)

  const pages = ['spells', 'details', 'slots', 'prepared']
  const totalPages = pages.length

  // Page navigation with animation
  const handlePageChange = useCallback((newPage: number) => {
    if (newPage === currentPage || isAnimating) return

    setIsAnimating(true)

    setTimeout(() => {
      setCurrentPage(newPage)
      setIsAnimating(false)
    }, 400)
  }, [currentPage, isAnimating])

  // Spell actions
  const handleSpellSelect = useCallback((spell: any) => {
    setSelectedSpell(spell)
    if (currentPage !== 1) {
      handlePageChange(1) // Go to details page
    }
  }, [currentPage, handlePageChange])

  const handleSpellPrepare = useCallback(async (spellId: string) => {
    const spell = allSpells.find(s => s.id === spellId)
    if (!spell) return

    try {
      prepareSpell(spellId)
      onSpellPrepared?.(spell)
    } catch (error) {
      console.error('Failed to prepare spell:', error)
    }
  }, [allSpells, prepareSpell, onSpellPrepared])

  const handleSpellCast = useCallback(async (spellId: string, level: number) => {
    const spell = allSpells.find(s => s.id === spellId)
    if (!spell) return

    try {
      const result = await castSpell(spellId, { upcast: level > spell.level })
      onSpellCast?.(spell, level)
    } catch (error) {
      console.error('Failed to cast spell:', error)
    }
  }, [allSpells, castSpell, onSpellCast])

  // Search and filter functions
  const handleClearFilters = useCallback(() => {
    setSearchQuery('')
    setSelectedSchool(null)
    setSelectedLevel(null)
  }, [])

  const handleSlotRefresh = useCallback(() => {
    longRest()
  }, [longRest])

  // Keyboard shortcuts
  useKeyboardShortcuts({
    'ArrowLeft': () => currentPage > 0 && handlePageChange(currentPage - 1),
    'ArrowRight': () => currentPage < totalPages - 1 && handlePageChange(currentPage + 1),
    'Escape': onClose,
    '1': () => handlePageChange(0),
    '2': () => handlePageChange(1),
    '3': () => handlePageChange(2),
    '4': () => handlePageChange(3)
  })

  // Auto-select first spell when opening spells page
  useEffect(() => {
    if (currentPage === 0 && allSpells.length > 0 && !selectedSpell) {
      setSelectedSpell(allSpells[0])
    }
  }, [currentPage, allSpells, selectedSpell])

  const currentSpellSchool = selectedSpell?.school || 'evocation'

  return (
    <Dialog.Root open={isOpen} onOpenChange={onClose}>
      <Dialog.Portal>
        <Dialog.Overlay className="fixed inset-0 bg-black/50 backdrop-blur-sm z-40" />
        <Dialog.Content className="fixed inset-4 md:inset-8 lg:inset-16 z-50 focus:outline-none">
          <motion.div
            className="spell-book-container w-full h-full relative overflow-hidden"
            initial={{ opacity: 0, scale: 0.9, rotateX: -15 }}
            animate={{ opacity: 1, scale: 1, rotateX: 0 }}
            exit={{ opacity: 0, scale: 0.9, rotateX: -15 }}
            transition={{ duration: 0.5, ease: "easeOut" }}
          >
            {/* Magical effects overlay */}
            <MagicalEffects
              isActive={enableAnimations}
              intensity="medium"
              spellSchool={currentSpellSchool}
            />

            {/* Page navigation */}
            <PageNavigation
              currentPage={currentPage}
              totalPages={totalPages}
              onPageChange={handlePageChange}
              onClose={onClose}
            />

            {/* Book pages */}
            <div className="flex h-full pt-16">
              {/* Left page */}
              <div className="flex-1 p-6 relative">
                <SpellBookPage
                  isVisible={currentPage === 0 || currentPage === 2}
                  isAnimating={isAnimating}
                  animationDirection="left"
                >
                  {currentPage === 0 && (
                    <div className="h-full flex flex-col">
                      <SpellSearch
                        searchQuery={searchQuery}
                        onSearchChange={setSearchQuery}
                        selectedSchool={selectedSchool}
                        onSchoolChange={setSelectedSchool}
                        selectedLevel={selectedLevel}
                        onLevelChange={setSelectedLevel}
                        onClearFilters={handleClearFilters}
                        className="mb-4"
                      />
                      <SpellList
                        spells={allSpells}
                        selectedSpell={selectedSpell}
                        onSpellSelect={handleSpellSelect}
                        onSpellPrepare={handleSpellPrepare}
                        onSpellCast={handleSpellCast}
                        searchQuery={searchQuery}
                        selectedSchool={selectedSchool}
                        selectedLevel={selectedLevel}
                        className="flex-1"
                      />
                    </div>
                  )}

                  {currentPage === 2 && (
                    <SpellSlotTracker
                      slots={spellSlots.reduce((acc, slot) => {
                        acc[slot.level] = { total: slot.total, used: slot.used }
                        return acc
                      }, {} as Record<number, { total: number; used: number }>)}
                      onRefresh={handleSlotRefresh}
                      className="h-full"
                    />
                  )}
                </SpellBookPage>
              </div>

              {/* Book spine */}
              <div className="w-4 bg-gradient-to-b from-gold-600 to-gold-800 relative">
                <div className="absolute inset-y-0 left-0 w-1 bg-gold-400" />
                <div className="absolute inset-y-0 right-0 w-1 bg-gold-900" />
              </div>

              {/* Right page */}
              <div className="flex-1 p-6 relative">
                <SpellBookPage
                  isVisible={currentPage === 1 || currentPage === 3}
                  isAnimating={isAnimating}
                  animationDirection="right"
                >
                  {currentPage === 1 && (
                    <SpellDetails
                      spell={selectedSpell}
                      onCast={handleSpellCast}
                      onPrepare={handleSpellPrepare}
                      className="h-full"
                    />
                  )}

                  {currentPage === 3 && (
                    <SpellList
                      spells={preparedSpells}
                      selectedSpell={selectedSpell}
                      onSpellSelect={handleSpellSelect}
                      onSpellPrepare={handleSpellPrepare}
                      onSpellCast={handleSpellCast}
                      searchQuery=""
                      selectedSchool={null}
                      selectedLevel={null}
                      className="h-full"
                    />
                  )}
                </SpellBookPage>
              </div>
            </div>

            {/* Loading overlay */}
            <AnimatePresence>
              {isCasting && (
                <motion.div
                  className="absolute inset-0 bg-magic-500/20 backdrop-blur-sm flex items-center justify-center z-10"
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
                >
                  <motion.div
                    className="text-display-md font-display text-accent"
                    animate={{
                      scale: [1, 1.1, 1],
                      opacity: [0.7, 1, 0.7]
                    }}
                    transition={{
                      duration: 1,
                      repeat: Infinity,
                      ease: "easeInOut"
                    }}
                  >
                    Casting Spell...
                  </motion.div>
                </motion.div>
              )}
            </AnimatePresence>
          </motion.div>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  )
}

/**
 * SpellDetails Component for ZimboMate V2
 * Comprehensive spell information display with casting details
 */

import React from 'react'
import { motion } from 'framer-motion'
import { Wand, Clock, Target, Zap, Eye, Sparkles } from 'lucide-react'
import { Card, Badge, Button } from '../../ui'

interface Spell {
  id: string
  name: string
  level: number
  school: string
  castingTime: string
  range: string
  components: string[]
  duration: string
  concentration: boolean
  ritual: boolean
  description: string
  damage?: string
  savingThrow?: string
  materialComponents?: string
  atHigherLevels?: string
  preparationStatus: 'not_prepared' | 'prepared' | 'used'
}

interface SpellDetailsProps {
  spell: Spell | null
  onCast?: (spellId: string, level: number) => void
  onPrepare?: (spellId: string) => void
  className?: string
}

export function SpellDetails({ 
  spell, 
  onCast, 
  onPrepare, 
  className = '' 
}: SpellDetailsProps) {
  if (!spell) {
    return (
      <motion.div
        className={`spell-book-page p-8 rounded-lg flex items-center justify-center ${className}`}
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
      >
        <div className="text-center text-muted-foreground">
          <Sparkles size={48} className="mx-auto mb-4 opacity-50" />
          <p className="text-body-lg">Select a spell to view details</p>
        </div>
      </motion.div>
    )
  }

  const getSpellSchoolColor = (school: string) => {
    const colors = {
      abjuration: 'text-primary',
      conjuration: 'text-chart-2',
      divination: 'text-chart-4',
      enchantment: 'text-accent',
      evocation: 'text-destructive',
      illusion: 'text-accent',
      necromancy: 'text-muted-foreground',
      transmutation: 'text-chart-4'
    }
    return colors[school.toLowerCase()] || 'text-muted-foreground'
  }

  const canCast = spell.preparationStatus === 'prepared' || spell.level === 0

  return (
    <motion.div
      className={`spell-book-page p-6 rounded-lg ${className}`}
      initial={{ opacity: 0, x: 20 }}
      animate={{ opacity: 1, x: 0 }}
      transition={{ duration: 0.3 }}
      key={spell.id}
    >
      {/* Header */}
      <div className="mb-6">
        <div className="flex items-start justify-between mb-3">
          <h2 className="text-display-md text-foreground font-display">
            {spell.name}
          </h2>
          <div className="flex items-center gap-2">
            {spell.ritual && (
              <Sparkles size={20} className="text-accent" />
            )}
            {spell.concentration && (
              <Eye size={20} className="text-primary" />
            )}
          </div>
        </div>

        <div className="flex items-center gap-2 mb-4">
          <Badge variant="outline" className="font-display">
            {spell.level === 0 ? 'Cantrip' : `${spell.level}${getOrdinalSuffix(spell.level)} Level`}
          </Badge>
          <Badge className={`${getSpellSchoolColor(spell.school)} bg-transparent border-current`}>
            {spell.school.charAt(0).toUpperCase() + spell.school.slice(1)}
          </Badge>
        </div>
      </div>

      {/* Casting Information */}
      <div className="grid grid-cols-2 gap-4 mb-6">
        <div className="space-y-3">
          <div className="flex items-center gap-2">
            <Clock size={16} className="text-muted-foreground" />
            <div>
              <div className="text-ui-small text-muted-foreground">Casting Time</div>
              <div className="text-ui-regular">{spell.castingTime}</div>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <Target size={16} className="text-muted-foreground" />
            <div>
              <div className="text-ui-small text-muted-foreground">Range</div>
              <div className="text-ui-regular">{spell.range}</div>
            </div>
          </div>
        </div>

        <div className="space-y-3">
          <div className="flex items-center gap-2">
            <Zap size={16} className="text-muted-foreground" />
            <div>
              <div className="text-ui-small text-muted-foreground">Duration</div>
              <div className="text-ui-regular">
                {spell.duration}
                {spell.concentration && ' (C)'}
              </div>
            </div>
          </div>

          <div>
            <div className="text-ui-small text-muted-foreground">Components</div>
            <div className="text-ui-regular">{spell.components.join(', ').toUpperCase()}</div>
          </div>
        </div>
      </div>

      {/* Material Components */}
      {spell.materialComponents && (
        <div className="mb-6 p-3 bg-parchment-100/50 rounded-lg border border-parchment-300/30">
          <div className="text-ui-small text-muted-foreground mb-1">Material Components</div>
          <div className="text-ui-regular italic">{spell.materialComponents}</div>
        </div>
      )}

      {/* Description */}
      <div className="mb-6">
        <h3 className="text-body-lg font-display text-foreground mb-2">Description</h3>
        <p className="text-body-regular text-muted-foreground leading-relaxed">
          {spell.description}
        </p>
      </div>

      {/* Damage/Effects */}
      {spell.damage && (
        <div className="mb-4 p-3 bg-destructive/12 rounded-lg border border-destructive/30">
          <div className="text-ui-small text-destructive mb-1">Damage</div>
          <div className="text-ui-regular font-mono">{spell.damage}</div>
          {spell.savingThrow && (
            <div className="text-ui-small text-destructive mt-1">
              Saving Throw: {spell.savingThrow}
            </div>
          )}
        </div>
      )}

      {/* At Higher Levels */}
      {spell.atHigherLevels && (
        <div className="mb-6 p-3 bg-magic-50 rounded-lg border border-magic-200">
          <div className="text-ui-small text-accent mb-1">At Higher Levels</div>
          <p className="text-ui-regular text-accent">{spell.atHigherLevels}</p>
        </div>
      )}

      {/* Action Buttons */}
      <div className="flex gap-3 pt-4 border-t border-parchment-300/30">
        {spell.preparationStatus === 'not_prepared' && spell.level > 0 && onPrepare && (
          <Button
            variant="outline"
            onClick={() => onPrepare(spell.id)}
            className="flex-1"
          >
            Prepare Spell
          </Button>
        )}

        {canCast && onCast && (
          <Button
            variant="default"
            onClick={() => onCast(spell.id, spell.level)}
            disabled={spell.preparationStatus === 'used'}
            className="flex-1 gap-2 magical-glow"
          >
            <Wand size={16} />
            Cast Spell
          </Button>
        )}
      </div>
    </motion.div>
  )
}

function getOrdinalSuffix(num: number): string {
  const suffixes = ['th', 'st', 'nd', 'rd']
  const remainder = num % 100
  return suffixes[(remainder - 20) % 10] || suffixes[remainder] || suffixes[0]
}

/**
 * Stat Roller Component
 *
 * Specialized dice roller for attribute tests (STR, DEX, CON, INT, WIS, CHA).
 * Automatically integrates with Chronicle system to prompt "Why did you roll DEX?"
 * type questions after each roll.
 */

import React, { useState } from 'react'
import { motion } from 'framer-motion'
import { ChronicleEnabledDiceRoller } from './ChronicleEnabledDiceRoller'
import { Card, CardContent, Button } from '../ui'
import {
  Zap,        // STR
  Wind,       // DEX
  Heart,      // CON
  Brain,      // INT
  Eye,        // WIS
  Sparkles    // CHA
} from 'lucide-react'
import { cn } from '@/lib/utils'

export type Stat = 'STR' | 'DEX' | 'CON' | 'INT' | 'WIS' | 'CHA'

interface StatInfo {
  name: string
  fullName: string
  description: string
  icon: React.ReactNode
  examples: string[]
  color: string
}

const STAT_INFO: Record<Stat, StatInfo> = {
  STR: {
    name: 'STR',
    fullName: 'Strength',
    description: 'Physical power and athleticism',
    icon: <Zap size={16} />,
    examples: ['Lifting heavy objects', 'Breaking down doors', 'Wrestling', 'Climbing'],
    color: 'text-destructive'
  },
  DEX: {
    name: 'DEX',
    fullName: 'Dexterity',
    description: 'Agility, reflexes, and precision',
    icon: <Wind size={16} />,
    examples: ['Dodging attacks', 'Sneaking quietly', 'Picking locks', 'Aiming accurately'],
    color: 'text-chart-2'
  },
  CON: {
    name: 'CON',
    fullName: 'Constitution',
    description: 'Endurance and physical resilience',
    icon: <Heart size={16} />,
    examples: ['Resisting poison', 'Enduring harsh weather', 'Holding breath', 'Fighting fatigue'],
    color: 'text-accent'
  },
  INT: {
    name: 'INT',
    fullName: 'Intelligence',
    description: 'Reasoning and memory',
    icon: <Brain size={16} />,
    examples: ['Recalling lore', 'Solving puzzles', 'Understanding magic', 'Analyzing clues'],
    color: 'text-primary'
  },
  WIS: {
    name: 'WIS',
    fullName: 'Wisdom',
    description: 'Awareness and intuition',
    icon: <Eye size={16} />,
    examples: ['Noticing details', 'Reading people', 'Tracking', 'Sensing danger'],
    color: 'text-accent'
  },
  CHA: {
    name: 'CHA',
    fullName: 'Charisma',
    description: 'Force of personality and leadership',
    icon: <Sparkles size={16} />,
    examples: ['Persuading others', 'Intimidating foes', 'Performing', 'Leading'],
    color: 'text-chart-4'
  }
}

interface StatRollerProps {
  characterName?: string
  statModifiers?: Partial<Record<Stat, number>>
  onStatRoll?: (stat: Stat, result: any) => void
  disabled?: boolean
  showExamples?: boolean
  className?: string
}

const StatButton: React.FC<{
  stat: Stat
  modifier: number
  onRoll: (stat: Stat) => void
  disabled?: boolean
}> = ({ stat, modifier, onRoll, disabled }) => {
  const info = STAT_INFO[stat]

  return (
    <motion.div
      whileHover={{ scale: 1.02 }}
      whileTap={{ scale: 0.98 }}
      className="h-full"
    >
      <Button
        variant="outline"
        onClick={() => onRoll(stat)}
        disabled={disabled}
        className="
          h-full w-full p-4 flex flex-col items-center gap-2
          hover:shadow-lg transition-all duration-200
          border-2 hover:border-primary/30
        "
      >
        <div className={`flex items-center gap-2 ${info.color}`}>
          {info.icon}
          <span className="font-bold text-lg">{stat}</span>
        </div>

        <div className="text-sm font-medium text-foreground ">
          {info.fullName}
        </div>

        <div className="text-xs text-center text-muted-foreground  leading-tight">
          {info.description}
        </div>

        {modifier !== 0 && (
          <div className={`
            text-xs font-mono px-2 py-1 rounded
            ${modifier >= 0 ? 'bg-chart-2/15 text-chart-2' : 'bg-destructive/15 text-destructive'}
          `}>
            {modifier >= 0 ? '+' : ''}{modifier}
          </div>
        )}
      </Button>
    </motion.div>
  )
}

const StatExamples: React.FC<{ stat: Stat }> = ({ stat }) => {
  const info = STAT_INFO[stat]

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      className="mt-4 p-4 bg-muted/50  rounded-lg"
    >
      <div className="text-sm font-medium mb-2 flex items-center gap-2">
        <span className={info.color}>{info.icon}</span>
        <span>Common {info.fullName} uses:</span>
      </div>
      <div className="grid grid-cols-2 gap-1 text-xs text-muted-foreground ">
        {info.examples.map((example, index) => (
          <div key={index} className="flex items-center gap-1">
            <span className="w-1 h-1 bg-gray-400 rounded-full" />
            <span>{example}</span>
          </div>
        ))}
      </div>
    </motion.div>
  )
}

export const StatRoller: React.FC<StatRollerProps> = ({
  characterName,
  statModifiers = {},
  onStatRoll,
  disabled = false,
  showExamples = true,
  className = ''
}) => {
  const [selectedStat, setSelectedStat] = useState<Stat | null>(null)
  const [isRolling, setIsRolling] = useState(false)

  const handleStatSelection = (stat: Stat) => {
    setSelectedStat(stat)
  }

  const handleDiceRoll = (result: any) => {
    setIsRolling(false)
    onStatRoll?.(selectedStat!, result)

    // Auto-close after a delay to allow viewing the result
    setTimeout(() => {
      if (!isRolling) {
        setSelectedStat(null)
      }
    }, 5000)
  }

  const handleBackToSelection = () => {
    setSelectedStat(null)
    setIsRolling(false)
  }

  if (selectedStat) {
    return (
      <div className={`space-y-4 ${className}`}>
        {/* Header with back button */}
        <div className="flex items-center justify-between">
          <Button
            variant="ghost"
            onClick={handleBackToSelection}
            disabled={isRolling}
          >
            ← Back to Stats
          </Button>
          <div className={`flex items-center gap-2 ${STAT_INFO[selectedStat].color}`}>
            {STAT_INFO[selectedStat].icon}
            <span className="font-medium">{STAT_INFO[selectedStat].fullName} Roll</span>
          </div>
        </div>

        {/* Dice Roller */}
        <ChronicleEnabledDiceRoller
          stat={selectedStat}
          modifier={statModifiers[selectedStat] || 0}
          characterName={characterName}
          onRoll={handleDiceRoll}
          disabled={disabled}
          showChronicleIntegration={true}
        />

        {/* Examples for the selected stat */}
        {showExamples && <StatExamples stat={selectedStat} />}
      </div>
    )
  }

  return (
    <div className={`space-y-6 ${className}`}>
      {/* Header */}
      <div className="text-center">
        <h3 className="text-xl font-display mb-2">Attribute Tests</h3>
        <p className="text-sm text-muted-foreground ">
          Choose an attribute to test
          {characterName && <span className="block text-primary mt-1">for {characterName}</span>}
        </p>
      </div>

      {/* Stat Grid */}
      <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
        {(Object.keys(STAT_INFO) as Stat[]).map(stat => (
          <StatButton
            key={stat}
            stat={stat}
            modifier={statModifiers[stat] || 0}
            onRoll={handleStatSelection}
            disabled={disabled}
          />
        ))}
      </div>

      {/* General help text */}
      <div className="text-center space-y-2">
        <p className="text-xs text-muted-foreground ">
          When you roll, you'll be prompted to chronicle why you needed to test that attribute
        </p>
        <div className="flex items-center justify-center gap-4 text-xs">
          <span className="text-chart-2">10+ Success</span>
          <span className="text-chart-4">7-9 Partial</span>
          <span className="text-destructive">6- Failure (XP)</span>
        </div>
      </div>
    </div>
  )
}

// Export individual stat roller for specific use cases
export const QuickStatRoll: React.FC<{
  stat: Stat
  modifier?: number
  characterName?: string
  onRoll?: (result: any) => void
  disabled?: boolean
}> = ({ stat, modifier = 0, characterName, onRoll, disabled }) => {
  return (
    <ChronicleEnabledDiceRoller
      stat={stat}
      modifier={modifier}
      characterName={characterName}
      onRoll={onRoll}
      disabled={disabled}
      showChronicleIntegration={true}
      className="max-w-md"
    />
  )
}

/**
 * XP Award Modal - Modal dialog for awarding experience points to characters
 */

import React, { useState, useEffect } from 'react'
import * as Dialog from '@radix-ui/react-dialog'
import { X, Trophy, Users, Plus, Star } from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle, Button, Badge } from '../ui'
import { Input } from '../ui/Input'
import { Textarea } from '../ui/Textarea'
import { useCharacterStore } from '../../stores/characterStore'
import type { Character } from '../../models/Character'

interface XPAwardModalProps {
  isOpen: boolean
  onClose: () => void
  onAwarded?: (totalXPAwarded: number, charactersAffected: number) => void
}

interface CharacterXPAward {
  character: Character
  xpAmount: number
  selected: boolean
  reason: string
}

const XP_PRESETS = [
  { label: 'Minor Achievement', amount: 1, description: 'Small progress or minor success' },
  { label: 'Significant Progress', amount: 2, description: 'Good roleplay or problem solving' },
  { label: 'Major Milestone', amount: 3, description: 'Completing major objectives' },
  { label: 'Session Completion', amount: 1, description: 'End of session bonus' }
]

export const XPAwardModal: React.FC<XPAwardModalProps> = ({
  isOpen,
  onClose,
  onAwarded
}) => {
  const characters = useCharacterStore(state => state.characters)
  const addXP = useCharacterStore(state => state.addXP)

  const [characterAwards, setCharacterAwards] = useState<CharacterXPAward[]>([])
  const [globalXP, setGlobalXP] = useState<number>(1)
  const [globalReason, setGlobalReason] = useState<string>('')
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [awardMode, setAwardMode] = useState<'global' | 'individual'>('global')

  // Initialize character awards when modal opens
  useEffect(() => {
    if (isOpen) {
      setCharacterAwards(
        characters.map(character => ({
          character,
          xpAmount: 1,
          selected: true,
          reason: ''
        }))
      )
      setGlobalXP(1)
      setGlobalReason('')
      setAwardMode('global')
    }
  }, [isOpen, characters])

  const handleGlobalXPChange = (amount: number) => {
    setGlobalXP(amount)
    setCharacterAwards(prev =>
      prev.map(award => ({
        ...award,
        xpAmount: amount
      }))
    )
  }

  const handleIndividualXPChange = (characterId: string, amount: number) => {
    setCharacterAwards(prev =>
      prev.map(award =>
        award.character.id === characterId
          ? { ...award, xpAmount: Math.max(0, Math.min(10, amount)) }
          : award
      )
    )
  }

  const handleToggleCharacter = (characterId: string) => {
    setCharacterAwards(prev =>
      prev.map(award =>
        award.character.id === characterId
          ? { ...award, selected: !award.selected }
          : award
      )
    )
  }

  const handleReasonChange = (characterId: string, reason: string) => {
    setCharacterAwards(prev =>
      prev.map(award =>
        award.character.id === characterId
          ? { ...award, reason }
          : award
      )
    )
  }

  const handlePresetXP = (amount: number, description: string) => {
    if (awardMode === 'global') {
      handleGlobalXPChange(amount)
      setGlobalReason(description)
    } else {
      setCharacterAwards(prev =>
        prev.map(award => ({
          ...award,
          xpAmount: amount,
          reason: description
        }))
      )
    }
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    const selectedAwards = characterAwards.filter(award => award.selected && award.xpAmount > 0)

    if (selectedAwards.length === 0) {
      return
    }

    setIsSubmitting(true)

    try {
      const totalXPAwarded = selectedAwards.reduce((sum, award) => sum + award.xpAmount, 0)

      // Award XP to each selected character
      for (const award of selectedAwards) {
        const reason = awardMode === 'global'
          ? globalReason || 'Session XP Award'
          : award.reason || 'Individual XP Award'

        addXP(
          award.character.id,
          award.xpAmount,
          'Session Award',
          reason
        )
      }

      onAwarded?.(totalXPAwarded, selectedAwards.length)
      onClose()
    } catch (error) {
      console.error('Error awarding XP:', error)
    } finally {
      setIsSubmitting(false)
    }
  }

  const selectedCharacters = characterAwards.filter(award => award.selected)
  const totalXPToAward = selectedCharacters.reduce((sum, award) => sum + award.xpAmount, 0)

  return (
    <Dialog.Root open={isOpen} onOpenChange={onClose}>
      <Dialog.Portal>
        <Dialog.Overlay className="fixed inset-0 z-50 bg-black/80 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0" />
        <Dialog.Content className="fixed left-1/2 top-1/2 z-50 w-full max-w-2xl -translate-x-1/2 -translate-y-1/2 border shadow-lg duration-200 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[state=closed]:slide-out-to-left-1/2 data-[state=closed]:slide-out-to-top-[48%] data-[state=open]:slide-in-from-left-1/2 data-[state=open]:slide-in-from-top-[48%] rounded-lg max-h-[90vh] overflow-y-auto">
          <Card variant="magical">
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-4">
              <div className="flex items-center gap-3">
                <Trophy className="h-5 w-5 text-primary" />
                <CardTitle className="text-xl">Award Experience Points</CardTitle>
              </div>
              <Dialog.Close asChild>
                <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
                  <X className="h-4 w-4" />
                </Button>
              </Dialog.Close>
            </CardHeader>

            <CardContent>
              <form onSubmit={handleSubmit} className="space-y-6">
                {/* Award Mode Toggle */}
                <div className="space-y-3">
                  <label className="text-sm font-medium">Award Method</label>
                  <div className="flex gap-2">
                    <Button
                      type="button"
                      variant={awardMode === 'global' ? 'primary' : 'ghost'}
                      size="sm"
                      onClick={() => setAwardMode('global')}
                    >
                      <Users size={16} />
                      Global Award
                    </Button>
                    <Button
                      type="button"
                      variant={awardMode === 'individual' ? 'primary' : 'ghost'}
                      size="sm"
                      onClick={() => setAwardMode('individual')}
                    >
                      <Star size={16} />
                      Individual Awards
                    </Button>
                  </div>
                </div>

                {/* XP Presets */}
                <div className="space-y-3">
                  <label className="text-sm font-medium">Quick Presets</label>
                  <div className="grid grid-cols-2 gap-2">
                    {XP_PRESETS.map(preset => (
                      <Button
                        key={preset.label}
                        type="button"
                        variant="outline"
                        size="sm"
                        className="justify-start h-auto p-3"
                        onClick={() => handlePresetXP(preset.amount, preset.description)}
                      >
                        <div className="text-left">
                          <div className="font-medium">{preset.label}</div>
                          <div className="text-xs text-muted-foreground">{preset.amount} XP - {preset.description}</div>
                        </div>
                      </Button>
                    ))}
                  </div>
                </div>

                {/* Global Settings */}
                {awardMode === 'global' && (
                  <div className="space-y-4">
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-2">
                        <label className="text-sm font-medium">XP Amount</label>
                        <Input
                          type="number"
                          value={globalXP}
                          onChange={(e) => handleGlobalXPChange(parseInt(e.target.value) || 0)}
                          min="0"
                          max="10"
                        />
                      </div>
                      <div className="space-y-2">
                        <label className="text-sm font-medium">Total XP</label>
                        <div className="px-3 py-2 bg-muted rounded-lg text-sm font-medium">
                          {totalXPToAward} XP to {selectedCharacters.length} character{selectedCharacters.length !== 1 ? 's' : ''}
                        </div>
                      </div>
                    </div>
                    <div className="space-y-2">
                      <label className="text-sm font-medium">Reason</label>
                      <Input
                        value={globalReason}
                        onChange={(e) => setGlobalReason(e.target.value)}
                        placeholder="Why are you awarding this XP?"
                      />
                    </div>
                  </div>
                )}

                {/* Character Selection */}
                <div className="space-y-3">
                  <label className="text-sm font-medium flex items-center gap-2">
                    <Users size={16} />
                    Characters ({selectedCharacters.length}/{characterAwards.length} selected)
                  </label>

                  {characterAwards.length === 0 ? (
                    <div className="text-center py-6 text-muted-foreground">
                      <Users size={32} className="mx-auto mb-2 opacity-50" />
                      <p>No characters found</p>
                      <p className="text-xs">Create characters first to award XP</p>
                    </div>
                  ) : (
                    <div className="space-y-3">
                      {characterAwards.map((award) => (
                        <Card key={award.character.id} variant="surface">
                          <CardContent className="p-4 pt-4">
                            <div className="flex items-center gap-4">
                              <input
                                type="checkbox"
                                checked={award.selected}
                                onChange={() => handleToggleCharacter(award.character.id)}
                                className="h-4 w-4"
                              />
                              <div className="flex-1">
                                <div className="font-medium">{award.character.name}</div>
                                <div className="text-sm text-muted-foreground">
                                  Level {award.character.level} • Current XP: {award.character.xp}
                                </div>
                              </div>

                              {awardMode === 'individual' && (
                                <div className="flex gap-2 items-center">
                                  <Input
                                    type="number"
                                    value={award.xpAmount}
                                    onChange={(e) => handleIndividualXPChange(award.character.id, parseInt(e.target.value) || 0)}
                                    min="0"
                                    max="10"
                                    className="w-20"
                                  />
                                  <span className="text-sm">XP</span>
                                </div>
                              )}

                              {awardMode === 'global' && (
                                <div className="text-sm font-medium">
                                  +{award.xpAmount} XP
                                </div>
                              )}
                            </div>

                            {awardMode === 'individual' && award.selected && (
                              <div className="mt-3">
                                <Input
                                  value={award.reason}
                                  onChange={(e) => handleReasonChange(award.character.id, e.target.value)}
                                  placeholder="Reason for this character's XP..."
                                  className="text-sm"
                                />
                              </div>
                            )}
                          </CardContent>
                        </Card>
                      ))}
                    </div>
                  )}
                </div>

                {/* Actions */}
                <div className="flex items-center justify-between pt-4">
                  <div className="text-sm text-muted-foreground">
                    {selectedCharacters.length > 0 ? (
                      <>
                        Awarding <span className="font-medium">{totalXPToAward} total XP</span> to{' '}
                        <span className="font-medium">{selectedCharacters.length}</span> character
                        {selectedCharacters.length !== 1 ? 's' : ''}
                      </>
                    ) : (
                      'Select characters to award XP'
                    )}
                  </div>
                  <div className="flex gap-3">
                    <Button
                      type="button"
                      variant="ghost"
                      onClick={onClose}
                      disabled={isSubmitting}
                    >
                      Cancel
                    </Button>
                    <Button
                      type="submit"
                      variant="primary"
                      disabled={isSubmitting || selectedCharacters.length === 0 || totalXPToAward === 0}
                      className="min-w-20"
                    >
                      {isSubmitting ? 'Awarding...' : 'Award XP'}
                    </Button>
                  </div>
                </div>
              </form>
            </CardContent>
          </Card>
        </Dialog.Content>
      </Dialog.Portal>
