                        <Icon size={20} style={{ color }} />
                      </div>
                      <div>
                        <h3 className="text-lg font-display text-foreground">
                          {category.name}
                        </h3>
                        <p className="text-sm text-muted-foreground">
                          {category.shortcuts.length} shortcuts
