                    </div>

                    {/* Shortcuts Grid */}
                    <div className="grid gap-3">
                      {category.shortcuts.map((shortcut, index) => (
                        <motion.div
                          key={shortcut.id}
                          className="flex items-center justify-between p-3 rounded-lg border border-border/60 bg-card/90 backdrop-blur-sm"
                          initial={{ opacity: 0, x: -20 }}
                          animate={{ opacity: 1, x: 0 }}
                          transition={{ duration: 0.2, delay: index * 0.05 }}
                        >
                          <div className="flex-1">
                            <h4 
                              className="font-medium mb-1 text-foreground">
                              {shortcut.description}
                            </h4>
                            {shortcut.context && (
                              <p 
                                className="text-xs text-muted-foreground">
                                Available in: {shortcut.context.join(', ')}
                              </p>
                            )}
                          </div>
                          
                          <div className="flex items-center gap-2">
                            {!shortcut.enabled && (
                              <Badge variant="secondary" size="sm">
                                Disabled
                              </Badge>
                            )}
                            <kbd 
                              className="px-3 py-1 rounded border font-mono text-sm"
                              style={{ 
                                borderColor: 'var(--primary)',
                                borderOpacity: 0.3,
                                backgroundColor: 'var(--card)',
                                color: 'var(--foreground)'
                              }}
                            >
                              {keyboardShortcutsService.formatShortcut(shortcut)}
                            </kbd>
                          </div>
                        </motion.div>
                      ))}
                    </div>
                  </CardContent>
                </Card>
              </motion.div>
            )
          })
        )}
      </div>

      {/* Tips */}
      <Card variant="surface">
        <CardContent className="p-4">
          <div className="space-y-3">
            <h4 className="font-medium flex items-center gap-2 text-foreground">
              <Zap className="text-accent" size={16} />
              Pro Tips
            </h4>
            <div className="space-y-2 text-sm text-muted-foreground">
              <p>• Press <kbd className="px-2 py-1 rounded border text-xs border-primary/30">Ctrl+K</kbd> anytime to open the command palette</p>
              <p>• Number keys (1-6) work as stat modifiers when in the dice tab</p>
              <p>• <kbd className="px-2 py-1 rounded border text-xs border-primary/30">Space</kbd> is your quick roll button - works in most contexts</p>
              <p>• Tab navigation (Ctrl+1-6) works from anywhere in the app</p>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  )
