export default ThemeComponentShowcase

import React, { createContext, useContext } from 'react'
import { useThemeStore } from '../../stores/themeStore'

interface ThemeContextType {
  readonly theme: 'matsu'
  animations: boolean
  sounds: boolean
  toggleAnimations: () => void
  toggleSounds: () => void
}

const ThemeContext = createContext<ThemeContextType | undefined>(undefined)

export function useTheme() {
  const context = useContext(ThemeContext)
  if (context === undefined) {
    throw new Error('useTheme must be used within a ThemeProvider')
  }
  return context
}

interface ThemeProviderProps {
  children: React.ReactNode
  defaultTheme?: 'matsu'
}

export function ThemeProvider({ children }: ThemeProviderProps) {
  const {
    theme,
    animations,
    sounds,
    toggleAnimations,
    toggleSounds
  } = useThemeStore()

  const value = {
    theme,
    animations,
    sounds,
    toggleAnimations,
    toggleSounds,
  }

  return (
    <ThemeContext.Provider value={value}>
      {children}
    </ThemeContext.Provider>
  )
}

/**
 * XP Notification Component
 * Shows animated notifications when XP is awarded for failed rolls
 */

import React from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { Star, TrendingUp } from 'lucide-react'
import { useXPStore } from '../../stores/xpStore'

interface XPNotificationProps {
  characterId: string
  className?: string
}

export const XPNotification: React.FC<XPNotificationProps> = ({
  characterId,
  className = ''
}) => {
  const { characterXP, characterLevel, showXPNotifications } = useXPStore()

  if (!showXPNotifications) return null

  const currentXP = characterXP[characterId] || 0
  const currentLevel = characterLevel[characterId] || 1

  return (
    <div className={`fixed top-4 right-4 z-50 ${className}`}>
      <AnimatePresence>
        {/* This would be triggered by XP events - simplified for now */}
        <motion.div
          initial={{ opacity: 0, scale: 0.8, x: 100 }}
          animate={{ opacity: 1, scale: 1, x: 0 }}
          exit={{ opacity: 0, scale: 0.8, x: 100 }}
          className="bg-gradient-to-r from-chart-4 to-primary text-primary-foreground px-4 py-3 rounded-lg shadow-lg flex items-center gap-3 min-w-[200px]"
        >
          <motion.div
            animate={{ rotate: 360 }}
            transition={{ duration: 2, repeat: Infinity, ease: "linear" }}
          >
            <Star size={20} className="text-chart-4" />
          </motion.div>

          <div className="flex-1">
            <div className="font-semibold text-sm">XP Gained!</div>
            <div className="text-xs text-chart-4">
              Failed roll grants experience
            </div>
          </div>

          <div className="text-right">
            <div className="text-lg font-bold">+1</div>
            <div className="text-xs text-chart-4">
              Level {currentLevel}
            </div>
          </div>
        </motion.div>
      </AnimatePresence>
    </div>
  )
}

// XP Progress Bar Component
export const XPProgressBar: React.FC<{
  characterId: string
  className?: string
  compact?: boolean
}> = ({ characterId, className = '', compact = false }) => {
  const { characterXP, characterLevel, getXPForNextLevel, calculateLevelFromXP } = useXPStore()

  const totalXP = characterXP[characterId] || 0
  const currentLevel = characterLevel[characterId] || 1
  const xpForNextLevel = getXPForNextLevel(characterId)

  // Calculate current level progress
  let xpInCurrentLevel = totalXP
  for (let level = 1; level < currentLevel; level++) {
    xpInCurrentLevel -= (7 + (level - 1))
  }

  const progressPercentage = Math.min((xpInCurrentLevel / xpForNextLevel) * 100, 100)

  if (compact) {
    return (
      <div className={`flex items-center gap-2 ${className}`}>
        <Star size={14} className="text-chart-4" />
        <div className="text-sm font-medium">
          Level {currentLevel}
        </div>
        <div className="flex-1 bg-muted rounded-full h-2 min-w-[60px]">
          <div
            className="bg-gradient-to-r from-chart-4 to-chart-4 h-2 rounded-full transition-all duration-300"
            style={{ width: `${progressPercentage}%` }}
          />
        </div>
        <div className="text-xs text-muted-foreground">
          {xpInCurrentLevel}/{xpForNextLevel}
        </div>
      </div>
    )
  }

  return (
    <div className={`p-4 bg-card rounded-lg shadow-sm border border-border ${className}`}>
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center gap-2">
          <TrendingUp size={16} className="text-primary" />
          <span className="font-semibold text-sm">Experience</span>
        </div>
        <div className="text-sm text-muted-foreground">
          Level {currentLevel}
        </div>
      </div>

      <div className="mb-2">
        <div className="flex justify-between text-xs text-muted-foreground mb-1">
          <span>{xpInCurrentLevel} / {xpForNextLevel} XP</span>
          <span>{Math.round(progressPercentage)}%</span>
        </div>
        <div className="w-full bg-muted rounded-full h-3">
          <motion.div
            className="bg-gradient-to-r from-chart-4 to-chart-4 h-3 rounded-full"
            initial={{ width: 0 }}
            animate={{ width: `${progressPercentage}%` }}
            transition={{ duration: 0.5, ease: "easeOut" }}
          />
        </div>
      </div>

      <div className="text-xs text-muted-foreground">
        Total XP: {totalXP} - Next level needs {xpForNextLevel} XP
      </div>
    </div>
  )
}

import * as React from "react"
import * as LabelPrimitive from "@radix-ui/react-label"
import { Slot } from "@radix-ui/react-slot"
import {
  Controller,
  FormProvider,
  useFormContext,
  useFormState,
  type ControllerProps,
  type FieldPath,
  type FieldValues,
} from "react-hook-form"

import { cn } from "src/lib/utils"
import { Label } from "src/components/ui/label"

const Form = FormProvider

type FormFieldContextValue<
  TFieldValues extends FieldValues = FieldValues,
  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
> = {
  name: TName
}

const FormFieldContext = React.createContext<FormFieldContextValue>(
  {} as FormFieldContextValue
)

const FormField = <
  TFieldValues extends FieldValues = FieldValues,
  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
>({
  ...props
}: ControllerProps<TFieldValues, TName>) => {
  return (
    <FormFieldContext.Provider value={{ name: props.name }}>
      <Controller {...props} />
    </FormFieldContext.Provider>
  )
}

const useFormField = () => {
  const fieldContext = React.useContext(FormFieldContext)
  const itemContext = React.useContext(FormItemContext)
  const { getFieldState } = useFormContext()
  const formState = useFormState({ name: fieldContext.name })
  const fieldState = getFieldState(fieldContext.name, formState)

  if (!fieldContext) {
    throw new Error("useFormField should be used within <FormField>")
  }

  const { id } = itemContext

  return {
    id,
    name: fieldContext.name,
    formItemId: `${id}-form-item`,
    formDescriptionId: `${id}-form-item-description`,
    formMessageId: `${id}-form-item-message`,
    ...fieldState,
  }
}

type FormItemContextValue = {
  id: string
}

const FormItemContext = React.createContext<FormItemContextValue>(
  {} as FormItemContextValue
)

function FormItem({ className, ...props }: React.ComponentProps<"div">) {
  const id = React.useId()

  return (
    <FormItemContext.Provider value={{ id }}>
      <div
        data-slot="form-item"
        className={cn("grid gap-2", className)}
        {...props}
      />
    </FormItemContext.Provider>
  )
}

function FormLabel({
  className,
  ...props
}: React.ComponentProps<typeof LabelPrimitive.Root>) {
  const { error, formItemId } = useFormField()

  return (
    <Label
      data-slot="form-label"
      data-error={!!error}
      className={cn("data-[error=true]:text-destructive", className)}
      htmlFor={formItemId}
      {...props}
    />
  )
}

function FormControl({ ...props }: React.ComponentProps<typeof Slot>) {
  const { error, formItemId, formDescriptionId, formMessageId } = useFormField()

  return (
    <Slot
      data-slot="form-control"
      id={formItemId}
      aria-describedby={
        !error
          ? `${formDescriptionId}`
          : `${formDescriptionId} ${formMessageId}`
      }
      aria-invalid={!!error}
      {...props}
    />
  )
}

function FormDescription({ className, ...props }: React.ComponentProps<"p">) {
  const { formDescriptionId } = useFormField()

  return (
    <p
      data-slot="form-description"
      id={formDescriptionId}
      className={cn("text-muted-foreground text-sm", className)}
      {...props}
    />
  )
}

function FormMessage({ className, ...props }: React.ComponentProps<"p">) {
  const { error, formMessageId } = useFormField()
  const body = error ? String(error?.message ?? "") : props.children

  if (!body) {
    return null
  }

  return (
    <p
      data-slot="form-message"
      id={formMessageId}
      className={cn("text-destructive text-sm", className)}
      {...props}
    >
      {body}
    </p>
  )
}

export {
  useFormField,
  Form,
  FormItem,
  FormLabel,
  FormControl,
  FormDescription,
  FormMessage,
  FormField,
}

