/**
 * useAnimations Hook for ZimboMate V2
 * Animation control and preferences with magical particle effects
 * Provides staggered animations, particle systems, and performance optimization
 */

import { useCallback, useState, useEffect, useRef } from 'react'

export interface AnimationPreferences {
  reduceMotion: boolean
  particleEffects: boolean
  staggeredAnimations: boolean
  glowEffects: boolean
  transitionSpeed: 'slow' | 'normal' | 'fast'
}

export interface ParticleConfig {
  count: number
  colors: string[]
  size: { min: number; max: number }
  speed: { min: number; max: number }
  lifetime: number
  gravity: number
  spread: number
}

export interface StaggerConfig {
  delay: number
  duration: number
  easing: string
  direction: 'up' | 'down' | 'left' | 'right' | 'center'
}

export interface UseAnimationsReturn {
  // Animation preferences
  preferences: AnimationPreferences
  updatePreferences: (updates: Partial<AnimationPreferences>) => void
  
  // Particle effects
  triggerParticles: (
    element: HTMLElement | null,
    type: 'success' | 'failure' | 'damage' | 'healing' | 'magic' | 'custom',
    config?: Partial<ParticleConfig>
  ) => void
  createParticleSystem: (
    container: HTMLElement,
    config: ParticleConfig
  ) => () => void // Returns cleanup function
  
  // Staggered animations
  useStaggeredAnimation: (
    elements: HTMLElement[],
    config?: Partial<StaggerConfig>
  ) => void
  createStaggeredEntrance: (
    selector: string,
    config?: Partial<StaggerConfig>
  ) => void
  
  // Magical effects
  addMagicalGlow: (element: HTMLElement | null, color?: string, intensity?: number) => void
  removeMagicalGlow: (element: HTMLElement | null) => void
  pulseElement: (element: HTMLElement | null, duration?: number) => void
  shimmerEffect: (element: HTMLElement | null, duration?: number) => void
  
  // Animation utilities
  getAnimationDuration: (baseMs: number) => number
  shouldAnimate: (animationType: 'particle' | 'stagger' | 'glow' | 'transition') => boolean
  createSpringConfig: (type: 'gentle' | 'wobbly' | 'stiff' | 'slow') => any
  
  // Performance
  isHighPerformance: boolean
  togglePerformanceMode: () => void
  
  // Theme integration
  getThemeColors: () => {
    primary: string
    secondary: string
    accent: string
    success: string
    warning: string
    error: string
  }
}

/**
 * Hook for managing animations and visual effects
 */
export function useAnimations(): UseAnimationsReturn {
  const [preferences, setPreferences] = useState<AnimationPreferences>(() => {
    // Check for user's motion preferences
    const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches
    
    return {
      reduceMotion: prefersReducedMotion,
      particleEffects: !prefersReducedMotion,
      staggeredAnimations: !prefersReducedMotion,
      glowEffects: true,
      transitionSpeed: 'normal',
    }
  })

  const [isHighPerformance, setIsHighPerformance] = useState(true)
  const particleSystemsRef = useRef<Map<string, () => void>>(new Map())

  // Monitor performance
  useEffect(() => {
    const checkPerformance = () => {
      // Simple performance check based on frame rate
      const start = performance.now()
      requestAnimationFrame(() => {
        const delta = performance.now() - start
        setIsHighPerformance(delta < 16.67) // 60fps threshold
      })
    }

    const interval = setInterval(checkPerformance, 5000)
    return () => clearInterval(interval)
  }, [])

  // Update preferences
  const updatePreferences = useCallback((updates: Partial<AnimationPreferences>) => {
    setPreferences(prev => ({ ...prev, ...updates }))
  }, [])

  // Get theme colors
  const getThemeColors = useCallback(() => {
    return {
      primary: 'var(--matsu-primary, var(--primary))',
      secondary: 'var(--matsu-secondary, var(--secondary))',
      accent: 'var(--matsu-accent, var(--accent))',
      success: 'var(--chart-2)',
      warning: 'var(--chart-4)',
      error: 'var(--destructive)',
    }
  }, [])

  // Particle effects
  const triggerParticles = useCallback((
    element: HTMLElement | null,
    type: 'success' | 'failure' | 'damage' | 'healing' | 'magic' | 'custom',
    config: Partial<ParticleConfig> = {}
  ) => {
    if (!element || !preferences.particleEffects || preferences.reduceMotion) return

    const themeColors = getThemeColors()
    const defaultConfigs: Record<string, ParticleConfig> = {
      success: {
        count: 20,
        colors: [themeColors.success, '#10B981', '#34D399'],
        size: { min: 2, max: 6 },
        speed: { min: 50, max: 150 },
        lifetime: 1000,
        gravity: 0.5,
        spread: 45,
      },
      failure: {
        count: 15,
        colors: [themeColors.error, '#EF4444', '#F87171'],
        size: { min: 1, max: 4 },
        speed: { min: 30, max: 100 },
        lifetime: 800,
        gravity: 0.8,
        spread: 30,
      },
      damage: {
        count: 25,
        colors: ['#DC2626', '#B91C1C', '#991B1B'],
        size: { min: 3, max: 8 },
        speed: { min: 100, max: 200 },
        lifetime: 600,
        gravity: 1.2,
        spread: 60,
      },
      healing: {
        count: 30,
        colors: ['#10B981', '#34D399', '#6EE7B7'],
        size: { min: 2, max: 5 },
        speed: { min: 20, max: 80 },
        lifetime: 1500,
        gravity: -0.3, // Float upward
        spread: 90,
      },
      magic: {
        count: 40,
        colors: [themeColors.primary, themeColors.accent, '#8B5CF6', '#A78BFA'],
        size: { min: 1, max: 7 },
        speed: { min: 40, max: 120 },
        lifetime: 2000,
        gravity: 0.1,
        spread: 120,
      },
      custom: {
        count: 20,
        colors: [themeColors.primary],
        size: { min: 2, max: 5 },
        speed: { min: 50, max: 100 },
        lifetime: 1000,
        gravity: 0.5,
        spread: 45,
      },
    }

    const finalConfig = { ...defaultConfigs[type], ...config }
    
    // Create particle system
    const rect = element.getBoundingClientRect()
    const container = document.createElement('div')
    container.style.position = 'fixed'
    container.style.top = '0'
    container.style.left = '0'
    container.style.width = '100vw'
    container.style.height = '100vh'
    container.style.pointerEvents = 'none'
    container.style.zIndex = '9999'
    
    document.body.appendChild(container)

    // Generate particles
    for (let i = 0; i < finalConfig.count; i++) {
      const particle = document.createElement('div')
      const size = Math.random() * (finalConfig.size.max - finalConfig.size.min) + finalConfig.size.min
      const color = finalConfig.colors[Math.floor(Math.random() * finalConfig.colors.length)]
      const angle = (Math.random() - 0.5) * finalConfig.spread * (Math.PI / 180)
      const speed = Math.random() * (finalConfig.speed.max - finalConfig.speed.min) + finalConfig.speed.min
      
      particle.style.position = 'absolute'
      particle.style.width = `${size}px`
      particle.style.height = `${size}px`
      particle.style.backgroundColor = color
      particle.style.borderRadius = '50%'
      particle.style.left = `${rect.left + rect.width / 2}px`
      particle.style.top = `${rect.top + rect.height / 2}px`
      particle.style.boxShadow = `0 0 ${size * 2}px ${color}`
      
      container.appendChild(particle)

      // Animate particle
      const startTime = performance.now()
      const animate = (currentTime: number) => {
        const elapsed = currentTime - startTime
        const progress = elapsed / finalConfig.lifetime

        if (progress >= 1) {
          particle.remove()
          return
        }

        const x = Math.cos(angle) * speed * (elapsed / 1000)
        const y = Math.sin(angle) * speed * (elapsed / 1000) + finalConfig.gravity * Math.pow(elapsed / 1000, 2) * 100
        const opacity = 1 - progress

        particle.style.transform = `translate(${x}px, ${y}px)`
        particle.style.opacity = opacity.toString()

        requestAnimationFrame(animate)
      }

      requestAnimationFrame(animate)
    }

    // Cleanup container after all particles are done
    setTimeout(() => {
      if (container.parentNode) {
        container.remove()
      }
    }, finalConfig.lifetime + 100)
  }, [preferences, getThemeColors])

  // Create persistent particle system
  const createParticleSystem = useCallback((
    container: HTMLElement,
    config: ParticleConfig
  ) => {
    if (!preferences.particleEffects || preferences.reduceMotion) {
      return () => {} // Return empty cleanup function
    }

    const systemId = Math.random().toString(36).slice(2, 11)
    let isActive = true

    const generateParticle = () => {
      if (!isActive) return

      const particle = document.createElement('div')
      const size = Math.random() * (config.size.max - config.size.min) + config.size.min
      const color = config.colors[Math.floor(Math.random() * config.colors.length)]
      
      particle.style.position = 'absolute'
      particle.style.width = `${size}px`
      particle.style.height = `${size}px`
      particle.style.backgroundColor = color
      particle.style.borderRadius = '50%'
      particle.style.pointerEvents = 'none'
      
      container.appendChild(particle)

      // Animate and remove particle
      setTimeout(() => {
        if (particle.parentNode) {
          particle.remove()
        }
      }, config.lifetime)

      // Schedule next particle
      if (isActive) {
        setTimeout(generateParticle, Math.random() * 200 + 100)
      }
    }

    // Start generating particles
    generateParticle()

    // Return cleanup function
    const cleanup = () => {
      isActive = false
      particleSystemsRef.current.delete(systemId)
    }

    particleSystemsRef.current.set(systemId, cleanup)
    return cleanup
  }, [preferences])

  // Staggered animations
  const useStaggeredAnimation = useCallback((
    elements: HTMLElement[],
    config: Partial<StaggerConfig> = {}
  ) => {
    if (!preferences.staggeredAnimations || preferences.reduceMotion) return

    const defaultConfig: StaggerConfig = {
      delay: 100,
      duration: 300,
      easing: 'cubic-bezier(0.4, 0, 0.2, 1)',
      direction: 'up',
    }

    const finalConfig = { ...defaultConfig, ...config }

    elements.forEach((element, index) => {
      if (!element) return

      const delay = index * finalConfig.delay
      
      // Set initial state
      element.style.opacity = '0'
      element.style.transform = getInitialTransform(finalConfig.direction)
      element.style.transition = `opacity ${finalConfig.duration}ms ${finalConfig.easing} ${delay}ms, transform ${finalConfig.duration}ms ${finalConfig.easing} ${delay}ms`

      // Trigger animation
      requestAnimationFrame(() => {
        element.style.opacity = '1'
        element.style.transform = 'translate(0, 0) scale(1)'
      })
    })
  }, [preferences])

  const createStaggeredEntrance = useCallback((
    selector: string,
    config: Partial<StaggerConfig> = {}
  ) => {
    const elements = Array.from(document.querySelectorAll(selector)) as HTMLElement[]
    useStaggeredAnimation(elements, config)
  }, [useStaggeredAnimation])

  // Magical effects
  const addMagicalGlow = useCallback((
    element: HTMLElement | null,
    color = 'var(--primary)',
    intensity = 1
  ) => {
    if (!element || !preferences.glowEffects) return

    const glowSize = 10 * intensity
    element.style.boxShadow = `0 0 ${glowSize}px ${color}, 0 0 ${glowSize * 2}px ${color}`
    element.style.transition = 'box-shadow 0.3s ease'
  }, [preferences])

  const removeMagicalGlow = useCallback((element: HTMLElement | null) => {
    if (!element) return
    element.style.boxShadow = ''
  }, [])

  const pulseElement = useCallback((element: HTMLElement | null, duration = 1000) => {
    if (!element || preferences.reduceMotion) return

    element.style.animation = `pulse ${duration}ms ease-in-out`
    
    // Remove animation after completion
    setTimeout(() => {
      element.style.animation = ''
    }, duration)
  }, [preferences])

  const shimmerEffect = useCallback((element: HTMLElement | null, duration = 2000) => {
    if (!element || preferences.reduceMotion) return

    element.style.animation = `shimmer ${duration}ms ease-in-out infinite`
    
    // Remove animation after specified duration
    setTimeout(() => {
      element.style.animation = ''
    }, duration)
  }, [preferences])

  // Animation utilities
  const getAnimationDuration = useCallback((baseMs: number) => {
    if (preferences.reduceMotion) return 0
    
    const speedMultipliers = {
      slow: 1.5,
      normal: 1,
      fast: 0.7,
    }
    
    return baseMs * speedMultipliers[preferences.transitionSpeed]
  }, [preferences])

  const shouldAnimate = useCallback((animationType: 'particle' | 'stagger' | 'glow' | 'transition') => {
    if (preferences.reduceMotion) return false
    if (!isHighPerformance && (animationType === 'particle' || animationType === 'stagger')) return false
    
    switch (animationType) {
      case 'particle': return preferences.particleEffects
      case 'stagger': return preferences.staggeredAnimations
      case 'glow': return preferences.glowEffects
      case 'transition': return true
      default: return true
    }
  }, [preferences, isHighPerformance])

  const createSpringConfig = useCallback((type: 'gentle' | 'wobbly' | 'stiff' | 'slow') => {
    const configs = {
      gentle: { tension: 120, friction: 14 },
      wobbly: { tension: 180, friction: 12 },
      stiff: { tension: 210, friction: 20 },
      slow: { tension: 280, friction: 60 },
    }
    
    return configs[type]
  }, [])

  const togglePerformanceMode = useCallback(() => {
    setIsHighPerformance(prev => !prev)
  }, [])

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      // Cleanup all particle systems
      particleSystemsRef.current.forEach(cleanup => cleanup())
      particleSystemsRef.current.clear()
    }
  }, [])

  return {
    // Animation preferences
    preferences,
    updatePreferences,
    
    // Particle effects
    triggerParticles,
    createParticleSystem,
    
    // Staggered animations
    useStaggeredAnimation,
    createStaggeredEntrance,
    
    // Magical effects
    addMagicalGlow,
    removeMagicalGlow,
    pulseElement,
    shimmerEffect,
    
    // Animation utilities
    getAnimationDuration,
    shouldAnimate,
    createSpringConfig,
    
    // Performance
    isHighPerformance,
    togglePerformanceMode,
    
    // Theme integration
    getThemeColors,
  }
}

// Helper function for initial transform based on direction
function getInitialTransform(direction: StaggerConfig['direction']): string {
  switch (direction) {
    case 'up': return 'translateY(20px) scale(0.95)'
    case 'down': return 'translateY(-20px) scale(0.95)'
    case 'left': return 'translateX(20px) scale(0.95)'
    case 'right': return 'translateX(-20px) scale(0.95)'
    case 'center': return 'scale(0.8)'
    default: return 'translateY(20px) scale(0.95)'
  }
}

/**
 * useCampaign Hook for ZimboMate V2
 * Campaign operations, world management, and multi-character coordination
 * Integrates campaignStore with character and session management
 */

import { useCallback, useMemo } from 'react'
import { useCampaignStore } from '../stores/campaignStore'
import { useCharacterStore } from '../stores/characterStore'
import { campaignService } from '../services/CampaignService'
import type { Campaign, CampaignSession, JournalEntry, NPC, Location } from '../models/Campaign'

export interface CampaignCharacter {
  id: string
  name: string
  class: string
  level: number
  player: string
  isActive: boolean
  lastPlayed: Date
}

export interface CampaignStats {
  totalSessions: number
  totalPlayTime: number
  averageSessionLength: number
  totalXPAwarded: number
  charactersCreated: number
  locationsVisited: number
  npcsEncountered: number
}

export interface UseCampaignReturn {
  // Current campaign
  currentCampaign: Campaign | null
  isActiveCampaign: boolean

  // Campaign management
  createCampaign: (campaignData: Omit<Campaign, 'id' | 'createdAt' | 'updatedAt'>) => Campaign
  updateCampaign: (updates: Partial<Campaign>) => void
  deleteCampaign: (campaignId: string) => void
  setActiveCampaign: (campaignId: string | null) => void

  // Campaign list
  allCampaigns: Campaign[]
  recentCampaigns: Campaign[]

  // Character management
  campaignCharacters: CampaignCharacter[]
  addCharacterToCampaign: (characterId: string) => void
  removeCharacterFromCampaign: (characterId: string) => void
  getCharacterCampaigns: (characterId: string) => Campaign[]

  // Session management
  campaignSessions: CampaignSession[]
  startCampaignSession: (name: string, characterIds: string[]) => void
  endCampaignSession: () => void
  getSessionHistory: () => CampaignSession[]

  // World management
  locations: Location[]
  npcs: NPC[]
  addLocation: (location: Omit<Location, 'id'>) => void
  updateLocation: (locationId: string, updates: Partial<Location>) => void
  addNPC: (npc: Omit<NPC, 'id'>) => void
  updateNPC: (npcId: string, updates: Partial<NPC>) => void

  // Journal management
  journalEntries: JournalEntry[]
  addJournalEntry: (entry: Omit<JournalEntry, 'id' | 'createdAt'>) => void
  updateJournalEntry: (entryId: string, updates: Partial<JournalEntry>) => void
  deleteJournalEntry: (entryId: string) => void
  searchJournal: (query: string) => JournalEntry[]

  // Campaign statistics
  campaignStats: CampaignStats

  // Import/Export
  exportCampaign: () => string
  importCampaign: (campaignData: string) => Campaign

  // Utility
  isLoading: boolean
  error: string | null
  clearError: () => void
}

/**
 * Hook for managing campaigns and world state
 */
export function useCampaign(): UseCampaignReturn {
  const {
    campaigns,
    activeCampaignId,
    isLoading,
    error,
    createCampaign: storeCreateCampaign,
    updateCampaign: storeUpdateCampaign,
    deleteCampaign: storeDeleteCampaign,
    setActiveCampaign: storeSetActiveCampaign,
    addCharacterToCampaign: storeAddCharacterToCampaign,
    removeCharacterFromCampaign: storeRemoveCharacterFromCampaign,
    addLocation: storeAddLocation,
    updateLocation: storeUpdateLocation,
    addNPC: storeAddNPC,
    updateNPC: storeUpdateNPC,
    addJournalEntry: storeAddJournalEntry,
    updateJournalEntry: storeUpdateJournalEntry,
    deleteJournalEntry: storeDeleteJournalEntry,
    clearError: storeClearError,
  } = useCampaignStore()

  const { characters, getCharacter } = useCharacterStore()

  // Current campaign
  const currentCampaign = useMemo(() => {
    if (!activeCampaignId) return null
    return campaigns.find(c => c.id === activeCampaignId) || null
  }, [campaigns, activeCampaignId])

  const isActiveCampaign = useMemo(() => currentCampaign !== null, [currentCampaign])

  // Campaign lists
  const allCampaigns = useMemo(() => campaigns, [campaigns])

  const recentCampaigns = useMemo(() => {
    return campaigns
      .sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime())
      .slice(0, 5)
  }, [campaigns])

  // Character management
  const campaignCharacters = useMemo((): CampaignCharacter[] => {
    if (!currentCampaign) return []

    return currentCampaign.characterIds.map(characterId => {
      const character = getCharacter(characterId)
      if (!character) {
        return {
          id: characterId,
          name: 'Unknown Character',
          class: 'Unknown',
          level: 1,
          player: 'Unknown',
          isActive: false,
          lastPlayed: new Date(),
        }
      }

      return {
        id: character.id,
        name: character.name,
        class: character.class,
        level: character.level,
        player: character.player || 'Unknown',
        isActive: true,
        lastPlayed: character.updatedAt,
      }
    })
  }, [currentCampaign, getCharacter])

  // World data
  const locations = useMemo(() => currentCampaign?.locations || [], [currentCampaign])
  const npcs = useMemo(() => currentCampaign?.npcs || [], [currentCampaign])
  const journalEntries = useMemo(() => currentCampaign?.journalEntries || [], [currentCampaign])
  const campaignSessions = useMemo(() => currentCampaign?.sessions || [], [currentCampaign])

  // Campaign statistics
  const campaignStats = useMemo((): CampaignStats => {
    if (!currentCampaign) {
      return {
        totalSessions: 0,
        totalPlayTime: 0,
        averageSessionLength: 0,
        totalXPAwarded: 0,
        charactersCreated: 0,
        locationsVisited: 0,
        npcsEncountered: 0,
      }
    }

    const sessions = currentCampaign.sessions
    const totalSessions = sessions.length
    const totalPlayTime = sessions.reduce((total, session) => {
      if (session.endTime) {
        return total + (new Date(session.endTime).getTime() - new Date(session.startTime).getTime())
      }
      return total
    }, 0)
    const averageSessionLength = totalSessions > 0 ? totalPlayTime / totalSessions : 0
    const totalXPAwarded = sessions.reduce((total, session) => total + (session.xpAwarded || 0), 0)

    return {
      totalSessions,
      totalPlayTime,
      averageSessionLength,
      totalXPAwarded,
      charactersCreated: currentCampaign.characterIds.length,
      locationsVisited: currentCampaign.locations.length,
      npcsEncountered: currentCampaign.npcs.length,
    }
  }, [currentCampaign])

  // Campaign management
  const createCampaign = useCallback((campaignData: Omit<Campaign, 'id' | 'createdAt' | 'updatedAt'>) => {
    return storeCreateCampaign(campaignData)
  }, [storeCreateCampaign])

  const updateCampaign = useCallback((updates: Partial<Campaign>) => {
    if (!currentCampaign) return
    storeUpdateCampaign(currentCampaign.id, updates)
  }, [currentCampaign, storeUpdateCampaign])

  const deleteCampaign = useCallback((campaignId: string) => {
    storeDeleteCampaign(campaignId)
  }, [storeDeleteCampaign])

  const setActiveCampaign = useCallback((campaignId: string | null) => {
    storeSetActiveCampaign(campaignId)
  }, [storeSetActiveCampaign])

  // Character management
  const addCharacterToCampaign = useCallback((characterId: string) => {
    if (!currentCampaign) return
    storeAddCharacterToCampaign(currentCampaign.id, characterId)
  }, [currentCampaign, storeAddCharacterToCampaign])

  const removeCharacterFromCampaign = useCallback((characterId: string) => {
    if (!currentCampaign) return
    storeRemoveCharacterFromCampaign(currentCampaign.id, characterId)
  }, [currentCampaign, storeRemoveCharacterFromCampaign])

  const getCharacterCampaigns = useCallback((characterId: string) => {
    return campaigns.filter(campaign => campaign.characterIds.includes(characterId))
  }, [campaigns])

  // Session management
  const startCampaignSession = useCallback((name: string, characterIds: string[]) => {
    if (!currentCampaign) return

    const session: CampaignSession = {
      id: `session-${Date.now()}`,
      name,
      startTime: new Date(),
      characterIds,
      notes: '',
      xpAwarded: 0,
    }

    const updatedSessions = [...currentCampaign.sessions, session]
    updateCampaign({ sessions: updatedSessions })
  }, [currentCampaign, updateCampaign])

  const endCampaignSession = useCallback(() => {
    if (!currentCampaign || currentCampaign.sessions.length === 0) return

    const lastSession = currentCampaign.sessions[currentCampaign.sessions.length - 1]
    if (lastSession.endTime) return // Already ended

    const updatedSession = {
      ...lastSession,
      endTime: new Date(),
    }

    const updatedSessions = [
      ...currentCampaign.sessions.slice(0, -1),
      updatedSession,
    ]

    updateCampaign({ sessions: updatedSessions })
  }, [currentCampaign, updateCampaign])

  const getSessionHistory = useCallback(() => {
    return campaignSessions.sort((a, b) => 
      new Date(b.startTime).getTime() - new Date(a.startTime).getTime()
    )
  }, [campaignSessions])

  // World management
  const addLocation = useCallback((location: Omit<Location, 'id'>) => {
    if (!currentCampaign) return
    storeAddLocation(currentCampaign.id, location)
  }, [currentCampaign, storeAddLocation])

  const updateLocation = useCallback((locationId: string, updates: Partial<Location>) => {
    if (!currentCampaign) return
    storeUpdateLocation(currentCampaign.id, locationId, updates)
  }, [currentCampaign, storeUpdateLocation])

  const addNPC = useCallback((npc: Omit<NPC, 'id'>) => {
    if (!currentCampaign) return
    storeAddNPC(currentCampaign.id, npc)
  }, [currentCampaign, storeAddNPC])

  const updateNPC = useCallback((npcId: string, updates: Partial<NPC>) => {
    if (!currentCampaign) return
    storeUpdateNPC(currentCampaign.id, npcId, updates)
  }, [currentCampaign, storeUpdateNPC])

  // Journal management
  const addJournalEntry = useCallback((entry: Omit<JournalEntry, 'id' | 'createdAt'>) => {
    if (!currentCampaign) return
    storeAddJournalEntry(currentCampaign.id, entry)
  }, [currentCampaign, storeAddJournalEntry])

  const updateJournalEntry = useCallback((entryId: string, updates: Partial<JournalEntry>) => {
    if (!currentCampaign) return
    storeUpdateJournalEntry(currentCampaign.id, entryId, updates)
  }, [currentCampaign, storeUpdateJournalEntry])

  const deleteJournalEntry = useCallback((entryId: string) => {
    if (!currentCampaign) return
    storeDeleteJournalEntry(currentCampaign.id, entryId)
  }, [currentCampaign, storeDeleteJournalEntry])

  const searchJournal = useCallback((query: string) => {
    return journalEntries.filter(entry =>
      entry.title.toLowerCase().includes(query.toLowerCase()) ||
      entry.content.toLowerCase().includes(query.toLowerCase()) ||
      entry.tags.some(tag => tag.toLowerCase().includes(query.toLowerCase()))
    )
  }, [journalEntries])

  // Import/Export
  const exportCampaign = useCallback(() => {
    if (!currentCampaign) return ''
    return campaignService.exportCampaign(currentCampaign)
  }, [currentCampaign])

  const importCampaign = useCallback((campaignData: string) => {
    const campaign = campaignService.importCampaign(campaignData)
    return storeCreateCampaign(campaign)
  }, [storeCreateCampaign])

  return {
    // Current campaign
    currentCampaign,
    isActiveCampaign,

    // Campaign management
    createCampaign,
    updateCampaign,
    deleteCampaign,
    setActiveCampaign,

    // Campaign list
    allCampaigns,
    recentCampaigns,

    // Character management
    campaignCharacters,
    addCharacterToCampaign,
    removeCharacterFromCampaign,
    getCharacterCampaigns,

    // Session management
    campaignSessions,
    startCampaignSession,
    endCampaignSession,
    getSessionHistory,

    // World management
    locations,
    npcs,
    addLocation,
    updateLocation,
    addNPC,
    updateNPC,

    // Journal management
    journalEntries,
    addJournalEntry,
    updateJournalEntry,
    deleteJournalEntry,
    searchJournal,

    // Campaign statistics
    campaignStats,

    // Import/Export
    exportCampaign,
    importCampaign,

    // Utility
    isLoading,
    error,
    clearError: storeClearError,
  }
}

/**
 * Simplified campaign hook for basic campaign operations
 */
export function useSimpleCampaign() {
  const {
    currentCampaign,
    isActiveCampaign,
    setActiveCampaign,
    campaignCharacters,
    campaignStats,
  } = useCampaign()

  return {
    campaign: currentCampaign,
    isActive: isActiveCampaign,
    setActive: setActiveCampaign,
    characters: campaignCharacters,
    stats: campaignStats,
  }
}

/**
 * useCharacter Hook for ZimboMate V2
 * Primary character management hook - foundation for all character operations
 * Integrates characterStore with CharacterStateService and AdvancementService
 */

import { useCallback, useMemo } from 'react'
import { useCharacterStore } from '../stores/characterStore'
import { characterStateService } from '../services/CharacterStateService'
import { advancementService } from '../services/AdvancementService'
import type { Character } from '../models/Character'

export interface UseCharacterReturn {
  // Character data
  character: Character | undefined
  isLoading: boolean
  error: string | null
  
  // Character operations
  updateCharacter: (updates: Partial<Character>) => void
  deleteCharacter: () => void
  duplicateCharacter: () => Character | undefined
  exportCharacter: () => string | undefined
  
  // Health management
  updateHP: (newHP: number) => void
  healCharacter: (amount: number) => void
  damageCharacter: (amount: number) => void
  
  // Load management
  updateLoad: (newLoad: number) => void
  
  // XP and advancement
  addXP: (amount: number, source: string, description: string) => void
  levelUp: () => void
  canLevelUp: boolean
  
  // Character state integration
  getStateSummary: () => {
    activeConditions: number
    totalOngoingModifiers: number
    availableForwardModifiers: number
    resourcesNeedingAttention: number
  }
  
  // Utility
  clearError: () => void
}

/**
 * Primary character management hook
 * @param characterId - Optional character ID. If not provided, uses active character
 * @returns Character data and operations
 */
export function useCharacter(characterId?: string): UseCharacterReturn {
  const {
    characters,
    activeCharacterId,
    isLoading,
    error,
    getCharacter,
    updateCharacter: storeUpdateCharacter,
    deleteCharacter: storeDeleteCharacter,
    duplicateCharacter: storeDuplicateCharacter,
    exportCharacter: storeExportCharacter,
    updateHP: storeUpdateHP,
    healCharacter: storeHealCharacter,
    damageCharacter: storeDamageCharacter,
    updateLoad: storeUpdateLoad,
    addXP: storeAddXP,
    levelUpCharacter: storeLevelUpCharacter,
    clearError,
  } = useCharacterStore()

  // Determine which character to use
  const targetCharacterId = characterId || activeCharacterId
  const character = useMemo(() => {
    if (!targetCharacterId) return undefined
    return getCharacter(targetCharacterId)
  }, [targetCharacterId, getCharacter, characters])

  // Character operations
  const updateCharacter = useCallback((updates: Partial<Character>) => {
    if (!targetCharacterId) return
    storeUpdateCharacter(targetCharacterId, updates)
  }, [targetCharacterId, storeUpdateCharacter])

  const deleteCharacter = useCallback(() => {
    if (!targetCharacterId) return
    storeDeleteCharacter(targetCharacterId)
  }, [targetCharacterId, storeDeleteCharacter])

  const duplicateCharacter = useCallback(() => {
    if (!targetCharacterId) return undefined
    return storeDuplicateCharacter(targetCharacterId)
  }, [targetCharacterId, storeDuplicateCharacter])

  const exportCharacter = useCallback(() => {
    if (!targetCharacterId) return undefined
    return storeExportCharacter(targetCharacterId)
  }, [targetCharacterId, storeExportCharacter])

  // Health management
  const updateHP = useCallback((newHP: number) => {
    if (!targetCharacterId) return
    storeUpdateHP(targetCharacterId, newHP)
  }, [targetCharacterId, storeUpdateHP])

  const healCharacter = useCallback((amount: number) => {
    if (!targetCharacterId) return
    storeHealCharacter(targetCharacterId, amount)
  }, [targetCharacterId, storeHealCharacter])

  const damageCharacter = useCallback((amount: number) => {
    if (!targetCharacterId) return
    storeDamageCharacter(targetCharacterId, amount)
  }, [targetCharacterId, storeDamageCharacter])

  // Load management
  const updateLoad = useCallback((newLoad: number) => {
    if (!targetCharacterId) return
    storeUpdateLoad(targetCharacterId, newLoad)
  }, [targetCharacterId, storeUpdateLoad])

  // XP and advancement
  const addXP = useCallback((amount: number, source: string, description: string) => {
    if (!targetCharacterId) return
    storeAddXP(targetCharacterId, amount, source, description)
  }, [targetCharacterId, storeAddXP])

  const levelUp = useCallback(() => {
    if (!targetCharacterId) return
    storeLevelUpCharacter(targetCharacterId)
  }, [targetCharacterId, storeLevelUpCharacter])

  const canLevelUp = useMemo(() => {
    if (!character) return false
    return advancementService.shouldLevelUp(character)
  }, [character])

  // Character state integration
  const getStateSummary = useCallback(() => {
    if (!targetCharacterId) {
      return {
        activeConditions: 0,
        totalOngoingModifiers: 0,
        availableForwardModifiers: 0,
        resourcesNeedingAttention: 0,
      }
    }
    return characterStateService.getStateSummary(targetCharacterId)
  }, [targetCharacterId])

  return {
    // Character data
    character,
    isLoading,
    error,
    
    // Character operations
    updateCharacter,
    deleteCharacter,
    duplicateCharacter,
    exportCharacter,
    
    // Health management
    updateHP,
    healCharacter,
    damageCharacter,
    
    // Load management
    updateLoad,
    
    // XP and advancement
    addXP,
    levelUp,
    canLevelUp,
    
    // Character state integration
    getStateSummary,
    
    // Utility
    clearError,
  }
}

/**
 * Hook for managing multiple characters
 * @returns All characters and bulk operations
 */
export function useCharacters() {
  const {
    characters,
    isLoading,
    error,
    createCharacter,
    importCharacter,
    clearError,
  } = useCharacterStore()

  const createNewCharacter = useCallback((characterData: Omit<Character, 'id' | 'createdAt' | 'updatedAt'>) => {
    return createCharacter(characterData)
  }, [createCharacter])

  const importFromData = useCallback((characterData: string) => {
    return importCharacter(characterData)
  }, [importCharacter])

  return {
    characters,
    isLoading,
    error,
    createCharacter: createNewCharacter,
    importCharacter: importFromData,
    clearError,
  }
}

/**
 * useCharacterHealth Hook for ZimboMate V2
 * Manages character HP, damage, healing with animations and death saves
 * Integrates with character state and triggers particle effects
 */

import { useCallback, useMemo, useState, useEffect } from 'react'
import { useCharacter } from './useCharacter'
import { characterStateService } from '../services/CharacterStateService'
import type { Character } from '../models/Character'

export interface HealthStatus {
  current: number
  max: number
  percentage: number
  status: 'healthy' | 'wounded' | 'critical' | 'unconscious' | 'dead'
  statusColor: 'green' | 'yellow' | 'orange' | 'red' | 'gray'
}

export interface DamageResult {
  previousHP: number
  newHP: number
  damageDealt: number
  isUnconscious: boolean
  isDead: boolean
  triggeredDeathSave: boolean
}

export interface HealingResult {
  previousHP: number
  newHP: number
  healingDone: number
  wasUnconscious: boolean
  isFullyHealed: boolean
}

export interface UseCharacterHealthReturn {
  // Health status
  health: HealthStatus
  isUnconscious: boolean
  isDead: boolean
  isFullHealth: boolean

  // Health operations
  updateHP: (newHP: number) => void
  heal: (amount: number, source?: string) => HealingResult
  damage: (amount: number, source?: string) => DamageResult
  setToFullHealth: () => void
  setToUnconscious: () => void

  // Death saves (Dungeon World style)
  deathSaves: {
    successes: number
    failures: number
    isStabilized: boolean
    needsDeathSave: boolean
  }
  rollDeathSave: () => {
    roll: number
    result: 'success' | 'failure' | 'critical_success'
    isStabilized: boolean
    isDead: boolean
  }

  // Healing over time
  startRegeneration: (amountPerTurn: number, duration: number) => void
  stopRegeneration: () => void
  isRegenerating: boolean

  // Animation triggers
  lastDamage: { amount: number; timestamp: number } | null
  lastHealing: { amount: number; timestamp: number } | null

  // Utility
  character: Character | undefined
  isLoading: boolean
  error: string | null
}

/**
 * Hook for managing character health with advanced features
 * @param characterId - Character ID (optional, uses active character if not provided)
 */
export function useCharacterHealth(characterId?: string): UseCharacterHealthReturn {
  const {
    character,
    updateHP: storeUpdateHP,
    healCharacter: storeHealCharacter,
    damageCharacter: storeDamageCharacter,
    isLoading,
    error,
  } = useCharacter(characterId)

  // Local state for death saves and animations
  const [deathSaveSuccesses, setDeathSaveSuccesses] = useState(0)
  const [deathSaveFailures, setDeathSaveFailures] = useState(0)
  const [lastDamage, setLastDamage] = useState<{ amount: number; timestamp: number } | null>(null)
  const [lastHealing, setLastHealing] = useState<{ amount: number; timestamp: number } | null>(null)
  const [regenerationTimer, setRegenerationTimer] = useState<NodeJS.Timeout | null>(null)

  // Health status calculation
  const health = useMemo((): HealthStatus => {
    if (!character) {
      return {
        current: 0,
        max: 0,
        percentage: 0,
        status: 'dead',
        statusColor: 'gray',
      }
    }

    const current = character.hp.current
    const max = character.hp.max
    const percentage = max > 0 ? (current / max) * 100 : 0

    let status: HealthStatus['status']
    let statusColor: HealthStatus['statusColor']

    if (current <= 0) {
      status = 'unconscious'
      statusColor = 'red'
    } else if (percentage <= 25) {
      status = 'critical'
      statusColor = 'red'
    } else if (percentage <= 50) {
      status = 'wounded'
      statusColor = 'orange'
    } else if (percentage <= 75) {
      status = 'wounded'
      statusColor = 'yellow'
    } else {
      status = 'healthy'
      statusColor = 'green'
    }

    return {
      current,
      max,
      percentage,
      status,
      statusColor,
    }
  }, [character?.hp])

  // Computed health states
  const isUnconscious = useMemo(() => health.current <= 0, [health.current])
  const isDead = useMemo(() => deathSaveFailures >= 3, [deathSaveFailures])
  const isFullHealth = useMemo(() => health.current >= health.max, [health.current, health.max])

  // Death saves state
  const deathSaves = useMemo(() => ({
    successes: deathSaveSuccesses,
    failures: deathSaveFailures,
    isStabilized: deathSaveSuccesses >= 3,
    needsDeathSave: isUnconscious && !isDead && deathSaveSuccesses < 3,
  }), [deathSaveSuccesses, deathSaveFailures, isUnconscious, isDead])

  // Reset death saves when character is healed above 0
  useEffect(() => {
    if (health.current > 0) {
      setDeathSaveSuccesses(0)
      setDeathSaveFailures(0)
    }
  }, [health.current])

  // Health operations
  const updateHP = useCallback((newHP: number) => {
    if (!character) return
    storeUpdateHP(newHP)
  }, [character, storeUpdateHP])

  const heal = useCallback((amount: number, source = 'Unknown'): HealingResult => {
    if (!character) {
      return {
        previousHP: 0,
        newHP: 0,
        healingDone: 0,
        wasUnconscious: false,
        isFullyHealed: false,
      }
    }

    const previousHP = character.hp.current
    const wasUnconscious = previousHP <= 0
    const maxPossibleHealing = character.hp.max - previousHP
    const actualHealing = Math.min(amount, maxPossibleHealing)
    const newHP = previousHP + actualHealing

    storeHealCharacter(actualHealing)

    // Trigger healing animation
    setLastHealing({ amount: actualHealing, timestamp: Date.now() })

    // Add healing to character state service as a temporary effect
    if (character && actualHealing > 0) {
      characterStateService.setResource(character.id, {
        id: `healing-${Date.now()}`,
        name: `Healing from ${source}`,
        current: actualHealing,
        max: actualHealing,
        type: 'custom',
        source,
        refreshOn: 'manual',
      })
    }

    return {
      previousHP,
      newHP,
      healingDone: actualHealing,
      wasUnconscious,
      isFullyHealed: newHP >= character.hp.max,
    }
  }, [character, storeHealCharacter])

  const damage = useCallback((amount: number, source = 'Unknown'): DamageResult => {
    if (!character) {
      return {
        previousHP: 0,
        newHP: 0,
        damageDealt: 0,
        isUnconscious: false,
        isDead: false,
        triggeredDeathSave: false,
      }
    }

    const previousHP = character.hp.current
    const actualDamage = Math.min(amount, previousHP)
    const newHP = previousHP - actualDamage

    storeDamageCharacter(actualDamage)

    // Trigger damage animation
    setLastDamage({ amount: actualDamage, timestamp: Date.now() })

    const isNowUnconscious = newHP <= 0
    const triggeredDeathSave = isNowUnconscious && previousHP > 0

    return {
      previousHP,
      newHP,
      damageDealt: actualDamage,
      isUnconscious: isNowUnconscious,
      isDead: false, // Death is determined by death saves, not HP
      triggeredDeathSave,
    }
  }, [character, storeDamageCharacter])

  const setToFullHealth = useCallback(() => {
    if (!character) return
    updateHP(character.hp.max)
  }, [character, updateHP])

  const setToUnconscious = useCallback(() => {
    updateHP(0)
  }, [updateHP])

  // Death save mechanics
  const rollDeathSave = useCallback(() => {
    const roll = Math.floor(Math.random() * 6) + Math.floor(Math.random() * 6) + 2 // 2d6

    let result: 'success' | 'failure' | 'critical_success'
    let newSuccesses = deathSaveSuccesses
    let newFailures = deathSaveFailures

    if (roll >= 10) {
      result = 'success'
      newSuccesses++
    } else if (roll >= 12) {
      result = 'critical_success'
      newSuccesses = 3 // Immediately stabilized
    } else {
      result = 'failure'
      newFailures++
    }

    setDeathSaveSuccesses(newSuccesses)
    setDeathSaveFailures(newFailures)

    const isStabilized = newSuccesses >= 3
    const isDead = newFailures >= 3

    return {
      roll,
      result,
      isStabilized,
      isDead,
    }
  }, [deathSaveSuccesses, deathSaveFailures])

  // Regeneration mechanics
  const startRegeneration = useCallback((amountPerTurn: number, duration: number) => {
    if (regenerationTimer) {
      clearInterval(regenerationTimer)
    }

    let turnsRemaining = duration
    const timer = setInterval(() => {
      if (turnsRemaining <= 0 || !character) {
        clearInterval(timer)
        setRegenerationTimer(null)
        return
      }

      heal(amountPerTurn, 'Regeneration')
      turnsRemaining--
    }, 6000) // 6 seconds per "turn" for demo purposes

    setRegenerationTimer(timer)
  }, [regenerationTimer, character, heal])

  const stopRegeneration = useCallback(() => {
    if (regenerationTimer) {
      clearInterval(regenerationTimer)
      setRegenerationTimer(null)
    }
  }, [regenerationTimer])

  const isRegenerating = regenerationTimer !== null

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (regenerationTimer) {
        clearInterval(regenerationTimer)
      }
    }
  }, [regenerationTimer])

  return {
    // Health status
    health,
    isUnconscious,
    isDead,
    isFullHealth,

    // Health operations
    updateHP,
    heal,
    damage,
    setToFullHealth,
    setToUnconscious,

    // Death saves
    deathSaves,
    rollDeathSave,

    // Healing over time
    startRegeneration,
    stopRegeneration,
    isRegenerating,

    // Animation triggers
    lastDamage,
    lastHealing,

    // Utility
    character,
    isLoading,
    error,
  }
}

