      intelligence: Math.floor((character.attributes.intelligence - 10) / 2),
      wisdom: Math.floor((character.attributes.wisdom - 10) / 2),
      charisma: Math.floor((character.attributes.charisma - 10) / 2),
    }
  }, [character?.attributes])

  return modifiers
}

/**
 * Dice Keyboard Shortcuts Hook
 * Provides desktop-optimized keyboard shortcuts for quick dice rolling
 * S = STR, D = DEX, C = CON, I = INT, W = WIS, H = CHA
 */

import { useEffect, useCallback } from 'react'
import { useDiceStore } from '../stores/diceStore'
import { type Attributes } from '../models/Character'

interface DiceKeyboardShortcutsOptions {
  characterId: string
  enabled?: boolean
  modifierKey?: 'ctrl' | 'alt' | 'shift' | 'none'
}

const STAT_SHORTCUTS: Record<string, keyof Attributes> = {
  KeyS: 'STR',  // S for Strength
  KeyD: 'DEX',  // D for Dexterity
  KeyC: 'CON',  // C for Constitution
  KeyI: 'INT',  // I for Intelligence
  KeyW: 'WIS',  // W for Wisdom
  KeyH: 'CHA',  // H for CHArisma
}

const MOVE_SHORTCUTS: Record<string, { moveId: string; stat: keyof Attributes }> = {
  KeyQ: { moveId: 'hack-and-slash', stat: 'STR' },     // Q for Quick attack
  KeyE: { moveId: 'defend', stat: 'CON' },            // E for dEfend
  KeyR: { moveId: 'volley', stat: 'DEX' },            // R for Ranged attack
  KeyT: { moveId: 'discern-realities', stat: 'WIS' }, // T for Truth/perception
  KeyY: { moveId: 'spout-lore', stat: 'INT' },        // Y for knowledgE (Y sounds like "why")
  KeyU: { moveId: 'parley', stat: 'CHA' },            // U for persUade
}

export const useDiceKeyboardShortcuts = ({
  characterId,
  enabled = true,
  modifierKey = 'none'
}: DiceKeyboardShortcutsOptions) => {
  const { rollStat, rollMove, isRolling } = useDiceStore()

  const handleKeyDown = useCallback((event: KeyboardEvent) => {
    // Don't trigger shortcuts if we're typing in an input
    const target = event.target as HTMLElement
    if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.contentEditable === 'true') {
      return
    }

    // Don't trigger if already rolling
    if (isRolling) {
      return
    }

    // Check modifier key requirement
    const hasCorrectModifier = (() => {
      switch (modifierKey) {
        case 'ctrl': return event.ctrlKey && !event.altKey && !event.shiftKey
        case 'alt': return event.altKey && !event.ctrlKey && !event.shiftKey
        case 'shift': return event.shiftKey && !event.ctrlKey && !event.altKey
        case 'none': return !event.ctrlKey && !event.altKey && !event.shiftKey && !event.metaKey
        default: return false
      }
    })()

    if (!hasCorrectModifier) {
      return
    }

    const code = event.code

    // Handle stat shortcuts
    if (STAT_SHORTCUTS[code]) {
      event.preventDefault()
      const stat = STAT_SHORTCUTS[code]
      console.log(`[DiceShortcuts] Rolling ${stat} via keyboard shortcut`)
      rollStat(stat, characterId, `${stat} (Keyboard Shortcut)`)
      return
    }

    // Handle move shortcuts (only with Shift modifier)
    if (event.shiftKey && MOVE_SHORTCUTS[code]) {
      event.preventDefault()
      const { moveId, stat } = MOVE_SHORTCUTS[code]
      console.log(`[DiceShortcuts] Rolling move ${moveId} via keyboard shortcut`)
      rollMove(moveId, stat, characterId)
      return
    }
  }, [characterId, rollStat, rollMove, isRolling, modifierKey])

  const handleKeyPress = useCallback((event: KeyboardEvent) => {
    // Handle number keys for custom modifiers (1-6 and -1 to -6)
    const target = event.target as HTMLElement
    if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.contentEditable === 'true') {
      return
    }

    if (isRolling) {
      return
    }

    // Check for Ctrl + number for custom rolls with modifiers
    if (event.ctrlKey && event.key >= '1' && event.key <= '6') {
      event.preventDefault()
      const modifier = parseInt(event.key)
      // TODO: Implement custom roll with specific modifier
      console.log(`[DiceShortcuts] Custom roll with +${modifier} modifier`)
      return
    }

    // Check for Ctrl + Shift + number for negative modifiers
    if (event.ctrlKey && event.shiftKey && event.key >= '1' && event.key <= '6') {
      event.preventDefault()
      const modifier = -parseInt(event.key)
      // TODO: Implement custom roll with specific modifier
      console.log(`[DiceShortcuts] Custom roll with ${modifier} modifier`)
      return
    }
  }, [isRolling])

  useEffect(() => {
    if (!enabled) return

    document.addEventListener('keydown', handleKeyDown, { passive: false })
    document.addEventListener('keypress', handleKeyPress, { passive: false })

    return () => {
      document.removeEventListener('keydown', handleKeyDown)
      document.removeEventListener('keypress', handleKeyPress)
    }
  }, [enabled, handleKeyDown, handleKeyPress])

  // Return shortcut information for display in help/tooltips
  const getShortcutInfo = useCallback(() => {
    const modifierText = modifierKey === 'none' ? '' : `${modifierKey.toUpperCase()} + `

    return {
      stats: Object.entries(STAT_SHORTCUTS).map(([key, stat]) => ({
        key: key.replace('Key', ''),
        description: `${modifierText}${key.replace('Key', '')} → Roll ${stat}`,
        stat
      })),
      moves: Object.entries(MOVE_SHORTCUTS).map(([key, { moveId, stat }]) => ({
        key: key.replace('Key', ''),
        description: `SHIFT + ${key.replace('Key', '')} → ${moveId.replace('-', ' ')} (${stat})`,
        moveId,
        stat
      })),
      custom: [
        { key: 'CTRL + 1-6', description: 'Custom roll with positive modifier' },
        { key: 'CTRL + SHIFT + 1-6', description: 'Custom roll with negative modifier' }
      ]
    }
  }, [modifierKey])

  return {
    getShortcutInfo,
    enabled,
    isRolling
  }
}

/**
 * useDiceRoll Hook for ZimboMate V2
 * Enhanced dice rolling with move integration, modifiers, and particle effects
 * Integrates DiceRollingService with character stats and session tracking
 */

import { useCallback, useMemo, useState } from 'react'
import { useActiveCharacter } from './useActiveCharacter'
import { useCharacterStats } from './useCharacterStats'
import { useSessionStore } from '../stores/sessionStore'
import { diceRollingService } from '../services/DiceRollingService'
import { characterStateService } from '../services/CharacterStateService'
import type { DiceRoll, RollModifiers, RollOptions } from '../services/DiceRollingService'
import type { Attribute } from '../models/Character'

export interface RollRequest {
  // Basic roll parameters
  stat?: keyof Attribute
  modifier?: number
  moveId?: string
  moveName?: string

  // Roll context
  description?: string
  difficulty?: number
  advantage?: boolean
  disadvantage?: boolean

  // Character context
  characterId?: string
}

export interface RollResult extends DiceRoll {
  // Enhanced result information
  wasSuccess: boolean
  wasPartialSuccess: boolean
  wasFailure: boolean
  outcomeDescription: string

  // Animation triggers
  shouldTriggerParticles: boolean
  particleType: 'success' | 'partial' | 'failure'
  particleColor: string
}

export interface UseDiceRollReturn {
  // Roll execution
  roll: (request: RollRequest) => Promise<RollResult>
  rollWithStat: (stat: keyof Attribute, modifier?: number, description?: string) => Promise<RollResult>
  rollBasic: (modifier?: number, description?: string) => Promise<RollResult>

  // Quick roll shortcuts
  rollStrength: (modifier?: number) => Promise<RollResult>
  rollDexterity: (modifier?: number) => Promise<RollResult>
  rollConstitution: (modifier?: number) => Promise<RollResult>
  rollIntelligence: (modifier?: number) => Promise<RollResult>
  rollWisdom: (modifier?: number) => Promise<RollResult>
  rollCharisma: (modifier?: number) => Promise<RollResult>

  // Roll history
  recentRolls: DiceRoll[]
  lastRoll: DiceRoll | null
  clearHistory: () => void

  // Roll state
  isRolling: boolean
  canRoll: boolean

  // Character context
  activeCharacter: any
  availableModifiers: Array<{
    id: string
    name: string
    value: number
    source: string
    type: 'ongoing' | 'forward'
  }>

  // Utility
  getOutcomeDescription: (total: number) => string
  getParticleType: (result: string) => 'success' | 'partial' | 'failure'
}

/**
 * Enhanced dice rolling hook with full game integration
 */
export function useDiceRoll(): UseDiceRollReturn {
  const { activeCharacter } = useActiveCharacter()
  const { getStatModifier, getTotalModifierForStat } = useCharacterStats(activeCharacter?.id)
  const { addRoll, getRecentRolls, clearRollHistory } = useSessionStore()

  const [isRolling, setIsRolling] = useState(false)

  // Get recent rolls
  const recentRolls = useMemo(() => getRecentRolls(10), [getRecentRolls])
  const lastRoll = useMemo(() => recentRolls[0] || null, [recentRolls])

  // Check if character can roll
  const canRoll = useMemo(() => {
    return activeCharacter !== undefined && !isRolling
  }, [activeCharacter, isRolling])

  // Get available modifiers for the active character
  const availableModifiers = useMemo(() => {
    if (!activeCharacter) return []

    const modifiers: Array<{
      id: string
      name: string
      value: number
      source: string
      type: 'ongoing' | 'forward'
    }> = []

    // Get forward modifiers
    const forwardMods = characterStateService.getAvailableForwardModifiers(
      activeCharacter.id,
      'next_roll'
    )

    forwardMods.forEach(mod => {
      modifiers.push({
        id: mod.id,
        name: mod.name,
        value: mod.value,
        source: mod.source,
        type: 'forward',
      })
    })

    return modifiers
  }, [activeCharacter])

  // Main roll function
  const roll = useCallback(async (request: RollRequest): Promise<RollResult> => {
    if (!canRoll || !activeCharacter) {
      throw new Error('Cannot roll: no active character or already rolling')
    }

    setIsRolling(true)

    try {
      // Calculate total modifier
      let totalModifier = request.modifier || 0

      // Add stat modifier if specified
      if (request.stat) {
        const statMod = getStatModifier(request.stat)
        const additionalMod = getTotalModifierForStat(request.stat)
        totalModifier += statMod + additionalMod
      }

      // Apply available forward modifiers
      const characterId = request.characterId || activeCharacter.id
      const forwardMods = characterStateService.getAvailableForwardModifiers(
        characterId,
        'next_roll'
      )

      forwardMods.forEach(mod => {
        totalModifier += mod.value
        characterStateService.useForwardModifier(characterId, mod.id)
      })

      // Create roll options
      const rollOptions: RollOptions = {
        description: request.description || 'Roll',
        characterId,
        moveId: request.moveId,
        moveName: request.moveName,
      }

      // Execute the roll
      const rollResult = await diceRollingService.rollDice(
        '2d6',
        { flat: totalModifier },
        rollOptions
      )

      // Add to session history
      addRoll(rollResult)

      // Clean up used forward modifiers
      characterStateService.cleanupForwardModifiers(characterId)

      // Create enhanced result
      const enhancedResult: RollResult = {
        ...rollResult,
        wasSuccess: rollResult.result === 'success',
        wasPartialSuccess: rollResult.result === 'partial',
        wasFailure: rollResult.result === 'failure',
        outcomeDescription: getOutcomeDescription(rollResult.total),
        shouldTriggerParticles: true,
        particleType: getParticleType(rollResult.result),
        particleColor: getParticleColor(rollResult.result),
      }

      return enhancedResult

    } finally {
      setIsRolling(false)
    }
  }, [canRoll, activeCharacter, getStatModifier, getTotalModifierForStat, addRoll])

  // Roll with specific stat
  const rollWithStat = useCallback(async (
    stat: keyof Attribute,
    modifier = 0,
    description?: string
  ): Promise<RollResult> => {
    return roll({
      stat,
      modifier,
      description: description || `${stat.charAt(0).toUpperCase() + stat.slice(1)} roll`,
    })
  }, [roll])

  // Basic roll without stat
  const rollBasic = useCallback(async (
    modifier = 0,
    description = 'Basic roll'
  ): Promise<RollResult> => {
    return roll({ modifier, description })
  }, [roll])

  // Quick stat roll shortcuts
  const rollStrength = useCallback((modifier = 0) => 
    rollWithStat('strength', modifier), [rollWithStat])

  const rollDexterity = useCallback((modifier = 0) => 
    rollWithStat('dexterity', modifier), [rollWithStat])

  const rollConstitution = useCallback((modifier = 0) => 
    rollWithStat('constitution', modifier), [rollWithStat])

  const rollIntelligence = useCallback((modifier = 0) => 
    rollWithStat('intelligence', modifier), [rollWithStat])

  const rollWisdom = useCallback((modifier = 0) => 
    rollWithStat('wisdom', modifier), [rollWithStat])

  const rollCharisma = useCallback((modifier = 0) => 
    rollWithStat('charisma', modifier), [rollWithStat])

  // Utility functions
  const getOutcomeDescription = useCallback((total: number): string => {
    if (total >= 10) return 'Success! You do it.'
    if (total >= 7) return 'Partial success. You do it, but...'
    return 'Failure. The GM makes a move.'
  }, [])

  const getParticleType = useCallback((result: string): 'success' | 'partial' | 'failure' => {
    switch (result) {
      case 'success': return 'success'
      case 'partial': return 'partial'
      default: return 'failure'
    }
  }, [])

  const getParticleColor = (result: string): string => {
    switch (result) {
      case 'success': return '#10B981' // Green
      case 'partial': return '#F59E0B' // Amber
      default: return '#EF4444' // Red
    }
  }

  return {
    // Roll execution
    roll,
    rollWithStat,
    rollBasic,

    // Quick roll shortcuts
    rollStrength,
    rollDexterity,
    rollConstitution,
    rollIntelligence,
    rollWisdom,
    rollCharisma,

    // Roll history
    recentRolls,
    lastRoll,
    clearHistory: clearRollHistory,

    // Roll state
    isRolling,
    canRoll,

    // Character context
    activeCharacter,
    availableModifiers,

    // Utility
    getOutcomeDescription,
    getParticleType,
  }
}

/**
 * Simplified dice rolling hook for basic use cases
 */
export function useSimpleDiceRoll() {
  const { rollBasic, rollWithStat, lastRoll, isRolling } = useDiceRoll()

  return {
    roll: rollBasic,
