  }
}

/**
 * Drag and Drop Hook for Stats
 * Provides desktop-optimized drag and drop functionality for stats to quick roll zones
 */

import { useState, useCallback, useRef } from 'react'
import { useDiceStore } from '../stores/diceStore'
import { type Attributes } from '../models/Character'

interface DragData {
  type: 'stat' | 'move' | 'custom'
  stat?: keyof Attributes
  statValue?: number
  moveId?: string
  moveName?: string
  modifier?: number
  label?: string
}

interface DropZone {
  id: string
  label: string
  accepts: Array<'stat' | 'move' | 'custom'>
  onDrop: (data: DragData) => void
  className?: string
}

export const useDragAndDrop = (characterId: string) => {
  const [isDragging, setIsDragging] = useState(false)
  const [dragData, setDragData] = useState<DragData | null>(null)
  const [activeDropZone, setActiveDropZone] = useState<string | null>(null)
  const dragStartPos = useRef<{ x: number; y: number }>({ x: 0, y: 0 })

  const { rollStat, rollMove, rollCustom } = useDiceStore()

  // Start dragging
  const startDrag = useCallback((data: DragData, event: React.DragEvent) => {
    console.log('[DragDrop] Starting drag:', data)
    setIsDragging(true)
    setDragData(data)
    dragStartPos.current = { x: event.clientX, y: event.clientY }

    // Set drag image to be semi-transparent
    if (event.dataTransfer) {
      event.dataTransfer.effectAllowed = 'copy'
      event.dataTransfer.setData('application/json', JSON.stringify(data))

      // Create custom drag image
      const dragElement = event.currentTarget as HTMLElement
      const dragImage = dragElement.cloneNode(true) as HTMLElement
      dragImage.style.opacity = '0.7'
      dragImage.style.transform = 'rotate(5deg)'
      dragImage.style.pointerEvents = 'none'

      // Append to body temporarily for drag image
      document.body.appendChild(dragImage)
      event.dataTransfer.setDragImage(dragImage, 0, 0)

      // Clean up drag image after a delay
      setTimeout(() => {
        if (document.body.contains(dragImage)) {
          document.body.removeChild(dragImage)
        }
      }, 0)
    }
  }, [])

  // End dragging
  const endDrag = useCallback(() => {
    console.log('[DragDrop] Ending drag')
    setIsDragging(false)
    setDragData(null)
    setActiveDropZone(null)
  }, [])

  // Handle drop
  const handleDrop = useCallback(async (event: React.DragEvent, dropZoneId: string) => {
    event.preventDefault()

    try {
      const dataString = event.dataTransfer.getData('application/json')
      if (!dataString) return

      const data: DragData = JSON.parse(dataString)
      console.log('[DragDrop] Handling drop:', data, 'to zone:', dropZoneId)

      // Apply drop zone modifiers
      let finalModifier = data.modifier || 0
      let rollLabel = data.label || 'Drag & Drop Roll'

      switch (dropZoneId) {
        case 'advantage-roll':
          finalModifier += 1
          rollLabel += ' (Advantage +1)'
          break
        case 'power-roll':
          finalModifier += 2
          rollLabel += ' (Power +2)'
          break
        case 'quick-roll':
        default:
          rollLabel += ' (Quick Roll)'
          break
      }

      // Execute the appropriate roll based on drag data
      if (data.type === 'stat' && data.stat) {
        await rollCustom(finalModifier, {
          label: rollLabel,
          type: 'stat',
          stat: data.stat
        }, characterId)
      } else if (data.type === 'move' && data.moveId && data.stat) {
        await rollCustom(finalModifier, {
          label: rollLabel,
          type: 'move',
          moveId: data.moveId,
          stat: data.stat
        }, characterId)
      } else if (data.type === 'custom') {
        await rollCustom(finalModifier, { label: rollLabel, type: 'custom' }, characterId)
      }

    } catch (error) {
      console.error('[DragDrop] Drop failed:', error)
    } finally {
      endDrag()
    }
  }, [characterId, rollStat, rollMove, rollCustom, endDrag])

  // Handle drag over (for drop zone highlighting)
  const handleDragOver = useCallback((event: React.DragEvent, dropZoneId: string) => {
    event.preventDefault()
    setActiveDropZone(dropZoneId)
  }, [])

  // Handle drag leave
  const handleDragLeave = useCallback((event: React.DragEvent) => {
    // Only clear if we're actually leaving the drop zone (not just moving to a child)
    const rect = (event.currentTarget as HTMLElement).getBoundingClientRect()
    const x = event.clientX
    const y = event.clientY

    if (x < rect.left || x > rect.right || y < rect.top || y > rect.bottom) {
      setActiveDropZone(null)
    }
  }, [])

  // Create draggable props for components
  const getDraggableProps = useCallback((data: DragData) => ({
    draggable: true,
    onDragStart: (e: React.DragEvent) => startDrag(data, e),
    onDragEnd: endDrag,
    className: isDragging && dragData === data ? 'opacity-50 cursor-grabbing' : 'cursor-grab'
  }), [startDrag, endDrag, isDragging, dragData])

  // Create drop zone props for components
  const getDropZoneProps = useCallback((dropZoneId: string) => ({
    onDrop: (e: React.DragEvent) => handleDrop(e, dropZoneId),
    onDragOver: (e: React.DragEvent) => handleDragOver(e, dropZoneId),
    onDragLeave: handleDragLeave,
    className: `${activeDropZone === dropZoneId ? 'bg-primary/10 border-primary/30 border-2 border-dashed' : 'border-2 border-transparent'} transition-all duration-200`
  }), [handleDrop, handleDragOver, handleDragLeave, activeDropZone])

  return {
    isDragging,
    dragData,
    activeDropZone,
    getDraggableProps,
    getDropZoneProps,
    startDrag,
    endDrag,
    handleDrop
  }
}

// Convenience hook for stat dragging
export const useStatDrag = (stat: keyof Attributes, statValue: number, label?: string) => {
  const { getDraggableProps } = useDragAndDrop('') // Character ID will be provided by parent

  return getDraggableProps({
    type: 'stat',
    stat,
    statValue,
    label: label || stat
  })
}

// Convenience hook for move dragging
export const useMoveDrag = (moveId: string, moveName: string, stat: keyof Attributes) => {
  const { getDraggableProps } = useDragAndDrop('') // Character ID will be provided by parent

  return getDraggableProps({
    type: 'move',
    moveId,
    moveName,
    stat
  })
}

import { useState, useCallback, useEffect } from 'react'
import type { RollResult } from '../components/ui/RollResultsToast'
import { gameLogicService, type RollConsequence } from '../services/GameLogicService'
import { useCharacterStore } from '../stores/characterStore'

export interface EnhancedRollResult extends RollResult {
  consequences: RollConsequence[]
  characterId?: string
  moveContext?: {
    moveId: string
    moveName: string
    targetId?: string
  }
}

export interface UseEnhancedRollResultsReturn {
  currentResult: EnhancedRollResult | null
  showRollResult: (result: Omit<RollResult, 'id' | 'timestamp'>, characterId?: string, moveContext?: any) => void
  clearResult: () => void
  rollHistory: EnhancedRollResult[]
  applyConsequences: (rollId: string, selectedConsequences?: string[]) => void
  getPendingConsequences: (rollId: string) => RollConsequence[]
}

export const useEnhancedRollResults = (): UseEnhancedRollResultsReturn => {
  const [currentResult, setCurrentResult] = useState<EnhancedRollResult | null>(null)
  const [rollHistory, setRollHistory] = useState<EnhancedRollResult[]>([])
  const { getActiveCharacter } = useCharacterStore()

  const showRollResult = useCallback((
    result: Omit<RollResult, 'id' | 'timestamp'>,
    characterId?: string,
    moveContext?: {
      moveId: string
      moveName: string
      targetId?: string
      combatContext?: boolean
    }
  ) => {
    const activeCharacter = getActiveCharacter()
    const effectiveCharacterId = characterId || activeCharacter?.id

    const fullResult: RollResult = {
      ...result,
      id: `roll-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      timestamp: new Date()
    }

    // Process consequences if we have a character
    let consequences: RollConsequence[] = []
    if (effectiveCharacterId) {
      consequences = gameLogicService.processRollResult(
        fullResult,
        effectiveCharacterId,
        moveContext
      )

      // Auto-apply automatic consequences
      const automaticConsequences = consequences
        .filter(c => c.automatic)
        .map(c => c.id)
      
      if (automaticConsequences.length > 0) {
        setTimeout(() => {
          gameLogicService.applyConsequences(fullResult.id, automaticConsequences)
        }, 1000) // Delay to show the roll result first
      }
    }

    const enhancedResult: EnhancedRollResult = {
      ...fullResult,
      consequences,
      characterId: effectiveCharacterId,
      moveContext
    }

    setCurrentResult(enhancedResult)
    setRollHistory(prev => [enhancedResult, ...prev.slice(0, 49)]) // Keep last 50 rolls
  }, [getActiveCharacter])

  const clearResult = useCallback(() => {
    setCurrentResult(null)
  }, [])

  const applyConsequences = useCallback((rollId: string, selectedConsequences?: string[]) => {
    gameLogicService.applyConsequences(rollId, selectedConsequences)
    
    // Update the roll in history to mark consequences as applied
    setRollHistory(prev => prev.map(roll => {
      if (roll.id === rollId) {
        return {
          ...roll,
          consequences: roll.consequences.map(c => ({
            ...c,
            applied: selectedConsequences?.includes(c.id) ? true : c.applied
          }))
        }
      }
      return roll
    }))

    // Update current result if it matches
    setCurrentResult(prev => {
      if (prev?.id === rollId) {
        return {
          ...prev,
          consequences: prev.consequences.map(c => ({
            ...c,
            applied: selectedConsequences?.includes(c.id) ? true : c.applied
          }))
        }
      }
      return prev
    })
  }, [])

  const getPendingConsequences = useCallback((rollId: string) => {
    return gameLogicService.getPendingConsequences(rollId)
  }, [])

  return {
    currentResult,
    showRollResult,
    clearResult,
    rollHistory,
    applyConsequences,
    getPendingConsequences
  }
}

// Helper functions for common roll types with enhanced consequences
export const createEnhancedBasicRoll = (
  dice: number[], 
  modifier: number = 0
): Omit<RollResult, 'id' | 'timestamp'> => {
  const total = dice.reduce((sum, die) => sum + die, 0) + modifier
  let outcome: 'success' | 'partial' | 'failure' | undefined
  let description: string | undefined

  if (dice.length === 2) { // 2d6 roll
    if (total >= 10) {
      outcome = 'success'
      description = 'You succeed and choose from the list'
    } else if (total >= 7) {
      outcome = 'partial'
      description = 'You succeed, but with complications'
    } else {
      outcome = 'failure'
      description = 'The GM makes a move. Mark XP.'
    }
  }

  return {
    type: 'basic',
    title: '2d6 Roll',
    dice,
    modifier,
    total,
    outcome,
    description
  }
}

export const createEnhancedAttributeRoll = (
  attribute: string, 
  dice: number[], 
  modifier: number
): Omit<RollResult, 'id' | 'timestamp'> => {
  const total = dice.reduce((sum, die) => sum + die, 0) + modifier
  let outcome: 'success' | 'partial' | 'failure' | undefined
  let description: string | undefined

  if (total >= 10) {
    outcome = 'success'
    description = `Your ${attribute} check succeeds!`
  } else if (total >= 7) {
    outcome = 'partial'
    description = `Your ${attribute} check partially succeeds`
  } else {
    outcome = 'failure'
    description = `Your ${attribute} check fails. Mark XP.`
  }

  return {
    type: 'attribute',
    title: `${attribute.charAt(0).toUpperCase() + attribute.slice(1)} Roll`,
    dice,
    modifier,
    total,
    outcome,
    description
  }
}

export const createEnhancedDamageRoll = (
  weaponName: string,
  dice: number[]
): Omit<RollResult, 'id' | 'timestamp'> => {
  const total = dice.reduce((sum, die) => sum + die, 0)
  
  return {
    type: 'damage',
    title: `${weaponName} Damage`,
    dice,
    modifier: 0,
    total,
    description: `${total} damage dealt`
  }
}

export const createEnhancedMoveRoll = (
  moveName: string,
  dice: number[],
  modifier: number,
  moveId?: string
): Omit<RollResult, 'id' | 'timestamp'> => {
  const total = dice.reduce((sum, die) => sum + die, 0) + modifier
  let outcome: 'success' | 'partial' | 'failure' | undefined
  let description: string | undefined

  if (total >= 10) {
    outcome = 'success'
    description = `${moveName} succeeds! Choose from the full list of options.`
  } else if (total >= 7) {
    outcome = 'partial'
    description = `${moveName} partially succeeds. The GM will tell you what happens.`
  } else {
    outcome = 'failure'
    description = `${moveName} fails. The GM makes a move. Mark XP.`
  }

  return {
    type: 'move',
    title: moveName,
    dice,
    modifier,
    total,
    outcome,
    description
  }
}

/**
 * useEquipment Hook for ZimboMate V2
 * Equipment management with drag-and-drop, load calculations, and state tracking
 * Integrates EquipmentManagementService with character inventory
 */

import { useCallback, useMemo, useState } from 'react'
import { useCharacter } from './useCharacter'
import { useInventoryStore } from '../stores/inventoryStore'
import { equipmentManagementService } from '../services/EquipmentManagementService'
import { characterStateService } from '../services/CharacterStateService'
import type { Equipment } from '../models/Equipment'

export interface EquipmentWithState extends Equipment {
  equipped: boolean
  condition: 'perfect' | 'good' | 'worn' | 'damaged' | 'broken'
  charges?: number
  maxCharges?: number
  modifiers: Array<{
    type: 'stat' | 'damage' | 'armor' | 'special'
    value: number | string
    condition?: string
  }>
}

export interface LoadCalculation {
  current: number
  max: number
  percentage: number
  status: 'light' | 'normal' | 'heavy' | 'overloaded'
  breakdown: Array<{
    item: string
    weight: number
    category: 'equipped' | 'carried' | 'stored'
  }>
}

export interface DragDropContext {
  draggedItem: Equipment | null
  draggedFromSlot: string | null
  canDrop: (targetSlot: string) => boolean
  drop: (targetSlot: string) => void
  cancelDrag: () => void
}

export interface UseEquipmentReturn {
  // Character equipment
  allItems: EquipmentWithState[]
  equippedItems: EquipmentWithState[]
  carriedItems: EquipmentWithState[]
  storedItems: EquipmentWithState[]

  // Equipment by category
  weapons: EquipmentWithState[]
  armor: EquipmentWithState[]
  gear: EquipmentWithState[]
  consumables: EquipmentWithState[]

  // Load management
  loadCalculation: LoadCalculation
  canCarryMore: boolean
  weightToNextThreshold: number

  // Equipment operations
  equipItem: (itemId: string) => void
  unequipItem: (itemId: string) => void
  addItem: (item: Equipment) => void
  removeItem: (itemId: string) => void
  updateItemCondition: (itemId: string, condition: EquipmentWithState['condition']) => void
  updateItemCharges: (itemId: string, charges: number) => void

  // Equipment sets
  saveEquipmentSet: (name: string) => void
  loadEquipmentSet: (setId: string) => void
  availableEquipmentSets: Array<{
    id: string
    name: string
    itemCount: number
    totalWeight: number
  }>

  // Drag and drop
  dragDropContext: DragDropContext

  // Quick actions
  equipWeapon: (weaponId: string) => void
  equipArmor: (armorId: string) => void
  quickEquipSet: (setName: 'combat' | 'exploration' | 'social') => void

  // Character context
  character: any
  isLoading: boolean
  error: string | null
}

/**
 * Hook for managing character equipment
 * @param characterId - Character ID (optional, uses active character if not provided)
 */
export function useEquipment(characterId?: string): UseEquipmentReturn {
  const { character, updateLoad, isLoading, error } = useCharacter(characterId)
  const { 
    items, 
    addItem: storeAddItem, 
    removeItem: storeRemoveItem, 
    updateItem: storeUpdateItem,
    getItemsByCharacter,
  } = useInventoryStore()

  const [draggedItem, setDraggedItem] = useState<Equipment | null>(null)
  const [draggedFromSlot, setDraggedFromSlot] = useState<string | null>(null)

  // Get character's equipment with state
  const allItems = useMemo((): EquipmentWithState[] => {
    if (!character) return []

    const characterItems = getItemsByCharacter(character.id)
    const characterState = characterStateService.getCharacterState(character.id)

    return characterItems.map(item => {
      const equipmentState = characterState.equipment.find(eq => eq.itemId === item.id)

      return {
        ...item,
        equipped: equipmentState?.equipped || false,
        condition: equipmentState?.condition || 'good',
        charges: equipmentState?.charges,
        maxCharges: equipmentState?.maxCharges,
        modifiers: equipmentState?.modifiers || [],
      }
    })
  }, [character, getItemsByCharacter, items])

  // Categorize equipment
  const equippedItems = useMemo(() => 
    allItems.filter(item => item.equipped), [allItems])

  const carriedItems = useMemo(() => 
    allItems.filter(item => !item.equipped), [allItems])

  const storedItems = useMemo(() => 
    allItems.filter(item => item.tags?.includes('stored')), [allItems])

  const weapons = useMemo(() => 
    allItems.filter(item => item.category === 'weapon'), [allItems])

  const armor = useMemo(() => 
    allItems.filter(item => item.category === 'armor'), [allItems])

  const gear = useMemo(() => 
    allItems.filter(item => item.category === 'gear'), [allItems])

  const consumables = useMemo(() => 
    allItems.filter(item => item.category === 'consumable'), [allItems])

  // Load calculation
  const loadCalculation = useMemo((): LoadCalculation => {
    if (!character) {
      return {
        current: 0,
        max: 0,
        percentage: 0,
        status: 'light',
        breakdown: [],
      }
    }

    const calculation = equipmentManagementService.calculateLoad(character, allItems)

    return {
      current: calculation.currentLoad,
      max: calculation.maxLoad,
      percentage: calculation.loadPercentage,
      status: calculation.loadStatus as any,
      breakdown: calculation.breakdown.map(item => ({
        item: item.name,
        weight: item.weight,
        category: item.equipped ? 'equipped' : 'carried',
      })),
    }
  }, [character, allItems])

  const canCarryMore = useMemo(() => 
    loadCalculation.current < loadCalculation.max, [loadCalculation])

  const weightToNextThreshold = useMemo(() => {
    const { current, max } = loadCalculation
    const lightThreshold = max * 0.33
    const normalThreshold = max * 0.66

    if (current <= lightThreshold) return lightThreshold - current
    if (current <= normalThreshold) return normalThreshold - current
    return max - current
  }, [loadCalculation])

  // Equipment operations
  const equipItem = useCallback((itemId: string) => {
    if (!character) return

    const item = allItems.find(i => i.id === itemId)
    if (!item) return

    // Check if item can be equipped
    const canEquip = equipmentManagementService.canEquipItem(character, item, equippedItems)
    if (!canEquip.canEquip) return

    // Update equipment state
    characterStateService.updateCharacterState(character.id, {
      equipment: [
        ...characterStateService.getCharacterState(character.id).equipment.filter(eq => eq.itemId !== itemId),
        {
          itemId,
          equipped: true,
          condition: 'good',
          modifiers: item.modifiers || [],
        }
      ]
    })

    // Recalculate load
    const newLoad = equipmentManagementService.calculateLoad(character, allItems)
    updateLoad(newLoad.currentLoad)
  }, [character, allItems, equippedItems, updateLoad])

  const unequipItem = useCallback((itemId: string) => {
    if (!character) return

    const characterState = characterStateService.getCharacterState(character.id)
    const updatedEquipment = characterState.equipment.map(eq =>
      eq.itemId === itemId ? { ...eq, equipped: false } : eq
    )

    characterStateService.updateCharacterState(character.id, {
      equipment: updatedEquipment
    })

    // Recalculate load
    const newLoad = equipmentManagementService.calculateLoad(character, allItems)
    updateLoad(newLoad.currentLoad)
  }, [character, allItems, updateLoad])

  const addItem = useCallback((item: Equipment) => {
    if (!character) return

    const newItem = {
      ...item,
      characterId: character.id,
      id: `item-${Date.now()}-${Math.random().toString(36).slice(2, 11)}`,
    }

    storeAddItem(newItem)
  }, [character, storeAddItem])

  const removeItem = useCallback((itemId: string) => {
    storeRemoveItem(itemId)

    // Also remove from character state
    if (character) {
      const characterState = characterStateService.getCharacterState(character.id)
      const updatedEquipment = characterState.equipment.filter(eq => eq.itemId !== itemId)

      characterStateService.updateCharacterState(character.id, {
        equipment: updatedEquipment
      })
    }
  }, [character, storeRemoveItem])

  const updateItemCondition = useCallback((itemId: string, condition: EquipmentWithState['condition']) => {
    if (!character) return

    const characterState = characterStateService.getCharacterState(character.id)
    const updatedEquipment = characterState.equipment.map(eq =>
      eq.itemId === itemId ? { ...eq, condition } : eq
    )

    characterStateService.updateCharacterState(character.id, {
      equipment: updatedEquipment
    })
  }, [character])

  const updateItemCharges = useCallback((itemId: string, charges: number) => {
    if (!character) return

    const characterState = characterStateService.getCharacterState(character.id)
    const updatedEquipment = characterState.equipment.map(eq =>
      eq.itemId === itemId ? { ...eq, charges } : eq
    )

    characterStateService.updateCharacterState(character.id, {
      equipment: updatedEquipment
    })
  }, [character])

  // Equipment sets
  const saveEquipmentSet = useCallback((name: string) => {
    if (!character) return

    const equipmentSet = {
      id: `set-${Date.now()}`,
      name,
      characterId: character.id,
      items: equippedItems.map(item => ({
        itemId: item.id,
        equipped: true,
        condition: item.condition,
      })),
    }

    equipmentManagementService.saveEquipmentSet(equipmentSet)
  }, [character, equippedItems])

  const loadEquipmentSet = useCallback((setId: string) => {
    if (!character) return

    const equipmentSet = equipmentManagementService.getEquipmentSet(setId)
    if (!equipmentSet) return

    equipmentManagementService.applyEquipmentSet(character, equipmentSet)
  }, [character])

  const availableEquipmentSets = useMemo(() => {
    if (!character) return []

    return equipmentManagementService.getEquipmentSetsForCharacter(character.id)
      .map(set => ({
        id: set.id,
        name: set.name,
        itemCount: set.items.length,
        totalWeight: set.items.reduce((total, item) => {
          const equipment = allItems.find(eq => eq.id === item.itemId)
          return total + (equipment?.weight || 0)
        }, 0),
      }))
  }, [character, allItems])

  // Drag and drop
  const dragDropContext: DragDropContext = useMemo(() => ({
    draggedItem,
    draggedFromSlot,
    canDrop: (targetSlot: string) => {
      if (!draggedItem || !character) return false

      // Implement drop validation logic
      return equipmentManagementService.canEquipItem(character, draggedItem, equippedItems).canEquip
    },
    drop: (targetSlot: string) => {
      if (!draggedItem) return

      if (targetSlot === 'equipped') {
        equipItem(draggedItem.id)
      } else if (targetSlot === 'inventory') {
        unequipItem(draggedItem.id)
      }

      setDraggedItem(null)
      setDraggedFromSlot(null)
    },
    cancelDrag: () => {
      setDraggedItem(null)
      setDraggedFromSlot(null)
    },
  }), [draggedItem, draggedFromSlot, character, equippedItems, equipItem, unequipItem])

  // Quick actions
  const equipWeapon = useCallback((weaponId: string) => {
    // Unequip current weapon first
    const currentWeapon = equippedItems.find(item => item.category === 'weapon')
    if (currentWeapon) {
      unequipItem(currentWeapon.id)
    }

    equipItem(weaponId)
  }, [equippedItems, equipItem, unequipItem])

  const equipArmor = useCallback((armorId: string) => {
    // Unequip current armor first
    const currentArmor = equippedItems.find(item => item.category === 'armor')
    if (currentArmor) {
      unequipItem(currentArmor.id)
    }

    equipItem(armorId)
  }, [equippedItems, equipItem, unequipItem])

  const quickEquipSet = useCallback((setName: 'combat' | 'exploration' | 'social') => {
    // This would load predefined equipment sets
    const setId = `${character?.id}-${setName}`
    loadEquipmentSet(setId)
  }, [character, loadEquipmentSet])

  return {
    // Character equipment
    allItems,
    equippedItems,
    carriedItems,
    storedItems,

    // Equipment by category
    weapons,
    armor,
    gear,
    consumables,

    // Load management
    loadCalculation,
    canCarryMore,
    weightToNextThreshold,

    // Equipment operations
    equipItem,
    unequipItem,
    addItem,
    removeItem,
    updateItemCondition,
    updateItemCharges,

    // Equipment sets
    saveEquipmentSet,
    loadEquipmentSet,
    availableEquipmentSets,

    // Drag and drop
    dragDropContext,

    // Quick actions
    equipWeapon,
    equipArmor,
    quickEquipSet,

    // Character context
    character,
    isLoading,
    error,
  }
}

/**
 * useGameState Hook for ZimboMate V2
 * Global game state management - time, environment, party resources, and world events
 * Integrates gameStateStore with session and campaign management
 */

import { useCallback, useMemo } from 'react'
import { useGameStateStore } from '../stores/gameStateStore'
import { useSession } from './useSession'
import { useCampaign } from './useCampaign'
import type { GlobalEffect, GameTime, PartyResource } from '../stores/gameStateStore'

export interface TimeOfDay {
  hour: number
  minute: number
  period: 'dawn' | 'morning' | 'midday' | 'afternoon' | 'dusk' | 'evening' | 'night' | 'midnight'
  description: string
}

export interface Weather {
  condition: 'clear' | 'cloudy' | 'overcast' | 'light_rain' | 'heavy_rain' | 'storm' | 'fog' | 'snow'
  temperature: 'freezing' | 'cold' | 'cool' | 'mild' | 'warm' | 'hot' | 'scorching'
  wind: 'calm' | 'light' | 'moderate' | 'strong' | 'gale'
  visibility: 'clear' | 'reduced' | 'poor' | 'zero'
}

export interface Environment {
  location: string
  terrain: 'urban' | 'wilderness' | 'dungeon' | 'underground' | 'water' | 'air' | 'planar'
  lighting: 'bright' | 'dim' | 'dark' | 'magical'
  hazards: string[]
  features: string[]
}

export interface UseGameStateReturn {
  // Time management
  gameTime: GameTime
  timeOfDay: TimeOfDay
  advanceTime: (amount: number, unit: 'minutes' | 'hours' | 'days') => void
  setTime: (hour: number, minute: number, day: number) => void

  // Weather and environment
  weather: Weather
  environment: Environment
  updateWeather: (weather: Partial<Weather>) => void
  updateEnvironment: (environment: Partial<Environment>) => void

  // Global effects
  globalEffects: GlobalEffect[]
  addGlobalEffect: (effect: Omit<GlobalEffect, 'id'>) => void
  removeGlobalEffect: (effectId: string) => void
  updateGlobalEffect: (effectId: string, updates: Partial<GlobalEffect>) => void
  getActiveGlobalEffects: () => GlobalEffect[]

  // Party resources
  partyResources: PartyResource[]
  updatePartyResource: (resourceId: string, amount: number) => void
  addPartyResource: (resource: Omit<PartyResource, 'id'>) => void
  removePartyResource: (resourceId: string) => void

  // World events
  triggerWorldEvent: (eventType: string, description: string, effects?: any[]) => void
  getRecentWorldEvents: () => Array<{
    id: string
    type: string
    description: string
    timestamp: Date
    effects: any[]
  }>

  // Quick actions
  shortRest: () => void
  longRest: () => void
  advanceDay: () => void
  changeLocation: (location: string, terrain?: Environment['terrain']) => void

  // State queries
  isDay: boolean
  isNight: boolean
  canSeeStars: boolean
  needsLight: boolean

  // Utility
  isLoading: boolean
  error: string | null
}

/**
 * Hook for managing global game state
 */
export function useGameState(): UseGameStateReturn {
  const {
    gameTime,
    environment,
    globalEffects,
    partyResources,
    worldEvents,
    updateGameTime,
    updateWeather: storeUpdateWeather,
    updateEnvironment: storeUpdateEnvironment,
    addGlobalEffect: storeAddGlobalEffect,
    removeGlobalEffect: storeRemoveGlobalEffect,
    updateGlobalEffect: storeUpdateGlobalEffect,
    updatePartyResource: storeUpdatePartyResource,
    addPartyResource: storeAddPartyResource,
    removePartyResource: storeRemovePartyResource,
    addWorldEvent,
    isLoading,
    error,
  } = useGameStateStore()

  const { advanceTime: sessionAdvanceTime } = useSession()
  const { currentCampaign } = useCampaign()

  // Time of day calculation
  const timeOfDay = useMemo((): TimeOfDay => {
    const hour = gameTime.hour
    const minute = gameTime.minute

    let period: TimeOfDay['period']
    let description: string

    if (hour >= 5 && hour < 7) {
      period = 'dawn'
      description = 'The sun rises, painting the sky in soft colors'
    } else if (hour >= 7 && hour < 12) {
      period = 'morning'
      description = 'The morning sun climbs higher in the sky'
    } else if (hour >= 12 && hour < 13) {
      period = 'midday'
      description = 'The sun reaches its zenith overhead'
    } else if (hour >= 13 && hour < 17) {
      period = 'afternoon'
      description = 'The afternoon sun begins its descent'
    } else if (hour >= 17 && hour < 19) {
      period = 'dusk'
      description = 'The sun sets, casting long shadows'
    } else if (hour >= 19 && hour < 22) {
      period = 'evening'
      description = 'Twilight settles over the land'
    } else if (hour >= 22 || hour < 1) {
      period = 'night'
      description = 'Night has fallen, stars twinkle above'
    } else {
      period = 'midnight'
      description = 'The deepest part of night, when shadows reign'
    }

    return { hour, minute, period, description }
  }, [gameTime])

  // State queries
  const isDay = useMemo(() => {
    const hour = gameTime.hour
    return hour >= 6 && hour < 18
  }, [gameTime.hour])

  const isNight = useMemo(() => !isDay, [isDay])

  // Derive weather object from environment (store shape uses environment.weather as string)
  const weather: Weather = useMemo(() => {
    const rawCondition = (environment as any)?.weather ?? 'clear'
    const normalized = String(rawCondition).toLowerCase().replace(/\s+/g, '_') as Weather['condition']
    const validConditions: ReadonlyArray<Weather['condition']> = [
      'clear',
      'cloudy',
      'overcast',
      'light_rain',
      'heavy_rain',
      'storm',
      'fog',
      'snow',
    ]
    const condition = (validConditions as readonly string[]).includes(normalized)
      ? (normalized as Weather['condition'])
      : 'clear'

    const temp = ((environment as any)?.temperature ?? 'mild') as Weather['temperature']

    return {
      condition,
      temperature: temp,
      wind: 'calm',
      visibility: 'clear',
    }
  }, [environment])

  const canSeeStars = useMemo(() => {
    return isNight && weather.condition !== 'overcast' && weather.condition !== 'storm'
  }, [isNight, weather.condition])

  const needsLight = useMemo(() => {
    return (isNight || environment.lighting === 'dark') && environment.lighting !== 'magical'
  }, [isNight, environment.lighting])

  // Time management
  const advanceTime = useCallback((amount: number, unit: 'minutes' | 'hours' | 'days') => {
    let totalMinutes = 0

    switch (unit) {
      case 'minutes':
        totalMinutes = amount
        break
      case 'hours':
        totalMinutes = amount * 60
        break
      case 'days':
        totalMinutes = amount * 24 * 60
        break
    }

    const newMinute = (gameTime.minute + totalMinutes) % 60
    const newHour = (gameTime.hour + Math.floor((gameTime.minute + totalMinutes) / 60)) % 24
    const newDay = gameTime.day + Math.floor((gameTime.hour * 60 + gameTime.minute + totalMinutes) / (24 * 60))

    updateGameTime({
      minute: newMinute,
      hour: newHour,
      day: newDay,
    })

    // Advance session time as well
    sessionAdvanceTime('turn')
  }, [gameTime, updateGameTime, sessionAdvanceTime])

  const setTime = useCallback((hour: number, minute: number, day: number) => {
    updateGameTime({ hour, minute, day })
  }, [updateGameTime])

  // Weather and environment
  const updateWeather = useCallback((weatherUpdates: Partial<Weather>) => {
    storeUpdateWeather(weatherUpdates)
  }, [storeUpdateWeather])

  const updateEnvironment = useCallback((environmentUpdates: Partial<Environment>) => {
    storeUpdateEnvironment(environmentUpdates)
  }, [storeUpdateEnvironment])

  // Global effects
  const addGlobalEffect = useCallback((effect: Omit<GlobalEffect, 'id'>) => {
    storeAddGlobalEffect(effect)
  }, [storeAddGlobalEffect])

  const removeGlobalEffect = useCallback((effectId: string) => {
    storeRemoveGlobalEffect(effectId)
  }, [storeRemoveGlobalEffect])

  const updateGlobalEffect = useCallback((effectId: string, updates: Partial<GlobalEffect>) => {
    storeUpdateGlobalEffect(effectId, updates)
  }, [storeUpdateGlobalEffect])

  const getActiveGlobalEffects = useCallback(() => {
    return globalEffects.filter(effect => {
      if (effect.duration === 'permanent') return true
      if (typeof effect.duration === 'number') return effect.duration > 0
      return true // Scene/encounter effects are active until removed
    })
  }, [globalEffects])

  // Party resources
  const updatePartyResource = useCallback((resourceId: string, amount: number) => {
    storeUpdatePartyResource(resourceId, amount)
  }, [storeUpdatePartyResource])

  const addPartyResource = useCallback((resource: Omit<PartyResource, 'id'>) => {
    storeAddPartyResource(resource)
  }, [storeAddPartyResource])

  const removePartyResource = useCallback((resourceId: string) => {
    storeRemovePartyResource(resourceId)
  }, [storeRemovePartyResource])

  // World events
  const triggerWorldEvent = useCallback((eventType: string, description: string, effects: any[] = []) => {
    addWorldEvent({
      type: eventType,
      description,
      effects,
    })
  }, [addWorldEvent])

  const getRecentWorldEvents = useCallback(() => {
    return worldEvents
      .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())
      .slice(0, 10)
  }, [worldEvents])

  // Quick actions
  const shortRest = useCallback(() => {
    // Advance time by 1 hour
    advanceTime(1, 'hours')

    // Trigger short rest effects
    triggerWorldEvent('short_rest', 'The party takes a short rest', [
      { type: 'heal', amount: 'partial' },
      { type: 'refresh', resources: ['short_rest'] }
    ])
  }, [advanceTime, triggerWorldEvent])

  const longRest = useCallback(() => {
    // Advance time by 8 hours
    advanceTime(8, 'hours')

    // Trigger long rest effects
    triggerWorldEvent('long_rest', 'The party takes a long rest', [
      { type: 'heal', amount: 'full' },
      { type: 'refresh', resources: ['all'] },
      { type: 'clear', effects: ['temporary'] }
    ])

    // Clear temporary global effects
    const temporaryEffects = globalEffects.filter(effect => 
      effect.duration !== 'permanent' && typeof effect.duration !== 'number'
    )
    temporaryEffects.forEach(effect => removeGlobalEffect(effect.id))
  }, [advanceTime, triggerWorldEvent, globalEffects, removeGlobalEffect])

  const advanceDay = useCallback(() => {
    advanceTime(1, 'days')
    triggerWorldEvent('new_day', 'A new day begins', [])
  }, [advanceTime, triggerWorldEvent])

  const changeLocation = useCallback((location: string, terrain: Environment['terrain'] = 'wilderness') => {
    updateEnvironment({ location, terrain })
    triggerWorldEvent('location_change', `The party arrives at ${location}`, [
      { type: 'location', name: location, terrain }
    ])
  }, [updateEnvironment, triggerWorldEvent])

  return {
    // Time management
    gameTime,
    timeOfDay,
    advanceTime,
    setTime,

    // Weather and environment
    weather,
    environment,
    updateWeather,
    updateEnvironment,

    // Global effects
    globalEffects,
    addGlobalEffect,
    removeGlobalEffect,
    updateGlobalEffect,
    getActiveGlobalEffects,

    // Party resources
    partyResources,
    updatePartyResource,
    addPartyResource,
    removePartyResource,

    // World events
    triggerWorldEvent,
    getRecentWorldEvents,

    // Quick actions
    shortRest,
    longRest,
    advanceDay,
    changeLocation,

    // State queries
    isDay,
    isNight,
    canSeeStars,
    needsLight,

    // Utility
    isLoading,
    error,
  }
}

/**
 * Simplified game state hook for basic time and environment queries
 */
export function useSimpleGameState() {
  const {
    timeOfDay,
    weather,
    environment,
    isDay,
    isNight,
    needsLight,
    advanceTime,
    shortRest,
    longRest,
  } = useGameState()

  return {
    time: timeOfDay,
    weather,
    location: environment.location,
    isDay,
    isNight,
    needsLight,
    advanceTime,
    shortRest,
    longRest,
  }
}

/**
 * useMove Hook for ZimboMate V2
 * Execute Dungeon World moves with full integration
 * Handles move selection, execution, outcomes, and follow-up effects
 */

import { useCallback, useMemo, useState } from 'react'
import { useActiveCharacter } from './useActiveCharacter'
import { useDiceRoll } from './useDiceRoll'
import { moveCompendiumService } from '../services/MoveCompendiumService'
import type { CompendiumMove } from '../services/MoveCompendiumService'
import type { Attribute } from '../models/Character'

export interface MoveExecutionContext {
  characterId: string
  moveId: string
  selectedOptions?: string[]
  customModifier?: number
  targetCharacterId?: string
  description?: string
}

export interface MoveExecutionResult {
  move: CompendiumMove
  rollResult: any // From useDiceRoll
  outcome: 'success' | 'partial' | 'failure'
  effects: Array<{
    type: 'condition' | 'modifier' | 'resource' | 'damage' | 'healing'
    target: string
    value: any
    description: string
  }>
  followUpOptions?: Array<{
    id: string
    name: string
    description: string
    action: () => void
  }>
}

export interface UseMoveReturn {
  // Move library
  allMoves: CompendiumMove[]
  basicMoves: CompendiumMove[]
  specialMoves: CompendiumMove[]
  classMoves: CompendiumMove[]

  // Move selection
  selectedMove: CompendiumMove | null
  selectMove: (moveId: string) => void
  clearSelection: () => void

  // Move execution
  executeMove: (context: MoveExecutionContext) => Promise<MoveExecutionResult>
  executeSelectedMove: (options?: {
    customModifier?: number
    selectedOptions?: string[]
    description?: string
  }) => Promise<MoveExecutionResult>

  // Quick move execution
  hackAndSlash: (modifier?: number) => Promise<MoveExecutionResult>
  volley: (modifier?: number) => Promise<MoveExecutionResult>
  defy: (stat: keyof Attribute, modifier?: number) => Promise<MoveExecutionResult>
  aid: (targetCharacterId: string, modifier?: number) => Promise<MoveExecutionResult>
  interfere: (targetCharacterId: string, modifier?: number) => Promise<MoveExecutionResult>

  // Move search and filtering
  searchMoves: (query: string) => CompendiumMove[]
  getMovesForClass: (className: string) => CompendiumMove[]
  getMovesForStat: (stat: keyof Attribute) => CompendiumMove[]

  // Move state
  isExecuting: boolean
  lastExecution: MoveExecutionResult | null

  // Character context
  activeCharacter: any
  availableMoves: CompendiumMove[]

  // Utility
  canExecuteMove: (moveId: string) => boolean
  getMovePrerequisites: (moveId: string) => string[]
}

/**
 * Hook for managing Dungeon World moves
 */
export function useMove(): UseMoveReturn {
  const { activeCharacter } = useActiveCharacter()
  const { roll } = useDiceRoll()

  const [selectedMove, setSelectedMove] = useState<CompendiumMove | null>(null)
  const [isExecuting, setIsExecuting] = useState(false)
  const [lastExecution, setLastExecution] = useState<MoveExecutionResult | null>(null)

  // Get all moves from the compendium
  const allMoves = useMemo(() => {
    return moveCompendiumService.getAllMoves()
  }, [])

  // Categorize moves
  const basicMoves = useMemo(() => {
    return allMoves.filter(move => move.type === 'basic')
  }, [allMoves])

  const specialMoves = useMemo(() => {
    return allMoves.filter(move => move.type === 'special')
  }, [allMoves])

  const classMoves = useMemo(() => {
    if (!activeCharacter) return []
    return allMoves.filter(move => 
      move.type === 'class' && 
      move.classes?.includes(activeCharacter.class.toLowerCase())
    )
  }, [allMoves, activeCharacter])

  // Available moves for the active character
  const availableMoves = useMemo(() => {
    if (!activeCharacter) return []

    return allMoves.filter(move => {
      // Basic moves are always available
      if (move.type === 'basic') return true

      // Special moves are situational
      if (move.type === 'special') return true

      // Class moves must match character class
      if (move.type === 'class') {
        return move.classes?.includes(activeCharacter.class.toLowerCase()) || false
      }
    return false
    })
  }, [allMoves, activeCharacter])

  // Move selection
  const selectMove = useCallback((moveId: string) => {
    const move = moveCompendiumService.getMove(moveId)
    setSelectedMove(move || null)
  }, [])

  const clearSelection = useCallback(() => {
    setSelectedMove(null)
  }, [])

  // Main move execution function
  const executeMove = useCallback(async (context: MoveExecutionContext): Promise<MoveExecutionResult> => {
    if (!activeCharacter) {
      throw new Error('No active character')
    }

    setIsExecuting(true)

    try {
      const move = moveCompendiumService.getMove(context.moveId)
      if (!move) {
        throw new Error(`Move not found: ${context.moveId}`)
      }

      // Determine the stat to roll with
      const rollStat = move.stat as keyof Attribute | undefined

      // Execute the roll
      const rollResult = await roll({
        stat: rollStat,
        modifier: context.customModifier,
        moveId: context.moveId,
        moveName: move.name,
        description: context.description || `${move.name} move`,
        characterId: context.characterId,
      })

      // Determine outcome
      const outcome = rollResult.result as 'success' | 'partial' | 'failure'

      // Apply move effects based on outcome
      const effects = await applyMoveEffects(move, outcome, rollResult, context)

      // Create follow-up options if needed
      const followUpOptions = createFollowUpOptions(move, outcome, context)

      const result: MoveExecutionResult = {
        move,
        rollResult,
        outcome,
        effects,
        followUpOptions,
      }

      setLastExecution(result)
      return result

    } finally {
      setIsExecuting(false)
    }
  }, [activeCharacter, roll])

  // Execute selected move
  const executeSelectedMove = useCallback(async (options = {}) => {
    if (!selectedMove || !activeCharacter) {
      throw new Error('No move selected or no active character')
    }
    return executeMove({
      characterId: activeCharacter.id,
      moveId: selectedMove.id,
      ...options,
    })
  }, [selectedMove, activeCharacter, executeMove])

  // Quick move execution functions
  const hackAndSlash = useCallback(async (modifier = 0) => {
    const hackAndSlashMove = allMoves.find(m => m.name.toLowerCase().includes('hack and slash'))
    if (!hackAndSlashMove || !activeCharacter) {
      throw new Error('Hack and Slash move not found or no active character')
    }
    return executeMove({
      characterId: activeCharacter.id,
      moveId: hackAndSlashMove.id,
      customModifier: modifier,
    })
  }, [allMoves, activeCharacter, executeMove])

  const volley = useCallback(async (modifier = 0) => {
    const volleyMove = allMoves.find(m => m.name.toLowerCase().includes('volley'))
    if (!volleyMove || !activeCharacter) {
      throw new Error('Volley move not found or no active character')
    }
    return executeMove({
      characterId: activeCharacter.id,
      moveId: volleyMove.id,
      customModifier: modifier,
    })
  }, [allMoves, activeCharacter, executeMove])

  const defy = useCallback(async (stat: keyof Attribute, modifier = 0) => {
    const defyMove = allMoves.find(m => m.name.toLowerCase().includes('defy danger'))
    if (!defyMove || !activeCharacter) {
      throw new Error('Defy Danger move not found or no active character')
    }
    return executeMove({
      characterId: activeCharacter.id,
      moveId: defyMove.id,
      customModifier: modifier,
      description: `Defy Danger with ${stat}`,
    })
  }, [allMoves, activeCharacter, executeMove])

  const aid = useCallback(async (targetCharacterId: string, modifier = 0) => {
    const aidMove = allMoves.find(m => m.name.toLowerCase().includes('aid'))
    if (!aidMove || !activeCharacter) {
      throw new Error('Aid move not found or no active character')
    }
    return executeMove({
      characterId: activeCharacter.id,
      moveId: aidMove.id,
      targetCharacterId,
      customModifier: modifier,
    })
  }, [allMoves, activeCharacter, executeMove])

  const interfere = useCallback(async (targetCharacterId: string, modifier = 0) => {
    const interfereMove = allMoves.find(m => m.name.toLowerCase().includes('interfere'))
    if (!interfereMove || !activeCharacter) {
      throw new Error('Interfere move not found or no active character')
    }
    return executeMove({
      characterId: activeCharacter.id,
      moveId: interfereMove.id,
      targetCharacterId,
      customModifier: modifier,
    })
  }, [allMoves, activeCharacter, executeMove])

  // Search and filtering
  const searchMoves = useCallback((query: string) => {
    return moveCompendiumService.searchMoves({ query })
  }, [])

  const getMovesForClass = useCallback((className: string) => {
    return allMoves.filter(move => 
      move.classes?.includes(className.toLowerCase())
    )
  }, [allMoves])

  const getMovesForStat = useCallback((stat: keyof Attribute) => {
    return allMoves.filter(move => move.stat === stat)
  }, [allMoves])

  // Utility functions
  const canExecuteMove = useCallback((moveId: string) => {
    if (!activeCharacter) return false

    const move = moveCompendiumService.getMove(moveId)
    if (!move) return false

    // Check prerequisites
    const validation = moveCompendiumService.validateMoveExecution(move, activeCharacter)
    return validation.canExecute
  }, [activeCharacter])

  const getMovePrerequisites = useCallback((moveId: string) => {
    const move = moveCompendiumService.getMove(moveId)
    if (!move || !activeCharacter) return []

    const validation = moveCompendiumService.validateMoveExecution(move, activeCharacter)
    return validation.missingPrerequisites
  }, [activeCharacter])

  return {
    // Move library
    allMoves,
    basicMoves,
    specialMoves,
    classMoves,

    // Move selection
    selectedMove,
    selectMove,
    clearSelection,

    // Move execution
    executeMove,
    executeSelectedMove,

    // Quick move execution
    hackAndSlash,
    volley,
    defy,
    aid,
    interfere,

    // Move search and filtering
    searchMoves,
    getMovesForClass,
    getMovesForStat,

    // Move state
    isExecuting,
    lastExecution,

    // Character context
    activeCharacter,
    availableMoves,

    // Utility
    canExecuteMove,
    getMovePrerequisites,
  }
}

