/**
 * useSpells Hook for ZimboMate V2
 * Authentic Dungeon World spell preparation and casting system
 * No spell slots - uses DW's prepare/cast mechanics
 */

import { useCallback, useMemo, useState } from 'react'
import { useCharacter } from './useCharacter'
import { useDiceRoll } from './useDiceRoll'
import { allDWSpells, dwWizardSpells, dwClericSpells, DWSpellClass } from '../spellBookMockData'

export interface DWSpell {
  id: string
  name: string
  level: number
  class: 'wizard' | 'cleric'
  range: string
  ongoing: boolean
  description: string
  preparationStatus: 'available' | 'prepared' | 'cast'
}

export interface SpellCastingResult {
  success: boolean
  roll?: number
  modifier?: number
  total?: number
  result: 'success' | 'partial' | 'failure'
  description: string
  animationTrigger?: {
    type: 'success' | 'partial' | 'failure'
    spellLevel: number
    spellClass: string
    particleColor: string
  }
}

export interface UseDWSpellsReturn {
  // Character spell info
  spellcastingClass: 'wizard' | 'cleric' | null
  canCastSpells: boolean
  characterLevel: number

  // Spell library (DW system)
  allSpells: DWSpell[]
  availableSpells: DWSpell[]
  preparedSpells: DWSpell[]
  castSpells: DWSpell[] // Spells already cast today

  // DW spell preparation (no slots!)
  maxPreparedSpells: number
  preparedCount: number
  canPrepareMore: boolean

  // Actions
  prepareSpell: (spellId: string) => boolean
  unprepareSpell: (spellId: string) => boolean
  castSpell: (spellId: string) => Promise<SpellCastingResult>
  restoreSpells: () => void // Long rest equivalent

  // Character progression
  getSpellsForLevel: (level: number) => DWSpell[]
  canLearnSpell: (spellId: string) => boolean
}

export const useDWSpells = (): UseDWSpellsReturn => {
  const { character } = useCharacter()
  const { rollDice } = useDiceRoll()

  const [preparedSpellIds, setPreparedSpellIds] = useState<string[]>([
    'light', 'magic-missile', 'cure-light-wounds', 'guidance'
  ])
  const [castSpellIds, setCastSpellIds] = useState<string[]>([])

  // Determine spellcasting class
  const spellcastingClass = useMemo((): 'wizard' | 'cleric' | null => {
    if (!character?.class) return null
    if (character.class.toLowerCase() === 'wizard') return 'wizard'
    if (character.class.toLowerCase() === 'cleric') return 'cleric'
    return null
  }, [character?.class])

  const canCastSpells = spellcastingClass !== null
  const characterLevel = character?.level || 1

  // DW spell system calculations - CORRECTED TO USE SPELL LEVELS NOT SPELL COUNT
  const maxPreparedSpellLevels = useMemo(() => {
    if (!spellcastingClass) return 0

    if (spellcastingClass === 'wizard') {
      // CORRECTED: Wizards prepare spell LEVELS totaling Level + 1 (not individual spells)
      return characterLevel + 1
    } else if (spellcastingClass === 'cleric') {
      // Clerics get access to all spells of their level, but limited daily casts
      // For simplicity, we'll say they can "prepare" Level + Wisdom modifier spell levels
      const wisModifier = character?.stats?.wisdom ?
        Math.floor((character.stats.wisdom - 10) / 2) : 0
      return characterLevel + Math.max(1, wisModifier)
    }

    return 0
  }, [spellcastingClass, characterLevel, character?.stats?.wisdom])

  // Calculate total spell levels currently prepared
  const preparedSpellLevels = useMemo(() => {
    return preparedSpellIds.reduce((total, spellId) => {
      const spell = availableSpells.find(s => s.id === spellId)
      return total + (spell?.level || 0)
    }, 0)
  }, [preparedSpellIds, availableSpells])

  // Get spells available to this class and level
  const availableSpells = useMemo(() => {
    if (!spellcastingClass) return []

    const classSpells = spellcastingClass === 'wizard' ? dwWizardSpells : dwClericSpells

    // Can access spells of current level and below
    return classSpells.filter(spell => spell.level <= characterLevel)
      .map(spell => ({
        ...spell,
        preparationStatus: preparedSpellIds.includes(spell.id) ?
          (castSpellIds.includes(spell.id) ? 'cast' : 'prepared') :
          'available'
      })) as DWSpell[]
  }, [spellcastingClass, characterLevel, preparedSpellIds, castSpellIds])

  const preparedSpells = availableSpells.filter(spell =>
    preparedSpellIds.includes(spell.id) && !castSpellIds.includes(spell.id)
  )

  const castSpells = availableSpells.filter(spell =>
    castSpellIds.includes(spell.id)
  )

  const preparedCount = preparedSpellIds.length
  // CORRECTED: Check if we can prepare more based on spell LEVELS not spell COUNT
  const canPrepareSpell = (spellLevel: number) => {
    return preparedSpellLevels + spellLevel <= maxPreparedSpellLevels
  }

  // Spell actions - CORRECTED to use spell level validation
  const prepareSpell = useCallback((spellId: string): boolean => {
    const spell = availableSpells.find(s => s.id === spellId)
    if (!spell || preparedSpellIds.includes(spellId)) return false

    // Check if we have enough spell level capacity
    if (!canPrepareSpell(spell.level)) return false

    setPreparedSpellIds(prev => [...prev, spellId])
    return true
  }, [availableSpells, preparedSpellIds, canPrepareSpell])

  const unprepareSpell = useCallback((spellId: string): boolean => {
    if (!preparedSpellIds.includes(spellId)) return false

    setPreparedSpellIds(prev => prev.filter(id => id !== spellId))
    // Also remove from cast if it was cast
    setCastSpellIds(prev => prev.filter(id => id !== spellId))
    return true
  }, [preparedSpellIds])

  const castSpell = useCallback(async (spellId: string): Promise<SpellCastingResult> => {
    const spell = availableSpells.find(s => s.id === spellId)

    if (!spell) {
      return {
        success: false,
        result: 'failure',
        description: 'Spell not found'
      }
    }

    if (!preparedSpellIds.includes(spellId)) {
      return {
        success: false,
        result: 'failure',
        description: 'Spell not prepared'
      }
    }

    if (castSpellIds.includes(spellId)) {
      return {
        success: false,
        result: 'failure',
        description: 'Spell already cast today'
      }
    }

    // DW uses Cast a Spell move for most spells (roll+INT for wizard, roll+WIS for cleric)
    const stat = spellcastingClass === 'wizard' ? 'intelligence' : 'wisdom'
    const statValue = character?.stats?.[stat as keyof typeof character.stats] || 10
    const modifier = Math.floor((statValue - 10) / 2)

    const rollResult = rollDice(`2d6+${modifier}`)
    const total = rollResult.total

    let result: 'success' | 'partial' | 'failure'
    let description: string
    let success: boolean

    if (total >= 10) {
      result = 'success'
      success = true
      description = `${spell.name} cast successfully! ${spell.description}`
    } else if (total >= 7) {
      result = 'partial'
      success = true
      description = `${spell.name} cast with complications. The GM will describe what happens.`
    } else {
      result = 'failure'
      success = false
      description = `${spell.name} fails to take hold. The GM makes a move.`
    }

    // Mark spell as cast (DW spells can usually only be cast once per day when prepared)
    setCastSpellIds(prev => [...prev, spellId])

    return {
      success,
      roll: rollResult.rolls[0],
      modifier,
      total,
      result,
      description,
      animationTrigger: {
        type: result,
        spellLevel: spell.level,
        spellClass: spell.class,
        particleColor: spell.class === 'wizard' ? '#8B5CF6' : '#F59E0B'
      }
    }
  }, [availableSpells, preparedSpellIds, castSpellIds, spellcastingClass, character, rollDice])

  const restoreSpells = useCallback(() => {
    // DW "Make Camp" equivalent - restore all cast spells
    setCastSpellIds([])
  }, [])

  const getSpellsForLevel = useCallback((level: number) => {
    return availableSpells.filter(spell => spell.level === level)
  }, [availableSpells])

  const canLearnSpell = useCallback((spellId: string): boolean => {
    const spell = allDWSpells.find(s => s.id === spellId)
    if (!spell) return false

    // Must be the right class and level
    if (spell.class !== spellcastingClass) return false
    if (spell.level > characterLevel) return false

    return true
  }, [spellcastingClass, characterLevel])

  return {
    spellcastingClass,
    canCastSpells,
    characterLevel,

    allSpells: allDWSpells as DWSpell[],
    availableSpells,
    preparedSpells,
    castSpells,

    // CORRECTED: Return spell level information instead of spell count
    maxPreparedSpellLevels,
    preparedSpellLevels,
    preparedCount, // Keep for backward compatibility
    canPrepareSpell, // New function that takes spell level

    prepareSpell,
    unprepareSpell,
    castSpell,
    restoreSpells,

    getSpellsForLevel,
    canLearnSpell
  }
}

// Keep the old export name for backwards compatibility, but use the new DW system
export const useSpells = useDWSpells

/**
 * Overall game state management for Dungeon World
 */

import type { Campaign } from './Campaign'
import type { Character } from './Character'
import type { ActiveCondition } from './Conditions'
import type { Inventory } from './Inventory'
import type { ModifierSet, TemporaryModifier } from './Modifiers'
import type { Move } from './Move'
import type { Session } from './Session'
import type { SpellPreparation } from './Spell'
import { createEmptyInventory } from './Inventory'

// Application-wide settings
export interface AppSettings {
  theme: 'light' | 'dark'
  autoSave: boolean
  autoSaveInterval: number // minutes
  showRollAnimations: boolean
  confirmDangerousActions: boolean
  keyboardShortcuts: Record<string, string>
  integration?: {
    contextMenuEnabled: boolean
    tooltipDelayMs: number
    highContrastMenu: boolean
    suspendShortcutsOnDialog: boolean
    overlayEnabled: boolean
  }
  conditionalContent?: {
    global: {
      preferClassRelevant: boolean
      showAllMoves: boolean
      showAllEquipment: boolean
      showSpellsForNonCasters: boolean
    }
    perPanel: {
      moves: { overrideEnabled: boolean; showAll: boolean }
      equipment: { overrideEnabled: boolean; showAll: boolean }
      stats: { overrideEnabled: boolean; showSpells: boolean }
    }
  }
  sidebarPrefs?: {
    favorites: string[]
    collapsedSections: string[]
    order: string[]
    recents: string[]
  }
}

// Complete game state
export interface GameState {
  // Core data
  characters: Record <string, Character> // Multiple characters by ID
  activeCharacterId: string | null // Currently active character
  inventories: Record <string, Inventory> // Inventory per character
  moves: Move[]
  customMoves: Move[]
  session: Session

  // Advanced features
  spellPreparations: Record <string, SpellPreparation> // Spell prep per character
  modifiers: ModifierSet
  conditions: ActiveCondition[]
  campaign: Campaign | null

  // UI state
  ui: {
    activePanel: string
    sidePanelOpen: boolean
    auxiliaryDrawerOpen: boolean
    modalStack: string[]
    panelState?: Record<string, any>
  }

  // App settings
  settings: AppSettings

  // Metadata
  version: string
  lastSaved: Date | null
  isDirty: boolean // Has unsaved changes
}

// Action types for state updates
export type GameStateAction
  = | { type: 'ADD_CHARACTER', payload: Character }
    | { type: 'UPDATE_CHARACTER', payload: { id: string, updates: Partial <Character> } }
    | { type: 'REMOVE_CHARACTER', payload: string }
    | { type: 'SET_ACTIVE_CHARACTER', payload: string }
    | { type: 'SET_CHARACTER', payload: Character } // Legacy support
    | { type: 'SET_INVENTORY', payload: { characterId: string, inventory: Inventory } }
    | { type: 'UPDATE_INVENTORY', payload: { characterId: string, updates: Partial <Inventory> } }
    | { type: 'ADD_MOVE', payload: Move }
    | { type: 'UPDATE_MOVE', payload: { id: string, changes: Partial <Move> } }
    | { type: 'REMOVE_MOVE', payload: string }
    | { type: 'SET_SESSION', payload: Session }
    | { type: 'UPDATE_SESSION', payload: Partial <Session> }
    | { type: 'SET_UI_STATE', payload: Partial <GameState['ui']> }
    | { type: 'SET_SETTINGS', payload: Partial <AppSettings> }
    | { type: 'ADD_MODIFIER', payload: TemporaryModifier }
    | { type: 'REMOVE_MODIFIER', payload: string }
    | { type: 'UPDATE_MODIFIER', payload: { id: string, updates: Partial <TemporaryModifier> } }
    | { type: 'SET_MODIFIERS', payload: ModifierSet }
    | { type: 'CLEAR_MODIFIERS' }
    | { type: 'MARK_SAVED' }
    | { type: 'MARK_DIRTY' }
    | { type: 'RESET_STATE' }
    | { type: 'REPLACE_STATE', payload: GameState }
    | { type: 'LOAD_STATE', payload: GameState }

// Utility functions

/**
 * Create initial game state
 */
export function createInitialGameState(): GameState {
  return {
    characters: {},
    activeCharacterId: null,
    inventories: {},
    moves: [],
    customMoves: [],
    session: {
      id: generateId(),
      startTime: new Date(),
      notes: [],
      rollHistory: [],
      events: [],
      trackers: [],
      bookmarks: [],
    },
    spellPreparations: {},
    modifiers: {
      modifiers: [],
      lastUpdated: new Date(),
    },
    conditions: [],
    campaign: null,
    ui: {
      activePanel: 'character',
      sidePanelOpen: true,
      auxiliaryDrawerOpen: false,
      modalStack: [],
      panelState: {},
    },
    settings: {
      theme: 'light',
      autoSave: true,
      autoSaveInterval: 5,
      showRollAnimations: true,
      confirmDangerousActions: true,
      keyboardShortcuts: {
        rollDamage: 'd',
        rollStat: 'r',
        quickSave: 'ctrl + s',
        toggleDrawer: 'ctrl + d',
      },
      integration: {
        contextMenuEnabled: true,
        tooltipDelayMs: 0,
        highContrastMenu: false,
        suspendShortcutsOnDialog: true,
        overlayEnabled: true,
      },
      conditionalContent: {
        global: {
          preferClassRelevant: true,
          showAllMoves: false,
          showAllEquipment: false,
          showSpellsForNonCasters: false,
        },
        perPanel: {
          moves: { overrideEnabled: false, showAll: false },
          equipment: { overrideEnabled: false, showAll: false },
          stats: { overrideEnabled: false, showSpells: false },
        },
      },
      sidebarPrefs: {
        favorites: [],
        collapsedSections: [],
        order: [],
        recents: [],
      },
    },
    version: '1.0.0',
    lastSaved: null,
    isDirty: false,
  }
}

/**
 * Game state reducer
 */
export function gameStateReducer(
  state: GameState,
  action: GameStateAction,
): GameState {
  switch (action.type) {
    case 'ADD_CHARACTER': {
      const charId = action.payload.id
      return {
        ...state,
        characters: {
          ...state.characters,
          [charId]: action.payload,
        },
        inventories: {
          ...state.inventories,
          [charId]: createEmptyInventory(),
        },
        activeCharacterId: state.activeCharacterId || charId,
        isDirty: true,
      }
    }

    case 'UPDATE_CHARACTER': {
      const { id, updates } = action.payload
      if (!state.characters[id])
        return state
      return {
        ...state,
        characters: {
          ...state.characters,
          [id]: {
            ...state.characters[id],
            ...updates,
            updatedAt: new Date(),
          },
        },
        isDirty: true,
      }
    }

    case 'REMOVE_CHARACTER': {
      const newCharacters = { ...state.characters }
      const newInventories = { ...state.inventories }
      delete newCharacters[action.payload]
      delete newInventories[action.payload]

      const remainingIds = Object.keys(newCharacters)
      const newActiveId = state.activeCharacterId === action.payload
        ? (remainingIds.length > 0 ? remainingIds[0] : null)
        : state.activeCharacterId

      return {
        ...state,
        characters: newCharacters,
        inventories: newInventories,
        activeCharacterId: newActiveId,
        isDirty: true,
      }
    }

    case 'SET_ACTIVE_CHARACTER':
      return {
        ...state,
        activeCharacterId: action.payload,
        isDirty: true,
      }

    case 'SET_CHARACTER': {
      // Legacy support-adds character and sets as active
      const legacyId = action.payload.id
      return {
        ...state,
        characters: {
          ...state.characters,
          [legacyId]: action.payload,
        },
        inventories: {
          ...state.inventories,
          [legacyId]: state.inventories[legacyId] || createEmptyInventory(),
        },
        activeCharacterId: legacyId,
        isDirty: true,
      }
    }

    case 'SET_INVENTORY': {
      const { characterId, inventory } = action.payload
      return {
        ...state,
        inventories: {
          ...state.inventories,
          [characterId]: inventory,
        },
        isDirty: true,
      }
    }

    case 'UPDATE_INVENTORY': {
      const invCharId = action.payload.characterId
      const invUpdates = action.payload.updates
      if (!state.inventories[invCharId])
        return state
      return {
        ...state,
        inventories: {
          ...state.inventories,
          [invCharId]: {
            ...state.inventories[invCharId],
            ...invUpdates,
            lastUpdated: new Date(),
          },
        },
        isDirty: true,
      }
    }

    case 'ADD_MOVE':
      return {
        ...state,
        customMoves: [...state.customMoves, action.payload],
        isDirty: true,
      }

    case 'UPDATE_MOVE':
      return {
        ...state,
        customMoves: state.customMoves.map(move =>
          move.id === action.payload.id
            ? { ...move, ...action.payload.changes }
            : move,
        ),
        isDirty: true,
      }

    case 'REMOVE_MOVE':
      return {
        ...state,
        customMoves: state.customMoves.filter(move => move.id !== action.payload),
        isDirty: true,
      }

    case 'SET_SESSION':
      return {
        ...state,
        session: action.payload,
        isDirty: true,
      }

    case 'UPDATE_SESSION':
      return {
        ...state,
        session: {
          ...state.session,
          ...action.payload,
        },
        isDirty: true,
      }

    case 'SET_UI_STATE':
      return {
        ...state,
        ui: {
          ...state.ui,
          ...action.payload,
        },
      }

    case 'SET_SETTINGS':
      return {
        ...state,
        settings: {
          ...state.settings,
          ...action.payload,
        },
        isDirty: true,
      }

    case 'ADD_MODIFIER': {
      return {
        ...state,
        modifiers: {
          ...state.modifiers,
          modifiers: [...state.modifiers.modifiers, action.payload],
        },
        isDirty: true,
      }
    }

    case 'REMOVE_MODIFIER': {
      return {
        ...state,
        modifiers: {
          ...state.modifiers,
          modifiers: state.modifiers.modifiers.filter(m => m.id !== action.payload),
        },
        isDirty: true,
      }
    }

    case 'UPDATE_MODIFIER': {
      return {
        ...state,
        modifiers: {
          ...state.modifiers,
          modifiers: state.modifiers.modifiers.map(m =>
            m.id === action.payload.id
              ? { ...m, ...action.payload.updates }
              : m,
          ),
        },
        isDirty: true,
      }
    }

    case 'SET_MODIFIERS': {
      return {
        ...state,
        modifiers: action.payload,
        isDirty: true,
      }
    }

    case 'CLEAR_MODIFIERS': {
      return {
        ...state,
        modifiers: { modifiers: [], lastUpdated: new Date() },
        isDirty: true,
      }
    }

    case 'MARK_SAVED':
      return {
        ...state,
        lastSaved: new Date(),
        isDirty: false,
      }

    case 'MARK_DIRTY':
      return {
        ...state,
        isDirty: true,
      }

    case 'RESET_STATE':
      return createInitialGameState()

    case 'REPLACE_STATE':
      return {
        ...action.payload,
        isDirty: true,
      }

    case 'LOAD_STATE':
      return {
        ...action.payload,
        isDirty: false,
      }

    default:
      return state
  }
}

/**
 * Generate unique ID
 */
function generateId(): string {
  return Date.now().toString(36) + Math.random().toString(36).slice(2)
}

/**
 * Validate game state
 */
export function validateGameState(state: any): state is GameState {
  return (
    state
    && typeof state === 'object'
    && 'character' in state
    && 'inventory' in state
    && 'moves' in state
    && 'session' in state
    && 'ui' in state
    && 'settings' in state
    && 'version' in state
  )
}

/**
 * Migrate game state from older versions
 */
export function migrateGameState(state: unknown, fromVersion: string): GameState {
  // Handle migration logic here as versions change
  // For now, just ensure all required fields exist
  const currentState = createInitialGameState()

  return {
    ...currentState,
    ...state,
    version: currentState.version,
  }
}

/**
 * Export game state for backup
 */
export function exportGameState(state: GameState): string {
  const exportData = {
    ...state,
    exportDate: new Date().toISOString(),
    exportVersion: state.version,
  }

  return JSON.stringify(exportData, null, 2)
}

/**
 * Import game state from backup
 */
export function importGameState(jsonString: string): GameState | null {
  try {
    const data = JSON.parse(jsonString)

    if (!validateGameState(data)) {
      return null
    }

    // Migrate if needed
    if (data.version !== createInitialGameState().version) {
      return migrateGameState(data, data.version)
    }

    return data
  }
  catch {
    return null
  }
}

/**
 * History management for undo / redo functionality
 */

import type { GameState } from './GameState'

// History state structure
export interface StateHistory<T = GameState> {
  past: T[]
  present: T
  future: T[]
  maxHistorySize: number
}

// History action types
export type HistoryAction<T = GameState>
  = | { type: 'UNDO' }
    | { type: 'REDO' }
    | { type: 'SAVE_STATE', payload: T }
    | { type: 'CLEAR_HISTORY' }
    | { type: 'JUMP_TO_PAST', payload: number }
    | { type: 'JUMP_TO_FUTURE', payload: number }

// Create initial history state
export function createInitialHistory<T>(
  initialState: T,
  maxHistorySize = 50,
): StateHistory <T> {
  return {
    past: [],
    present: initialState,
    future: [],
    maxHistorySize,
  }
}

// History reducer
export function historyReducer<T>(
  state: StateHistory <T>,
  action: HistoryAction <T>,
): StateHistory <T> {
  switch (action.type) {
    case 'UNDO': {
      if (state.past.length === 0)
        return state

      const previousState = state.past[state.past.length - 1]
      const newPast = state.past.slice(0, state.past.length - 1)

      return {
        ...state,
        past: newPast,
        present: previousState,
        future: [state.present, ...state.future],
      }
    }

    case 'REDO': {
      if (state.future.length === 0)
        return state

      const nextState = state.future[0]
      const newFuture = state.future.slice(1)

      return {
        ...state,
        past: [...state.past, state.present],
        present: nextState,
        future: newFuture,
      }
    }

    case 'SAVE_STATE': {
      // Don't save if the state hasn't changed
      if (deepEqual(state.present, action.payload))
        return state

      let newPast = [...state.past, state.present]

      // Limit history size
      if (newPast.length > state.maxHistorySize) {
        newPast = newPast.slice(newPast.length - state.maxHistorySize)
      }

      return {
        ...state,
        past: newPast,
        present: action.payload,
        future: [], // Clear future on new action
      }
    }

    case 'CLEAR_HISTORY':
      return {
        ...state,
        past: [],
        future: [],
      }

    case 'JUMP_TO_PAST': {
      const pastIndex = action.payload
      if (pastIndex < 0 || pastIndex >= state.past.length)
        return state

      const targetPastState = state.past[pastIndex]
      const statesAfterTarget = [
        ...state.past.slice(pastIndex + 1),
        state.present,
        ...state.future,
      ]

      return {
        ...state,
        past: state.past.slice(0, pastIndex),
        present: targetPastState,
        future: statesAfterTarget,
      }
    }

    case 'JUMP_TO_FUTURE': {
      const futureIndex = action.payload
      if (futureIndex < 0 || futureIndex >= state.future.length)
        return state

      const targetFutureState = state.future[futureIndex]
      const statesBeforeTarget = [
        ...state.past,
        state.present,
        ...state.future.slice(0, futureIndex),
      ]

      return {
        ...state,
        past: statesBeforeTarget,
        present: targetFutureState,
        future: state.future.slice(futureIndex + 1),
      }
    }

    default:
      return state
  }
}

// Utility functions

/**
 * Check if undo is available
 */
export function canUndo<T>(history: StateHistory <T>): boolean {
  return history.past.length > 0
}

/**
 * Check if redo is available
 */
export function canRedo<T>(history: StateHistory <T>): boolean {
  return history.future.length > 0
}

/**
 * Get undo / redo counts
 */
export function getHistoryCounts<T>(history: StateHistory <T>): {
  undoCount: number
  redoCount: number
} {
  return {
    undoCount: history.past.length,
    redoCount: history.future.length,
  }
}

/**
 * Create a history-aware wrapper for unknown reducer
 */
export function withHistory<T, A>(
  reducer: (state: T, action: A) => T,
  shouldSaveHistory?: (action: A) => boolean,
) {
  return function historyAwareReducer(
    history: StateHistory <T>,
    action: A | HistoryAction <T>,
  ): StateHistory <T> {
    // Handle history actions
    if (isHistoryAction(action)) {
      return historyReducer(history, action)
    }

    // Handle regular actions
    const newPresent = reducer(history.present, action as A)

    // Check if we should save history for this action
    if (shouldSaveHistory && !shouldSaveHistory(action as A)) {
      return {
        ...history,
        present: newPresent,
      }
    }

    // Save to history
    return historyReducer(history, {
      type: 'SAVE_STATE',
      payload: newPresent,
    })
  }
}

/**
 * Type guard for history actions
 */
function isHistoryAction<T>(action: any): action is HistoryAction <T> {
  return [
    'UNDO',
    'REDO',
    'SAVE_STATE',
    'CLEAR_HISTORY',
    'JUMP_TO_PAST',
    'JUMP_TO_FUTURE',
  ].includes(action.type)
}

/**
 * Simple deep equality check
 */
function deepEqual(a: unknown, b: any): boolean {
  if (a === b)
    return true

  if (a == null || b == null)
    return false

  if (a.constructor !== b.constructor)
    return false

  if (a instanceof Date && b instanceof Date) {
    return a.getTime() === b.getTime()
  }

  if (Array.isArray(a)) {
    if (a.length !== b.length)
      return false
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i]))
        return false
    }
    return true
  }

  if (typeof a === 'object') {
    const keysA = Object.keys(a)
    const keysB = Object.keys(b)

    if (keysA.length !== keysB.length)
      return false

    for (const key of keysA) {
      if (!keysB.includes(key))
        return false
      if (!deepEqual(a[key], b[key]))
        return false
    }

    return true
  }

  return false
}

/**
 * Create a debounced history saver
 */
export function createHistorySaver<T>(
  saveHistory: (state: T) => void,
  debounceMs = 1000,
) {
  let timeoutId: ReturnType <typeof setTimeout> | null = null

  return (state: T) => {
    if (timeoutId) {
      clearTimeout(timeoutId)
    }

    timeoutId = setTimeout(() => {
      saveHistory(state)
      timeoutId = null
    }, debounceMs)
  }
}

/**
 * Advancement Service for ZimboMate V2
 * Handles character advancement, leveling up, and XP management
 * New service for V2 to handle character progression
 */

import type { Character, AdvancementChoice, Attribute, CharacterClass } from '../models/Character'
import { getXPThreshold, calculateMaxHP, calculateMaxLoad } from '../models/Character'

// Advancement options available when leveling up
export interface AdvancementOption {
  id: string
  type: 'move' | 'stat' | 'other'
  name: string
  description: string
  requirements?: string[]
  mutuallyExclusive?: string[] // Other options that can't be taken with this one
}

// Level up result
export interface LevelUpResult {
  character: Character
  availableOptions: AdvancementOption[]
  newLevel: number
  hpIncrease: number
  loadIncrease: number
}

// XP sources for tracking
export type XPSource = 
  | 'failed-roll' 
  | 'end-of-session' 
  | 'bond-resolution' 
  | 'alignment-move' 
  | 'gm-award' 
  | 'other'

// XP entry for history tracking
export interface XPEntry {
  id: string
  amount: number
  source: XPSource
  description: string
  timestamp: Date
  sessionId?: string
}

export class AdvancementService {
  private xpHistory: Map<string, XPEntry[]> = new Map()

  /**
   * Check if character should level up
   */
  shouldLevelUp(character: Character): boolean {
    return character.xp >= getXPThreshold(character.level)
  }

  /**
   * Get XP needed for next level
   */
  getXPNeeded(character: Character): number {
    const threshold = getXPThreshold(character.level)
    return Math.max(0, threshold - character.xp)
  }

  /**
   * Get XP progress as percentage
   */
  getXPProgress(character: Character): number {
    const threshold = getXPThreshold(character.level)
    return Math.min(100, (character.xp / threshold) * 100)
  }

  /**
   * Add XP to character
   */
  addXP(character: Character, amount: number, source: XPSource, description: string, sessionId?: string): Character {
    const entry: XPEntry = {
      id: `xp-${Date.now()}-${Math.random().toString(36).slice(2, 11)}`,
      amount,
      source,
      description,
      timestamp: new Date(),
      sessionId,
    }

    // Add to history
    const history = this.xpHistory.get(character.id) || []
    history.push(entry)
    this.xpHistory.set(character.id, history)

    return {
      ...character,
      xp: character.xp + amount,
      updatedAt: new Date(),
    }
  }

  /**
   * Get XP history for character
   */
  getXPHistory(characterId: string): XPEntry[] {
    return this.xpHistory.get(characterId) || []
  }

  /**
   * Get XP statistics
   */
  getXPStats(characterId: string): {
    totalXP: number
    xpFromFailedRolls: number
    xpFromSessions: number
    xpFromBonds: number
    xpFromAlignment: number
    xpFromOther: number
    averageXPPerSession: number
  } {
    const history = this.getXPHistory(characterId)
    
    const stats = {
      totalXP: 0,
      xpFromFailedRolls: 0,
      xpFromSessions: 0,
      xpFromBonds: 0,
      xpFromAlignment: 0,
      xpFromOther: 0,
      averageXPPerSession: 0,
    }

    const sessionXP = new Map<string, number>()

    for (const entry of history) {
      stats.totalXP += entry.amount

      switch (entry.source) {
        case 'failed-roll':
          stats.xpFromFailedRolls += entry.amount
          break
        case 'end-of-session':
          stats.xpFromSessions += entry.amount
          break
        case 'bond-resolution':
          stats.xpFromBonds += entry.amount
          break
        case 'alignment-move':
          stats.xpFromAlignment += entry.amount
          break
        default:
          stats.xpFromOther += entry.amount
          break
      }

      // Track XP per session
      if (entry.sessionId) {
        const current = sessionXP.get(entry.sessionId) || 0
        sessionXP.set(entry.sessionId, current + entry.amount)
      }
    }

    // Calculate average XP per session
    if (sessionXP.size > 0) {
      const totalSessionXP = Array.from(sessionXP.values()).reduce((sum, xp) => sum + xp, 0)
      stats.averageXPPerSession = totalSessionXP / sessionXP.size
    }

    return stats
  }

  /**
   * Get available advancement options for a character
   */
  getAdvancementOptions(character: Character): AdvancementOption[] {
    const options: AdvancementOption[] = []

    // Stat improvements (can increase any stat by 1, max 18)
    for (const stat of ['STR', 'DEX', 'CON', 'INT', 'WIS', 'CHA'] as Attribute[]) {
      if (character.attributes[stat] < 18) {
        options.push({
          id: `stat-${stat.toLowerCase()}`,
          type: 'stat',
          name: `Increase ${stat}`,
          description: `Increase your ${stat} by 1 (to ${character.attributes[stat] + 1})`,
        })
      }
    }

    // Class moves (this would be populated from move compendium)
    // For now, add placeholder options
    options.push({
      id: 'class-move-1',
      type: 'move',
      name: 'New Class Move',
      description: 'Learn a new move from your class',
    })

    // Advanced moves (levels 2-5)
    if (character.level >= 2 && character.level <= 5) {
      options.push({
        id: 'advanced-move',
        type: 'move',
        name: 'Advanced Move',
        description: 'Learn an advanced move from another class',
      })
    }

    // Master moves (levels 6-10)
    if (character.level >= 6) {
      options.push({
        id: 'master-move',
        type: 'move',
        name: 'Master Move',
        description: 'Learn a master move',
      })
    }

    return options
  }

  /**
   * Level up character
   */
  levelUp(character: Character): LevelUpResult {
    if (!this.shouldLevelUp(character)) {
      throw new Error('Character does not have enough XP to level up')
    }

    const newLevel = character.level + 1
    const oldMaxHP = calculateMaxHP(character)
    const oldMaxLoad = calculateMaxLoad(character)

    // Create leveled up character
    const leveledCharacter: Character = {
      ...character,
      level: newLevel,
      updatedAt: new Date(),
    }

    // Recalculate derived stats
    const newMaxHP = calculateMaxHP(leveledCharacter)
    const newMaxLoad = calculateMaxLoad(leveledCharacter)

    // Update HP and load maximums
    leveledCharacter.hp = {
      current: character.hp.current + (newMaxHP - oldMaxHP), // Increase current HP by the increase in max
      max: newMaxHP,
    }

    leveledCharacter.load = {
      current: character.load.current,
      max: newMaxLoad,
    }

    const availableOptions = this.getAdvancementOptions(leveledCharacter)

    return {
      character: leveledCharacter,
      availableOptions,
      newLevel,
      hpIncrease: newMaxHP - oldMaxHP,
      loadIncrease: newMaxLoad - oldMaxLoad,
    }
  }

  /**
   * Apply advancement choice
   */
  applyAdvancement(character: Character, option: AdvancementOption): Character {
    const advancement: AdvancementChoice = {
      level: character.level,
      type: option.type,
      choice: option.id,
      description: option.description,
      timestamp: new Date(),
    }

    const updated = {
      ...character,
      advancements: [...character.advancements, advancement],
      updatedAt: new Date(),
    }

    // Apply the specific advancement
    switch (option.type) {
      case 'stat':
        const statMatch = option.id.match(/stat-(\w+)/)
        if (statMatch) {
          const stat = statMatch[1].toUpperCase() as Attribute
          updated.attributes = {
            ...updated.attributes,
            [stat]: Math.min(18, updated.attributes[stat] + 1),
          }
          
          // Recalculate derived stats if CON or STR changed
          if (stat === 'CON') {
            const newMaxHP = calculateMaxHP(updated)
            const hpIncrease = newMaxHP - updated.hp.max
            updated.hp = {
              current: updated.hp.current + hpIncrease,
              max: newMaxHP,
            }
          }
          
          if (stat === 'STR') {
            updated.load = {
              ...updated.load,
              max: calculateMaxLoad(updated),
            }
          }
        }
        break

      case 'move':
        // Add move to known moves
        updated.knownMoves = [...updated.knownMoves, option.id]
        break

      case 'other':
        // Handle other advancement types as needed
        break
    }

    return updated
  }

  /**
   * Get advancement history for character
   */
  getAdvancementHistory(character: Character): AdvancementChoice[] {
    return [...character.advancements].sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime())
  }

  /**
   * Check if character can take a specific advancement
   */
  canTakeAdvancement(character: Character, option: AdvancementOption): {
    canTake: boolean
    reasons: string[]
  } {
    const reasons: string[] = []
    let canTake = true

    // Check requirements
    if (option.requirements) {
      for (const requirement of option.requirements) {
        // This would check specific requirements
        // For now, assume all requirements are met
      }
    }

    // Check mutually exclusive options
    if (option.mutuallyExclusive) {
      const takenChoices = character.advancements.map(a => a.choice)
      for (const exclusive of option.mutuallyExclusive) {
        if (takenChoices.includes(exclusive)) {
          reasons.push(`Cannot take because you already have ${exclusive}`)
          canTake = false
        }
      }
    }

    // Check stat limits
    if (option.type === 'stat') {
      const statMatch = option.id.match(/stat-(\w+)/)
      if (statMatch) {
        const stat = statMatch[1].toUpperCase() as Attribute
        if (character.attributes[stat] >= 18) {
          reasons.push(`${stat} is already at maximum (18)`)
          canTake = false
        }
      }
    }

    return { canTake, reasons }
  }

  /**
   * Reset character to level 1 (for testing or character recreation)
   */
  resetToLevel1(character: Character): Character {
    return {
      ...character,
      level: 1,
      xp: 0,
      advancements: [],
      knownMoves: [], // Reset to starting moves only
      hp: {
        current: calculateMaxHP({ ...character, level: 1 }),
        max: calculateMaxHP({ ...character, level: 1 }),
      },
      load: {
        current: 0,
        max: calculateMaxLoad({ ...character, level: 1 }),
      },
      updatedAt: new Date(),
    }
  }

  /**
   * Clear XP history for character (useful for testing)
   */
  clearXPHistory(characterId: string): void {
    this.xpHistory.delete(characterId)
  }
}

