/**
 * Campaign Service for ZimboMate V2
 * Handles CRUD operations for campaigns, sessions, journal entries, NPCs, and locations
 * Modernized from V1 with improved TypeScript patterns and V2 model integration
 */

import type { Campaign, CampaignSession, JournalEntry, Location, NPC } from '../models/Campaign'
import { createCampaign, createJournalEntry, createLocation, createNPC, createSession } from '../models/Campaign'

export class CampaignService {
  private campaigns: Map<string, Campaign> = new Map()

  constructor() {
    this.loadFromStorage()
  }

  // Campaign Management
  createCampaign(name: string, description?: string): Campaign {
    const campaign = createCampaign(name, description)
    this.campaigns.set(campaign.id, campaign)
    this.saveToStorage()
    return campaign
  }

  getCampaign(id: string): Campaign | undefined {
    return this.campaigns.get(id)
  }

  getAllCampaigns(): Campaign[] {
    return [...this.campaigns.values()]
  }

  updateCampaign(id: string, updates: Partial<Campaign>): Campaign | undefined {
    const campaign = this.campaigns.get(id)
    if (!campaign) return undefined

    const updated = {
      ...campaign,
      ...updates,
      lastModified: new Date(),
    }

    this.campaigns.set(id, updated)
    this.saveToStorage()
    return updated
  }

  deleteCampaign(id: string): boolean {
    const deleted = this.campaigns.delete(id)
    if (deleted) {
      this.saveToStorage()
    }
    return deleted
  }

  // Session Management
  addSession(campaignId: string, title: string, summary: string): CampaignSession | undefined {
    const campaign = this.campaigns.get(campaignId)
    if (!campaign) return undefined

    const session = createSession(title, summary)
    const updated = {
      ...campaign,
      sessions: [...campaign.sessions, session],
      lastModified: new Date(),
    }

    this.campaigns.set(campaignId, updated)
    this.saveToStorage()
    return session
  }

  updateSession(campaignId: string, sessionId: string, updates: Partial<CampaignSession>): CampaignSession | undefined {
    const campaign = this.campaigns.get(campaignId)
    if (!campaign) return undefined

    const sessionIndex = campaign.sessions.findIndex(s => s.id === sessionId)
    if (sessionIndex === -1) return undefined

    const updatedSession = { ...campaign.sessions[sessionIndex], ...updates }
    const updatedSessions = [...campaign.sessions]
    updatedSessions[sessionIndex] = updatedSession

    const updated = {
      ...campaign,
      sessions: updatedSessions,
      lastModified: new Date(),
    }

    this.campaigns.set(campaignId, updated)
    this.saveToStorage()
    return updatedSession
  }

  deleteSession(campaignId: string, sessionId: string): boolean {
    const campaign = this.campaigns.get(campaignId)
    if (!campaign) return false

    const updatedSessions = campaign.sessions.filter(s => s.id !== sessionId)
    const updated = {
      ...campaign,
      sessions: updatedSessions,
      lastModified: new Date(),
    }

    this.campaigns.set(campaignId, updated)
    this.saveToStorage()
    return true
  }

  // Journal Management
  addJournalEntry(campaignId: string, title: string, content: string): JournalEntry | undefined {
    const campaign = this.campaigns.get(campaignId)
    if (!campaign) return undefined

    const entry = createJournalEntry(title, content)
    const updated = {
      ...campaign,
      journal: [...campaign.journal, entry],
      lastModified: new Date(),
    }

    this.campaigns.set(campaignId, updated)
    this.saveToStorage()
    return entry
  }

  updateJournalEntry(campaignId: string, entryId: string, updates: Partial<JournalEntry>): JournalEntry | undefined {
    const campaign = this.campaigns.get(campaignId)
    if (!campaign) return undefined

    const entryIndex = campaign.journal.findIndex(e => e.id === entryId)
    if (entryIndex === -1) return undefined

    const updatedEntry = { ...campaign.journal[entryIndex], ...updates }
    const updatedJournal = [...campaign.journal]
    updatedJournal[entryIndex] = updatedEntry

    const updated = {
      ...campaign,
      journal: updatedJournal,
      lastModified: new Date(),
    }

    this.campaigns.set(campaignId, updated)
    this.saveToStorage()
    return updatedEntry
  }

  deleteJournalEntry(campaignId: string, entryId: string): boolean {
    const campaign = this.campaigns.get(campaignId)
    if (!campaign) return false

    const updatedJournal = campaign.journal.filter(e => e.id !== entryId)
    const updated = {
      ...campaign,
      journal: updatedJournal,
      lastModified: new Date(),
    }

    this.campaigns.set(campaignId, updated)
    this.saveToStorage()
    return true
  }

  // NPC Management
  addNPC(campaignId: string, name: string, description: string, role: string): NPC | undefined {
    const campaign = this.campaigns.get(campaignId)
    if (!campaign) return undefined

    const npc = createNPC(name, description, role)
    const updated = {
      ...campaign,
      npcs: [...campaign.npcs, npc],
      lastModified: new Date(),
    }

    this.campaigns.set(campaignId, updated)
    this.saveToStorage()
    return npc
  }

  updateNPC(campaignId: string, npcId: string, updates: Partial<NPC>): NPC | undefined {
    const campaign = this.campaigns.get(campaignId)
    if (!campaign) return undefined

    const npcIndex = campaign.npcs.findIndex(n => n.id === npcId)
    if (npcIndex === -1) return undefined

    const updatedNPC = { ...campaign.npcs[npcIndex], ...updates }
    const updatedNPCs = [...campaign.npcs]
    updatedNPCs[npcIndex] = updatedNPC

    const updated = {
      ...campaign,
      npcs: updatedNPCs,
      lastModified: new Date(),
    }

    this.campaigns.set(campaignId, updated)
    this.saveToStorage()
    return updatedNPC
  }

  deleteNPC(campaignId: string, npcId: string): boolean {
    const campaign = this.campaigns.get(campaignId)
    if (!campaign) return false

    const updatedNPCs = campaign.npcs.filter(n => n.id !== npcId)
    const updated = {
      ...campaign,
      npcs: updatedNPCs,
      lastModified: new Date(),
    }

    this.campaigns.set(campaignId, updated)
    this.saveToStorage()
    return true
  }

  // Location Management
  addLocation(campaignId: string, name: string, description: string, type: Location['type']): Location | undefined {
    const campaign = this.campaigns.get(campaignId)
    if (!campaign) return undefined

    const location = createLocation(name, description, type)
    const updated = {
      ...campaign,
      locations: [...campaign.locations, location],
      lastModified: new Date(),
    }

    this.campaigns.set(campaignId, updated)
    this.saveToStorage()
    return location
  }

  updateLocation(campaignId: string, locationId: string, updates: Partial<Location>): Location | undefined {
    const campaign = this.campaigns.get(campaignId)
    if (!campaign) return undefined

    const locationIndex = campaign.locations.findIndex(l => l.id === locationId)
    if (locationIndex === -1) return undefined

    const updatedLocation = { ...campaign.locations[locationIndex], ...updates }
    const updatedLocations = [...campaign.locations]
    updatedLocations[locationIndex] = updatedLocation

    const updated = {
      ...campaign,
      locations: updatedLocations,
      lastModified: new Date(),
    }

    this.campaigns.set(campaignId, updated)
    this.saveToStorage()
    return updatedLocation
  }

  deleteLocation(campaignId: string, locationId: string): boolean {
    const campaign = this.campaigns.get(campaignId)
    if (!campaign) return false

    const updatedLocations = campaign.locations.filter(l => l.id !== locationId)
    const updated = {
      ...campaign,
      locations: updatedLocations,
      lastModified: new Date(),
    }

    this.campaigns.set(campaignId, updated)
    this.saveToStorage()
    return true
  }

  // Search functionality
  searchCampaign(campaignId: string, query: string): {
    sessions: CampaignSession[]
    journal: JournalEntry[]
    npcs: NPC[]
    locations: Location[]
  } {
    const campaign = this.campaigns.get(campaignId)
    if (!campaign) return { sessions: [], journal: [], npcs: [], locations: [] }

    const lowerQuery = query.toLowerCase()

    const sessions = campaign.sessions.filter(s =>
      s.title.toLowerCase().includes(lowerQuery) ||
      s.summary.toLowerCase().includes(lowerQuery) ||
      s.notes.toLowerCase().includes(lowerQuery)
    )

    const journal = campaign.journal.filter(e =>
      e.title.toLowerCase().includes(lowerQuery) ||
      e.content.toLowerCase().includes(lowerQuery) ||
      e.tags.some(tag => tag.toLowerCase().includes(lowerQuery))
    )

    const npcs = campaign.npcs.filter(n =>
      n.name.toLowerCase().includes(lowerQuery) ||
      n.description.toLowerCase().includes(lowerQuery) ||
      n.role.toLowerCase().includes(lowerQuery) ||
      n.notes.toLowerCase().includes(lowerQuery)
    )

    const locations = campaign.locations.filter(l =>
      l.name.toLowerCase().includes(lowerQuery) ||
      l.description.toLowerCase().includes(lowerQuery) ||
      l.notes.toLowerCase().includes(lowerQuery)
    )

    return { sessions, journal, npcs, locations }
  }

  // Export / Import functionality
  exportCampaign(campaignId: string): string {
    const campaign = this.campaigns.get(campaignId)
    if (!campaign) throw new Error('Campaign not found')

    return JSON.stringify(campaign, null, 2)
  }

  importCampaign(campaignData: string): Campaign {
    try {
      const campaign = JSON.parse(campaignData) as Campaign

      // Validate required fields
      if (!campaign.id || !campaign.name) {
        throw new Error('Invalid campaign data: missing required fields')
      }

      // Update timestamps
      campaign.lastModified = new Date()

      this.campaigns.set(campaign.id, campaign)
      this.saveToStorage()
      return campaign
    } catch (error) {
      throw new Error(`Failed to import campaign: ${error instanceof Error ? error.message : 'Unknown error'}`)
    }
  }

  // Character association
  addCharacterToCampaign(campaignId: string, characterId: string): boolean {
    const campaign = this.campaigns.get(campaignId)
    if (!campaign) return false

    if (!campaign.characterIds.includes(characterId)) {
      const updated = {
        ...campaign,
        characterIds: [...campaign.characterIds, characterId],
        lastModified: new Date(),
      }
      this.campaigns.set(campaignId, updated)
      this.saveToStorage()
    }
    return true
  }

  removeCharacterFromCampaign(campaignId: string, characterId: string): boolean {
    const campaign = this.campaigns.get(campaignId)
    if (!campaign) return false

    const updated = {
      ...campaign,
      characterIds: campaign.characterIds.filter(id => id !== characterId),
      lastModified: new Date(),
    }
    this.campaigns.set(campaignId, updated)
    this.saveToStorage()
    return true
  }

  getCampaignsForCharacter(characterId: string): Campaign[] {
    return [...this.campaigns.values()].filter(campaign =>
      campaign.characterIds.includes(characterId)
    )
  }

  // Statistics
  getCampaignStats(campaignId: string): {
    totalSessions: number
    totalJournalEntries: number
    totalNPCs: number
    totalLocations: number
    totalXP: number
    averageSessionLength: number
  } | null {
    const campaign = this.campaigns.get(campaignId)
    if (!campaign) return null

    const totalXP = campaign.sessions.reduce((sum, session) => sum + session.xpGained, 0)
    const sessionsWithDuration = campaign.sessions.filter(s => s.duration)
    const averageSessionLength = sessionsWithDuration.length > 0
      ? sessionsWithDuration.reduce((sum, s) => sum + (s.duration || 0), 0) / sessionsWithDuration.length
      : 0

    return {
      totalSessions: campaign.sessions.length,
      totalJournalEntries: campaign.journal.length,
      totalNPCs: campaign.npcs.length,
      totalLocations: campaign.locations.length,
      totalXP,
      averageSessionLength,
    }
  }

  // Local storage persistence
  private saveToStorage(): void {
    try {
      const data = [...this.campaigns.entries()]
      localStorage.setItem('zimbomate-campaigns', JSON.stringify(data))
    } catch (error) {
      console.warn('Failed to save campaigns to localStorage:', error)
    }
  }

  private loadFromStorage(): void {
    try {
      const data = localStorage.getItem('zimbomate-campaigns')
      if (data) {
        const campaigns = JSON.parse(data) as [string, Campaign][]
        this.campaigns = new Map(campaigns)
      }
    } catch (error) {
      console.warn('Failed to load campaigns from localStorage:', error)
      this.campaigns = new Map()
    }
  }
}

// Export singleton instance
export const campaignService = new CampaignService()

/**
 * Character State Service for ZimboMate V2
 * Manages dynamic character state including modifiers, conditions, and resources
 * Modernized from V1 with improved TypeScript patterns and V2 model integration
 */

import type { Attribute, Character } from '../models/Character'

export interface CharacterState {
  characterId: string
  conditions: Condition[]
  ongoingModifiers: OngoingModifier[]
  forwardModifiers: ForwardModifier[]
  resources: ResourceTracker[]
  bonds: BondState[]
  equipment: EquipmentState[]
  lastUpdated: number
}

export interface Condition {
  id: string
  name: string
  description: string
  effects: ConditionEffect[]
  duration: 'permanent' | 'scene' | 'encounter' | 'turn' | number // number = specific turns
  source: string
  severity: 'minor' | 'moderate' | 'severe' | 'critical'
}

export interface ConditionEffect {
  type: 'stat_modifier' | 'move_restriction' | 'damage_modifier' | 'special'
  target: string // stat name, move id, etc.
  value: number | string
  description: string
}

export interface OngoingModifier {
  id: string
  name: string
  value: number
  appliesTo: 'all' | 'stat' | 'move' | 'damage'
  target?: string // specific stat or move
  source: string
  duration: 'permanent' | 'scene' | 'encounter' | number
  stacks: boolean
}

export interface ForwardModifier {
  id: string
  name: string
  value: number
  appliesTo: 'next_roll' | 'next_move' | 'next_stat_roll'
  target?: string // specific move or stat
  source: string
  used: boolean
}

export interface ResourceTracker {
  id: string
  name: string
  current: number
  max: number
  type: 'hold' | 'uses' | 'ammo' | 'spell_slots' | 'custom'
  source: string // move or item that granted this
  refreshOn: 'rest' | 'scene' | 'session' | 'manual'
}

export interface BondState {
  id: string
  targetCharacterId: string
  targetName: string
  description: string
  strength: number // 0-3, affects Aid / Interfere
  lastUsed?: number
  timesUsed: number
}

export interface EquipmentState {
  itemId: string
  equipped: boolean
  condition: 'perfect' | 'good' | 'worn' | 'damaged' | 'broken'
  charges?: number
  maxCharges?: number
  modifiers: EquipmentModifier[]
}

export interface EquipmentModifier {
  type: 'stat' | 'damage' | 'armor' | 'special'
  value: number | string
  condition?: string // when this modifier applies
}

export class CharacterStateService {
  private characterStates: Map<string, CharacterState> = new Map()

  /**
   * Get character state (creates if doesn't exist)
   */
  getCharacterState(characterId: string): CharacterState {
    let state = this.characterStates.get(characterId)
    if (!state) {
      state = this.createDefaultState(characterId)
      this.characterStates.set(characterId, state)
    }
    return state
  }

  /**
   * Update character state
   */
  updateCharacterState(characterId: string, updates: Partial<CharacterState>): void {
    const state = this.getCharacterState(characterId)
    Object.assign(state, updates, { lastUpdated: Date.now() })
    this.characterStates.set(characterId, state)
  }

  /**
   * Add condition to character
   */
  addCondition(characterId: string, condition: Condition): void {
    const state = this.getCharacterState(characterId)

    // Remove existing condition with same name if it doesn't stack
    const existingIndex = state.conditions.findIndex(c => c.id === condition.id)
    if (existingIndex >= 0) {
      state.conditions.splice(existingIndex, 1)
    }

    state.conditions.push(condition)
    state.lastUpdated = Date.now()
  }

  /**
   * Remove condition from character
   */
  removeCondition(characterId: string, conditionId: string): void {
    const state = this.getCharacterState(characterId)
    state.conditions = state.conditions.filter(c => c.id !== conditionId)
    state.lastUpdated = Date.now()
  }

  /**
   * Add ongoing modifier
   */
  addOngoingModifier(characterId: string, modifier: OngoingModifier): void {
    const state = this.getCharacterState(characterId)

    // Handle stacking
    if (!modifier.stacks) {
      const existingIndex = state.ongoingModifiers.findIndex(m =>
        m.name === modifier.name && m.appliesTo === modifier.appliesTo && m.target === modifier.target
      )
      if (existingIndex >= 0) {
        state.ongoingModifiers.splice(existingIndex, 1)
      }
    }

    state.ongoingModifiers.push(modifier)
    state.lastUpdated = Date.now()
  }

  /**
   * Add forward modifier
   */
  addForwardModifier(characterId: string, modifier: ForwardModifier): void {
    const state = this.getCharacterState(characterId)
    state.forwardModifiers.push(modifier)
    state.lastUpdated = Date.now()
  }

  /**
   * Use forward modifier (marks as used)
   */
  useForwardModifier(characterId: string, modifierId: string): ForwardModifier | null {
    const state = this.getCharacterState(characterId)
    const modifier = state.forwardModifiers.find(m => m.id === modifierId)
    if (modifier) {
      modifier.used = true
      state.lastUpdated = Date.now()
      return modifier
    }

    return null
  }

  /**
   * Clean up used forward modifiers
   */
  cleanupForwardModifiers(characterId: string): void {
    const state = this.getCharacterState(characterId)
    state.forwardModifiers = state.forwardModifiers.filter(m => !m.used)
    state.lastUpdated = Date.now()
  }

  /**
   * Update resource tracker
   */
  updateResource(characterId: string, resourceId: string, newCurrent: number): void {
    const state = this.getCharacterState(characterId)
    const resource = state.resources.find(r => r.id === resourceId)
    if (resource) {
      resource.current = Math.max(0, Math.min(resource.max, newCurrent))
      state.lastUpdated = Date.now()
    }
  }

  /**
   * Add or update resource tracker
   */
  setResource(characterId: string, resource: ResourceTracker): void {
    const state = this.getCharacterState(characterId)
    const existingIndex = state.resources.findIndex(r => r.id === resource.id)

    if (existingIndex >= 0) {
      state.resources[existingIndex] = resource
    } else {
      state.resources.push(resource)
    }

    state.lastUpdated = Date.now()
  }

  /**
   * Get total modifier for a specific context
   */
  getTotalModifier(
    characterId: string,
    context: 'stat' | 'move' | 'damage',
    target?: string
  ): number {
    const state = this.getCharacterState(characterId)
    let total = 0

    // Add ongoing modifiers
    for (const modifier of state.ongoingModifiers) {
      if (modifier.appliesTo === 'all' ||
          (modifier.appliesTo === context && (!modifier.target || modifier.target === target))) {
        total += modifier.value
      }
    }

    // Add condition effects
    for (const condition of state.conditions) {
      for (const effect of condition.effects) {
        if (effect.type === `${context}_modifier` &&
            (!effect.target || effect.target === target)) {
          total += typeof effect.value === 'number' ? effect.value : 0
        }
      }
    }

    // Add equipment modifiers
    for (const equipment of state.equipment) {
      if (equipment.equipped) {
        for (const modifier of equipment.modifiers) {
          if (modifier.type === context) {
            total += typeof modifier.value === 'number' ? modifier.value : 0
          }
        }
      }
    }

    return total
  }

  /**
   * Get available forward modifiers for a context
   */
  getAvailableForwardModifiers(
    characterId: string,
    context: 'next_roll' | 'next_move' | 'next_stat_roll',
    target?: string
  ): ForwardModifier[] {
    const state = this.getCharacterState(characterId)
    return state.forwardModifiers.filter(m =>
      !m.used &&
      m.appliesTo === context &&
      (!m.target || m.target === target)
    )
  }

  /**
   * Get active conditions
   */
  getActiveConditions(characterId: string): Condition[] {
    const state = this.getCharacterState(characterId)
    return state.conditions.filter(c => this.isConditionActive(c))
  }

  /**
   * Get bond strength with another character
   */
  getBondStrength(characterId: string, targetCharacterId: string): number {
    const state = this.getCharacterState(characterId)
    const bond = state.bonds.find(b => b.targetCharacterId === targetCharacterId)
    return bond?.strength || 0
  }

  /**
   * Use bond (for Aid / Interfere)
   */
  useBond(characterId: string, targetCharacterId: string): boolean {
    const state = this.getCharacterState(characterId)
    const bond = state.bonds.find(b => b.targetCharacterId === targetCharacterId)

    if (bond && bond.strength > 0) {
      bond.lastUsed = Date.now()
      bond.timesUsed++
      state.lastUpdated = Date.now()
      return true
    }

    return false
  }

  /**
   * Refresh resources based on trigger
   */
  refreshResources(characterId: string, trigger: 'rest' | 'scene' | 'session'): void {
    const state = this.getCharacterState(characterId)

    for (const resource of state.resources) {
      if (resource.refreshOn === trigger) {
        resource.current = resource.max
      }
    }

    state.lastUpdated = Date.now()
  }

  /**
   * Advance time (for duration-based effects)
   */
  advanceTime(characterId: string, timeType: 'turn' | 'scene' | 'encounter'): void {
    const state = this.getCharacterState(characterId)

    // Update condition durations
    state.conditions = state.conditions.filter((condition) => {
      if (typeof condition.duration === 'number') {
        condition.duration--
        return condition.duration > 0
      }
      return condition.duration !== timeType
    })

    // Update ongoing modifier durations
    state.ongoingModifiers = state.ongoingModifiers.filter((modifier) => {
      if (typeof modifier.duration === 'number') {
        modifier.duration--
        return modifier.duration > 0
      }
      return modifier.duration !== timeType
    })

    state.lastUpdated = Date.now()
  }

  /**
   * Get character state summary for UI
   */
  getStateSummary(characterId: string): {
    activeConditions: number
    totalOngoingModifiers: number
    availableForwardModifiers: number
    resourcesNeedingAttention: number
  } {
    const state = this.getCharacterState(characterId)

    return {
      activeConditions: this.getActiveConditions(characterId).length,
      totalOngoingModifiers: state.ongoingModifiers.length,
      availableForwardModifiers: state.forwardModifiers.filter(m => !m.used).length,
      resourcesNeedingAttention: state.resources.filter(r => r.current <= r.max * 0.25).length,
    }
  }

  /**
   * Clear all state for a character (useful for testing)
   */
  clearCharacterState(characterId: string): void {
    this.characterStates.delete(characterId)
  }

  /**
   * Get all character states (for debugging/admin)
   */
  getAllStates(): Map<string, CharacterState> {
    return new Map(this.characterStates)
  }

  /**
   * Private helper methods
   */
  private createDefaultState(characterId: string): CharacterState {
    return {
      characterId,
      conditions: [],
      ongoingModifiers: [],
      forwardModifiers: [],
      resources: [],
      bonds: [],
      equipment: [],
      lastUpdated: Date.now(),
    }
  }

  private isConditionActive(condition: Condition): boolean {
    if (condition.duration === 'permanent') return true
    if (typeof condition.duration === 'number') return condition.duration > 0
    return true // Scene / encounter conditions are active until explicitly removed
  }
}

// Singleton instance
export const characterStateService = new CharacterStateService()

/**
 * Chronicle Action Listener Service
 *
 * This service acts as a global event listener for meaningful actions throughout the app,
 * providing contextual Chronicle prompts when users perform dice rolls, equipment actions,
 * combat moves, and other significant activities.
 *
 * Key Features:
 * - Event-driven architecture for listening to app-wide actions
 * - Context-aware prompt generation based on action type and current game state
 * - Integration with existing Chronicle store for seamless story building
 * - Smart filtering to avoid prompt overload
 * - Elegant floating overlay system for non-intrusive prompts
 */

import { useChronicleStore } from '../stores/chronicleStore'
import { chronicleTemplateService } from './ChronicleTemplateService'
import { contextIntelligence } from './ChronicleContextIntelligence'

// Action types that can trigger Chronicle prompts
export type ChronicleActionType =
  | 'dice_roll'
  | 'stat_roll'
  | 'move_roll'
  | 'damage_roll'
  | 'equipment_use'
  | 'equipment_equip'
  | 'equipment_drop'
  | 'item_acquire'
  | 'combat_action'
  | 'spell_cast'
  | 'advancement_gain'
  | 'character_creation'
  | 'session_milestone'

// Context data structure for different action types
export interface ActionContext {
  // Common fields
  actionType: ChronicleActionType
  timestamp: Date
  sessionId?: string
  characterId?: string
  characterName?: string

  // Dice roll context
  diceRoll?: {
    type: 'move' | 'stat' | 'damage' | 'custom'
    stat?: string // STR, DEX, CON, etc.
    moveName?: string
    result: 'success' | 'partial' | 'failure'
    total: number
    modifier: number
    dice: number[]
  }

  // Equipment context
  equipment?: {
    action: 'use' | 'equip' | 'unequip' | 'drop' | 'acquire'
    itemName: string
    itemType?: string
    quantity?: number
  }

  // Combat context
  combat?: {
    action: 'attack' | 'defend' | 'move_combat' | 'use_ability'
    target?: string
    weapon?: string
    damage?: number
  }

  // Location context (if available)
  location?: {
    currentLocation?: string
    previousLocation?: string
  }

  // Additional context for smart prompts
  gameState?: {
    inCombat?: boolean
    currentScene?: string
    recentEvents?: string[]
  }
}

// Chronicle prompt configuration
export interface ChroniclePrompt {
  id: string
  actionContext: ActionContext
  promptText: string
  suggestedEntries: string[]
  priority: 'low' | 'medium' | 'high'
  expiresAt: Date
  isVisible: boolean
  position?: { x: number; y: number }
}

// Action listener callback type
export type ActionListener = (context: ActionContext) => void

// Prompt generation strategies for different action types
type MaybePromise<T> = T | Promise<T>
interface PromptStrategy {
  generatePrompt(context: ActionContext): MaybePromise<ChroniclePrompt | null>
  shouldPrompt(context: ActionContext): boolean
}

export class ChronicleActionListenerService {
  private listeners: Map<ChronicleActionType, ActionListener[]> = new Map()
  private activePrompts: ChroniclePrompt[] = []
  private promptStrategies: Map<ChronicleActionType, PromptStrategy> = new Map()
  private recentActions: ActionContext[] = []
  private isEnabled: boolean = true

  // Settings
  private maxActivePrompts = 2 // Prevent prompt overload
  private promptTimeout = 30000 // 30 seconds
  private minTimeBetweenPrompts = 5000 // 5 seconds cooldown
  private lastPromptTime = 0

  constructor() {
    this.initializePromptStrategies()
    this.startPromptCleanup()
  }

  /**
   * Register an action listener for a specific action type
   */
  addListener(actionType: ChronicleActionType, listener: ActionListener): () => void {
    if (!this.listeners.has(actionType)) {
      this.listeners.set(actionType, [])
    }

    const listeners = this.listeners.get(actionType)!
    listeners.push(listener)

    // Return cleanup function
    return () => {
      const index = listeners.indexOf(listener)
      if (index > -1) {
        listeners.splice(index, 1)
      }
    }
  }

  /**
   * Emit an action event to trigger listeners and potential Chronicle prompts
   */
  emitAction(context: ActionContext): void {
    if (!this.isEnabled) return

    // Add to recent actions
    this.recentActions.push(context)
    if (this.recentActions.length > 10) {
      this.recentActions.shift()
    }

    // Notify listeners
    const listeners = this.listeners.get(context.actionType) || []
    listeners.forEach(listener => {
      try {
        listener(context)
      } catch (error) {
        console.error('Error in action listener:', error)
      }
    })

    // Generate Chronicle prompt if appropriate
    this.considerChroniclePrompt(context)
  }

  /**
   * Get all active Chronicle prompts
   */
  getActivePrompts(): ChroniclePrompt[] {
    return this.activePrompts.filter(p => p.isVisible)
  }

  /**
   * Dismiss a Chronicle prompt
   */
  dismissPrompt(promptId: string): void {
    const prompt = this.activePrompts.find(p => p.id === promptId)
    if (prompt) {
      prompt.isVisible = false
    }
  }

  /**
   * Accept a Chronicle prompt and create an entry
   */
  acceptPrompt(promptId: string, selectedEntry: string, customText?: string): void {
    const prompt = this.activePrompts.find(p => p.id === promptId)
    if (!prompt) return

    const chronicleStore = useChronicleStore.getState()

    // Create chronicle entry with action context
    const entryText = customText || selectedEntry
    const tags = this.generateTagsFromContext(prompt.actionContext)

    chronicleStore.addEntry({
      rawText: entryText,
      tags,
      sessionId: prompt.actionContext.sessionId || chronicleStore.currentSessionId || undefined,
      parsedEntities: [], // Will be parsed by Chronicle system
      actionContext: prompt.actionContext, // Store the original action for reference
      isSceneBreak: false,
      emotionalTone: this.inferEmotionalTone(entryText)
    })

    // Remove the prompt
    this.dismissPrompt(promptId)
  }

  /**
   * Enable/disable the action listener system
   */
  setEnabled(enabled: boolean): void {
    this.isEnabled = enabled
    if (!enabled) {
      this.clearAllPrompts()
    }
  }

  /**
   * Clear all active prompts
   */
  clearAllPrompts(): void {
    this.activePrompts.forEach(p => p.isVisible = false)
  }

  /**
   * Get recent actions for context
   */
  getRecentActions(limit = 5): ActionContext[] {
    return this.recentActions.slice(-limit)
  }

  // Private methods

  private considerChroniclePrompt(context: ActionContext): void {
    // Check cooldown
    const now = Date.now()
    if (now - this.lastPromptTime < this.minTimeBetweenPrompts) {
      return
    }

    // Check active prompt limit
    const visiblePrompts = this.activePrompts.filter(p => p.isVisible)
    if (visiblePrompts.length >= this.maxActivePrompts) {
      return
    }

    // Get strategy for this action type
    const strategy = this.promptStrategies.get(context.actionType)
    if (!strategy || !strategy.shouldPrompt(context)) {
      return
    }

    // Generate prompt (supports sync or async strategies)
    Promise.resolve(strategy.generatePrompt(context))
      .then((prompt) => {
        if (prompt) {
          this.activePrompts.push(prompt)
          this.lastPromptTime = now
        }
      })
      .catch((err) => {
        console.error('Failed to generate Chronicle prompt:', err)
      })
  }

  private initializePromptStrategies(): void {
    // Dice roll strategy
    this.promptStrategies.set('dice_roll', new DiceRollPromptStrategy())
    this.promptStrategies.set('stat_roll', new StatRollPromptStrategy())
    this.promptStrategies.set('move_roll', new MoveRollPromptStrategy())

    // Equipment strategy
    this.promptStrategies.set('equipment_use', new EquipmentPromptStrategy())
    this.promptStrategies.set('equipment_equip', new EquipmentPromptStrategy())

    // Combat strategy
    this.promptStrategies.set('combat_action', new CombatPromptStrategy())
  }

  private startPromptCleanup(): void {
    setInterval(() => {
      const now = new Date()
      this.activePrompts = this.activePrompts.filter(prompt => {
        if (prompt.expiresAt < now) {
          return false
        }
        return true
      })
    }, 5000) // Check every 5 seconds
  }

  private generateTagsFromContext(context: ActionContext): string[] {
    const tags: string[] = []

    if (context.characterName) {
      tags.push(`character:${context.characterName}`)
    }

    if (context.diceRoll?.stat) {
      tags.push(`stat:${context.diceRoll.stat}`)
    }

    if (context.diceRoll?.moveName) {
      tags.push(`move:${context.diceRoll.moveName}`)
    }

    if (context.equipment?.itemName) {
      tags.push(`equipment:${context.equipment.itemName}`)
    }

    if (context.combat) {
      tags.push('combat')
    }

    tags.push(`action:${context.actionType}`)

    return tags
  }

  private inferEmotionalTone(text: string): 'positive' | 'negative' | 'neutral' {
    const lowerText = text.toLowerCase()

    const positiveWords = ['success', 'triumph', 'victory', 'amazing', 'excellent', 'great']
    const negativeWords = ['fail', 'disaster', 'terrible', 'awful', 'miss', 'fumble']

    const hasPositive = positiveWords.some(word => lowerText.includes(word))
    const hasNegative = negativeWords.some(word => lowerText.includes(word))

    if (hasPositive && !hasNegative) return 'positive'
    if (hasNegative && !hasPositive) return 'negative'
    return 'neutral'
  }

  private generatePromptId(): string {
    return `prompt-${Date.now()}-${Math.random().toString(36).slice(2, 11)}`
  }
}

// Prompt strategy implementations

class DiceRollPromptStrategy implements PromptStrategy {
  async generatePrompt(context: ActionContext): Promise<ChroniclePrompt | null> {
    if (!context.diceRoll) return null

    const { result, total } = context.diceRoll
    const character = context.characterName || 'your character'

    // Use template service for better suggestions
    const recentActions = [context] // Would get from action listener
    const contextAnalysis = await contextIntelligence.analyzeContext(recentActions)
    const suggestedEntries = chronicleTemplateService.generateSuggestions(
      context,
      contextAnalysis.situation,
      contextAnalysis.intensity,
      contextAnalysis.narrative.emotionalTone,
      3
    )

    // Generate context-aware prompt text
    let promptText: string
    if (result === 'success') {
      promptText = `${character} rolled a ${total}! Chronicle this success?`
    } else if (result === 'partial') {
      promptText = `${character} got a partial success (${total}). What's the complication?`
    } else {
      promptText = `${character} missed with a ${total}. What goes wrong?`
    }

    return {
      id: `dice-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      actionContext: context,
      promptText,
      suggestedEntries: suggestedEntries.length > 0 ? suggestedEntries : [
        `${character}'s ${result} shapes what happens next.`
      ],
      priority: result === 'failure' ? 'high' : 'medium',
      expiresAt: new Date(Date.now() + 30000),
      isVisible: true
    }
  }

  shouldPrompt(context: ActionContext): boolean {
    // Always prompt for dice rolls - they're core moments
    return true
  }
}

class StatRollPromptStrategy implements PromptStrategy {
  generatePrompt(context: ActionContext): ChroniclePrompt | null {
    if (!context.diceRoll?.stat) return null

    const { stat, result, total } = context.diceRoll
    const character = context.characterName || 'your character'

    const statActions: Record<string, string[]> = {
      'STR': ['lifting', 'breaking', 'forcing', 'overpowering'],
      'DEX': ['dodging', 'sneaking', 'balancing', 'aiming'],
      'CON': ['enduring', 'resisting', 'surviving', 'persevering'],
      'INT': ['analyzing', 'reasoning', 'recalling', 'understanding'],
      'WIS': ['perceiving', 'intuiting', 'sensing', 'noticing'],
      'CHA': ['persuading', 'intimidating', 'deceiving', 'inspiring']
    }

    const actions = statActions[stat] || ['acting']
    const randomAction = actions[Math.floor(Math.random() * actions.length)]

    return {
      id: `stat-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      actionContext: context,
      promptText: `Why did ${character} roll ${stat}? What were they ${randomAction}?`,
      suggestedEntries: [
        `${character} used their ${stat} to ${randomAction} in this situation.`,
        `The situation called for ${character} to test their ${stat}.`,
        `${character}'s ${stat} was put to the test.`
      ],
      priority: 'high',
      expiresAt: new Date(Date.now() + 30000),
      isVisible: true
    }
  }

  shouldPrompt(context: ActionContext): boolean {
    return true // Stat rolls are always significant
  }
}

class MoveRollPromptStrategy implements PromptStrategy {
  generatePrompt(context: ActionContext): ChroniclePrompt | null {
    if (!context.diceRoll?.moveName) return null

    const { moveName, result } = context.diceRoll
    const character = context.characterName || 'your character'

    return {
      id: `move-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      actionContext: context,
      promptText: `${character} used ${moveName}. Chronicle the outcome?`,
      suggestedEntries: [
        `${character} attempted ${moveName} and ${result === 'success' ? 'succeeded' : result === 'partial' ? 'partially succeeded' : 'failed'}.`,
        `The ${moveName} move led to ${result === 'success' ? 'excellent results' : result === 'partial' ? 'mixed results' : 'complications'}.`,
        `${character}'s use of ${moveName} changed the situation.`
      ],
      priority: 'high',
      expiresAt: new Date(Date.now() + 30000),
      isVisible: true
    }
  }

  shouldPrompt(context: ActionContext): boolean {
    return true // Moves are always significant
  }
}

class EquipmentPromptStrategy implements PromptStrategy {
  generatePrompt(context: ActionContext): ChroniclePrompt | null {
    if (!context.equipment) return null

    const { action, itemName } = context.equipment
    const character = context.characterName || 'your character'

    const actionVerbs: Record<string, string> = {
      'use': 'used',
      'equip': 'equipped',
      'unequip': 'put away',
      'drop': 'dropped',
      'acquire': 'acquired'
    }

    const verb = actionVerbs[action] || 'interacted with'

    return {
      id: `equipment-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      actionContext: context,
      promptText: `${character} ${verb} ${itemName}. Chronicle this moment?`,
      suggestedEntries: [
        `${character} ${verb} their ${itemName} at just the right moment.`,
        `The ${itemName} proved ${action === 'use' ? 'useful' : 'important'} to ${character}.`,
        `${character}'s decision to ${action === 'acquire' ? 'take' : action} the ${itemName} was significant.`
      ],
      priority: action === 'use' ? 'medium' : 'low',
      expiresAt: new Date(Date.now() + 25000),
      isVisible: true
    }
  }

  shouldPrompt(context: ActionContext): boolean {
    // Only prompt for meaningful equipment actions
    return context.equipment?.action === 'use' || context.equipment?.action === 'acquire'
  }
}

class CombatPromptStrategy implements PromptStrategy {
  generatePrompt(context: ActionContext): ChroniclePrompt | null {
    if (!context.combat) return null

    const { action, target, weapon, damage } = context.combat
    const character = context.characterName || 'your character'

    let promptText: string
    let suggestedEntries: string[]

    if (action === 'attack') {
      promptText = `${character} attacked${target ? ` ${target}` : ''}${weapon ? ` with ${weapon}` : ''}. Chronicle the combat?`
      suggestedEntries = [
        `${character} strikes ${target || 'their foe'}${weapon ? ` with their ${weapon}` : ''}${damage ? ` for ${damage} damage` : ''}.`,
        `The battle intensifies as ${character} launches their attack.`,
        `${character}'s combat prowess is on full display.`
      ]
    } else {
      promptText = `${character} ${action}ed in combat. What happened?`
      suggestedEntries = [
        `${character}'s ${action} in combat was ${['crucial', 'decisive', 'impressive'][Math.floor(Math.random() * 3)]}.`,
        `The tide of battle shifts as ${character} takes action.`,
        `${character} demonstrates their combat skills.`
      ]
    }

    return {
      id: `combat-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      actionContext: context,
      promptText,
      suggestedEntries,
      priority: 'high',
      expiresAt: new Date(Date.now() + 35000),
      isVisible: true
    }
  }

  shouldPrompt(context: ActionContext): boolean {
    return true // Combat actions are always worth chronicling
  }
}

// Export singleton instance
export const chronicleActionListener = new ChronicleActionListenerService()

/**
 * Chronicle Context Intelligence Engine
 *
 * This engine analyzes the current game state, recent actions, character context,
 * and story patterns to generate intelligent Chronicle prompts and suggestions.
 *
 * Key Features:
 * - Analyzes recent actions to understand narrative flow
 * - Considers character state, location, and ongoing situations
 * - Generates contextually appropriate prompt suggestions
 * - Learns from user patterns to improve future suggestions
 * - Integrates with entity recognition for @mentions
 * - Provides smart templating based on action context
 */

import { useChronicleStore } from '../stores/chronicleStore'
import { useCharacterStore } from '../stores/characterStore'
import { useGameStateStore } from '../stores/gameStateStore'
import type { ActionContext, ChronicleActionType } from './ChronicleActionListenerService'
import { chronicleTemplateService } from './ChronicleTemplateService'

// Context analysis results
export interface ContextAnalysis {
  // Current situation
  situation: 'combat' | 'exploration' | 'social' | 'downtime' | 'unknown'
  intensity: 'low' | 'medium' | 'high'

  // Character context
  characterState: {
    currentHP?: number
    maxHP?: number
    isInjured?: boolean
    hasActiveHolds?: boolean
    recentXPGains?: number
  }

  // Narrative context
  narrative: {
    currentScene?: string
    recentEvents: string[]
    emotionalTone: 'positive' | 'negative' | 'neutral' | 'tense'
    pacing: 'slow' | 'normal' | 'fast'
  }

  // Entity context
  entities: {
    recentlyMentioned: string[]
    currentLocation?: string
    nearbyCharacters?: string[]
    availableItems?: string[]
  }

  // Prompt intelligence
  promptContext: {
    shouldPromptNow: boolean
    suggestedTriggers: ChronicleActionType[]
    recommendedStyle: 'detailed' | 'concise' | 'dramatic'
    suggestedEntities: string[]
  }
}

// Template for generating contextual prompts
export interface PromptTemplate {
  id: string
  actionTypes: ChronicleActionType[]
  situation: string[]
  template: string
  variables: string[]
  priority: number
  examples: string[]
}

// Learning data to improve suggestions over time
interface UserBehaviorPattern {
  userId?: string
  actionType: ChronicleActionType
  promptAcceptanceRate: number
  preferredPromptStyle: 'detailed' | 'concise' | 'dramatic'
  commonWords: string[]
  frequentEntityTypes: string[]
  avgResponseTime: number
}

export class ChronicleContextIntelligence {
  private userPatterns: Map<string, UserBehaviorPattern> = new Map()
  private promptTemplates: PromptTemplate[] = []
  private recentAnalyses: ContextAnalysis[] = []
  private entityCache: Map<string, any> = new Map() // Cache for frequently mentioned entities

  constructor() {
    this.initializePromptTemplates()
    this.loadUserPatterns()
  }

  /**
   * Analyze the current context and generate intelligent Chronicle suggestions
   */
  async analyzeContext(recentActions: ActionContext[]): Promise<ContextAnalysis> {
    const chronicleStore = useChronicleStore.getState()
    const characterStore = useCharacterStore.getState()
    const gameState = useGameStateStore.getState()

    // Analyze current situation
    const situation = this.determineSituation(recentActions, gameState)
    const intensity = this.calculateIntensity(recentActions, situation)

    // Analyze character state
    const characterState = this.analyzeCharacterState(characterStore, gameState)

    // Analyze narrative context
    const narrative = await this.analyzeNarrativeContext(recentActions, chronicleStore)

    // Analyze entity context
    const entities = await this.analyzeEntityContext(recentActions, chronicleStore)

    // Generate prompt intelligence
    const promptContext = this.generatePromptIntelligence(
      situation,
      intensity,
      recentActions,
      narrative,
      entities
    )

    const analysis: ContextAnalysis = {
      situation,
      intensity,
      characterState,
      narrative,
      entities,
      promptContext
    }

    // Cache this analysis
    this.recentAnalyses.push(analysis)
    if (this.recentAnalyses.length > 20) {
      this.recentAnalyses.shift()
    }

    return analysis
  }

  /**
   * Generate smart prompt suggestions based on context
   */
  generateSmartPrompts(
    actionContext: ActionContext,
    contextAnalysis: ContextAnalysis
  ): string[] {
    // Generate highly contextual suggestions based on the specific action
    const contextualSuggestions = this.generateContextualSuggestions(actionContext, contextAnalysis)

    // Add stat-specific suggestions if it's a stat roll
    const statSuggestions = this.generateStatSpecificSuggestions(actionContext, contextAnalysis)

    // Add situation-specific suggestions
    const situationSuggestions = this.generateSituationSuggestions(actionContext, contextAnalysis)

    // Combine all suggestions
    const allSuggestions = [...contextualSuggestions, ...statSuggestions, ...situationSuggestions]
    const uniqueSuggestions = allSuggestions.filter((suggestion, index) =>
      allSuggestions.indexOf(suggestion) === index
    )

    // Sort by relevance and limit results
    return this.rankSuggestions(uniqueSuggestions, actionContext, contextAnalysis).slice(0, 4)
  }

  /**
   * Generate entity mentions for @mention system
   */
  generateEntitySuggestions(
    actionContext: ActionContext,
    contextAnalysis: ContextAnalysis,
    partialInput: string = ''
  ): Array<{ name: string; type: string; confidence: number }> {
    const suggestions: Array<{ name: string; type: string; confidence: number }> = []

    // Suggest recently mentioned entities
    contextAnalysis.entities.recentlyMentioned.forEach(entityName => {
      if (entityName.toLowerCase().includes(partialInput.toLowerCase())) {
        suggestions.push({
          name: entityName,
          type: 'recent',
          confidence: 0.9
        })
      }
    })

    // Suggest contextually relevant entities based on action type
    const contextualEntities = this.getContextualEntities(actionContext, contextAnalysis)
    contextualEntities.forEach(entity => {
      if (entity.name.toLowerCase().includes(partialInput.toLowerCase())) {
        suggestions.push(entity)
      }
    })

    // Sort by confidence and return top matches
    return suggestions
      .sort((a, b) => b.confidence - a.confidence)
      .slice(0, 8)
  }

  /**
   * Learn from user behavior to improve future suggestions
   */
  recordUserBehavior(
    actionType: ChronicleActionType,
    promptAccepted: boolean,
    responseTime: number,
    finalText: string
  ): void {
    const userId = 'current-user' // Would get from auth system

    let pattern = this.userPatterns.get(userId)
    if (!pattern) {
      pattern = {
        actionType,
        promptAcceptanceRate: 0,
        preferredPromptStyle: 'concise',
        commonWords: [],
        frequentEntityTypes: [],
        avgResponseTime: 0
      }
    }

    // Update acceptance rate
    const currentAcceptance = pattern.promptAcceptanceRate
    pattern.promptAcceptanceRate = (currentAcceptance + (promptAccepted ? 1 : 0)) / 2

    // Update average response time
    pattern.avgResponseTime = (pattern.avgResponseTime + responseTime) / 2

    // Analyze text for patterns
    if (promptAccepted && finalText) {
      const words = finalText.toLowerCase().split(/\s+/)
      pattern.commonWords = this.updateWordFrequency(pattern.commonWords, words)

      // Determine preferred style based on text length
      if (finalText.length > 100) {
        pattern.preferredPromptStyle = 'detailed'
      } else if (finalText.length < 50) {
        pattern.preferredPromptStyle = 'concise'
      }
    }

    this.userPatterns.set(userId, pattern)
    this.saveUserPatterns()
  }

  // Private methods

  private determineSituation(
    recentActions: ActionContext[],
    gameState: any
  ): 'combat' | 'exploration' | 'social' | 'downtime' | 'unknown' {
    // Check for combat indicators
    const hasCombatActions = recentActions.some(action =>
      action.actionType === 'combat_action' ||
      action.actionType === 'damage_roll' ||
      action.combat
    )

    if (hasCombatActions || gameState?.inCombat) {
      return 'combat'
    }

    // Check for movement/exploration
    const hasMovement = recentActions.some(action =>
      action.location?.currentLocation !== action.location?.previousLocation
    )

    if (hasMovement) {
      return 'exploration'
    }

    // Check for social interaction
    const hasSocialRolls = recentActions.some(action =>
      action.diceRoll?.stat === 'CHA' ||
      action.diceRoll?.moveName?.toLowerCase().includes('parley')
    )

    if (hasSocialRolls) {
      return 'social'
    }

    // Default based on recent activity
    const recentActivity = recentActions.length > 0
    return recentActivity ? 'unknown' : 'downtime'
  }

  private calculateIntensity(
    recentActions: ActionContext[],
    situation: string
  ): 'low' | 'medium' | 'high' {
    const actionCount = recentActions.length
    const timeSpan = recentActions.length > 1
      ? recentActions[recentActions.length - 1].timestamp.getTime() - recentActions[0].timestamp.getTime()
      : 0

    // High intensity: lots of actions in short time, or combat
    if (situation === 'combat' || (actionCount >= 5 && timeSpan < 60000)) {
      return 'high'
    }

    // Medium intensity: moderate activity
    if (actionCount >= 3 || situation !== 'downtime') {
      return 'medium'
    }

    return 'low'
  }

  private analyzeCharacterState(characterStore: any, gameState: any): any {
    const activeCharacter = characterStore?.activeCharacter
    if (!activeCharacter) {
      return {}
    }

    return {
      currentHP: activeCharacter.hitPoints?.current,
      maxHP: activeCharacter.hitPoints?.max,
      isInjured: (activeCharacter.hitPoints?.current || 0) < (activeCharacter.hitPoints?.max || 0),
      hasActiveHolds: (activeCharacter.holds || []).length > 0,
      recentXPGains: 0 // Would track recent XP gains
    }
  }

  private async analyzeNarrativeContext(
    recentActions: ActionContext[],
    chronicleStore: any
  ): Promise<any> {
    const recentEntries = chronicleStore.entries.slice(-5)
    const recentEvents = recentActions.map(action => {
      if (action.diceRoll) {
        return `${action.diceRoll.type} roll: ${action.diceRoll.result}`
      }
      if (action.equipment) {
        return `${action.equipment.action} ${action.equipment.itemName}`
      }
      return `${action.actionType} action`
    })

    // Determine emotional tone from recent actions
    let emotionalTone: 'positive' | 'negative' | 'neutral' | 'tense' = 'neutral'
    const failures = recentActions.filter(a => a.diceRoll?.result === 'failure').length
    const successes = recentActions.filter(a => a.diceRoll?.result === 'success').length

    if (failures > successes) {
      emotionalTone = 'negative'
    } else if (successes > failures * 2) {
      emotionalTone = 'positive'
    } else if (recentActions.some(a => a.combat)) {
      emotionalTone = 'tense'
    }

    // Determine pacing
    const actionFrequency = recentActions.length / Math.max(1,
      (Date.now() - (recentActions[0]?.timestamp?.getTime() || Date.now())) / 60000
    )

    const pacing = actionFrequency > 2 ? 'fast' : actionFrequency < 0.5 ? 'slow' : 'normal'

    return {
      recentEvents,
      emotionalTone,
      pacing,
      currentScene: 'current scene' // Would be determined by game state
    }
  }

  private async analyzeEntityContext(
    recentActions: ActionContext[],
    chronicleStore: any
  ): Promise<any> {
    const recentEntries = chronicleStore.entries.slice(-10)
    const recentlyMentioned: string[] = []

    // Extract recently mentioned entities
    recentEntries.forEach((entry: any) => {
      if (entry.parsedEntities) {
        entry.parsedEntities.forEach((entity: any) => {
          if (!recentlyMentioned.includes(entity.name)) {
            recentlyMentioned.push(entity.name)
          }
        })
      }
    })

    return {
      recentlyMentioned: recentlyMentioned.slice(0, 10),
      currentLocation: 'current location', // Would be determined from game state
      nearbyCharacters: [], // Would be determined from game state
      availableItems: [] // Would be determined from inventory
    }
  }

  private generatePromptIntelligence(
    situation: string,
    intensity: string,
    recentActions: ActionContext[],
    narrative: any,
    entities: any
  ): any {
    // Determine if we should prompt now
    const shouldPromptNow = this.shouldPromptBasedOnContext(
      situation, intensity, recentActions, narrative
    )

    // Suggest relevant action triggers
    const suggestedTriggers: ChronicleActionType[] = []
    if (situation === 'combat') {
      suggestedTriggers.push('combat_action', 'damage_roll')
    }
    if (intensity === 'high') {
      suggestedTriggers.push('dice_roll', 'move_roll')
    }

    // Recommend style based on situation and user patterns
    let recommendedStyle: 'detailed' | 'concise' | 'dramatic' = 'concise'
    if (situation === 'combat' || intensity === 'high') {
      recommendedStyle = 'dramatic'
    } else if (narrative.pacing === 'slow') {
      recommendedStyle = 'detailed'
    }

    return {
      shouldPromptNow,
      suggestedTriggers,
      recommendedStyle,
      suggestedEntities: entities.recentlyMentioned.slice(0, 5)
    }
  }

  private shouldPromptBasedOnContext(
    situation: string,
    intensity: string,
    recentActions: ActionContext[],
    narrative: any
  ): boolean {
    // Don't prompt too frequently
    const lastPromptTime = this.getLastPromptTime()
    if (Date.now() - lastPromptTime < 10000) { // 10 seconds cooldown
      return false
    }

    // Always prompt for significant moments
    if (situation === 'combat' && intensity === 'high') {
      return true
    }

    // Prompt for dramatic moments
    if (narrative.emotionalTone === 'tense' && recentActions.length > 0) {
      return true
    }

    // Prompt for failures (learning opportunities)
    if (recentActions.some(a => a.diceRoll?.result === 'failure')) {
      return true
    }

    return false
  }

  private selectRelevantTemplates(
    actionContext: ActionContext,
    contextAnalysis: ContextAnalysis
  ): PromptTemplate[] {
    return this.promptTemplates.filter(template => {
      // Match action type
      if (!template.actionTypes.includes(actionContext.actionType)) {
        return false
      }

      // Match situation
      if (!template.situation.includes(contextAnalysis.situation)) {
        return false
      }

      return true
    }).sort((a, b) => b.priority - a.priority)
  }

  private populateTemplate(
    template: PromptTemplate,
    actionContext: ActionContext,
    contextAnalysis: ContextAnalysis
  ): string {
    let result = template.template

    // Replace common variables
    result = result.replace(/\{character\}/g, actionContext.characterName || 'your character')
    result = result.replace(/\{action\}/g, actionContext.actionType.replace('_', ' '))

    if (actionContext.diceRoll) {
      result = result.replace(/\{result\}/g, actionContext.diceRoll.result)
      result = result.replace(/\{stat\}/g, actionContext.diceRoll.stat || 'unknown')
      result = result.replace(/\{total\}/g, actionContext.diceRoll.total.toString())
    }

    if (actionContext.equipment) {
      result = result.replace(/\{item\}/g, actionContext.equipment.itemName)
      result = result.replace(/\{equipment_action\}/g, actionContext.equipment.action)
    }

    return result
  }

  private generateContextualSuggestions(
    actionContext: ActionContext,
    contextAnalysis: ContextAnalysis
  ): string[] {
    const suggestions: string[] = []
    const character = actionContext.characterName || 'I'

    // High-priority contextual suggestions based on action outcome and context
    if (actionContext.diceRoll) {
      const result = actionContext.diceRoll.result
      const total = actionContext.diceRoll.total
      const moveName = actionContext.diceRoll.moveName

      if (result === 'success' && total >= 12) {
        suggestions.push(`${character} exceeded expectations`)
        suggestions.push(`The success was more impressive than anticipated`)
      } else if (result === 'success') {
        suggestions.push(`${character} accomplished the goal`)
        suggestions.push(`Things went according to plan`)
      } else if (result === 'partial') {
        suggestions.push(`${character} succeeded, but with complications`)
        suggestions.push(`There was a cost to this success`)
      } else if (result === 'failure') {
        suggestions.push(`${character} faced an unexpected setback`)
        suggestions.push(`This didn't go as planned`)
      }

      // Move-specific context
      if (moveName) {
        if (moveName.toLowerCase().includes('hack') || moveName.toLowerCase().includes('slash')) {
          suggestions.push(`${character} struck with determination`)
          suggestions.push(`The combat was fierce and brutal`)
        } else if (moveName.toLowerCase().includes('defy')) {
          suggestions.push(`${character} refused to back down`)
          suggestions.push(`Danger was met head-on`)
        } else if (moveName.toLowerCase().includes('discern')) {
          suggestions.push(`${character} carefully observed the situation`)
          suggestions.push(`Important details became clear`)
        }
      }
    }

    return suggestions.filter(s => s.length > 0)
  }

  private generateStatSpecificSuggestions(
    actionContext: ActionContext,
    contextAnalysis: ContextAnalysis
  ): string[] {
    const suggestions: string[] = []
    const character = actionContext.characterName || 'I'

    if (actionContext.diceRoll?.stat) {
      const stat = actionContext.diceRoll.stat
      const result = actionContext.diceRoll.result

      switch (stat) {
        case 'STR':
          if (result === 'success') {
            suggestions.push(`${character} overpowered the obstacle`)
            suggestions.push(`Raw strength proved decisive`)
            suggestions.push(`Physical force was exactly what was needed`)
          } else if (result === 'failure') {
            suggestions.push(`${character} wasn't strong enough`)
            suggestions.push(`The physical challenge proved too much`)
            suggestions.push(`Brute force wasn't the answer`)
          } else {
            suggestions.push(`${character} strained with effort`)
            suggestions.push(`It required every ounce of strength`)
          }
          break

        case 'DEX':
          if (result === 'success') {
            suggestions.push(`${character} moved with perfect timing`)
            suggestions.push(`Agility and precision paid off`)
            suggestions.push(`The quick reflexes made all the difference`)
          } else if (result === 'failure') {
            suggestions.push(`${character} was too slow`)
            suggestions.push(`The timing was off`)
            suggestions.push(`Clumsiness at the worst moment`)
          } else {
            suggestions.push(`${character} managed with careful coordination`)
            suggestions.push(`It was a close call requiring dexterity`)
          }
          break

        case 'CON':
          if (result === 'success') {
            suggestions.push(`${character} endured through sheer toughness`)
            suggestions.push(`Resilience and stamina prevailed`)
            suggestions.push(`The constitution training paid off`)
          } else if (result === 'failure') {
            suggestions.push(`${character} reached physical limits`)
            suggestions.push(`The strain was too much to bear`)
            suggestions.push(`Exhaustion took its toll`)
          } else {
            suggestions.push(`${character} pushed through the discomfort`)
            suggestions.push(`It took significant physical effort`)
          }
          break

        case 'INT':
          if (result === 'success') {
            suggestions.push(`${character} figured out the solution`)
            suggestions.push(`Quick thinking saved the day`)
            suggestions.push(`The puzzle pieces fell into place`)
          } else if (result === 'failure') {
            suggestions.push(`${character} was stumped by the complexity`)
            suggestions.push(`The problem proved too challenging`)
            suggestions.push(`Logic wasn't enough this time`)
          } else {
            suggestions.push(`${character} worked through the problem`)
            suggestions.push(`It required careful analysis`)
          }
          break

        case 'WIS':
          if (result === 'success') {
            suggestions.push(`${character} trusted their instincts`)
            suggestions.push(`Experience and wisdom guided the choice`)
            suggestions.push(`The gut feeling was right`)
          } else if (result === 'failure') {
            suggestions.push(`${character} misread the situation`)
            suggestions.push(`The instincts were wrong this time`)
            suggestions.push(`Wisdom failed in this moment`)
          } else {
            suggestions.push(`${character} sensed something important`)
            suggestions.push(`Intuition provided partial clarity`)
          }
          break

        case 'CHA':
          if (result === 'success') {
            suggestions.push(`${character} was charming and persuasive`)
            suggestions.push(`The words had exactly the right effect`)
            suggestions.push(`Charisma won them over`)
          } else if (result === 'failure') {
            suggestions.push(`${character} said the wrong thing`)
            suggestions.push(`The social approach backfired`)
            suggestions.push(`Words failed to convince`)
          } else {
            suggestions.push(`${character} made some headway socially`)
            suggestions.push(`The conversation was complex`)
          }
          break
      }
    }

    return suggestions.filter(s => s.length > 0)
  }

  private generateSituationSuggestions(
    actionContext: ActionContext,
    contextAnalysis: ContextAnalysis
  ): string[] {
    const suggestions: string[] = []
    const character = actionContext.characterName || 'I'

    // Situation-based suggestions
    switch (contextAnalysis.situation) {
      case 'combat':
        if (contextAnalysis.intensity === 'high') {
          suggestions.push(`The battle reached a critical moment`)
          suggestions.push(`Adrenaline surged through the fight`)
        } else {
          suggestions.push(`The combat continued steadily`)
          suggestions.push(`Each move was calculated`)
        }
        break

      case 'exploration':
        suggestions.push(`${character} discovered something unexpected`)
        suggestions.push(`The environment revealed new details`)
        suggestions.push(`Careful exploration paid off`)
        break

      case 'social':
        suggestions.push(`The conversation took an interesting turn`)
        suggestions.push(`Social dynamics shifted`)
        suggestions.push(`Understanding grew between the participants`)
        break

      case 'downtime':
        suggestions.push(`${character} took time to reflect`)
        suggestions.push(`The quiet moment provided clarity`)
        suggestions.push(`Rest allowed for deeper thoughts`)
        break
    }

    // Emotional tone suggestions
    switch (contextAnalysis.narrative.emotionalTone) {
      case 'tense':
        suggestions.push(`Tension filled the air`)
        suggestions.push(`Everyone held their breath`)
        break
      case 'positive':
        suggestions.push(`Optimism grew stronger`)
        suggestions.push(`Things were looking up`)
        break
      case 'negative':
        suggestions.push(`The mood grew darker`)
        suggestions.push(`Concerns weighed heavily`)
        break
    }

    return suggestions.filter(s => s.length > 0)
  }

  private generatePatternBasedSuggestions(
    actionContext: ActionContext,
    contextAnalysis: ContextAnalysis
  ): string[] {
    const suggestions: string[] = []
    const character = actionContext.characterName || 'your character'

    // Pattern-based suggestions based on user behavior
    const userId = 'current-user'
    const userPattern = this.userPatterns.get(userId)

    if (userPattern?.commonWords.length > 0) {
      const commonWord = userPattern.commonWords[0]
      suggestions.push(`${character} ${commonWord} in this moment.`)
    }

    return suggestions
  }

  private rankSuggestions(
    suggestions: string[],
    actionContext: ActionContext,
    contextAnalysis: ContextAnalysis
  ): string[] {
    // Simple ranking based on length preference and context relevance
    const userId = 'current-user'
    const userPattern = this.userPatterns.get(userId)
    const preferredStyle = userPattern?.preferredPromptStyle || 'concise'

    return suggestions.sort((a, b) => {
      let scoreA = 0
      let scoreB = 0

      // Score based on length preference
      if (preferredStyle === 'detailed') {
        scoreA += a.length > 80 ? 10 : 0
        scoreB += b.length > 80 ? 10 : 0
      } else if (preferredStyle === 'concise') {
        scoreA += a.length < 60 ? 10 : 0
        scoreB += b.length < 60 ? 10 : 0
      }

      // Score based on context relevance
      if (contextAnalysis.entities.recentlyMentioned.some(entity =>
        a.toLowerCase().includes(entity.toLowerCase())
      )) {
        scoreA += 5
      }

      if (contextAnalysis.entities.recentlyMentioned.some(entity =>
        b.toLowerCase().includes(entity.toLowerCase())
      )) {
        scoreB += 5
      }

      return scoreB - scoreA
    })
  }

  private getContextualEntities(
    actionContext: ActionContext,
    contextAnalysis: ContextAnalysis
  ): Array<{ name: string; type: string; confidence: number }> {
    const entities: Array<{ name: string; type: string; confidence: number }> = []

    // Add character name if available
    if (actionContext.characterName) {
      entities.push({
        name: actionContext.characterName,
        type: 'character',
        confidence: 1.0
      })
    }

    // Add equipment entities
    if (actionContext.equipment) {
      entities.push({
        name: actionContext.equipment.itemName,
        type: 'item',
        confidence: 0.8
      })
    }

    // Add location entities
    if (contextAnalysis.entities.currentLocation) {
      entities.push({
        name: contextAnalysis.entities.currentLocation,
        type: 'location',
        confidence: 0.7
      })
    }

    return entities
  }

  private updateWordFrequency(currentWords: string[], newWords: string[]): string[] {
    const wordCount: Map<string, number> = new Map()

    // Count current words
    currentWords.forEach(word => {
      wordCount.set(word, (wordCount.get(word) || 0) + 1)
    })

    // Add new words
    newWords.filter(word => word.length > 3).forEach(word => {
      wordCount.set(word, (wordCount.get(word) || 0) + 1)
    })

    // Return top words
    return Array.from(wordCount.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, 20)
      .map(entry => entry[0])
  }

