/**
 * Spell Casting Service for ZimboMate V2
 * Utilities for Dungeon World spell preparation and casting (official rules)
 * Modernized from V1 with improved TypeScript patterns and V2 model integration
 */

import type { Attribute, Character, CharacterClass } from '../models/Character'
import type { DiceRoll, RollModifiers, RollOptions } from './DiceRollingService'
import { getAttributeModifier } from '../models/Character'
import { diceRollingService } from './DiceRollingService'

// Spell interface for the service
export interface ServiceSpell {
  id: string
  name: string
  level: number
  description: string
  tags?: string[]
  range?: string
  duration?: string
  requiresClass?: CharacterClass
}

// Spell classes that can cast spells
export type SpellClass = 'Wizard' | 'Cleric' | 'Immolator'

// Spell casting result tiers
export type CastingTier = '10+' | '7-9' | '6-'

// Spell casting result
export interface SpellCastingResult {
  roll: DiceRoll
  updated: Character
  tier: CastingTier
  spellLost?: boolean
  consequences?: string[]
}

// 7-9 consequence options
export type SevenToNineConsequence = 'unwelcome-attention' | 'forget' | 'strain'

/**
 * Utilities for Dungeon World spell preparation and casting (official rules)
 */
export class SpellCastingService {
  constructor(private dice = diceRollingService) {}

  /**
   * Which stat is used to cast spells for this character
   */
  getSpellcastingStat(character: Character): keyof Attribute | undefined {
    if (character.class === 'Wizard') return 'INT'
    if (character.class === 'Cleric') return 'WIS'
    if (character.class === 'Immolator') return 'INT' // Immolator uses INT
    return undefined
  }

  /**
   * Check if character can cast spells
   */
  canCastSpells(character: Character): boolean {
    return this.getSpellcastingStat(character) !== undefined
  }

  /**
   * Cantrip / Rote check (level 0)
   */
  isCantrip(spell: ServiceSpell): boolean {
    return spell.level === 0
  }

  /**
   * Official preparation budget: Level + 1 total spell levels; cantrips / rotes don't count
   */
  getPreparationBudget(character: Character): number {
    return character.level + 1
  }

  /**
   * Sum of non-cantrip spell levels in list
   */
  calculatePreparedLevels(spells: ServiceSpell[]): number {
    return spells.reduce((sum, s) => sum + (this.isCantrip(s) ? 0 : s.level), 0)
  }

  /**
   * Check if spell list fits within preparation budget
   */
  canPrepareSpells(character: Character, spells: ServiceSpell[]): {
    canPrepare: boolean
    totalLevels: number
    budget: number
    overflow: number
  } {
    const totalLevels = this.calculatePreparedLevels(spells)
    const budget = this.getPreparationBudget(character)
    const overflow = Math.max(0, totalLevels - budget)

    return {
      canPrepare: overflow === 0,
      totalLevels,
      budget,
      overflow,
    }
  }

  /**
   * Replace prepared spells for Wizard / Cleric according to budget rules
   */
  prepareSpells(character: Character, selectedSpells: ServiceSpell[]): Character {
    if (!this.canCastSpells(character)) {
      throw new Error('This class does not cast spells.')
    }

    const preparationCheck = this.canPrepareSpells(character, selectedSpells)
    if (!preparationCheck.canPrepare) {
      throw new Error(`Preparation exceeds budget by ${preparationCheck.overflow} spell levels`)
    }

    const updated: Character = {
      ...character,
      preparedSpells: selectedSpells.map(s => s.id),
      // Remove spellcasting strain on new preparation / commune
      conditions: character.conditions.filter(c => c !== 'spellcasting-strain'),
      updatedAt: new Date(),
    }

    return updated
  }

  /**
   * Cast a prepared spell following DW rules
   */
  castPreparedSpell(
    character: Character, 
    spell: ServiceSpell, 
    options?: { 
      advantage?: boolean
      disadvantage?: boolean
      description?: string
      customModifier?: number
    }
  ): SpellCastingResult {
    const statKey = this.getSpellcastingStat(character)
    if (!statKey) {
      throw new Error('This class does not cast spells.')
    }

    // Verify the spell is prepared (DW requires prepared / granted spells)
    const prepared = character.preparedSpells || []
    if (!prepared.includes(spell.id) && !this.isCantrip(spell)) {
      throw new Error('Spell is not prepared.')
    }

    // Compute modifiers: stat + ongoing penalties specific to casting
    const statMod = getAttributeModifier(character.attributes[statKey])
    const hasStrain = character.conditions.includes('spellcasting-strain')
    const ongoingPenalty = hasStrain ? -1 : 0

    const modifiers: RollModifiers = {
      stat: statMod,
      ongoing: ongoingPenalty,
      forward: 0,
      other: options?.customModifier || 0,
    }

    const rollOptions: RollOptions = {
      character,
      description: options?.description ?? `Cast ${spell.name}`,
      advantage: options?.advantage,
      disadvantage: options?.disadvantage,
    }

    const roll = this.dice.roll2d6(modifiers, rollOptions)

    // Apply DW outcomes
    let updated: Character = { ...character, updatedAt: new Date() }
    let tier: CastingTier
    const spellLost = false
    const consequences: string[] = []

    if (roll.total >= 10) {
      // 10+: success, retain spell
      tier = '10+'
      consequences.push('The spell is successfully cast and retained.')
    } else if (roll.total >= 7) {
      // 7–9: caller must choose one of DW-listed consequences
      tier = '7-9'
      consequences.push('Choose one: draw unwelcome attention, forget the spell, or take -1 ongoing to cast a spell until you prepare spells again.')
    } else {
      // 6-: failure — mark XP immediately
      tier = '6-'
      updated = { ...updated, xp: (updated.xp || 0) + 1 }
      consequences.push('Mark XP. The GM makes a move.')
    }

    return { roll, updated, tier, spellLost, consequences }
  }

  /**
   * Apply a 7–9 consequence. Returns an updated character.
   */
  applySevenToNineConsequence(
    character: Character, 
    spell: ServiceSpell, 
    consequence: SevenToNineConsequence
  ): Character {
    const updated = { ...character, updatedAt: new Date() }

    switch (consequence) {
      case 'forget':
        // Wizard: forgotten; Cleric: revoked — same effect: remove from prepared
        const prepared = character.preparedSpells || []
        updated.preparedSpells = prepared.filter(id => id !== spell.id)
        break

      case 'strain':
        // -1 ongoing to Cast a Spell until next Prepare / Commune
        const conditions = new Set(character.conditions || [])
        conditions.add('spellcasting-strain')
        updated.conditions = [...conditions]
        break

      case 'unwelcome-attention':
        // This is fictional; no mechanical change here
        // The GM will make a move based on the fiction
        break
    }

    return updated
  }

  /**
   * Get available spells for a character class and level
   */
  getAvailableSpells(characterClass: CharacterClass, level: number): ServiceSpell[] {
    // This would typically load from a spell compendium
    // For now, return empty array as we don't have spell data loaded
    return []
  }

  /**
   * Get spell by ID
   */
  getSpellById(spellId: string): ServiceSpell | undefined {
    // This would typically load from a spell compendium
    // For now, return undefined as we don't have spell data loaded
    return undefined
  }

  /**
   * Check if a spell can be cast by a character
   */
  canCastSpell(character: Character, spell: ServiceSpell): {
    canCast: boolean
    reasons: string[]
  } {
    const reasons: string[] = []
    let canCast = true

    // Check if character can cast spells
    if (!this.canCastSpells(character)) {
      reasons.push('Character class cannot cast spells')
      canCast = false
    }

    // Check class requirement
    if (spell.requiresClass && spell.requiresClass !== character.class) {
      reasons.push(`Spell requires ${spell.requiresClass} class`)
      canCast = false
    }

    // Check if spell is prepared (unless it's a cantrip)
    if (!this.isCantrip(spell)) {
      const prepared = character.preparedSpells || []
      if (!prepared.includes(spell.id)) {
        reasons.push('Spell is not prepared')
        canCast = false
      }
    }

    return { canCast, reasons }
  }

  /**
   * Get spell casting statistics for a character
   */
  getSpellcastingStats(character: Character): {
    canCastSpells: boolean
    spellcastingStat?: keyof Attribute
    preparationBudget: number
    preparedSpells: number
    preparedLevels: number
    hasStrain: boolean
    availableCantrips: number
  } {
    const canCastSpells = this.canCastSpells(character)
    const spellcastingStat = this.getSpellcastingStat(character)
    const preparationBudget = this.getPreparationBudget(character)
    const preparedSpells = (character.preparedSpells || []).length
    const hasStrain = character.conditions.includes('spellcasting-strain')

    // Calculate prepared levels (would need actual spell data)
    const preparedLevels = 0 // This would calculate from actual prepared spells

    return {
      canCastSpells,
      spellcastingStat,
      preparationBudget,
      preparedSpells,
      preparedLevels,
      hasStrain,
      availableCantrips: 0, // This would count available cantrips
    }
  }

  /**
   * Remove spellcasting strain (typically done during spell preparation)
   */
  removeSpellcastingStrain(character: Character): Character {
    return {
      ...character,
      conditions: character.conditions.filter(c => c !== 'spellcasting-strain'),
      updatedAt: new Date(),
    }
  }

  /**
   * Add spellcasting strain
   */
  addSpellcastingStrain(character: Character): Character {
    const conditions = new Set(character.conditions || [])
    conditions.add('spellcasting-strain')
    
    return {
      ...character,
      conditions: [...conditions],
      updatedAt: new Date(),
    }
  }
}

// Export singleton instance
export const spellCastingService = new SpellCastingService()

/**
 * XP Integration Service for ZimboMate V2
 * Centralized XP management from all sources with notifications and analytics
 */

import { getXPThreshold } from '../models/Character'

export interface XPSource {
  id: string
  name: string
  description: string
  category: 'failure' | 'bond' | 'alignment' | 'advancement' | 'gm-award' | 'special'
  color: string
  icon: string
}

export interface XPEntry {
  id: string
  characterId: string
  source: XPSource
  amount: number
  reason: string
  timestamp: Date
  sessionId?: string
  metadata?: Record<string, any>
}

export interface XPNotification {
  id: string
  characterId: string
  entry: XPEntry
  message: string
  type: 'success' | 'milestone' | 'level-up'
  duration: number
  actions?: Array<{
    label: string
    action: () => void
  }>
}

export interface XPAnalytics {
  totalXP: number
  xpBySource: Record<string, number>
  xpBySession: Record<string, number>
  averageXPPerSession: number
  mostCommonSource: XPSource
  xpTrend: Array<{
    date: Date
    amount: number
    cumulative: number
  }>
}

class XPIntegrationService {
  private xpEntries: Map<string, XPEntry[]> = new Map() // characterId -> entries
  private notifications: XPNotification[] = []
  private listeners: Set<(notification: XPNotification) => void> = new Set()
  private analyticsCache: Map<string, XPAnalytics> = new Map()

  // Predefined XP sources
  private xpSources: Map<string, XPSource> = new Map([
    ['failure', {
      id: 'failure',
      name: 'Failed Roll',
      description: 'XP gained from rolling 6- on a move',
      category: 'failure',
      color: 'var(--chart-4)',
      icon: 'AlertTriangle'
    }],
    ['bond-resolution', {
      id: 'bond-resolution',
      name: 'Bond Resolution',
      description: 'XP gained from resolving a bond with another character',
      category: 'bond',
      color: 'var(--chart-2)',
      icon: 'Heart'
    }],
    ['alignment-good', {
      id: 'alignment-good',
      name: 'Good Alignment',
      description: 'XP gained from acting according to Good alignment',
      category: 'alignment',
      color: 'var(--chart-3)',
      icon: 'Heart'
    }],
    ['alignment-lawful', {
      id: 'alignment-lawful',
      name: 'Lawful Alignment',
      description: 'XP gained from acting according to Lawful alignment',
      category: 'alignment',
      color: 'var(--primary)',
      icon: 'Shield'
    }],
    ['alignment-neutral', {
      id: 'alignment-neutral',
      name: 'Neutral Alignment',
      description: 'XP gained from acting according to Neutral alignment',
      category: 'alignment',
      color: 'var(--muted-foreground)',
      icon: 'Scale'
    }],
    ['alignment-chaotic', {
      id: 'alignment-chaotic',
      name: 'Chaotic Alignment',
      description: 'XP gained from acting according to Chaotic alignment',
      category: 'alignment',
      color: 'var(--accent)',
      icon: 'Zap'
    }],
    ['alignment-evil', {
      id: 'alignment-evil',
      name: 'Evil Alignment',
      description: 'XP gained from acting according to Evil alignment',
      category: 'alignment',
      color: 'var(--destructive)',
      icon: 'Skull'
    }],
    ['level-up', {
      id: 'level-up',
      name: 'Level Up',
      description: 'XP reset when leveling up',
      category: 'advancement',
      color: 'var(--chart-2)',
      icon: 'Star'
    }],
    ['gm-award', {
      id: 'gm-award',
      name: 'GM Award',
      description: 'XP awarded by the GM for exceptional roleplay',
      category: 'gm-award',
      color: 'var(--primary)',
      icon: 'Award'
    }],
    ['end-of-session', {
      id: 'end-of-session',
      name: 'End of Session',
      description: 'XP gained at the end of a session',
      category: 'special',
      color: 'var(--accent)',
      icon: 'Calendar'
    }]
  ])

  /**
   * Award XP to a character
   */
  awardXP(
    characterId: string,
    sourceId: string,
    amount: number,
    reason: string,
    sessionId?: string,
    metadata?: Record<string, any>
  ): XPEntry {
    const source = this.xpSources.get(sourceId)
    if (!source) {
      throw new Error(`Unknown XP source: ${sourceId}`)
    }

    const entry: XPEntry = {
      id: `xp-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      characterId,
      source,
      amount,
      reason,
      timestamp: new Date(),
      sessionId,
      metadata
    }

    // Add to character's XP entries
    if (!this.xpEntries.has(characterId)) {
      this.xpEntries.set(characterId, [])
    }
    this.xpEntries.get(characterId)!.push(entry)

    // Clear analytics cache for this character
    this.analyticsCache.delete(characterId)

    // Create notification
    this.createNotification(entry)

    // Check for level up
    this.checkLevelUp(characterId)

    return entry
  }

  /**
   * Get XP entries for a character
   */
  getXPEntries(characterId: string, limit?: number): XPEntry[] {
    const entries = this.xpEntries.get(characterId) || []
    const sortedEntries = entries.sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime())
    return limit ? sortedEntries.slice(0, limit) : sortedEntries
  }

  /**
   * Get total XP for a character
   */
  getTotalXP(characterId: string): number {
    const entries = this.xpEntries.get(characterId) || []
    return entries.reduce((total, entry) => total + entry.amount, 0)
  }

  /**
   * Get XP analytics for a character
   */
  getAnalytics(characterId: string): XPAnalytics {
    if (this.analyticsCache.has(characterId)) {
      return this.analyticsCache.get(characterId)!
    }

    const entries = this.xpEntries.get(characterId) || []
    
    // Calculate analytics
    const totalXP = entries.reduce((sum, entry) => sum + entry.amount, 0)
    
    const xpBySource: Record<string, number> = {}
    entries.forEach(entry => {
      xpBySource[entry.source.id] = (xpBySource[entry.source.id] || 0) + entry.amount
    })

    const xpBySession: Record<string, number> = {}
    entries.forEach(entry => {
      if (entry.sessionId) {
        xpBySession[entry.sessionId] = (xpBySession[entry.sessionId] || 0) + entry.amount
      }
    })

    const sessionCount = Object.keys(xpBySession).length
    const averageXPPerSession = sessionCount > 0 ? totalXP / sessionCount : 0

    const mostCommonSourceId = Object.entries(xpBySource)
      .sort(([,a], [,b]) => b - a)[0]?.[0]
    const mostCommonSource = mostCommonSourceId ? this.xpSources.get(mostCommonSourceId)! : this.xpSources.get('failure')!

    // Calculate XP trend
    const xpTrend = entries
      .sort((a, b) => a.timestamp.getTime() - b.timestamp.getTime())
      .reduce((trend, entry) => {
        const cumulative = (trend[trend.length - 1]?.cumulative || 0) + entry.amount
        trend.push({
          date: entry.timestamp,
          amount: entry.amount,
          cumulative
        })
        return trend
      }, [] as Array<{ date: Date; amount: number; cumulative: number }>)

    const analytics: XPAnalytics = {
      totalXP,
      xpBySource,
      xpBySession,
      averageXPPerSession,
      mostCommonSource,
      xpTrend
    }

    this.analyticsCache.set(characterId, analytics)
    return analytics
  }

  /**
   * Get available XP sources
   */
  getXPSources(): XPSource[] {
    return Array.from(this.xpSources.values())
  }

  /**
   * Add notification listener
   */
  addNotificationListener(listener: (notification: XPNotification) => void) {
    this.listeners.add(listener)
  }

  /**
   * Remove notification listener
   */
  removeNotificationListener(listener: (notification: XPNotification) => void) {
    this.listeners.delete(listener)
  }

  /**
   * Get pending notifications
   */
  getNotifications(): XPNotification[] {
    return [...this.notifications]
  }

  /**
   * Clear notification
   */
  clearNotification(notificationId: string) {
    this.notifications = this.notifications.filter(n => n.id !== notificationId)
  }

  /**
   * Create XP notification
   */
  private createNotification(entry: XPEntry) {
    const notification: XPNotification = {
      id: `notification-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      characterId: entry.characterId,
      entry,
      message: this.formatXPMessage(entry),
      type: entry.amount >= 3 ? 'milestone' : 'success',
      duration: entry.amount >= 3 ? 8000 : 5000,
      actions: entry.source.category === 'failure' ? [
        {
          label: 'View Character',
          action: () => {
            // Navigate to character sheet
            console.log('Navigate to character sheet')
          }
        }
      ] : undefined
    }

    this.notifications.push(notification)
    
    // Notify listeners
    this.listeners.forEach(listener => listener(notification))

    // Auto-clear notification after duration
    setTimeout(() => {
      this.clearNotification(notification.id)
    }, notification.duration)
  }

  /**
   * Format XP gain message
   */
  private formatXPMessage(entry: XPEntry): string {
    const amount = entry.amount > 0 ? `+${entry.amount}` : entry.amount.toString()
    return `${amount} XP from ${entry.source.name}: ${entry.reason}`
  }

  /**
   * Check if character should level up
   */
  private checkLevelUp(characterId: string) {
    const totalXP = this.getTotalXP(characterId)
    
    // Use official DW rule: Current Level + 7
    
    // Find current level based on XP using official DW rules
    let currentLevel = 1
    while (totalXP >= getXPThreshold(currentLevel)) {
      currentLevel++
    }

    // Check if character has enough XP for next level
    if (totalXP >= getXPThreshold(currentLevel)) {
      this.createLevelUpNotification(characterId, currentLevel + 1)
    }
  }

  /**
   * Create level up notification
   */
  private createLevelUpNotification(characterId: string, newLevel: number) {
    const notification: XPNotification = {
      id: `levelup-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      characterId,
      entry: {
        id: 'level-up-check',
        characterId,
        source: this.xpSources.get('level-up')!,
        amount: 0,
        reason: `Ready to advance to level ${newLevel}`,
        timestamp: new Date()
      },
      message: `🎉 Ready to Level Up! You can advance to level ${newLevel}`,
      type: 'level-up',
      duration: 10000,
      actions: [
        {
          label: 'Level Up Now',
          action: () => {
            console.log('Trigger level up process')
          }
        },
        {
          label: 'View Character',
          action: () => {
            console.log('Navigate to character sheet')
          }
        }
      ]
    }

    this.notifications.push(notification)
    this.listeners.forEach(listener => listener(notification))
  }

  /**
   * Export XP data for backup
   */
  exportXPData(characterId: string): any {
    return {
      characterId,
      entries: this.xpEntries.get(characterId) || [],
      analytics: this.getAnalytics(characterId),
      exportDate: new Date()
    }
  }

  /**
   * Import XP data from backup
   */
  importXPData(data: any): boolean {
    try {
      if (!data.characterId || !Array.isArray(data.entries)) {
        return false
      }

      this.xpEntries.set(data.characterId, data.entries)
      this.analyticsCache.delete(data.characterId)
      return true
    } catch (error) {
      console.error('Failed to import XP data:', error)
      return false
    }
  }
}

