  async initialize(): Promise<void> {
    if (this.initializationPromise) {
      return this.initializationPromise;
    }

    this.initializationPromise = this.doInitialize();
    return this.initializationPromise;
  }

  private async doInitialize(): Promise<void> {
    const startTime = Date.now();
    const progressInterval: NodeJS.Timeout | null = null;

    try {
      logger.info("Starting AI initialization - downloading Hermes 3 model (q4f32_1 - ~5.8GB)...");
      this.onProgress?.({ progress: 0, text: "Initializing AI engine..." });

      // Enhanced progress callback with WebLLM cache loading format parsing
      const progressCallback = (report: any) => {
        logger.info("AI Loading Progress:", JSON.stringify(report, null, 2));

        let progress = 0;
        let text = "Loading AI model...";
        let isRealProgress = false;

        if (report && typeof report === 'object') {
          logger.info("Progress report keys:", Object.keys(report));

          // Parse WebLLM's cache loading format: "Loading model from cache[48/108]: 2048MB loaded. 44% completed, 30 secs elapsed."
          if (typeof report.text === 'string') {
            const cacheMatch = report.text.match(/Loading model from cache\[(\d+)\/(\d+)\].*?(\d+)% completed/);
            if (cacheMatch) {
              const [, current, total, percentage] = cacheMatch;
              progress = parseInt(percentage);
              text = `Loading model parts (${current}/${total})`;
              isRealProgress = true;
              logger.info(`📦 Cache loading: ${current}/${total} parts, ${progress}%`);
            } else {
              // Try other progress patterns
              const percentMatch = report.text.match(/(\d+)%/);
              if (percentMatch) {
                progress = parseInt(percentMatch[1]);
                text = report.text.replace(/Loading model from cache\[\d+\/\d+\]:\s*/, '');
                isRealProgress = true;
              } else {
                // Use the raw text but clean it up
                text = report.text.replace(/Loading model from cache\[\d+\/\d+\]:\s*/, 'Loading model: ');
              }
            }
          }

          // Fallback to other progress formats
          if (!isRealProgress) {
            if (typeof report.progress === 'number') {
              progress = Math.round(report.progress * 100);
              isRealProgress = true;
            } else if (typeof report.loaded === 'number' && typeof report.total === 'number' && report.total > 0) {
              progress = Math.round((report.loaded / report.total) * 100);
              isRealProgress = true;
            }
          }

          // Extract other text sources
          if (!text || text === "Loading AI model...") {
            if (typeof report.message === 'string') {
              text = report.message;
            } else if (typeof report.status === 'string') {
              text = report.status;
            } else if (typeof report.task === 'string') {
              text = report.task;
            }
          }

          if (isRealProgress) {
            logger.info(`✅ Real progress detected: ${progress}% - ${text}`);

            // Calculate time remaining for real progress
            let timeRemaining;
            if (progress > 5 && progress < 95) {
              const elapsed = Date.now() - startTime;
              const estimated = (elapsed / progress) * (100 - progress);
              if (estimated > 2000) {
                timeRemaining = `${Math.round(estimated / 1000)}s remaining`;
              }
            }

            this.onProgress?.({ progress, text, timeRemaining });
          } else {
            logger.info("❌ No progress data found in report");
            // Show indeterminate progress with cleaned up text
            this.onProgress?.({ progress: 0, text: text.length < 100 ? text : "Loading model..." });
          }
        }
      };

      // Use CreateMLCEngine with progress callback instead of reload
      logger.info("🚀 Creating WebLLM engine with progress tracking (q4f32_1)...");
      logger.info("📊 Model specs: Hermes-3-Llama-3.1-8B-q4f32_1-MLC (~5.8GB, 32-bit precision)");
      this.engine = await webllm.CreateMLCEngine("Hermes-3-Llama-3.1-8B-q4f32_1-MLC", {
        initProgressCallback: progressCallback
      });

      this.isReady = true;
      this.onProgress?.({ progress: 100, text: "AI ready!" });
      logger.info("✅ AI Note Enhancer ready! Hermes 3 model loaded successfully.");
    } catch (error) {
      logger.error("❌ Failed to initialize AI Note Enhancer:", error);

      // Fallback to manual engine creation without progress
      try {
        logger.info("🔄 Retrying with manual engine creation...");
        this.onProgress?.({ progress: 50, text: "Retrying without progress tracking..." });

        this.engine = new webllm.MLCEngine();
        await this.engine.reload("Hermes-3-Llama-3.1-8B-q4f32_1-MLC");

        this.isReady = true;
        this.onProgress?.({ progress: 100, text: "AI ready!" });
        logger.info("✅ AI Note Enhancer ready! (fallback successful)");
      } catch (fallbackError) {
        logger.error("❌ Fallback also failed:", fallbackError);
        this.onProgress?.({ progress: 0, text: "AI failed to load" });
        throw fallbackError;
      }
    } finally {
      if (progressInterval) {
        clearInterval(progressInterval);
      }
    }
  }

  // JSON repair utility for malformed function call arguments
  private repairJSON(jsonStr: string): string {
    try {
      // First try parsing as-is
      JSON.parse(jsonStr);
      return jsonStr;
    } catch {
      // Common fixes for malformed JSON
      let repaired = jsonStr;

      // Fix single quotes to double quotes
      repaired = repaired.replace(/'/g, '"');

      // Fix unquoted keys
      repaired = repaired.replace(/(\w+):/g, '"$1":');

      // Fix trailing commas
      repaired = repaired.replace(/,\s*}/g, '}');
      repaired = repaired.replace(/,\s*]/g, ']');

      // Try parsing again
      try {
        JSON.parse(repaired);
        logger.info("🔧 JSON repaired successfully:", { original: jsonStr, repaired });
        return repaired;
      } catch {
        logger.warn("❌ Could not repair JSON:", jsonStr);
        return jsonStr; // Return original if repair fails
      }
    }
  }

  async enhance(note: string, vibe: CampaignVibe = 'fantasy'): Promise<EnhancementResult> {
    if (!this.isReady || !this.engine) {
      throw new Error("AI not ready - call initialize() first");
    }

    logger.info(`🎭 Enhancing note with ${vibe} vibe:`, note);
    const startTime = Date.now();

    try {
      const response = await this.engine.chat.completions.create({
        messages: [
          {
            role: "system",
            content: this.getVibeSystemPrompt(vibe)
          },
          {
            role: "user",
            content: `Process this story note: "${note}"`
          }
        ],
        tools: this.dungeonWorldTools,
        tool_choice: "auto",
        temperature: 0.7,
        max_tokens: 300 // Increased for better narrative enhancement
      });

      const processingTime = Date.now() - startTime;
      logger.info(`⚡ AI processing completed in ${processingTime}ms`);

      const message = response.choices[0].message;
      const enhancedText = message.content?.trim() || note;
      const actions: CharacterAction[] = [];

      logger.info("📝 Raw AI response:", {
        content: message.content,
        toolCalls: message.tool_calls?.length || 0
      });

      // Process tool calls with JSON validation and repair
      if (message.tool_calls && message.tool_calls.length > 0) {
        logger.info(`🔧 Processing ${message.tool_calls.length} tool calls...`);

        for (const toolCall of message.tool_calls) {
          if (toolCall.type === 'function') {
            try {
              logger.info(`🛠️ Processing function: ${toolCall.function.name}`);
              logger.info(`📋 Raw arguments: ${toolCall.function.arguments}`);

              // Attempt to repair JSON if needed
              const repairedArgs = this.repairJSON(toolCall.function.arguments);
              const params = JSON.parse(repairedArgs);

              actions.push({
                type: toolCall.function.name as CharacterAction['type'],
                params
              });

              logger.info(`✅ Successfully parsed function call: ${toolCall.function.name}`, params);
            } catch (parseError) {
              logger.error(`❌ Failed to parse tool call ${toolCall.function.name}:`, {
                error: parseError,
                arguments: toolCall.function.arguments
              });

              // Attempt retry with minimal params based on function type
              try {
                const fallbackParams = this.createFallbackParams(toolCall.function.name, note);
                if (fallbackParams) {
                  actions.push({
                    type: toolCall.function.name as CharacterAction['type'],
                    params: fallbackParams
                  });
                  logger.info(`🔄 Created fallback params for ${toolCall.function.name}`, fallbackParams);
                }
              } catch (fallbackError) {
                logger.error(`❌ Fallback creation failed for ${toolCall.function.name}:`, fallbackError);
              }
            }
          }
        }
      }

      // Validate that narrative was actually enhanced
      if (enhancedText === note) {
        logger.warn("⚠️ AI returned unchanged text - narrative enhancement may have failed");
      }

      logger.info(`🎉 Enhancement complete:`, {
        originalLength: note.length,
        enhancedLength: enhancedText.length,
        actionsCount: actions.length,
        processingTime: `${processingTime}ms`
      });

      return {
        enhancedText,
        actions
      };
    } catch (error) {
      logger.error("❌ AI enhancement failed:", {
        error,
        note,
        vibe,
        processingTime: `${Date.now() - startTime}ms`
      });
      throw error;
    }
  }

  // Create fallback parameters when JSON parsing fails
  private createFallbackParams(functionName: string, originalNote: string): any {
    switch (functionName) {
      case 'apply_debility':
        return {
          debility: 'sick', // Default safe debility
          reason: `From: ${originalNote}`
        };
      case 'modify_hp':
        return {
          change: -1, // Conservative damage
          reason: `From: ${originalNote}`
        };
      case 'gain_xp':
        return {
          amount: 1,
          trigger: 'discovery',
          description: `From: ${originalNote}`
        };
      default:
        return null; // No safe fallback available
    }
  }

  isInitialized(): boolean {
    return this.isReady;
  }

  async dispose(): Promise<void> {
    if (this.engine) {
      await this.engine.unload();
      this.engine = undefined;
      this.isReady = false;
    }
  }
}

import { logger } from '../utils/logger'
import { invoke } from '@tauri-apps/api/core';
import { listen } from '@tauri-apps/api/event';

export type CampaignVibe = 'fantasy' | 'scifi' | 'cyberpunk' | 'horror' | 'western' | 'modern';

export interface CharacterAction {
  type: 'apply_debility' | 'modify_hp' | 'add_gear' | 'spend_resource' | 'gain_xp' | 'update_bonds';
  params: any;
}

export interface EnhancementResult {
  enhanced_text: string;
  actions: CharacterAction[];
}

export interface AIProgress {
  progress: number; // 0-100
  text: string;
  time_remaining?: string;
  stage: string; // "downloading", "loading", "ready", "error"
}

export interface ModelInfo {
  name: string;
  size_gb: number;
  is_available: boolean;
  is_loaded: boolean;
}

export class OllamaAiNoteEnhancer {
  private ready = false;
  private initializationPromise?: Promise<void>;
  public onProgress?: (progress: AIProgress) => void;
  private currentModel = 'calebfahlgren/natural-functions';
  private progressListener?: () => Promise<void>;

  constructor() {
    // Set up progress event listener
    this.setupProgressListener();
  }

  private async setupProgressListener() {
    if (this.progressListener) return;

    try {
      this.progressListener = await listen<AIProgress>('llm_progress', (event) => {
        logger.info('📊 LLM Progress:', event.payload);
        if (this.onProgress) {
          this.onProgress(event.payload);
        }
      });
    } catch (error) {
      logger.error('Failed to set up progress listener:', error);
    }
  }

  async checkOllamaStatus(): Promise<boolean> {
    try {
      return await invoke<boolean>('check_ollama_status');
    } catch (error) {
      logger.error('Failed to check Ollama status:', error);
      return false;
    }
  }

  async listModels(): Promise<ModelInfo[]> {
    try {
      return await invoke<ModelInfo[]>('list_models');
    } catch (error) {
      logger.error('Failed to list models:', error);
      return [];
    }
  }

  async ensureModel(modelName: string): Promise<void> {
    try {
      await invoke('ensure_model', { modelName });
    } catch (error) {
      logger.error('Failed to ensure model:', error);
      throw new Error(`Failed to ensure model ${modelName}: ${error}`);
    }
  }

  async initialize(modelName?: string): Promise<void> {
    if (this.initializationPromise) {
      return this.initializationPromise;
    }

    this.initializationPromise = this.doInitialize(modelName);
    return this.initializationPromise;
  }

  private async doInitialize(modelName?: string): Promise<void> {
    const model = modelName || this.currentModel;

    try {
      logger.info(`🚀 Initializing AI with model: ${model}`);

      // Check if Ollama is running
      const ollamaStatus = await this.checkOllamaStatus();
      if (!ollamaStatus) {
        throw new Error('Ollama is not running. Please start Ollama first.');
      }

      // Initialize the LLM service
      await invoke('initialize_llm', { modelName: model });

      this.ready = true;
      this.currentModel = model;

      logger.info(`✅ AI Note Enhancer ready with ${model}!`);
    } catch (error) {
      logger.error('❌ Failed to initialize AI Note Enhancer:', error);
      this.ready = false;
      throw error;
    }
  }

  async enhance(note: string, vibe: CampaignVibe = 'fantasy'): Promise<EnhancementResult> {
    if (!this.ready) {
      throw new Error('AI not ready - call initialize() first');
    }

    logger.info(`🎭 Enhancing note with ${vibe} vibe:`, note);
    const startTime = Date.now();

    try {
      const result = await invoke<EnhancementResult>('enhance_note', {
        note,
        vibe,
      });

      const processingTime = Date.now() - startTime;
      logger.info(`⚡ AI processing completed in ${processingTime}ms`);

      logger.info('📝 Enhancement result:', {
        originalLength: note.length,
        enhancedLength: result.enhanced_text.length,
        actionsCount: result.actions.length,
        processingTime: `${processingTime}ms`,
      });

      // Validate that narrative was actually enhanced
      if (result.enhanced_text.trim() === note.trim()) {
        logger.warn('⚠️ AI returned unchanged text - narrative enhancement may have failed');
      }

      return result;
    } catch (error) {
      const processingTime = Date.now() - startTime;
      logger.error('❌ AI enhancement failed:', {
        error,
        note,
        vibe,
        processingTime: `${processingTime}ms`,
      });
      throw error;
    }
  }

  async isInitialized(): Promise<boolean> {
    try {
      return await invoke<boolean>('is_llm_ready');
    } catch (error) {
      logger.error('Failed to check if LLM is ready:', error);
      return false;
    }
  }

  // Legacy method for compatibility with existing code
  isReady(): boolean {
    return this.ready;
  }

  async dispose(): Promise<void> {
    // Clean up progress listener
    if (this.progressListener) {
      // Note: In Tauri 2.0, the unlisten function might be called differently
      // This is a placeholder - adjust based on actual Tauri API
      try {
        // this.progressListener(); // Call to unlisten
      } catch (error) {
        logger.warn('Failed to clean up progress listener:', error);
      }
    }

    this.ready = false;
    this.initializationPromise = undefined;
    logger.info('🧹 AI Note Enhancer disposed');
  }

  // Utility method to get available models with their status
  async getAvailableModels(): Promise<ModelInfo[]> {
    return this.listModels();
  }

  // Method to switch models if needed
  async switchModel(modelName: string): Promise<void> {
    this.ready = false;
    this.initializationPromise = undefined;
    this.currentModel = modelName;

    await this.initialize(modelName);
  }

  getCurrentModel(): string {
    return this.currentModel;
  }
}

/**
 * Character Store for ZimboMate V2
 * Manages character state, CRUD operations, and persistence
 * Integrates with CharacterStateService and AdvancementService
 */

import { create } from 'zustand'
import { persist } from 'zustand/middleware'
import type { Character } from '../models/Character'
import { createDummyCharacter } from '../models/Character'
import { characterStateService } from '../services/CharacterStateService'
import { advancementService } from '../services/AdvancementService'

interface CharacterState {
  // Character data
  characters: Character[]
  activeCharacterId: string | null
  isLoading: boolean
  error: string | null

  // Character CRUD operations
  createCharacter: (character: Omit<Character, 'id' | 'createdAt' | 'updatedAt'>) => Character
  updateCharacter: (id: string, updates: Partial<Character>) => void
  deleteCharacter: (id: string) => void
  getCharacter: (id: string) => Character | undefined
  setActiveCharacter: (id: string | null) => void
  getActiveCharacter: () => Character | undefined

  // Character management
  duplicateCharacter: (id: string) => Character | undefined
  exportCharacter: (id: string) => string | undefined
  importCharacter: (characterData: string) => Character

  // XP and advancement
  addXP: (characterId: string, amount: number, source: string, description: string) => void
  levelUpCharacter: (characterId: string) => void

  // Health management
  updateHP: (characterId: string, newHP: number) => void
  healCharacter: (characterId: string, amount: number) => void
  damageCharacter: (characterId: string, amount: number) => void

  // Load management
  updateLoad: (characterId: string, newLoad: number) => void

  // Utility
  clearError: () => void
  setLoading: (loading: boolean) => void
}

export const useCharacterStore = create<CharacterState>()(
  persist(
    (set, get) => ({
      // Initial state
      characters: [],
      activeCharacterId: null,
      isLoading: false,
      error: null,

      // Character CRUD operations
      createCharacter: (characterData) => {
        try {
          const character: Character = {
            ...characterData,
            id: `char-${Date.now()}-${Math.random().toString(36).slice(2, 11)}`,
            createdAt: new Date(),
            updatedAt: new Date(),
          }

          set((state) => ({
            characters: [...state.characters, character],
            activeCharacterId: character.id,
            error: null,
          }))

          return character
        } catch (error) {
          set({ error: `Failed to create character: ${error instanceof Error ? error.message : 'Unknown error'}` })
          throw error
        }
      },

      updateCharacter: (id, updates) => {
        try {
          set((state) => ({
            characters: state.characters.map((char) =>
              char.id === id
                ? { ...char, ...updates, updatedAt: new Date() }
                : char
            ),
            error: null,
          }))
        } catch (error) {
          set({ error: `Failed to update character: ${error instanceof Error ? error.message : 'Unknown error'}` })
        }
      },

      deleteCharacter: (id) => {
        try {
          // Clear character state service data
          characterStateService.clearCharacterState(id)

          // Clear advancement service data
          advancementService.clearXPHistory(id)

          set((state) => ({
            characters: state.characters.filter((char) => char.id !== id),
            activeCharacterId: state.activeCharacterId === id ? null : state.activeCharacterId,
            error: null,
          }))
        } catch (error) {
          set({ error: `Failed to delete character: ${error instanceof Error ? error.message : 'Unknown error'}` })
        }
      },

      getCharacter: (id) => {
        const { characters } = get()
        return characters.find((char) => char.id === id)
      },

      setActiveCharacter: (id) => {
        const { characters } = get()
        if (id === null || characters.some((char) => char.id === id)) {
          set({ activeCharacterId: id, error: null })
        } else {
          set({ error: 'Character not found' })
        }
      },

      getActiveCharacter: () => {
        const { characters, activeCharacterId } = get()
        if (!activeCharacterId) return undefined
        return characters.find((char) => char.id === activeCharacterId)
      },

      // Character management
      duplicateCharacter: (id) => {
        try {
          const { characters, createCharacter } = get()
          const originalCharacter = characters.find((char) => char.id === id)

          if (!originalCharacter) {
            set({ error: 'Character not found' })
            return undefined
          }

          const duplicatedCharacter = createCharacter({
            ...originalCharacter,
            name: `${originalCharacter.name} (Copy)`,
          })

          return duplicatedCharacter
        } catch (error) {
          set({ error: `Failed to duplicate character: ${error instanceof Error ? error.message : 'Unknown error'}` })
          return undefined
        }
      },

      exportCharacter: (id) => {
        try {
          const { characters } = get()
          const character = characters.find((char) => char.id === id)

          if (!character) {
            set({ error: 'Character not found' })
            return undefined
          }

          return JSON.stringify(character, null, 2)
        } catch (error) {
          set({ error: `Failed to export character: ${error instanceof Error ? error.message : 'Unknown error'}` })
          return undefined
        }
      },

      importCharacter: (characterData) => {
        try {
          const parsedCharacter = JSON.parse(characterData) as Character

          // Validate required fields
          if (!parsedCharacter.name || !parsedCharacter.class) {
            throw new Error('Invalid character data: missing required fields')
          }

          // Create new character with imported data
          const importedCharacter = get().createCharacter({
            ...parsedCharacter,
            name: `${parsedCharacter.name} (Imported)`,
          })

          return importedCharacter
        } catch (error) {
          const errorMessage = `Failed to import character: ${error instanceof Error ? error.message : 'Unknown error'}`
          set({ error: errorMessage })
          throw new Error(errorMessage)
        }
      },

      // XP and advancement
      addXP: (characterId, amount, source, description) => {
        try {
          const { characters, updateCharacter } = get()
          const character = characters.find((char) => char.id === characterId)

          if (!character) {
            set({ error: 'Character not found' })
            return
          }

          // Use advancement service to add XP
          const updatedCharacter = advancementService.addXP(
            character, 
            amount, 
            source as any, 
            description
          )

          updateCharacter(characterId, updatedCharacter)
        } catch (error) {
          set({ error: `Failed to add XP: ${error instanceof Error ? error.message : 'Unknown error'}` })
        }
      },

      levelUpCharacter: (characterId) => {
        try {
          const { characters, updateCharacter } = get()
          const character = characters.find((char) => char.id === characterId)

          if (!character) {
            set({ error: 'Character not found' })
            return
          }

          // Use advancement service to level up
          const levelUpResult = advancementService.levelUp(character)
          updateCharacter(characterId, levelUpResult.character)
        } catch (error) {
          set({ error: `Failed to level up character: ${error instanceof Error ? error.message : 'Unknown error'}` })
        }
      },

      // Health management
      updateHP: (characterId, newHP) => {
        try {
          const { characters, updateCharacter } = get()
          const character = characters.find((char) => char.id === characterId)

          if (!character) {
            set({ error: 'Character not found' })
            return
          }

          const clampedHP = Math.max(0, Math.min(character.hp.max, newHP))
          updateCharacter(characterId, {
            hp: { ...character.hp, current: clampedHP }
          })
        } catch (error) {
          set({ error: `Failed to update HP: ${error instanceof Error ? error.message : 'Unknown error'}` })
        }
      },

      healCharacter: (characterId, amount) => {
        try {
          const { characters, updateHP } = get()
          const character = characters.find((char) => char.id === characterId)

          if (!character) {
            set({ error: 'Character not found' })
            return
          }

          updateHP(characterId, character.hp.current + amount)
        } catch (error) {
          set({ error: `Failed to heal character: ${error instanceof Error ? error.message : 'Unknown error'}` })
        }
      },

      damageCharacter: (characterId, amount) => {
        try {
          const { characters, updateHP } = get()
          const character = characters.find((char) => char.id === characterId)

          if (!character) {
            set({ error: 'Character not found' })
            return
          }

          updateHP(characterId, character.hp.current - amount)
        } catch (error) {
          set({ error: `Failed to damage character: ${error instanceof Error ? error.message : 'Unknown error'}` })
        }
      },

      // Load management
      updateLoad: (characterId, newLoad) => {
        try {
          const { characters, updateCharacter } = get()
          const character = characters.find((char) => char.id === characterId)

          if (!character) {
            set({ error: 'Character not found' })
            return
          }

          const clampedLoad = Math.max(0, newLoad)
          updateCharacter(characterId, {
            load: { ...character.load, current: clampedLoad }
          })
        } catch (error) {
          set({ error: `Failed to update load: ${error instanceof Error ? error.message : 'Unknown error'}` })
        }
      },

      // Utility
      clearError: () => set({ error: null }),

      setLoading: (loading) => set({ isLoading: loading }),
    }),
    {
      name: 'zimbomate-character-storage',
      partialize: (state) => ({
        characters: state.characters,
        activeCharacterId: state.activeCharacterId,
      }),
    }
  )
)

/**
 * Chronicle Store - Zustand state management for Chronicle system
 * Handles all chronicle entries, entities, relationships, and wiki pages
 */

import { create } from 'zustand'
import { persist } from 'zustand/middleware'
import {
  ChronicleEntry,
  Entity,
  Relationship,
  WikiPage,
  ChronicleSearchResult,
  NarrativeThread,
  ChronicleSettings,
  EntityType,
  RelationshipType,
  WikiFact,
  WikiTimelineEntry,
  RelationshipEvent
} from '../types/chronicle'

interface ChronicleState {
  // Core data
  entries: ChronicleEntry[]
  entities: Entity[]
  relationships: Relationship[]
  wikiPages: WikiPage[]
  narrativeThreads: NarrativeThread[]

  // Current session
  currentSessionId: string | null
  currentCampaignId: string | null

  // Settings
  settings: ChronicleSettings

  // UI State
  selectedEntity: string | null
  searchQuery: string
  isWriting: boolean

  // Actions - Chronicle Entries
  addEntry: (entry: Omit<ChronicleEntry, 'id'>) => string
  updateEntry: (id: string, updates: Partial<ChronicleEntry>) => void
  deleteEntry: (id: string) => void
  getEntry: (id: string) => ChronicleEntry | undefined
  getEntriesBySession: (sessionId: string) => ChronicleEntry[]

  // Actions - Entities
  addEntity: (entity: Omit<Entity, 'id' | 'createdAt' | 'lastUpdated'>) => string
  updateEntity: (id: string, updates: Partial<Entity>) => void
  deleteEntity: (id: string) => void
  getEntity: (id: string) => Entity | undefined
  getEntitiesByType: (type: EntityType) => Entity[]
  findEntityByName: (name: string, type?: EntityType) => Entity | undefined

  // Actions - Relationships
  addRelationship: (relationship: Omit<Relationship, 'id' | 'createdAt' | 'lastUpdated'>) => string
  updateRelationship: (id: string, updates: Partial<Relationship>) => void
  deleteRelationship: (id: string) => void
  getRelationship: (id: string) => Relationship | undefined
  getEntityRelationships: (entityId: string) => Relationship[]

  // Actions - Wiki Pages
  generateWikiPage: (entityId: string) => void
  updateWikiPage: (entityId: string, updates: Partial<WikiPage>) => void
  getWikiPage: (entityId: string) => WikiPage | undefined
  incrementWikiView: (entityId: string) => void

  // Actions - Search
  searchAll: (query: string) => ChronicleSearchResult[]
  searchEntries: (query: string) => ChronicleEntry[]
  searchEntities: (query: string) => Entity[]

  // Actions - Session Management
  startSession: (campaignId?: string) => string
  endSession: () => void
  getCurrentSession: () => ChronicleEntry[]

  // Actions - Utility
  clearAll: () => void
  exportData: () => string
  importData: (data: string) => void
  updateSettings: (settings: Partial<ChronicleSettings>) => void
}

// Default settings
const defaultSettings: ChronicleSettings = {
  autoEntityCreation: true,
  minimumConfidenceForAutoCreation: 0.7,
  enableVoiceInput: false,
  enableSmartSuggestions: true,
  parseOnType: true,
  defaultEntityTypes: ['character', 'location', 'item', 'event'],
  customTags: []
}

// Helper function to generate IDs
const generateId = (prefix: string = '') => {
  return `${prefix}${Date.now()}-${Math.random().toString(36).slice(2, 11)}`
}

// Helper function to calculate entity importance
const calculateEntityImportance = (entity: Entity, entries: ChronicleEntry[]): number => {
  // Factor in: mention frequency, recency, user bookmarking
  const mentionCount = entity.appearances.length
  const recentMentions = entity.appearances.filter(entryId => {
    const entry = entries.find(e => e.id === entryId)
    if (!entry) return false
    const daysSince = (Date.now() - entry.timestamp.getTime()) / (1000 * 60 * 60 * 24)
    return daysSince < 30 // Recent = within 30 days
  }).length

  // Weight: 40% total mentions, 40% recent mentions, 20% type importance
  const typeWeight = entity.type === 'character' ? 1.2 : entity.type === 'location' ? 1.1 : 1.0
  const importance = Math.min(100, (mentionCount * 0.4 + recentMentions * 0.4 + typeWeight * 20))

  return Math.round(importance)
}

// Helper function to extract key facts from chronicle entries
const extractKeyFacts = (entity: Entity, entries: ChronicleEntry[]): WikiFact[] => {
  const relevantEntries = entries.filter(entry =>
    entry.parsedEntities.some(mention => mention.entityId === entity.id)
  )

  const facts: WikiFact[] = []

  relevantEntries.forEach(entry => {
    // Extract factual statements about the entity
    const sentences = entry.rawText.split(/[.!?]+/).filter(s => s.trim().length > 0)

    sentences.forEach(sentence => {
      const lowerSentence = sentence.toLowerCase()
      const entityNameLower = entity.name.toLowerCase()

      // Look for factual patterns
      if (lowerSentence.includes(entityNameLower) &&
          (lowerSentence.includes(' is ') ||
           lowerSentence.includes(' has ') ||
           lowerSentence.includes(' owns ') ||
           lowerSentence.includes(' wears ') ||
           lowerSentence.includes(' lives '))) {

        facts.push({
          fact: sentence.trim(),
          confidence: 0.8,
          sourceEntryId: entry.id,
          extractedAt: new Date()
        })
      }
    })
  })

  // Remove duplicates and sort by confidence
  const uniqueFacts = facts.filter((fact, index, arr) =>
    index === arr.findIndex(f => f.fact.toLowerCase() === fact.fact.toLowerCase())
  ).sort((a, b) => b.confidence - a.confidence)

  return uniqueFacts.slice(0, 10) // Limit to top 10 facts
}

// Helper function to build timeline from chronicle entries
const buildEntityTimeline = (entity: Entity, entries: ChronicleEntry[]): WikiTimelineEntry[] => {
  const relevantEntries = entries.filter(entry =>
    entry.parsedEntities.some(mention => mention.entityId === entity.id)
  ).sort((a, b) => a.timestamp.getTime() - b.timestamp.getTime())

  return relevantEntries.map(entry => {
    const mention = entry.parsedEntities.find(m => m.entityId === entity.id)

    return {
      entryId: entry.id,
      timestamp: entry.timestamp,
      event: entry.rawText.length > 150
        ? `${entry.rawText.substring(0, 150)  }...`
        : entry.rawText,
      context: mention?.context || 'mentioned',
      importance: entry.isSceneBreak ? 'high' : 'medium',
      emotionalTone: entry.emotionalTone
    }
  })
}

// Helper function to analyze relationships for wiki
const generateRelationshipSummary = (entity: Entity, relationships: Relationship[]): string => {
  const entityRelationships = relationships.filter(rel =>
    rel.fromEntityId === entity.id || rel.toEntityId === entity.id
  )

  if (entityRelationships.length === 0) {
    return `No known relationships documented for ${entity.name}.`
  }

  const relationshipTexts = entityRelationships.map(rel => {
    const isSource = rel.fromEntityId === entity.id
    const otherEntityId = isSource ? rel.toEntityId : rel.fromEntityId
    const relationshipType = rel.type

    return `${relationshipType} relationship with entity ${otherEntityId}`
  })

  return `${entity.name} has ${relationshipTexts.join(', ')}.`
}

// Helper function to generate wiki summary
const generateWikiSummary = (entity: Entity, entries: ChronicleEntry[]): string => {
  const relevantEntries = entries.filter(entry =>
    entry.parsedEntities.some(mention => mention.entityId === entity.id)
  )

  if (relevantEntries.length === 0) {
    return `${entity.name} is ${entity.type === 'character' ? 'a character' : entity.type === 'location' ? 'a location' : `an ${entity.type}`} in your campaign.`
  }

  const firstMention = relevantEntries.find(e => e.id === entity.firstMention)
  const lastMention = relevantEntries.find(e => e.id === entity.lastMention)

  let summary = `${entity.name} is ${entity.type === 'character' ? 'a character' : entity.type === 'location' ? 'a location' : `an ${entity.type}`} `

  if (firstMention) {
    const context = `${firstMention.rawText.substring(0, 100)  }...`
    summary += `first mentioned when: "${context}"`
  }

  if (entity.appearances.length > 1 && lastMention && lastMention.id !== firstMention?.id) {
    summary += ` Last seen: ${lastMention.timestamp.toLocaleDateString()}`
  }

  return summary
}

export const useChronicleStore = create<ChronicleState>()(
  persist(
    (set, get) => ({
      // Initial state
      entries: [],
      entities: [],
      relationships: [],
      wikiPages: [],
      narrativeThreads: [],
      currentSessionId: null,
      currentCampaignId: null,
      settings: defaultSettings,
      selectedEntity: null,
      searchQuery: '',
      isWriting: false,

      // Chronicle Entries Actions
      addEntry: (entryData) => {
        const id = generateId('entry-')
        const entry: ChronicleEntry = {
          ...entryData,
          id,
          timestamp: new Date()
        }

        set((state) => ({
          entries: [...state.entries, entry]
        }))

        return id
      },

      updateEntry: (id, updates) => {
        set((state) => ({
          entries: state.entries.map(entry =>
            entry.id === id ? { ...entry, ...updates } : entry
          )
        }))
      },

      deleteEntry: (id) => {
        set((state) => ({
          entries: state.entries.filter(entry => entry.id !== id)
        }))
      },

      getEntry: (id) => {
        return get().entries.find(entry => entry.id === id)
      },

      getEntriesBySession: (sessionId) => {
        return get().entries.filter(entry => entry.sessionId === sessionId)
      },

      // Entity Actions
      addEntity: (entityData) => {
        const id = generateId('entity-')
        const now = new Date()
        const entity: Entity = {
          ...entityData,
          id,
          createdAt: now,
          lastUpdated: now,
          importance: 1 // Will be calculated later
        }

        set((state) => {
          const newEntities = [...state.entities, entity]
          // Recalculate importance
          entity.importance = calculateEntityImportance(entity, state.entries)

          return {
            entities: newEntities
          }
        })

        // Generate initial wiki page
        get().generateWikiPage(id)

        return id
      },

      updateEntity: (id, updates) => {
        set((state) => ({
          entities: state.entities.map(entity =>
            entity.id === id
              ? {
                  ...entity,
                  ...updates,
                  lastUpdated: new Date(),
                  importance: calculateEntityImportance({ ...entity, ...updates }, state.entries)
                }
              : entity
          )
        }))
      },

      deleteEntity: (id) => {
        set((state) => ({
          entities: state.entities.filter(entity => entity.id !== id),
          wikiPages: state.wikiPages.filter(page => page.entityId !== id),
          relationships: state.relationships.filter(rel =>
            rel.fromEntityId !== id && rel.toEntityId !== id
          )
        }))
      },

      getEntity: (id) => {
        return get().entities.find(entity => entity.id === id)
      },

      getEntitiesByType: (type) => {
        return get().entities.filter(entity => entity.type === type)
      },

      findEntityByName: (name, type) => {
        const { entities } = get()
        const lowerName = name.toLowerCase()

        return entities.find(entity => {
          if (type && entity.type !== type) return false

          const matchesName = entity.name.toLowerCase() === lowerName
          const matchesAlias = entity.aliases.some(alias =>
            alias.toLowerCase() === lowerName
          )

          return matchesName || matchesAlias
        })
      },

      // Relationship Actions
      addRelationship: (relationshipData) => {
        const id = generateId('rel-')
        const now = new Date()
        const relationship: Relationship = {
          ...relationshipData,
          id,
          createdAt: now,
          lastUpdated: now,
          history: []
        }

        set((state) => ({
          relationships: [...state.relationships, relationship]
        }))

        return id
      },

      updateRelationship: (id, updates) => {
        set((state) => ({
          relationships: state.relationships.map(rel =>
            rel.id === id
              ? { ...rel, ...updates, lastUpdated: new Date() }
              : rel
          )
        }))
      },

      deleteRelationship: (id) => {
        set((state) => ({
          relationships: state.relationships.filter(rel => rel.id !== id)
        }))
      },

      getRelationship: (id) => {
        return get().relationships.find(rel => rel.id === id)
      },

      getEntityRelationships: (entityId) => {
        return get().relationships.filter(rel =>
          rel.fromEntityId === entityId || rel.toEntityId === entityId
        )
      },

      // Wiki Actions
      generateWikiPage: (entityId) => {
        const { entities, entries, relationships, wikiPages } = get()
        const entity = entities.find(e => e.id === entityId)
        if (!entity) return

        const existingPage = wikiPages.find(p => p.entityId === entityId)

        // Generate comprehensive wiki data
        const autoGeneratedSummary = generateWikiSummary(entity, entries)
        const keyFacts = extractKeyFacts(entity, entries)
        const timeline = buildEntityTimeline(entity, entries)
        const relationshipSummary = generateRelationshipSummary(entity, relationships)

        // Extract potential mysteries/questions about the entity
        const mysteries: string[] = []
        const relevantEntries = entries.filter(entry =>
          entry.parsedEntities.some(mention => mention.entityId === entity.id)
        )

        relevantEntries.forEach(entry => {
          // Look for questions or mysterious references
          const sentences = entry.rawText.split(/[.!?]+/).filter(s => s.trim().length > 0)
          sentences.forEach(sentence => {
            if ((sentence.includes('?') ||
                 sentence.toLowerCase().includes('mystery') ||
                 sentence.toLowerCase().includes('unknown') ||
                 sentence.toLowerCase().includes('secret')) &&
                sentence.toLowerCase().includes(entity.name.toLowerCase())) {
              mysteries.push(sentence.trim())
            }
          })
        })

        const wikiPage: WikiPage = {
          entityId,
          autoGeneratedSummary,
          keyFacts,
          timeline,
          relationshipSummary,
          mysteries: mysteries.slice(0, 5), // Limit to 5 mysteries
          userContent: existingPage?.userContent || '',
          lastGenerated: new Date(),
          viewCount: existingPage?.viewCount || 0,
          bookmarked: existingPage?.bookmarked || false
        }

        set((state) => ({
          wikiPages: state.wikiPages.filter(p => p.entityId !== entityId).concat(wikiPage)
        }))
      },

      updateWikiPage: (entityId, updates) => {
        set((state) => ({
          wikiPages: state.wikiPages.map(page =>
            page.entityId === entityId
              ? { ...page, ...updates }
              : page
          )
        }))
      },

      getWikiPage: (entityId) => {
        return get().wikiPages.find(page => page.entityId === entityId)
      },

      incrementWikiView: (entityId) => {
        set((state) => ({
          wikiPages: state.wikiPages.map(page =>
            page.entityId === entityId
              ? { ...page, viewCount: page.viewCount + 1 }
              : page
          )
        }))
      },

      // Search Actions
      searchAll: (query) => {
        const { entries, entities } = get()
        const results: ChronicleSearchResult[] = []
        const lowerQuery = query.toLowerCase()

        // Search entries
        entries.forEach(entry => {
          if (entry.rawText.toLowerCase().includes(lowerQuery)) {
            const startIndex = entry.rawText.toLowerCase().indexOf(lowerQuery)
            const excerpt = entry.rawText.substring(
              Math.max(0, startIndex - 50),
              Math.min(entry.rawText.length, startIndex + 150)
            )

            results.push({
              type: 'entry',
              id: entry.id,
              title: `Entry from ${entry.timestamp.toLocaleDateString()}`,
              excerpt,
              relevanceScore: 1,
              matchedTerms: [query]
            })
          }
        })

        // Search entities
        entities.forEach(entity => {
          const nameMatch = entity.name.toLowerCase().includes(lowerQuery)
          const descMatch = entity.description.toLowerCase().includes(lowerQuery)
          const tagMatch = entity.tags.some(tag => tag.toLowerCase().includes(lowerQuery))

          if (nameMatch || descMatch || tagMatch) {
            results.push({
              type: 'entity',
              id: entity.id,
              title: entity.name,
              excerpt: entity.description,
              relevanceScore: nameMatch ? 2 : 1,
              matchedTerms: [query]
            })
          }
        })

        // Sort by relevance
        return results.sort((a, b) => b.relevanceScore - a.relevanceScore)
      },

      searchEntries: (query) => {
        const { entries } = get()
        const lowerQuery = query.toLowerCase()

        return entries.filter(entry =>
          entry.rawText.toLowerCase().includes(lowerQuery) ||
          entry.tags.some(tag => tag.toLowerCase().includes(lowerQuery))
        )
      },

      searchEntities: (query) => {
        const { entities } = get()
        const lowerQuery = query.toLowerCase()

        return entities.filter(entity =>
          entity.name.toLowerCase().includes(lowerQuery) ||
          entity.description.toLowerCase().includes(lowerQuery) ||
          entity.aliases.some(alias => alias.toLowerCase().includes(lowerQuery)) ||
          entity.tags.some(tag => tag.toLowerCase().includes(lowerQuery))
        )
      },

      // Session Management
      startSession: (campaignId) => {
        const sessionId = generateId('session-')

        set(() => ({
          currentSessionId: sessionId,
          currentCampaignId: campaignId || null
        }))

        return sessionId
      },

      endSession: () => {
        set(() => ({
          currentSessionId: null
        }))
      },

      getCurrentSession: () => {
        const { currentSessionId, entries } = get()
        if (!currentSessionId) return []

        return entries.filter(entry => entry.sessionId === currentSessionId)
      },

      // Utility Actions
      clearAll: () => {
        set(() => ({
          entries: [],
          entities: [],
          relationships: [],
          wikiPages: [],
          narrativeThreads: [],
          currentSessionId: null,
          currentCampaignId: null,
          selectedEntity: null,
          searchQuery: ''
        }))
      },

      exportData: () => {
        const { entries, entities, relationships, wikiPages, narrativeThreads } = get()
        return JSON.stringify({
          entries,
          entities,
          relationships,
          wikiPages,
          narrativeThreads,
          exportedAt: new Date(),
          version: '1.0'
        }, null, 2)
      },

      importData: (data) => {
        try {
          const parsed = JSON.parse(data)
          set(() => ({
            entries: parsed.entries || [],
            entities: parsed.entities || [],
            relationships: parsed.relationships || [],
            wikiPages: parsed.wikiPages || [],
            narrativeThreads: parsed.narrativeThreads || []
          }))
        } catch (error) {
          console.error('Failed to import chronicle data:', error)
        }
      },

      updateSettings: (newSettings) => {
        set((state) => ({
          settings: { ...state.settings, ...newSettings }
        }))
      }
    }),
    {
      name: 'chronicle-store',
      version: 1
    }
  )
)

/**
 * Combat Store for ZimboMate V2
 * Manages combat state, initiative, damage tracking, and battle flow
 */

import { create } from 'zustand'
import { persist } from 'zustand/middleware'
import { gameLogicService, type CombatResult } from '../services/GameLogicService'

export interface CombatParticipant {
  id: string
  name: string
  type: 'character' | 'npc' | 'monster'
  characterId?: string // For player characters
  hp: { current: number; max: number }
  armor: number
  initiative?: number
  conditions: string[]
  position: 'front' | 'close' | 'near' | 'far'
  isActive: boolean
  isPlayer: boolean
}

export interface CombatAction {
  id: string
  participantId: string
  type: 'attack' | 'defend' | 'move' | 'other'
  description: string
  timestamp: Date
  rollResult?: any
  damage?: number
  target?: string
}

export interface CombatEncounter {
  id: string
  name: string
  participants: CombatParticipant[]
  currentTurn: number
  round: number
  status: 'setup' | 'active' | 'paused' | 'completed'
  startTime: Date
  endTime?: Date
  actions: CombatAction[]
  environment: {
    terrain: string
    hazards: string[]
    lighting: 'bright' | 'dim' | 'dark'
    weather?: string
  }
}

interface CombatState {
  // Current encounter
  currentEncounter: CombatEncounter | null
  encounterHistory: CombatEncounter[]
  
  // Combat management
  startCombat: (name: string, participants: Omit<CombatParticipant, 'id'>[]) => void
  endCombat: () => void
  pauseCombat: () => void
  resumeCombat: () => void
  
  // Participant management
  addParticipant: (participant: Omit<CombatParticipant, 'id'>) => void
  removeParticipant: (participantId: string) => void
  updateParticipant: (participantId: string, updates: Partial<CombatParticipant>) => void
  
  // Turn management
  nextTurn: () => void
  previousTurn: () => void
  setCurrentTurn: (participantIndex: number) => void
  
  // Damage and healing
  applyDamage: (participantId: string, damage: number, armor?: number, piercing?: number) => CombatResult
  healParticipant: (participantId: string, amount: number) => void
  
  // Conditions
  addCondition: (participantId: string, condition: string) => void
  removeCondition: (participantId: string, condition: string) => void
  
  // Actions
  addAction: (action: Omit<CombatAction, 'id' | 'timestamp'>) => void
  getActionsForParticipant: (participantId: string) => CombatAction[]
  
  // Initiative
  rollInitiative: (participantId: string) => void
  setInitiative: (participantId: string, initiative: number) => void
  sortByInitiative: () => void
  
  // Utility
  getCurrentParticipant: () => CombatParticipant | null
  getAliveParticipants: () => CombatParticipant[]
  isEncounterComplete: () => boolean
  getCombatSummary: () => {
    round: number
    turn: number
    activeParticipants: number
    totalDamageDealt: number
    actionsThisRound: number
  }
}

export const useCombatStore = create<CombatState>()(
  persist(
    (set, get) => ({
      // Initial state
      currentEncounter: null,
      encounterHistory: [],

      // Combat management
      startCombat: (name, participants) => {
        const encounter: CombatEncounter = {
          id: `combat-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`,
          name,
          participants: participants.map((p, index) => ({
            ...p,
            id: `participant-${Date.now()}-${index}`,
            conditions: [],
            isActive: true
          })),
          currentTurn: 0,
          round: 1,
          status: 'setup',
          startTime: new Date(),
          actions: [],
          environment: {
            terrain: 'normal',
            hazards: [],
            lighting: 'bright'
          }
        }

        set({ currentEncounter: encounter })
      },

      endCombat: () => {
        const { currentEncounter } = get()
        if (!currentEncounter) return

        const completedEncounter = {
          ...currentEncounter,
          status: 'completed' as const,
          endTime: new Date()
        }

        set((state) => ({
          currentEncounter: null,
          encounterHistory: [completedEncounter, ...state.encounterHistory.slice(0, 19)] // Keep last 20
        }))
      },

      pauseCombat: () => {
        set((state) => ({
          currentEncounter: state.currentEncounter
            ? { ...state.currentEncounter, status: 'paused' }
            : null
        }))
      },

      resumeCombat: () => {
        set((state) => ({
          currentEncounter: state.currentEncounter
            ? { ...state.currentEncounter, status: 'active' }
            : null
        }))
      },

      // Participant management
      addParticipant: (participant) => {
        set((state) => {
          if (!state.currentEncounter) return state

          const newParticipant: CombatParticipant = {
            ...participant,
            id: `participant-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`,
            conditions: [],
            isActive: true
          }

          return {
            currentEncounter: {
              ...state.currentEncounter,
              participants: [...state.currentEncounter.participants, newParticipant]
            }
          }
        })
      },

      removeParticipant: (participantId) => {
        set((state) => {
          if (!state.currentEncounter) return state

          return {
            currentEncounter: {
              ...state.currentEncounter,
              participants: state.currentEncounter.participants.filter(p => p.id !== participantId)
            }
          }
        })
      },

      updateParticipant: (participantId, updates) => {
        set((state) => {
          if (!state.currentEncounter) return state

          return {
            currentEncounter: {
              ...state.currentEncounter,
              participants: state.currentEncounter.participants.map(p =>
                p.id === participantId ? { ...p, ...updates } : p
              )
            }
          }
        })
      },

      // Turn management
      nextTurn: () => {
        set((state) => {
          if (!state.currentEncounter) return state

          const aliveParticipants = state.currentEncounter.participants.filter(p => 
            p.isActive && p.hp.current > 0
          )
          
          let nextTurn = state.currentEncounter.currentTurn + 1
          let nextRound = state.currentEncounter.round

          if (nextTurn >= aliveParticipants.length) {
            nextTurn = 0
            nextRound += 1
          }

          return {
            currentEncounter: {
              ...state.currentEncounter,
              currentTurn: nextTurn,
              round: nextRound
            }
          }
        })
      },

      previousTurn: () => {
        set((state) => {
          if (!state.currentEncounter) return state

          const aliveParticipants = state.currentEncounter.participants.filter(p => 
            p.isActive && p.hp.current > 0
          )
          
          let prevTurn = state.currentEncounter.currentTurn - 1
          let prevRound = state.currentEncounter.round

          if (prevTurn < 0) {
            prevTurn = aliveParticipants.length - 1
            prevRound = Math.max(1, prevRound - 1)
          }

          return {
            currentEncounter: {
              ...state.currentEncounter,
              currentTurn: prevTurn,
              round: prevRound
            }
          }
        })
      },

      setCurrentTurn: (participantIndex) => {
        set((state) => {
          if (!state.currentEncounter) return state

          return {
            currentEncounter: {
              ...state.currentEncounter,
              currentTurn: participantIndex
            }
          }
        })
      },

      // Damage and healing
      applyDamage: (participantId, damage, armor = 0, piercing = 0) => {
        const { currentEncounter, updateParticipant } = get()
        if (!currentEncounter) {
          return { damage: 0, armorReduction: 0, finalDamage: 0, conditions: [], effects: [] }
        }

        const participant = currentEncounter.participants.find(p => p.id === participantId)
        if (!participant) {
          return { damage: 0, armorReduction: 0, finalDamage: 0, conditions: [], effects: [] }
        }

        const effectiveArmor = armor || participant.armor
        const combatResult = gameLogicService.calculateCombatDamage(
          damage,
          effectiveArmor,
          piercing,
          participant.conditions
        )

        // Apply damage
        const newHP = Math.max(0, participant.hp.current - combatResult.finalDamage)
        updateParticipant(participantId, {
          hp: { ...participant.hp, current: newHP },
          conditions: [...participant.conditions, ...combatResult.conditions]
        })

        // Add combat action
        get().addAction({
          participantId,
          type: 'other',
          description: `Takes ${combatResult.finalDamage} damage (${damage} - ${combatResult.armorReduction} armor)`,
          damage: combatResult.finalDamage
        })

        return combatResult
      },

      healParticipant: (participantId, amount) => {
        const { currentEncounter, updateParticipant } = get()
        if (!currentEncounter) return

        const participant = currentEncounter.participants.find(p => p.id === participantId)
        if (!participant) return

        const newHP = Math.min(participant.hp.max, participant.hp.current + amount)
        updateParticipant(participantId, {
          hp: { ...participant.hp, current: newHP }
        })

        get().addAction({
          participantId,
          type: 'other',
          description: `Heals ${amount} HP (${participant.hp.current} → ${newHP})`
        })
      },

      // Conditions
      addCondition: (participantId, condition) => {
        const { currentEncounter, updateParticipant } = get()
        if (!currentEncounter) return

        const participant = currentEncounter.participants.find(p => p.id === participantId)
        if (!participant || participant.conditions.includes(condition)) return

        updateParticipant(participantId, {
          conditions: [...participant.conditions, condition]
        })

        get().addAction({
          participantId,
          type: 'other',
          description: `Gains condition: ${condition}`
        })
      },

      removeCondition: (participantId, condition) => {
        const { currentEncounter, updateParticipant } = get()
        if (!currentEncounter) return

        const participant = currentEncounter.participants.find(p => p.id === participantId)
        if (!participant) return

        updateParticipant(participantId, {
          conditions: participant.conditions.filter(c => c !== condition)
        })

        get().addAction({
          participantId,
          type: 'other',
          description: `Removes condition: ${condition}`
        })
      },

      // Actions
      addAction: (actionData) => {
        set((state) => {
          if (!state.currentEncounter) return state

          const action: CombatAction = {
            ...actionData,
            id: `action-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`,
            timestamp: new Date()
          }

          return {
            currentEncounter: {
              ...state.currentEncounter,
              actions: [...state.currentEncounter.actions, action]
            }
          }
        })
      },

      getActionsForParticipant: (participantId) => {
        const { currentEncounter } = get()
        if (!currentEncounter) return []

        return currentEncounter.actions.filter(a => a.participantId === participantId)
      },

      // Initiative
      rollInitiative: (participantId) => {
        const initiative = Math.floor(Math.random() * 20) + 1
        get().setInitiative(participantId, initiative)
      },

      setInitiative: (participantId, initiative) => {
        get().updateParticipant(participantId, { initiative })
      },

      sortByInitiative: () => {
        set((state) => {
          if (!state.currentEncounter) return state

          const sortedParticipants = [...state.currentEncounter.participants].sort((a, b) => {
            const aInit = a.initiative || 0
            const bInit = b.initiative || 0
            return bInit - aInit // Highest first
          })

          return {
            currentEncounter: {
              ...state.currentEncounter,
              participants: sortedParticipants,
              currentTurn: 0 // Reset to first participant
            }
          }
        })
      },

      // Utility
      getCurrentParticipant: () => {
        const { currentEncounter } = get()
        if (!currentEncounter) return null

        const aliveParticipants = currentEncounter.participants.filter(p => 
          p.isActive && p.hp.current > 0
        )
        
        return aliveParticipants[currentEncounter.currentTurn] || null
      },

      getAliveParticipants: () => {
        const { currentEncounter } = get()
        if (!currentEncounter) return []

        return currentEncounter.participants.filter(p => p.isActive && p.hp.current > 0)
      },

      isEncounterComplete: () => {
        const { currentEncounter } = get()
        if (!currentEncounter) return false

        const alivePlayers = currentEncounter.participants.filter(p => 
          p.isPlayer && p.isActive && p.hp.current > 0
        )
        const aliveEnemies = currentEncounter.participants.filter(p => 
          !p.isPlayer && p.isActive && p.hp.current > 0
        )

        return alivePlayers.length === 0 || aliveEnemies.length === 0
      },

      getCombatSummary: () => {
        const { currentEncounter } = get()
        if (!currentEncounter) {
          return { round: 0, turn: 0, activeParticipants: 0, totalDamageDealt: 0, actionsThisRound: 0 }
        }

        const activeParticipants = get().getAliveParticipants().length
        const totalDamageDealt = currentEncounter.actions
          .filter(a => a.damage && a.damage > 0)
          .reduce((sum, a) => sum + (a.damage || 0), 0)
        
        const currentRoundActions = currentEncounter.actions.filter(a => {
          const actionTime = a.timestamp.getTime()
          const roundStart = currentEncounter.startTime.getTime() + 
            ((currentEncounter.round - 1) * 60000) // Assume 1 minute per round
          return actionTime >= roundStart
        }).length

        return {
          round: currentEncounter.round,
          turn: currentEncounter.currentTurn + 1,
          activeParticipants,
          totalDamageDealt,
          actionsThisRound: currentRoundActions
        }
      }
    }),
    {
      name: 'zimbomate-combat-storage',
      partialize: (state) => ({
        currentEncounter: state.currentEncounter,
        encounterHistory: state.encounterHistory.slice(0, 5) // Only persist last 5 encounters
      }),
    }
  )
)

/**
 * Dice Store for ZimboMate V2
 * Manages unified dice rolling system with character-scoped history
 * Integrates with Dungeon World mechanics and auto-XP/hold systems
 */
import { logger } from '../utils/logger'


import { create } from 'zustand'
import { persist } from 'zustand/middleware'
import type { Attributes } from '../models/Character'
import { getAttributeModifier } from '../models/Character'
import { useXPStore } from './xpStore'
import { useHoldStore } from './holdStore'

// Versioned roll result schema for future migrations
export interface RollResult {
  version: 1
  id: string
  timestamp: number
  characterId: string

  // Roll mechanics
  dice1: number
  dice2: number
  diceTotal: number
  modifier: number
  finalResult: number
  outcome: 'success' | 'partial' | 'failure'

  // Context information
  type: 'stat' | 'move' | 'custom'
  context: {
    label: string           // "STR Roll", "Hack and Slash", etc.
    stat?: keyof Attributes // Which stat was rolled
    moveId?: string         // Which move was used
    description?: string    // Additional context
  }

  // Game mechanic effects
  effects: {
    xpAwarded?: boolean     // Did this roll award XP?
    holdGranted?: number    // How much hold was granted?
    additional?: string[]   // Other effects applied
  }
}

export interface RollContext {
  label: string
  stat?: keyof Attributes
  moveId?: string
  description?: string
}

interface DiceState {
  // Current state
  currentRoll: RollResult | null
  isRolling: boolean

  // History (character-scoped)
  rollHistoryByCharacter: Record<string, RollResult[]>
  maxHistoryPerCharacter: number

  // UI state
  showHistory: boolean
  showCommandPalette: boolean
  activeNotifications: RollResult[]
  maxNotifications: number

  // Core rolling functions
  rollStat: (stat: keyof Attributes, characterId: string, customLabel?: string) => Promise<RollResult>
  rollMove: (moveId: string, stat: keyof Attributes, characterId: string) => Promise<RollResult>
  rollCustom: (modifier: number, context: RollContext, characterId: string) => Promise<RollResult>

  // History management
  getHistoryForCharacter: (characterId: string) => RollResult[]
  getAllRolls: () => RollResult[]
  clearHistoryForCharacter: (characterId: string) => void
  clearAllHistory: () => void
  exportHistory: (characterId: string) => string
  rerollWithSameContext: (rollId: string) => Promise<RollResult | null>

  // UI actions
  toggleHistory: () => void
  toggleCommandPalette: () => void
  dismissNotification: (rollId: string) => void
  copyRollToClipboard: (roll: RollResult) => void

  // Internal helpers
  _addRollToHistory: (roll: RollResult) => void
  _createRollResult: (
    dice1: number,
    dice2: number,
    modifier: number,
    context: RollContext,
    characterId: string,
    type: RollResult['type']
  ) => RollResult
  _getCharacterStats: (characterId: string) => Attributes | null
}

// Dungeon World outcome calculation
const getOutcome = (total: number): RollResult['outcome'] => {
  if (total >= 10) return 'success'
  if (total >= 7) return 'partial'
  return 'failure'
}

// Generate unique roll ID
const generateRollId = (): string => {
  return `roll-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`
}

// Simulate dice roll with slight delay for animation
const rollDice = (): Promise<{ dice1: number, dice2: number }> => {
  return new Promise((resolve) => {
    setTimeout(() => {
      resolve({
        dice1: Math.floor(Math.random() * 6) + 1,
        dice2: Math.floor(Math.random() * 6) + 1
      })
    }, 1500) // 1.5s animation delay
  })
}

export const useDiceStore = create<DiceState>()(
  persist(
    (set, get) => ({
      // Initial state
      currentRoll: null,
      isRolling: false,
      rollHistoryByCharacter: {},
      maxHistoryPerCharacter: 100,
      showHistory: true,
      showCommandPalette: false,
      activeNotifications: [],
      maxNotifications: 3,

      // Core rolling functions
      rollStat: async (stat: keyof Attributes, characterId: string, customLabel?: string) => {
        logger.debug('🎲 rollStat called:', { stat, characterId, customLabel })
        const state = get()
        if (state.isRolling) {
          logger.debug('⚠️ Already rolling, returning current roll')
          return state.currentRoll!
        }

        logger.debug('🎯 Starting roll process')
        set({ isRolling: true, currentRoll: null })

        try {
          logger.debug('📊 Getting character stats for:', characterId)
          const stats = state._getCharacterStats(characterId)
          logger.debug('📊 Character stats result:', stats)
          if (!stats) throw new Error('Character not found')

          const modifier = getAttributeModifier(stats[stat])
          logger.debug('🔢 Modifier calculated:', modifier)

          logger.debug('🎲 Rolling dice...')
          const { dice1, dice2 } = await rollDice()
          logger.debug('🎲 Dice result:', { dice1, dice2 })

          const context: RollContext = {
            label: customLabel || `${stat} Roll`,
            stat,
            description: `Rolling ${stat} with modifier ${modifier >= 0 ? '+' : ''}${modifier}`
          }

          logger.debug('📝 Creating roll result with context:', context)
          const roll = state._createRollResult(dice1, dice2, modifier, context, characterId, 'stat')
          logger.debug('✅ Roll result created:', roll)

          // Award XP for failed stat rolls
          if (roll.outcome === 'failure') {
            logger.debug('💔 Failed roll, awarding XP')
            roll.effects.xpAwarded = true
            const xpStore = useXPStore.getState()
            xpStore.awardFailedRoll(characterId, roll.id)
          }

          logger.debug('💾 Setting roll state...')
          set({
            currentRoll: roll,
            isRolling: false,
            activeNotifications: [roll, ...state.activeNotifications].slice(0, state.maxNotifications)
          })

          logger.debug('📚 Adding roll to history...')
          state._addRollToHistory(roll)
          logger.debug('✅ Roll process completed successfully')

          // Auto-dismiss notification after 4 seconds
          setTimeout(() => {
            set(state => ({
              activeNotifications: state.activeNotifications.filter(n => n.id !== roll.id)
            }))
          }, 4000)

          return roll
        } catch (error) {
          logger.error('❌ rollStat error:', error)
          set({ isRolling: false })
          throw error
        }
      },

      rollMove: async (moveId: string, stat: keyof Attributes, characterId: string) => {
        const state = get()
        if (state.isRolling) return state.currentRoll!

        set({ isRolling: true, currentRoll: null })

        try {
          const stats = state._getCharacterStats(characterId)
          if (!stats) throw new Error('Character not found')

          const modifier = getAttributeModifier(stats[stat])
          const { dice1, dice2 } = await rollDice()

          const context: RollContext = {
            label: moveId.replace('-', ' ').replace(/\b\w/g, l => l.toUpperCase()),
            stat,
            moveId,
            description: `${moveId} using ${stat} (${modifier >= 0 ? '+' : ''}${modifier})`
          }

          const roll = state._createRollResult(dice1, dice2, modifier, context, characterId, 'move')

          // Apply move-specific effects
          if (roll.outcome === 'failure') {
            roll.effects.xpAwarded = true
            // Award XP for failed rolls
            const xpStore = useXPStore.getState()
            xpStore.awardFailedRoll(characterId, roll.id, moveId)
          }

          // Handle hold-granting moves
          const holdAmount = (() => {
            switch (moveId) {
              case 'defend':
                return roll.outcome === 'success' ? 3 : roll.outcome === 'partial' ? 1 : 0
              case 'discern-realities':
                return roll.outcome === 'success' ? 3 : roll.outcome === 'partial' ? 1 : 0
              case 'spout-lore':
                return roll.outcome === 'success' ? 3 : roll.outcome === 'partial' ? 1 : 0
              default:
                return 0
            }
          })()

          if (holdAmount > 0) {
            roll.effects.holdGranted = holdAmount
            const holdStore = useHoldStore.getState()
            holdStore.grantHold(characterId, moveId, holdAmount, roll.id)
          }

          set({
            currentRoll: roll,
            isRolling: false,
            activeNotifications: [roll, ...state.activeNotifications].slice(0, state.maxNotifications)
          })

          state._addRollToHistory(roll)

          // Auto-dismiss notification after 4 seconds
          setTimeout(() => {
            set(state => ({
              activeNotifications: state.activeNotifications.filter(n => n.id !== roll.id)
            }))
          }, 4000)

          return roll
        } catch (error) {
          set({ isRolling: false })
          throw error
        }
      },

      rollCustom: async (modifier: number, context: RollContext, characterId: string) => {
        const state = get()
        if (state.isRolling) return state.currentRoll!

        set({ isRolling: true, currentRoll: null })

        try {
          const { dice1, dice2 } = await rollDice()
          const roll = state._createRollResult(dice1, dice2, modifier, context, characterId, 'custom')

          // Award XP for failed custom rolls (if they're meaningful rolls, not just tests)
          if (roll.outcome === 'failure' && context.stat) {
            roll.effects.xpAwarded = true
            const xpStore = useXPStore.getState()
            xpStore.awardFailedRoll(characterId, roll.id, context.moveId)
          }

          set({
            currentRoll: roll,
            isRolling: false,
            activeNotifications: [roll, ...state.activeNotifications].slice(0, state.maxNotifications)
          })

          state._addRollToHistory(roll)

          // Auto-dismiss notification after 4 seconds
          setTimeout(() => {
            set(state => ({
              activeNotifications: state.activeNotifications.filter(n => n.id !== roll.id)
            }))
          }, 4000)

          return roll
        } catch (error) {
          set({ isRolling: false })
          throw error
        }
      },

      // History management
      getHistoryForCharacter: (characterId: string) => {
        const state = get()
        // Safety check: ensure rollHistoryByCharacter is an object
        if (!state.rollHistoryByCharacter || typeof state.rollHistoryByCharacter !== 'object') {
          logger.warn('rollHistoryByCharacter is not an object, reinitializing...')
          // Reinitialize as empty object if corrupted
          state.rollHistoryByCharacter = {}
          return []
        }
        return state.rollHistoryByCharacter[characterId] || []
      },

      getAllRolls: () => {
        const state = get()
        const allRolls: RollResult[] = []

        // Safety check: ensure rollHistoryByCharacter is an object
        if (!state.rollHistoryByCharacter || typeof state.rollHistoryByCharacter !== 'object') {
          logger.warn('rollHistoryByCharacter is not an object in getAllRolls, returning empty array')
          return []
        }

        for (const rolls of Object.values(state.rollHistoryByCharacter)) {
          allRolls.push(...rolls)
        }
        // Sort by timestamp, newest first
        return allRolls.sort((a, b) => b.timestamp - a.timestamp)
      },

      clearHistoryForCharacter: (characterId: string) => {
        set(state => {
          const newHistory = { ...state.rollHistoryByCharacter }
          delete newHistory[characterId]
          return { rollHistoryByCharacter: newHistory }
        })
      },

      clearAllHistory: () => {
        set({ rollHistoryByCharacter: {} })
      },

      exportHistory: (characterId: string) => {
        const history = get().getHistoryForCharacter(characterId)
        return history.map(roll =>
          `${new Date(roll.timestamp).toLocaleString()} - ${roll.context.label}: ${roll.dice1}+${roll.dice2}+${roll.modifier}=${roll.finalResult} (${roll.outcome})`
        ).join('\r\n')
      },

      rerollWithSameContext: async (rollId: string) => {
        const state = get()

        // Find the original roll across all character histories
        let originalRoll: RollResult | null = null
        for (const [_characterId, history] of Object.entries(state.rollHistoryByCharacter)) {
          originalRoll = history.find(r => r.id === rollId) || null
          if (originalRoll) break
        }

        if (!originalRoll) return null

        // Re-roll with same parameters
        if (originalRoll.type === 'stat' && originalRoll.context.stat) {
          return await state.rollStat(originalRoll.context.stat, originalRoll.characterId, originalRoll.context.label)
        } else if (originalRoll.type === 'move' && originalRoll.context.moveId && originalRoll.context.stat) {
          return await state.rollMove(originalRoll.context.moveId, originalRoll.context.stat, originalRoll.characterId)
        } else if (originalRoll.type === 'custom') {
          return await state.rollCustom(originalRoll.modifier, originalRoll.context, originalRoll.characterId)
        }

        return null
      },

      // UI actions
      toggleHistory: () => {
        set(state => ({ showHistory: !state.showHistory }))
      },

      toggleCommandPalette: () => {
        set(state => ({ showCommandPalette: !state.showCommandPalette }))
      },

      dismissNotification: (rollId: string) => {
        set(state => ({
          activeNotifications: state.activeNotifications.filter(n => n.id !== rollId)
        }))
      },

      copyRollToClipboard: (roll: RollResult) => {
        const text = `${roll.context.label}: ${roll.dice1}+${roll.dice2}+${roll.modifier}=${roll.finalResult} (${roll.outcome})`
        navigator.clipboard.writeText(text).catch(logger.error)
      },

      // Internal helpers
      _addRollToHistory: (roll: RollResult) => {
        logger.debug('📚 _addRollToHistory called with roll:', roll)
        set(state => {
          logger.debug('📚 Current state.rollHistoryByCharacter:', state.rollHistoryByCharacter)

          // Safety check: ensure rollHistoryByCharacter is an object
          if (!state.rollHistoryByCharacter || typeof state.rollHistoryByCharacter !== 'object') {
            logger.warn('rollHistoryByCharacter is not an object in _addRollToHistory, reinitializing...')
            state.rollHistoryByCharacter = {}
          }

          const newHistory = { ...state.rollHistoryByCharacter }
          const characterHistory = newHistory[roll.characterId] || []
          logger.debug('📚 Current character history:', characterHistory)

          // Add new roll to front, limit to max history
          const updatedHistory = [roll, ...characterHistory].slice(0, state.maxHistoryPerCharacter)
          logger.debug('📚 Updated history:', updatedHistory)
          newHistory[roll.characterId] = updatedHistory
          logger.debug('📚 New history object:', newHistory)

          return { rollHistoryByCharacter: newHistory }
        })
      },

      _createRollResult: (
        dice1: number,
        dice2: number,
        modifier: number,
        context: RollContext,
        characterId: string,
        type: RollResult['type']
      ): RollResult => {
        const diceTotal = dice1 + dice2
        const finalResult = diceTotal + modifier
        const outcome = getOutcome(finalResult)

        return {
          version: 1,
          id: generateRollId(),
          timestamp: Date.now(),
          characterId,
          dice1,
          dice2,
          diceTotal,
          modifier,
          finalResult,
          outcome,
          type,
          context,
          effects: {}
        }
      },

      _getCharacterStats: (characterId: string): Attributes | null => {
        // Import character store dynamically to avoid circular dependencies
        try {
          // Use dynamic import for ES modules
          import('../stores/characterStore').then(({ useCharacterStore }) => {
            const character = useCharacterStore.getState().getCharacter(characterId)
            if (character?.attributes) {
              // Convert from new format {value, modifier} to old format (just values)
              const attributes: Attributes = {}
              Object.entries(character.attributes).forEach(([key, attr]) => {
                attributes[key as keyof Attributes] = attr.value
              })
              return attributes
            }
            return null
          }).catch(error => {
            logger.error('Failed to import character store:', error)
            return null
          })

          // For now, return hardcoded stats to test dice rolling
          logger.debug('🧪 Using hardcoded stats for testing')
          return {
            STR: 8,
            DEX: 12,
            CON: 14,
            INT: 18,
            WIS: 16,
            CHA: 10
          }
        } catch (error) {
          logger.error('Failed to get character stats:', error)
          return null
        }
      }
    }),
    {
      name: 'zimbomate-dice-store',
      // Only persist essential data, not UI state
      partialize: (state) => ({
        rollHistoryByCharacter: state.rollHistoryByCharacter,
        maxHistoryPerCharacter: state.maxHistoryPerCharacter,
        showHistory: state.showHistory
      }),
    }
  )
)

// Migration helper for future data format changes
export const migrateRollHistory = (data: any[]): RollResult[] => {
  return data.map(item => {
    if (!item.version) {
      // Migrate v0 to v1
      return {
        ...item,
        version: 1,
        characterId: item.characterId || 'default',
        effects: item.effects || {}
      }
    }
    return item
  })
}

// Export types for other components to use
export type { RollResult, RollContext }

import { logger } from '../utils/logger'
/**
 * Hold Store for Dungeon World
 * Manages hold points for various moves (Defend, Discern Realities, etc.)
 */

import { create } from 'zustand'
import { persist } from 'zustand/middleware'

export interface HoldEntry {
  id: string
  characterId: string
  moveId: string
  moveName: string
  amount: number
  maxAmount: number
  timestamp: number
  description: string
  rollId?: string // Reference to the roll that granted this hold
}

export interface HoldOption {
  id: string
  label: string
  description: string
  cost: number
}

// Define hold-granting moves and their options
export const HOLD_MOVES: Record<string, {
  name: string
  description: string
  options: HoldOption[]
}> = {
  'defend': {
    name: 'Defend',
    description: 'Stand in defense of a person, item, or location',
    options: [
      { id: 'redirect-attack', label: 'Redirect Attack', description: 'Redirect an attack from the thing you defend to yourself', cost: 1 },
      { id: 'halve-damage', label: 'Halve Damage', description: 'Halve the attack\'s effect or damage', cost: 1 },
      { id: 'open-attacker', label: 'Open Up Attacker', description: 'Open up the attacker to an ally giving them +1 forward', cost: 1 },
      { id: 'deal-damage', label: 'Deal Damage', description: 'Deal damage to the attacker equal to your level', cost: 1 }
    ]
  },
  'discern-realities': {
    name: 'Discern Realities',
    description: 'Study a situation or person',
    options: [
      { id: 'what-happened', label: 'What happened here recently?', description: 'Learn about recent events', cost: 1 },
      { id: 'about-to-happen', label: 'What is about to happen?', description: 'Anticipate immediate events', cost: 1 },
      { id: 'should-be-cautious', label: 'What should I be on the lookout for?', description: 'Identify potential threats', cost: 1 },
      { id: 'most-valuable', label: 'What here is most valuable to me?', description: 'Identify valuable things', cost: 1 },
      { id: 'who-in-control', label: 'Who\'s really in control here?', description: 'Understand power dynamics', cost: 1 },
      { id: 'not-what-seems', label: 'What here is not what it appears to be?', description: 'Reveal hidden truths', cost: 1 }
    ]
  },
  'spout-lore': {
    name: 'Spout Lore',
    description: 'Consult your accumulated knowledge',
    options: [
      { id: 'ask-question', label: 'Ask a Question', description: 'Ask the GM a question about the subject', cost: 1 },
      { id: 'useful-fact', label: 'Useful Fact', description: 'The GM will tell you something useful about the subject', cost: 1 }
    ]
  }
}

interface HoldState {
  // Hold tracking
  characterHolds: Record<string, HoldEntry[]>

  // Actions
  grantHold: (characterId: string, moveId: string, amount: number, rollId?: string) => void
  spendHold: (characterId: string, holdId: string, optionId?: string, amount?: number) => boolean
  getHoldsForCharacter: (characterId: string) => HoldEntry[]
  getHoldsForMove: (characterId: string, moveId: string) => HoldEntry[]
  clearExpiredHolds: (characterId: string) => void
  clearAllHolds: (characterId: string) => void
}

export const useHoldStore = create<HoldState>()(
  persist(
    (set, get) => ({
      // Initial state
      characterHolds: {},

      // Grant hold to a character from a move
      grantHold: (characterId, moveId, amount, rollId) => {
        const moveInfo = HOLD_MOVES[moveId]
        if (!moveInfo) {
          logger.warn(`[Hold] Unknown move: ${moveId}`)
          return
        }

        const holdEntry: HoldEntry = {
          id: `hold-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
          characterId,
          moveId,
          moveName: moveInfo.name,
          amount,
          maxAmount: amount,
          timestamp: Date.now(),
          description: moveInfo.description,
          rollId
        }

        set((state) => ({
          characterHolds: {
            ...state.characterHolds,
            [characterId]: [
              ...(state.characterHolds[characterId] || []),
              holdEntry
            ]
          }
        }))

        logger.info(`[Hold] Granted ${amount} hold for ${moveInfo.name} to ${characterId}`)
      },

      // Spend hold points
      spendHold: (characterId, holdId, optionId, amount = 1) => {
        const state = get()
        const characterHolds = state.characterHolds[characterId] || []
        const holdEntry = characterHolds.find(h => h.id === holdId)

        if (!holdEntry) {
          logger.warn(`[Hold] Hold not found: ${holdId}`)
          return false
        }

        if (holdEntry.amount < amount) {
          logger.warn(`[Hold] Not enough hold: ${holdEntry.amount} < ${amount}`)
          return false
        }

        // Log the option used if provided
        if (optionId) {
          const moveInfo = HOLD_MOVES[holdEntry.moveId]
          const option = moveInfo?.options.find(o => o.id === optionId)
          if (option) {
            logger.info(`[Hold] ${holdEntry.moveName}: ${option.label}`)
          }
        }

        set((state) => {
          const updatedHolds = state.characterHolds[characterId].map(hold =>
            hold.id === holdId
              ? { ...hold, amount: hold.amount - amount }
              : hold
          ).filter(hold => hold.amount > 0) // Remove holds with 0 points

          return {
            characterHolds: {
              ...state.characterHolds,
              [characterId]: updatedHolds
            }
          }
        })

        return true
      },

      // Get all holds for a character
      getHoldsForCharacter: (characterId) => {
        const state = get()
        return (state.characterHolds[characterId] || [])
          .sort((a, b) => b.timestamp - a.timestamp) // Most recent first
      },

      // Get holds for a specific move
      getHoldsForMove: (characterId, moveId) => {
        const state = get()
        return (state.characterHolds[characterId] || [])
          .filter(hold => hold.moveId === moveId)
          .sort((a, b) => b.timestamp - a.timestamp)
      },

      // Clear expired holds (if we ever implement expiration)
      clearExpiredHolds: (characterId) => {
        // For now, holds don't expire in basic Dungeon World
        // This could be used for custom rules or time-based holds
      },

      // Clear all holds for a character
      clearAllHolds: (characterId) => {
        set((state) => ({
          characterHolds: {
            ...state.characterHolds,
            [characterId]: []
          }
        }))
      }
    }),
    {
      name: 'zimbomate-hold-store',
      version: 1
    }
  )
)

/**
 * Monster Store for ZimboMate V2
 * Manages monster templates, custom creatures, and combat integration
 */

import { create } from 'zustand'
import { persist } from 'zustand/middleware'
import {
  MonsterTemplate,
  QuickMonster,
  DW_MONSTER_TEMPLATES,
  createQuickMonster,
  monsterToCombatParticipant,
  scaleMonster,
  MonsterTag,
  MonsterOrigin
} from '../models/Monster'

interface MonsterState {
  // Template management
  officialTemplates: MonsterTemplate[]
  customTemplates: MonsterTemplate[]
  favorites: string[] // Template IDs

  // Quick monsters for ad-hoc encounters
  quickMonsters: QuickMonster[]

  // Template operations
  addCustomTemplate: (template: Omit<MonsterTemplate, 'id' | 'createdAt' | 'updatedAt'>) => void
  updateTemplate: (id: string, updates: Partial<MonsterTemplate>) => void
  deleteTemplate: (id: string) => void
  duplicateTemplate: (id: string, newName?: string) => void

  // Quick monster operations
  createQuickMonster: (name: string, hp: number, armor: number, damage: string, tags?: MonsterTag[], instinct?: string, moves?: string[]) => void
  updateQuickMonster: (index: number, updates: Partial<QuickMonster>) => void
  deleteQuickMonster: (index: number) => void

  // Favorites
  toggleFavorite: (templateId: string) => void
  getFavoriteTemplates: () => MonsterTemplate[]

  // Search and filtering
  searchTemplates: (query: string, origin?: MonsterOrigin, tags?: MonsterTag[]) => MonsterTemplate[]
  getTemplatesByLevel: (minLevel: number, maxLevel: number) => MonsterTemplate[]

  // Combat integration
  addToCombat: (template: MonsterTemplate | QuickMonster, level?: number) => any
  createEncounterGroup: (templateIds: string[], count: number[]) => any[]

  // Scaling and customization
  scaleTemplateForLevel: (templateId: string, level: number) => MonsterTemplate | null

  // Utility
  getAllTemplates: () => MonsterTemplate[]
  getTemplateById: (id: string) => MonsterTemplate | null
}

export const useMonsterStore = create<MonsterState>()(
  persist(
    (set, get) => ({
      // Initial state
      officialTemplates: DW_MONSTER_TEMPLATES,
      customTemplates: [],
      favorites: [],
      quickMonsters: [],

      // Template operations
      addCustomTemplate: (templateData) => {
        const newTemplate: MonsterTemplate = {
          ...templateData,
          id: `custom-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`,
          official: false,
          createdAt: new Date(),
          updatedAt: new Date()
        }

        set((state) => ({
          customTemplates: [...state.customTemplates, newTemplate]
        }))
      },

      updateTemplate: (id, updates) => {
        set((state) => ({
          customTemplates: state.customTemplates.map(template =>
            template.id === id
              ? { ...template, ...updates, updatedAt: new Date() }
              : template
          )
        }))
      },

      deleteTemplate: (id) => {
        set((state) => ({
          customTemplates: state.customTemplates.filter(template => template.id !== id),
          favorites: state.favorites.filter(fav => fav !== id)
        }))
      },

      duplicateTemplate: (id, newName) => {
        const template = get().getTemplateById(id)
        if (!template) return

        const duplicatedTemplate: MonsterTemplate = {
          ...template,
          id: `custom-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`,
          name: newName || `${template.name} (Copy)`,
          official: false,
          createdAt: new Date(),
          updatedAt: new Date()
        }

        set((state) => ({
          customTemplates: [...state.customTemplates, duplicatedTemplate]
        }))
      },

      // Quick monster operations
      createQuickMonster: (name, hp, armor, damage, tags = [], instinct = 'To survive', moves = ['Attack']) => {
        const quickMonster = createQuickMonster(name, hp, armor, damage, tags, instinct, moves)
        set((state) => ({
          quickMonsters: [...state.quickMonsters, quickMonster]
        }))
      },

      updateQuickMonster: (index, updates) => {
        set((state) => ({
          quickMonsters: state.quickMonsters.map((monster, i) =>
            i === index ? { ...monster, ...updates } : monster
          )
        }))
      },

      deleteQuickMonster: (index) => {
        set((state) => ({
          quickMonsters: state.quickMonsters.filter((_, i) => i !== index)
        }))
      },

      // Favorites
      toggleFavorite: (templateId) => {
        set((state) => ({
          favorites: state.favorites.includes(templateId)
            ? state.favorites.filter(id => id !== templateId)
            : [...state.favorites, templateId]
        }))
      },

      getFavoriteTemplates: () => {
        const { favorites, getAllTemplates } = get()
        return getAllTemplates().filter(template => favorites.includes(template.id))
      },

      // Search and filtering
      searchTemplates: (query, origin, tags) => {
        const allTemplates = get().getAllTemplates()
        return allTemplates.filter(template => {
          const matchesQuery = !query ||
            template.name.toLowerCase().includes(query.toLowerCase()) ||
            template.description.toLowerCase().includes(query.toLowerCase()) ||
            template.instinct.toLowerCase().includes(query.toLowerCase())

          const matchesOrigin = !origin || template.origin === origin

          const matchesTags = !tags || tags.length === 0 ||
            tags.every(tag => template.tags.includes(tag))

          return matchesQuery && matchesOrigin && matchesTags
        })
      },

      getTemplatesByLevel: (minLevel, maxLevel) => {
        const allTemplates = get().getAllTemplates()
        return allTemplates.filter(template => {
          const templateMin = template.minLevel || 1
          const templateMax = template.maxLevel || 10
          return templateMin <= maxLevel && templateMax >= minLevel
        })
      },

      // Combat integration
      addToCombat: (template, level) => {
        let finalTemplate: MonsterTemplate | QuickMonster = template

        // Scale official template if level provided
        if ('official' in template && template.official && level) {
          finalTemplate = scaleMonster(template, level)
        }

        return monsterToCombatParticipant(finalTemplate)
      },

      createEncounterGroup: (templateIds, counts) => {
        const { getTemplateById } = get()
        const participants: any[] = []

        templateIds.forEach((templateId, index) => {
          const template = getTemplateById(templateId)
          if (!template) return

          const count = counts[index] || 1
          for (let i = 0; i < count; i++) {
            const participant = monsterToCombatParticipant(
              template,
              `${templateId}-${i + 1}`
            )
            participant.name = count > 1 ? `${template.name} ${i + 1}` : template.name
            participants.push(participant)
          }
        })

        return participants
      },

      // Scaling
      scaleTemplateForLevel: (templateId, level) => {
        const template = get().getTemplateById(templateId)
        if (!template) return null
        return scaleMonster(template, level)
      },

      // Utility
      getAllTemplates: () => {
        const { officialTemplates, customTemplates } = get()
        return [...officialTemplates, ...customTemplates]
      },

      getTemplateById: (id) => {
        const allTemplates = get().getAllTemplates()
        return allTemplates.find(template => template.id === id) || null
      }
    }),
    {
      name: 'zimbomate-monster-storage',
      partialize: (state) => ({
        customTemplates: state.customTemplates,
        favorites: state.favorites,
        quickMonsters: state.quickMonsters
        // Don't persist official templates - they're loaded from the model
      })
    }
  )
)

/**
 * Notification Queue Management System
 * Handles dice roll notifications, XP awards, and other system messages
 * Prevents notification spam with intelligent queuing and prioritization
 */

import { create } from 'zustand'
import { persist } from 'zustand/middleware'

export type NotificationType = 'dice-roll' | 'xp-award' | 'hold-granted' | 'level-up' | 'achievement' | 'error' | 'info'

export interface Notification {
  id: string
  type: NotificationType
  title: string
  message: string
  icon?: string
  priority: 'low' | 'medium' | 'high' | 'urgent'
  duration: number // milliseconds, 0 = permanent
  timestamp: number
  characterId?: string
  rollId?: string
  dismissible: boolean
  actions?: Array<{
    label: string
    action: () => void
    style?: 'primary' | 'secondary' | 'danger'
  }>
}

interface NotificationState {
  // State
  activeNotifications: Notification[]
  notificationHistory: Notification[]
  maxActiveNotifications: number
  isEnabled: boolean
  preferences: {
    enableDiceRolls: boolean
    enableXPAwards: boolean
    enableHoldGrants: boolean
    enableLevelUps: boolean
    enableAchievements: boolean
    mutedDuration: number // 0 = not muted
  }

  // Actions
  addNotification: (notification: Omit<Notification, 'id' | 'timestamp'>) => void
  dismissNotification: (id: string) => void
  dismissAllNotifications: () => void
  muteNotifications: (durationMs: number) => void
  unmuteNotifications: () => void
  setPreference: <K extends keyof NotificationState['preferences']>(key: K, value: NotificationState['preferences'][K]) => void
  clearHistory: () => void
  getNotificationsByType: (type: NotificationType) => Notification[]
  getNotificationsByCharacter: (characterId: string) => Notification[]
}

const DEFAULT_DURATIONS: Record<NotificationType, number> = {
  'dice-roll': 3000,
  'xp-award': 4000,
  'hold-granted': 3500,
  'level-up': 8000,
  'achievement': 6000,
  'error': 6000,
  'info': 4000
}

const PRIORITY_WEIGHTS: Record<Notification['priority'], number> = {
  'urgent': 1000,
  'high': 100,
  'medium': 10,
  'low': 1
}

export const useNotificationStore = create<NotificationState>()(
  persist(
    (set, get) => ({
      // Initial state
      activeNotifications: [],
      notificationHistory: [],
      maxActiveNotifications: 3,
      isEnabled: true,
      preferences: {
        enableDiceRolls: true,
        enableXPAwards: true,
        enableHoldGrants: true,
        enableLevelUps: true,
        enableAchievements: true,
        mutedDuration: 0
      },

      // Add notification with intelligent queuing
      addNotification: (notificationData) => {
        const state = get()

        // Check if notifications are muted
        if (!state.isEnabled || (state.preferences.mutedDuration > Date.now())) {
          return
        }

        // Check type-specific preferences
        const typeEnabled = (() => {
          switch (notificationData.type) {
            case 'dice-roll': return state.preferences.enableDiceRolls
            case 'xp-award': return state.preferences.enableXPAwards
            case 'hold-granted': return state.preferences.enableHoldGrants
            case 'level-up': return state.preferences.enableLevelUps
            case 'achievement': return state.preferences.enableAchievements
            default: return true
          }
        })()

        if (!typeEnabled) return

        const notification: Notification = {
          ...notificationData,
          id: `notification-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
          timestamp: Date.now(),
          duration: notificationData.duration || DEFAULT_DURATIONS[notificationData.type] || 4000
        }

        set((state) => {
          let newActive = [...state.activeNotifications]

          // Handle duplicate prevention for dice rolls
          if (notification.type === 'dice-roll' && notification.rollId) {
            newActive = newActive.filter(n => n.rollId !== notification.rollId)
          }

          // Add new notification
          newActive.push(notification)

          // Sort by priority and timestamp
          newActive.sort((a, b) => {
            const priorityDiff = PRIORITY_WEIGHTS[b.priority] - PRIORITY_WEIGHTS[a.priority]
            if (priorityDiff !== 0) return priorityDiff
            return b.timestamp - a.timestamp
          })

          // Limit active notifications
          if (newActive.length > state.maxActiveNotifications) {
            // Remove lowest priority, oldest notifications
            const removed = newActive.splice(state.maxActiveNotifications)

            // But keep urgent notifications
            removed.forEach(removedNotification => {
              if (removedNotification.priority === 'urgent') {
                newActive[newActive.length - 1] = removedNotification
              }
            })
          }

          // Add to history
          const newHistory = [notification, ...state.notificationHistory].slice(0, 100) // Keep last 100

          console.log(`[Notifications] Added: ${notification.title} (${notification.type})`)

          return {
            activeNotifications: newActive,
            notificationHistory: newHistory
          }
        })

        // Auto-dismiss if duration is set
        if (notification.duration > 0) {
          setTimeout(() => {
            get().dismissNotification(notification.id)
          }, notification.duration)
        }
      },

      // Dismiss specific notification
      dismissNotification: (id) => {
        set((state) => ({
          activeNotifications: state.activeNotifications.filter(n => n.id !== id)
        }))
      },

      // Dismiss all notifications
      dismissAllNotifications: () => {
        set({ activeNotifications: [] })
      },

      // Mute notifications temporarily
      muteNotifications: (durationMs) => {
        set((state) => ({
          preferences: {
            ...state.preferences,
            mutedDuration: Date.now() + durationMs
          }
        }))
      },

      // Unmute notifications
      unmuteNotifications: () => {
        set((state) => ({
          preferences: {
            ...state.preferences,
            mutedDuration: 0
          }
        }))
      },

      // Update preferences
      setPreference: (key, value) => {
        set((state) => ({
          preferences: {
            ...state.preferences,
            [key]: value
          }
        }))
      },

      // Clear notification history
      clearHistory: () => {
        set({ notificationHistory: [] })
      },

      // Get notifications by type
      getNotificationsByType: (type) => {
        const state = get()
        return state.notificationHistory.filter(n => n.type === type)
      },

      // Get notifications by character
      getNotificationsByCharacter: (characterId) => {
        const state = get()
        return state.notificationHistory.filter(n => n.characterId === characterId)
      }
    }),
    {
      name: 'zimbomate-notification-store',
      version: 1,
      // Don't persist active notifications - they should reset on page reload
      partialize: (state) => ({
        preferences: state.preferences,
        notificationHistory: state.notificationHistory,
        maxActiveNotifications: state.maxActiveNotifications,
        isEnabled: state.isEnabled
      })
    }
  )
)

// Convenience functions for common notification types
