export const performanceStressTest = async (context: E2ETestContext) => {
  const { user, navigateToTab, measurePerformance } = context

  const results = []

  // Rapid tab switching
  const tabSwitchPerf = await measurePerformance(async () => {
    for (let i = 0; i < 10; i++) {
