    const rollButton = screen.getByRole('button', { name: /roll dice/i })
    for (let i = 0; i < 5; i++) {
      await user.click(rollButton)
      await waitFor(() => screen.queryByText(/rolling/i), { timeout: 1000 })
      await waitFor(() => !screen.queryByText(/rolling/i), { timeout: 3000 })
