import { logger } from './logger'
/**
 * Browser Compatibility and Progressive Enhancement
 * Ensures core dice functionality works across browsers with graceful degradation
 */

// Feature detection utilities
export const BrowserFeatures = {
  // Core web APIs
  intersectionObserver: () => typeof IntersectionObserver !== 'undefined',
  requestAnimationFrame: () => typeof requestAnimationFrame !== 'undefined',
  localStorage: () => {
    try {
      const test = 'zimbo-test'
      localStorage.setItem(test, test)
      localStorage.removeItem(test)
      return true
    } catch {
      return false
    }
  },

  // Advanced APIs
  dragAndDrop: () => 'draggable' in document.createElement('div'),
  clipboard: () => navigator.clipboard && typeof navigator.clipboard.writeText === 'function',
  webShare: () => navigator.share && typeof navigator.share === 'function',
  serviceWorker: () => 'serviceWorker' in navigator,

  // Input methods
  touch: () => 'ontouchstart' in window || navigator.maxTouchPoints > 0,
  keyboard: () => true, // Always available
  mouse: () => matchMedia('(pointer: fine)').matches,

  // Display capabilities
  reducedMotion: () => matchMedia('(prefers-reduced-motion: reduce)').matches,
  highContrast: () => matchMedia('(prefers-contrast: high)').matches,
  darkMode: () => matchMedia('(prefers-color-scheme: dark)').matches,

  // Performance features
  webGL: () => {
    try {
      const canvas = document.createElement('canvas')
      return !!(canvas.getContext('webgl') || canvas.getContext('experimental-webgl'))
    } catch {
      return false
    }
  }
}

// Browser-specific compatibility layers
export class CompatibilityLayer {
  private features: Record<string, boolean> = {}

  constructor() {
    this.detectFeatures()
  }

  private detectFeatures() {
    Object.entries(BrowserFeatures).forEach(([feature, detector]) => {
      this.features[feature] = detector()
    })

    logger.info('[Compatibility] Browser features:', this.features)
  }

  // Clipboard API with fallback
  async copyToClipboard(text: string): Promise<boolean> {
    if (this.features.clipboard) {
      try {
        await navigator.clipboard.writeText(text)
        return true
      } catch (error) {
        logger.warn('[Compatibility] Clipboard API failed, using fallback:', error)
      }
    }

    // Fallback method
    try {
      const textArea = document.createElement('textarea')
      textArea.value = text
      textArea.style.position = 'fixed'
      textArea.style.opacity = '0'
      textArea.style.pointerEvents = 'none'

      document.body.appendChild(textArea)
      textArea.select()
      textArea.setSelectionRange(0, text.length)

      const success = document.execCommand('copy')
      document.body.removeChild(textArea)

      return success
    } catch {
      return false
    }
  }

  // Local storage with fallback
  setItem(key: string, value: string): boolean {
    if (this.features.localStorage) {
      try {
        localStorage.setItem(key, value)
        return true
      } catch (error) {
        logger.warn('[Compatibility] LocalStorage failed:', error)
      }
    }

    // Fallback to in-memory storage
    if (typeof window !== 'undefined') {
      ;(window as any).__zimboFallbackStorage = (window as any).__zimboFallbackStorage || {}
      ;(window as any).__zimboFallbackStorage[key] = value
      return true
    }

    return false
  }

  getItem(key: string): string | null {
    if (this.features.localStorage) {
      try {
        return localStorage.getItem(key)
      } catch {
        // Fall through to fallback
      }
    }

    // Fallback storage
    if (typeof window !== 'undefined' && (window as any).__zimboFallbackStorage) {
      return (window as any).__zimboFallbackStorage[key] || null
    }

    return null
  }

  // Intersection Observer with fallback
  createIntersectionObserver(
    callback: (entries: any[]) => void,
    options?: IntersectionObserverInit
  ): { observe: (el: Element) => void; unobserve: (el: Element) => void; disconnect: () => void } {
    if (this.features.intersectionObserver) {
      const observer = new IntersectionObserver(callback, options)
      return observer
    }

    // Fallback: use scroll events and manual calculations
    const observedElements = new Set<Element>()

    const checkVisibility = () => {
      const entries = Array.from(observedElements).map(element => {
        const rect = element.getBoundingClientRect()
        const isIntersecting = rect.top < window.innerHeight && rect.bottom > 0

        return {
          target: element,
          isIntersecting,
          boundingClientRect: rect
        }
      })

      callback(entries)
    }

    const throttledCheck = this.throttle(checkVisibility, 100)

    window.addEventListener('scroll', throttledCheck)
    window.addEventListener('resize', throttledCheck)

    return {
      observe: (element: Element) => {
        observedElements.add(element)
        checkVisibility() // Initial check
      },
      unobserve: (element: Element) => {
        observedElements.delete(element)
      },
      disconnect: () => {
        observedElements.clear()
        window.removeEventListener('scroll', throttledCheck)
        window.removeEventListener('resize', throttledCheck)
      }
    }
  }

  // Animation with fallback
  animate(element: HTMLElement, animations: Keyframe[], options?: KeyframeAnimationOptions) {
    if ('animate' in element) {
      return element.animate(animations, options)
    }

    // CSS fallback for basic animations
    const duration = (options?.duration as number) || 1000
    const easing = options?.easing || 'ease'

    element.style.transition = `all ${duration}ms ${easing}`

    // Apply final state
    if (animations.length > 0) {
      const finalFrame = animations[animations.length - 1] as any
      Object.assign(element.style, finalFrame)
    }

    // Return a fake animation object
    return {
      finished: new Promise(resolve => setTimeout(resolve, duration)),
      cancel: () => {
        element.style.transition = ''
      }
    }
  }

  // Utility methods
  private throttle<T extends (...args: any[]) => any>(func: T, limit: number): T {
    let inThrottle: boolean
    return ((...args: any[]) => {
      if (!inThrottle) {
        func.apply(this, args)
        inThrottle = true
        setTimeout(() => inThrottle = false, limit)
      }
    }) as T
  }

  // Get feature support status
  hasFeature(feature: keyof typeof BrowserFeatures): boolean {
    return this.features[feature] || false
  }

  // Get browser info for debugging
  getBrowserInfo() {
    return {
      userAgent: navigator.userAgent,
      features: this.features,
      viewport: {
        width: window.innerWidth,
        height: window.innerHeight
      },
      colorScheme: this.features.darkMode ? 'dark' : 'light',
      reducedMotion: this.features.reducedMotion,
      highContrast: this.features.highContrast,
      inputMethods: {
        touch: this.features.touch,
        mouse: this.features.mouse,
        keyboard: this.features.keyboard
      }
    }
  }
}

// Global instance
export const compatibility = new CompatibilityLayer()

// Progressive enhancement helpers
export const ProgressiveEnhancement = {
  // Enhanced dice rolling with fallbacks
  createDiceRoller: () => {
    const hasAnimations = !compatibility.hasFeature('reducedMotion')
    const hasAdvancedFeatures = compatibility.hasFeature('intersectionObserver')

    return {
      enableAnimations: hasAnimations,
      enableLazyLoading: hasAdvancedFeatures,
      enableAdvancedHover: compatibility.hasFeature('mouse'),
      enableDragDrop: compatibility.hasFeature('dragAndDrop') && compatibility.hasFeature('mouse')
    }
  },

  // Adaptive UI based on capabilities
  getUIConfig: () => {
    return {
      enableHoverEffects: compatibility.hasFeature('mouse'),
      enableTouchGestures: compatibility.hasFeature('touch'),
      enableKeyboardShortcuts: compatibility.hasFeature('keyboard'),
      enableNotifications: true, // Always available with fallbacks
      enableComplexAnimations: !compatibility.hasFeature('reducedMotion'),
      enableHighContrast: compatibility.hasFeature('highContrast'),
      showTooltips: compatibility.hasFeature('mouse'), // Touch users don't need hover tooltips
      enableRightClick: compatibility.hasFeature('mouse')
    }
  },

  // Performance optimizations
  getPerformanceConfig: () => {
    const isLowEnd = !compatibility.hasFeature('webGL') ||
                     navigator.hardwareConcurrency < 4 ||
                     navigator.deviceMemory < 4

    return {
      enableLazyLoading: compatibility.hasFeature('intersectionObserver'),
      reduceAnimations: compatibility.hasFeature('reducedMotion') || isLowEnd,
      limitNotifications: isLowEnd ? 2 : 3,
      enableVirtualization: isLowEnd,
      preloadImages: !isLowEnd
    }
  }
}

// CSS custom properties for progressive enhancement
export const setCSSFeatures = () => {
  const root = document.documentElement

  root.style.setProperty('--supports-backdrop-filter',
    CSS.supports('backdrop-filter', 'blur(10px)') ? '1' : '0')

  root.style.setProperty('--supports-sticky',
    CSS.supports('position', 'sticky') ? '1' : '0')

  root.style.setProperty('--supports-grid',
    CSS.supports('display', 'grid') ? '1' : '0')

  root.style.setProperty('--supports-aspect-ratio',
    CSS.supports('aspect-ratio', '1/1') ? '1' : '0')

  // Set feature classes on body
  document.body.classList.toggle('supports-hover', compatibility.hasFeature('mouse'))
  document.body.classList.toggle('supports-touch', compatibility.hasFeature('touch'))
  document.body.classList.toggle('supports-motion', !compatibility.hasFeature('reducedMotion'))
  document.body.classList.toggle('supports-high-contrast', compatibility.hasFeature('highContrast'))
}

// Initialize compatibility features
export const initCompatibility = () => {
  setCSSFeatures()

  // Log browser support for debugging
  logger.info('[Compatibility] Browser info:', compatibility.getBrowserInfo())
  logger.info('[Compatibility] UI config:', ProgressiveEnhancement.getUIConfig())
  logger.info('[Compatibility] Performance config:', ProgressiveEnhancement.getPerformanceConfig())
}

/**
 * Button utilities for debugging and fixing common button issues in ZimboMate v2
 */

export interface ButtonDiagnostic {
  element: HTMLButtonElement
  issues: string[]
  fixes: string[]
  working: boolean
}

/**
 * Diagnose button functionality issues
 */
export function diagnoseButton(button: HTMLButtonElement): ButtonDiagnostic {
  const issues: string[] = []
  const fixes: string[] = []

  // Check if button is disabled
  if (button.disabled) {
    issues.push('Button is disabled')
    fixes.push('Remove disabled attribute or check disable condition')
  }

  // Check for click handlers
  const hasOnClick = button.onclick !== null
  const hasEventListeners = (button as any).getEventListeners?.('click')?.length > 0

  if (!hasOnClick && !hasEventListeners) {
    issues.push('No click handler found')
    fixes.push('Add onClick handler or addEventListener')
  }

  // Check CSS pointer-events
  const computedStyle = window.getComputedStyle(button)
  if (computedStyle.pointerEvents === 'none') {
    issues.push('CSS pointer-events is set to none')
    fixes.push('Remove pointer-events: none from CSS')
  }

  // Check if button is hidden
  if (computedStyle.display === 'none' || computedStyle.visibility === 'hidden') {
    issues.push('Button is hidden')
    fixes.push('Make button visible')
  }

  // Check z-index issues
  const zIndex = parseInt(computedStyle.zIndex) || 0
  if (zIndex < 0) {
    issues.push('Button has negative z-index')
    fixes.push('Increase z-index value')
  }

  // Check for overlapping elements
  const rect = button.getBoundingClientRect()
  const centerX = rect.left + rect.width / 2
  const centerY = rect.top + rect.height / 2
  const elementAtCenter = document.elementFromPoint(centerX, centerY)

  if (elementAtCenter && elementAtCenter !== button && !button.contains(elementAtCenter)) {
    issues.push('Button is covered by another element')
    fixes.push('Adjust z-index or element positioning')
  }

  // Check for form submission issues
  if (button.type === 'submit' && !button.form) {
    issues.push('Submit button not inside a form')
    fixes.push('Place button inside a form element or change type')
  }

  return {
    element: button,
    issues,
    fixes,
    working: issues.length === 0
  }
}

/**
 * Diagnose all buttons on the page
 */
export function diagnoseAllButtons(): ButtonDiagnostic[] {
  const buttons = document.querySelectorAll('button')
  return Array.from(buttons).map(diagnoseButton)
}

/**
 * Fix common button issues automatically
 */
export function fixButtonIssues(button: HTMLButtonElement): boolean {
  let fixed = false

  // Remove pointer-events: none if present
  if (button.style.pointerEvents === 'none') {
    button.style.pointerEvents = 'auto'
    fixed = true
  }

  // Ensure button is focusable
  if (button.tabIndex < 0) {
    button.tabIndex = 0
    fixed = true
  }

  // Add basic click handler if none exists
  if (!button.onclick && !button.hasAttribute('data-has-listeners')) {
    button.onclick = function(e) {
      console.log('🔧 Auto-fixed button clicked:', this)
      // Prevent default if it's a submit button without a form
      if (this.type === 'submit' && !this.form) {
        e.preventDefault()
      }
    }
    button.setAttribute('data-has-listeners', 'true')
    fixed = true
  }

  return fixed
}

/**
 * Add debugging capabilities to buttons
 */
export function enableButtonDebugging(): void {
  // Add click logging to all buttons
  document.addEventListener('click', (e) => {
    if (e.target instanceof HTMLButtonElement) {
      console.log('🎯 Button clicked:', {
        element: e.target,
        text: e.target.textContent,
        disabled: e.target.disabled,
        type: e.target.type,
        className: e.target.className,
        hasOnClick: !!e.target.onclick,
        variant: e.target.getAttribute('data-variant'),
        event: e
      })
    }
  }, true)

  // Add visual debugging
  const style = document.createElement('style')
  style.id = 'zimbomate-button-debug'
  style.textContent = `
    button:hover::after {
      content: '🔍 DEBUG';
      position: absolute;
      top: -25px;
      right: -10px;
      background: var(--primary);
      color: white;
      padding: 2px 6px;
      border-radius: 4px;
      font-size: 10px;
      font-weight: bold;
      z-index: 10000;
      pointer-events: none;
      white-space: nowrap;
    }

    button:disabled::after {
      content: '❌ DISABLED';
      background: var(--red-500);
    }

    button[onclick=""]::after,
    button:not([onclick]):not([data-has-listeners])::after {
      content: '⚠️ NO HANDLER';
      background: var(--yellow-500);
      color: black;
    }

    button[data-working="false"]::after {
      content: '🚫 BROKEN';
      background: var(--red-600);
    }
  `
  document.head.appendChild(style)
}

/**
 * Create a button test report
 */
export function generateButtonReport(): string {
  const diagnostics = diagnoseAllButtons()
  const workingButtons = diagnostics.filter(d => d.working).length
  const brokenButtons = diagnostics.filter(d => !d.working)

  let report = `ZimboMate v2 Button Functionality Report\n`
  report += `========================================\n\n`
  report += `Total buttons: ${diagnostics.length}\n`
  report += `Working buttons: ${workingButtons}\n`
  report += `Problematic buttons: ${brokenButtons.length}\n\n`

  if (brokenButtons.length > 0) {
    report += `Issues found:\n`
    brokenButtons.forEach((diagnostic, index) => {
      report += `\n${index + 1}. Button: "${diagnostic.element.textContent?.trim() || 'No text'}"\n`
      report += `   Class: ${diagnostic.element.className}\n`
      report += `   Variant: ${diagnostic.element.getAttribute('data-variant') || 'unknown'}\n`
      report += `   Issues:\n`
      diagnostic.issues.forEach(issue => {
        report += `   - ${issue}\n`
      })
      report += `   Suggested fixes:\n`
      diagnostic.fixes.forEach(fix => {
        report += `   - ${fix}\n`
      })
    })
  }

  return report
}

/**
 * Auto-fix all button issues on the page
 */
export function autoFixAllButtons(): number {
  const buttons = document.querySelectorAll('button')
  let fixedCount = 0

  buttons.forEach(button => {
    if (fixButtonIssues(button as HTMLButtonElement)) {
      fixedCount++
    }
  })

  return fixedCount
}

