// Test utilities for ZimboMate V2
interface TestWrapperProps {
  children: React.ReactNode
  theme?: 'matsu'
  withErrorBoundary?: boolean
  withQueryClient?: boolean
  withTooltips?: boolean
}

// Custom test wrapper with all providers
const TestWrapper: React.FC<TestWrapperProps> = ({
  children,
  theme = 'matsu',
  withErrorBoundary = true,
  withQueryClient = true,
  withTooltips = true
}) => {
  const queryClient = new QueryClient({
    defaultOptions: {
      queries: {
        retry: false,
        gcTime: 0,
      },
    },
  })

  let wrappedChildren = children

  // Wrap with QueryClient if needed
  if (withQueryClient) {
    wrappedChildren = (
      <QueryClientProvider client={queryClient}>
        {wrappedChildren}
      </QueryClientProvider>
    )
  }

  // Wrap with Tooltips if needed
  if (withTooltips) {
    wrappedChildren = (
      <Tooltip.Provider delayDuration={0}>
        {wrappedChildren}
      </Tooltip.Provider>
    )
  }

  // Wrap with ThemeProvider
  wrappedChildren = (
    <ThemeProvider defaultTheme={theme}>
      {wrappedChildren}
    </ThemeProvider>
  )

  // Wrap with ErrorBoundary if needed
  if (withErrorBoundary) {
    wrappedChildren = (
      <ErrorBoundary>
        {wrappedChildren}
      </ErrorBoundary>
    )
  }

  return <>{wrappedChildren}</>
}

// Enhanced render function with custom wrapper
interface CustomRenderOptions extends Omit<RenderOptions, 'wrapper'> {
  theme?: 'matsu'
  withErrorBoundary?: boolean
  withQueryClient?: boolean
  withTooltips?: boolean
}

export const renderWithProviders = (
  ui: React.ReactElement,
  options: CustomRenderOptions = {}
) => {
  const {
    theme = 'matsu',
    withErrorBoundary = true,
    withQueryClient = true,
    withTooltips = true,
    ...renderOptions
  } = options

  const Wrapper = ({ children }: { children: React.ReactNode }) => (
    <TestWrapper
      theme={theme}
      withErrorBoundary={withErrorBoundary}
      withQueryClient={withQueryClient}
      withTooltips={withTooltips}
    >
      {children}
    </TestWrapper>
  )

  return {
    user: userEvent.setup({ writeToClipboard: false }),
    ...render(ui, { wrapper: Wrapper, ...renderOptions })
  }
}

